function getEventStateStorageKey(eventId) {
  return `rc-drift-event-state-${eventId}-v${EVENT_STORAGE_VERSION}`;
}

function buildDefaultRoleNames(overrides = {}) {
  return {
    admin: ROLE_LABELS.admin,
    j1: overrides.j1?.trim() || ROLE_LABELS.j1,
    j2: overrides.j2?.trim() || ROLE_LABELS.j2,
    j3: overrides.j3?.trim() || ROLE_LABELS.j3,
  };
}

function normalizeDeletedEventIds(value) {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((entry) => String(entry || "").trim()).filter(Boolean))];
}

function getDeletedEventIdsSnapshot() {
  return normalizeDeletedEventIds([...deletedEventIds]);
}

function setDeletedEventId(eventId, deleted = true) {
  const normalizedId = String(eventId || "").trim();
  if (!normalizedId) return;
  if (deleted) {
    deletedEventIds.add(normalizedId);
  } else {
    deletedEventIds.delete(normalizedId);
  }
}

function isDeletedEventId(eventId) {
  return deletedEventIds.has(String(eventId || "").trim());
}

function normalizeJudgeCount(value) {
  const parsed = Number.parseInt(value, 10);
  if (parsed === 1 || parsed === 2 || parsed === 3) return parsed;
  return 3;
}

function normalizeJudgingMode(value) {
  return value === JUDGING_MODE_LINE_ANGLE_STYLE ? JUDGING_MODE_LINE_ANGLE_STYLE : JUDGING_MODE_AVERAGE;
}

function normalizeCompetitionMode(value) {
  return normalizeCompetitionModeValue(value);
}

function getCompetitionModeSettings(competitionMode, options = {}) {
  const normalizedMode = normalizeCompetitionMode(competitionMode);
  if (normalizedMode !== COMPETITION_MODE_TECH1_ANNIVERSARY) return null;
  const optionMeta = options?.eventMeta || null;
  const optionSpecialEventId = String(
    options?.specialEventId
    || optionMeta?.specialEventId
    || optionMeta?.modeSettings?.specialEventId
    || "",
  ).trim();
  const seededSpecialEventId = optionSpecialEventId
    && optionSpecialEventId !== TECH1_ANNIVERSARY_COMPETITION_MODE.specialEventId
      ? optionSpecialEventId
      : `tech1-${slugifyEventId(options?.eventId || optionMeta?.id || options?.eventName || optionMeta?.name || "event")}`.slice(0, 120);
  return {
    mode: TECH1_ANNIVERSARY_COMPETITION_MODE.mode,
    competitionType: TECH1_ANNIVERSARY_COMPETITION_MODE.competitionType,
    qualifyingEnabled: TECH1_ANNIVERSARY_COMPETITION_MODE.qualifyingEnabled,
    registrationEnabled: TECH1_ANNIVERSARY_COMPETITION_MODE.registrationEnabled,
    raffleEnabled: TECH1_ANNIVERSARY_COMPETITION_MODE.raffleEnabled,
    raffleTicketPrice: TECH1_ANNIVERSARY_COMPETITION_MODE.raffleTicketPrice,
    freeTicketsPerRegistration: TECH1_ANNIVERSARY_COMPETITION_MODE.freeTicketsPerRegistration,
    bracketGeneration: TECH1_ANNIVERSARY_COMPETITION_MODE.bracketGeneration,
    defaultBracketSource: TECH1_ANNIVERSARY_COMPETITION_MODE.defaultBracketSource,
    specialEventId: seededSpecialEventId,
  };
}

function buildTech1SpecialEventIdForEvent(eventMeta = activeEventMeta, eventId = activeEventId) {
  const modeSettings = eventMeta?.modeSettings || null;
  const explicitSpecialEventId = String(
    modeSettings?.specialEventId || eventMeta?.specialEventId || "",
  ).trim();
  if (
    explicitSpecialEventId
    && explicitSpecialEventId !== TECH1_ANNIVERSARY_COMPETITION_MODE.specialEventId
  ) {
    return explicitSpecialEventId;
  }
  const slug = slugifyEventId(eventId || eventMeta?.id || eventMeta?.name || "tech1-event");
  return `tech1-${slug}`.slice(0, 120);
}

function getActiveTech1SpecialEventId(eventMeta = activeEventMeta, eventId = activeEventId) {
  return buildTech1SpecialEventIdForEvent(eventMeta, eventId);
}

function normalizeEventCompetitionModeState(eventMeta) {
  if (!eventMeta) return null;
  const normalizedMode = eventLooksLikeTech1Anniversary(eventMeta)
    ? COMPETITION_MODE_TECH1_ANNIVERSARY
    : normalizeCompetitionMode(eventMeta.modeSettings?.mode || eventMeta.competitionMode || eventMeta.mode);
  const modeSettings = getCompetitionModeSettings(normalizedMode, { eventMeta, eventId: eventMeta.id, eventName: eventMeta.name });
  return {
    ...eventMeta,
    competitionMode: normalizedMode,
    modeSettings,
    specialEventId: eventMeta.specialEventId || modeSettings?.specialEventId || null,
  };
}

function normalizeJudgeCountForMode(value, judgingMode) {
  const normalizedCount = normalizeJudgeCount(value);
  return normalizeJudgingMode(judgingMode) === JUDGING_MODE_LINE_ANGLE_STYLE ? 3 : normalizedCount;
}

function getEventCompetitionMode(eventMeta = activeEventMeta) {
  if (eventLooksLikeTech1Anniversary(eventMeta)) return COMPETITION_MODE_TECH1_ANNIVERSARY;
  return normalizeCompetitionMode(eventMeta?.competitionMode);
}

function eventLooksLikeTech1Anniversary(eventMeta = activeEventMeta) {
  if (!eventMeta) return false;
  const modeSettings = eventMeta.modeSettings || {};
  const values = [
    eventMeta.id,
    eventMeta.eventId,
    eventMeta.name,
    eventMeta.title,
    eventMeta.mode,
    eventMeta.competitionMode,
    eventMeta.specialEventId,
    modeSettings.mode,
    modeSettings.specialEventId,
    modeSettings.competitionType,
  ].map((value) => String(value || "").trim().toLowerCase());
  if (values.some((value) => value === getActiveTech1SpecialEventId() || value === TECH1DRIFT_ANNIVERSARY_CONFIG.mode || value === TECH1DRIFT_ANNIVERSARY_CONFIG.legacySpecialEventMode)) {
    return true;
  }
  return values.some((value) => value.includes("tech 1") && value.includes("anniversary"))
    || values.some((value) => value.includes("tech1") && value.includes("anniversary"));
}

function isTeamTandemMode(eventMeta = activeEventMeta) {
  return getEventCompetitionMode(eventMeta) === COMPETITION_MODE_TEAM_TANDEM;
}

function isTwinDoubleMode(eventMeta = activeEventMeta) {
  return getEventCompetitionMode(eventMeta) === COMPETITION_MODE_TWIN_DOUBLE;
}

function isTwinTripleMode(eventMeta = activeEventMeta) {
  return getEventCompetitionMode(eventMeta) === COMPETITION_MODE_TWIN_TRIPLE || isTwinDoubleMode(eventMeta);
}

function isTech1AnniversaryMode(eventMeta = activeEventMeta) {
  return getEventCompetitionMode(eventMeta) === COMPETITION_MODE_TECH1_ANNIVERSARY
    || eventLooksLikeTech1Anniversary(eventMeta);
}

function shouldUseTech1Branding(eventMeta = activeEventMeta, viewName = getActiveViewName()) {
  if (isTech1AnniversaryMode(eventMeta)) return true;
  const tech1Panel = document.getElementById("tech1EventControlPanel");
  return Boolean(tech1Panel && !tech1Panel.classList.contains("hidden") && tech1Panel.textContent?.includes("Tech 1"));
}

function getTech1NoQualifyingFallbackView(role = currentRole) {
  if (role === "admin") return "registration";
  if (role === "spectator") return "home";
  return "bracket";
}

function getTwinCompEliminationLimit(eventMeta = activeEventMeta) {
  return isTwinDoubleMode(eventMeta) ? 2 : 3;
}

function getTwinCompEliminationLabel(eventMeta = activeEventMeta) {
  return isTwinDoubleMode(eventMeta) ? "Double Elimination" : "Triple Elimination";
}

function getTwinCompEliminationAdjective(eventMeta = activeEventMeta) {
  return isTwinDoubleMode(eventMeta) ? "double-elimination" : "triple-elimination";
}

function getTwinCompRoundPointCount(source = null) {
  const teamCount = Number.isFinite(Number(source))
    ? Number(source)
    : Array.isArray(source?.teamIds)
      ? source.teamIds.length
      : getTwinCompActiveTeams().length;
  if (teamCount <= 1) return 0;
  return Math.max(1, Math.min(teamCount - 1, Math.floor(teamCount / 2)));
}

function getTwinCompRoundPointLabel(source = null) {
  const pointCount = getTwinCompRoundPointCount(source);
  return pointCount ? `bottom half (${pointCount} team${pointCount === 1 ? "" : "s"})` : "bottom half";
}

function getTwinCompModeTitle(eventMeta = activeEventMeta) {
  return `Twin Comp ${getTwinCompEliminationLabel(eventMeta)}`;
}

function isTeamCompetitionMode(eventMeta = activeEventMeta) {
  return isTeamTandemMode(eventMeta) || isTwinTripleMode(eventMeta);
}

function getTeamTandemEntryId(entry) {
  const normalizedTeamName = normalizeDriverName(entry?.teamName || "");
  if (normalizedTeamName) return normalizedTeamName;
  const explicitId = String(entry?.teamRegistrationId || "").trim();
  if (explicitId) return explicitId;
  return String(entry?.id || generateId());
}

function getTeamTandemRosterEntries(drivers = appDrivers) {
  const registeredDrivers = getRegisteredDrivers(drivers);
  const groups = new Map();
  registeredDrivers.forEach((driver, index) => {
    const groupId = getTeamTandemEntryId(driver);
    if (!groupId) return;
    if (!groups.has(groupId)) {
      groups.set(groupId, {
        id: groupId,
        teamName: "",
        members: [],
        signUpPosition: Number.isFinite(Number(driver?.signUpPosition)) ? Number(driver.signUpPosition) : (index + 1),
      });
    }
    const group = groups.get(groupId);
    const nextPosition = Number.isFinite(Number(driver?.signUpPosition)) ? Number(driver.signUpPosition) : (index + 1);
    group.signUpPosition = Math.min(group.signUpPosition, nextPosition);
    if ((driver?.teamName || "").trim()) {
      group.teamName = (driver.teamName || "").trim();
    }
    group.members.push(driver);
  });

  return [...groups.values()]
    .map((group, index) => {
      const members = [...group.members].sort((left, right) => {
        const leftOrder = Number(left?.teamMemberOrder || left?.signUpPosition || 0);
        const rightOrder = Number(right?.teamMemberOrder || right?.signUpPosition || 0);
        if (leftOrder !== rightOrder) return leftOrder - rightOrder;
        return String(left?.name || "").localeCompare(String(right?.name || ""), undefined, { sensitivity: "base" });
      });
      const memberNames = members.map((member) => String(member?.name || "").trim()).filter(Boolean);
      const teamName = String(group.teamName || "").trim() || memberNames.join(" / ") || `Team ${index + 1}`;
      const memberCount = members.length;
      return {
        id: group.id,
        teamName,
        members,
        memberNames,
        memberCount,
        signUpPosition: group.signUpPosition,
        bonusPoints: memberCount >= TEAM_TANDEM_MAX_DRIVERS ? TEAM_TANDEM_THREE_DRIVER_BONUS : 0,
      };
    })
    .sort((left, right) => left.signUpPosition - right.signUpPosition);
}

function shuffleEntries(entries) {
  const nextEntries = [...(Array.isArray(entries) ? entries : [])];
  for (let index = nextEntries.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [nextEntries[index], nextEntries[swapIndex]] = [nextEntries[swapIndex], nextEntries[index]];
  }
  return nextEntries;
}

function shuffleEntriesForVisibleOrder(entries) {
  const originalEntries = Array.isArray(entries) ? entries : [];
  const shuffledEntries = shuffleEntries(originalEntries);
  if (shuffledEntries.length < 2) return shuffledEntries;
  const unchanged = shuffledEntries.every((entry, index) => entry?.id === originalEntries[index]?.id);
  if (!unchanged) return shuffledEntries;
  return [...shuffledEntries.slice(1), shuffledEntries[0]];
}

function buildTeamTandemParticipant(entry, seed) {
  const memberNames = Array.isArray(entry?.memberNames) ? entry.memberNames.filter(Boolean) : [];
  const memberCount = Number(entry?.memberCount || memberNames.length || 0);
  const bonusPoints = Number(entry?.bonusPoints || (memberCount >= TEAM_TANDEM_MAX_DRIVERS ? TEAM_TANDEM_THREE_DRIVER_BONUS : 0));
  return {
    id: entry?.id || generateId(),
    seed,
    name: String(entry?.teamName || "").trim() || `Team ${seed}`,
    teamName: memberNames.join(", "),
    chassis: memberCount ? `${memberCount} driver${memberCount === 1 ? "" : "s"}` : "",
    registrationNumber: seed,
    signUpPosition: Number(entry?.signUpPosition || seed),
    run1: null,
    run2: null,
    bestScore: null,
    memberCount,
    tandemMembers: memberNames,
    tandemBonusPoints: bonusPoints,
    tandemType: "team",
  };
}

function buildTeamTandemOrderedParticipants(drivers = appDrivers) {
  return getTeamTandemRosterEntries(drivers).map((entry, index) => buildTeamTandemParticipant(entry, index + 1));
}

function buildTeamTandemBracketParticipants(drivers = appDrivers) {
  return shuffleEntries(getTeamTandemRosterEntries(drivers)).map((entry, index) => buildTeamTandemParticipant(entry, index + 1));
}

function isTeamTandemParticipant(entry) {
  return Boolean(entry?.tandemType === "team" || (Array.isArray(entry?.tandemMembers) && entry.tandemMembers.length));
}

function getTeamTandemBonusPoints(entry) {
  const explicit = Number(entry?.tandemBonusPoints);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const memberCount = Number(entry?.memberCount || entry?.teamMemberCount || entry?.tandemMembers?.length || 0);
  return memberCount >= TEAM_TANDEM_MAX_DRIVERS ? TEAM_TANDEM_THREE_DRIVER_BONUS : 0;
}

function getTeamTandemMemberSummary(entry) {
  const members = Array.isArray(entry?.tandemMembers) ? entry.tandemMembers.filter(Boolean) : [];
  if (members.length) return members.join(", ");
  return String(entry?.teamName || "").trim();
}

function getTeamTandemMetaLine(entry) {
  if (!isTeamTandemParticipant(entry)) return "";
  const memberCount = Number(entry?.memberCount || entry?.teamMemberCount || entry?.tandemMembers?.length || 0);
  const bonusPoints = getTeamTandemBonusPoints(entry);
  const parts = [];
  if (memberCount) {
    parts.push(`${memberCount} driver${memberCount === 1 ? "" : "s"}`);
  }
  if (bonusPoints) {
    parts.push(`+${bonusPoints} team bonus`);
  }
  return parts.join(" | ");
}

function getTeamTandemCompetitionPlan(teamCount) {
  const qualifiedCount = Math.max(0, Number(teamCount || 0));
  if (qualifiedCount < 2) {
    return {
      qualifiedCount,
      preferredFormat: FORMAT_CLASSIC,
      resolvedFormat: FORMAT_CLASSIC,
      mainBracketSize: 0,
      usesLowerBracket: false,
      lowerBracketSize: 0,
      lowerBracketCount: 0,
      directMainCount: 0,
      validLowerCounts: [],
      validMainBracketSizes: [],
      description: "Need at least 2 registered teams before the randomized Team Tandem bracket can launch.",
    };
  }
  const mainBracketSize = nextPowerOfTwo(qualifiedCount);
  const byes = mainBracketSize - qualifiedCount;
  return {
    qualifiedCount,
    preferredFormat: FORMAT_CLASSIC,
    resolvedFormat: FORMAT_CLASSIC,
    mainBracketSize,
    usesLowerBracket: false,
    lowerBracketSize: 0,
    lowerBracketCount: 0,
    directMainCount: qualifiedCount,
    validLowerCounts: [],
    validMainBracketSizes: [],
    description: byes > 0
      ? `Randomized Team Tandem Top ${mainBracketSize} (${byes} bye${byes === 1 ? "" : "s"}). Teams with 3 drivers receive +${TEAM_TANDEM_THREE_DRIVER_BONUS} automatically.`
      : `Randomized Team Tandem Top ${mainBracketSize}. Teams with 3 drivers receive +${TEAM_TANDEM_THREE_DRIVER_BONUS} automatically.`,
  };
}

function createEmptyRegistrationDraft() {
  return {
    name: "",
    driverNumber: "",
    teamName: "",
    chassis: "",
    teammate2Name: "",
    teammate2Number: "",
    teammate2Chassis: "",
    teammate3Name: "",
    teammate3Number: "",
    teammate3Chassis: "",
  };
}

function normalizeRegistrationDraftState(draft) {
  const normalized = {
    ...createEmptyRegistrationDraft(),
    ...(draft && typeof draft === "object" ? draft : {}),
  };
  return {
    name: typeof normalized.name === "string" ? normalized.name : "",
    driverNumber: normalized.driverNumber == null ? "" : String(normalized.driverNumber),
    teamName: typeof normalized.teamName === "string" ? normalized.teamName : "",
    chassis: typeof normalized.chassis === "string" ? normalized.chassis : "",
    teammate2Name: typeof normalized.teammate2Name === "string" ? normalized.teammate2Name : "",
    teammate2Number: normalized.teammate2Number == null ? "" : String(normalized.teammate2Number),
    teammate2Chassis: typeof normalized.teammate2Chassis === "string" ? normalized.teammate2Chassis : "",
    teammate3Name: typeof normalized.teammate3Name === "string" ? normalized.teammate3Name : "",
    teammate3Number: normalized.teammate3Number == null ? "" : String(normalized.teammate3Number),
    teammate3Chassis: typeof normalized.teammate3Chassis === "string" ? normalized.teammate3Chassis : "",
  };
}

function getDraftDriverMembers(draft) {
  const normalized = normalizeRegistrationDraftState(draft);
  return [
    { order: 1, name: normalized.name.trim(), driverNumber: normalized.driverNumber.trim(), chassis: normalized.chassis.trim() },
    { order: 2, name: normalized.teammate2Name.trim(), driverNumber: normalized.teammate2Number.trim(), chassis: normalized.teammate2Chassis.trim() },
    { order: 3, name: normalized.teammate3Name.trim(), driverNumber: normalized.teammate3Number.trim(), chassis: normalized.teammate3Chassis.trim() },
  ];
}

function getNamedDraftDriverMembers(draft) {
  return getDraftDriverMembers(draft).filter((member) => Boolean(member.name));
}

function getEventJudgingMode(eventMeta = activeEventMeta) {
  return normalizeJudgingMode(eventMeta?.judgingMode);
}

function getEventJudgeCount(eventMeta = activeEventMeta) {
  return normalizeJudgeCountForMode(eventMeta?.judgeCount, eventMeta?.judgingMode);
}

function getActiveJudgeRoles(eventMeta = activeEventMeta) {
  return JUDGE_ROLE_ORDER.slice(0, getEventJudgeCount(eventMeta));
}

function usesCategoryJudging(eventMeta = activeEventMeta) {
  return getEventJudgingMode(eventMeta) === JUDGING_MODE_LINE_ANGLE_STYLE;
}

function getJudgeCategoryConfig(role = currentRole, eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) {
    if (role === "j1") {
      return { label: "Line", shortLabel: "Line", maxScore: 10 };
    }
    if (role === "j2") {
      return { label: "Angle", shortLabel: "Angle", maxScore: 10 };
    }
    return { label: "Proximity", shortLabel: "Prox", maxScore: 10 };
  }

  if (!usesCategoryJudging(eventMeta)) {
    return {
      label: "Score",
      shortLabel: "Score",
      maxScore: 100,
    };
  }

  if (role === "j1") {
    return { label: "Line", shortLabel: "Line", maxScore: 40 };
  }
  if (role === "j2") {
    return { label: "Angle", shortLabel: "Angle", maxScore: 40 };
  }
  return { label: "Style", shortLabel: "Style", maxScore: 20 };
}

function getJudgeScoreMax(role = currentRole, eventMeta = activeEventMeta) {
  return getJudgeCategoryConfig(role, eventMeta).maxScore;
}

function getJudgeDefaultRunScore(role = currentRole, eventMeta = activeEventMeta) {
  return getJudgeScoreMax(role, eventMeta);
}

function getJudgeScorePlaceholder(role = currentRole, eventMeta = activeEventMeta) {
  return formatScore(getJudgeDefaultRunScore(role, eventMeta));
}

function getJudgeRunTitle(runNumber, role = currentRole, eventMeta = activeEventMeta) {
  if (isTwinTripleMode(eventMeta)) {
    return "Scored Run";
  }
  if (usesCategoryJudging(eventMeta) && role?.startsWith("j")) {
    return `Run ${runNumber} ${getJudgeCategoryConfig(role, eventMeta).label}`;
  }
  return `Run ${runNumber} Score`;
}

function getQualifyingRunAggregateLabel(runNumber, eventMeta = activeEventMeta, options = {}) {
  const live = Boolean(options.live);
  if (isTwinTripleMode(eventMeta)) {
    return `Scored Run${live ? " Live" : ""}`;
  }
  if (usesCategoryJudging(eventMeta)) {
    return `Run ${runNumber}${live ? " Live" : ""} Total`;
  }
  if (getEventJudgeCount(eventMeta) === 1) {
    return `Run ${runNumber}${live ? " Live" : ""} Score`;
  }
  return `Run ${runNumber}${live ? " Live" : ""} Avg`;
}

function getBestRunColumnLabel(eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) return "Best (Team)";
  if (usesCategoryJudging(eventMeta)) return "Best (Total)";
  return getEventJudgeCount(eventMeta) === 1 ? "Best (Score)" : "Best (Avg)";
}

function getQualifyingBoardCopy(eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) {
    return `Team Tandem skips qualifying. Register 2-3 driver teams, then launch a randomized bracket directly from registration. Teams with 3 drivers receive +${TEAM_TANDEM_THREE_DRIVER_BONUS} automatically.`;
  }
  if (isTwinTripleMode(eventMeta)) {
    return `Twin Comp uses the qualifying scoring controls for each team run. Every active team runs each round; finalize the round to give one elimination point to the bottom half of scores. Teams are eliminated at ${getTwinCompEliminationLimit(eventMeta)} points.`;
  }
  const judgeCount = getEventJudgeCount(eventMeta);
  if (usesCategoryJudging(eventMeta)) {
    return "Manage the driver list, monitor the combined Line, Angle, and Style totals, and launch the competition bracket when qualifying is complete.";
  }
  return `Manage the driver list, monitor the ${judgeCount === 1 ? "live score" : "averaged scores"} from ${judgeCount} judge${judgeCount === 1 ? "" : "s"}, and launch the competition bracket when qualifying is complete.`;
}

function getJudgeBoardCopy(role = currentRole, eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) {
    const category = getJudgeCategoryConfig(role, eventMeta);
    return `Judge the current Team Tandem battle on ${category.label.toLowerCase()}. Score each team out of ${formatScore(category.maxScore)} after the scored lap, and 3-driver teams receive +${TEAM_TANDEM_THREE_DRIVER_BONUS} automatically.`;
  }
  if (isTwinTripleMode(eventMeta)) {
    return `Score the current Twin Comp team with the qualifying controls. The event admin locks the round results and applies ${getTwinCompEliminationAdjective(eventMeta)} points after every active team has run.`;
  }
  if (usesCategoryJudging(eventMeta)) {
    const category = getJudgeCategoryConfig(role, eventMeta);
    return `Enter your ${category.label.toLowerCase()} score for each driver. ${category.label} contributes up to ${formatScore(category.maxScore)} points per run, and all judge categories are added together to form the driver's final run score.`;
  }
  const judgeCount = getEventJudgeCount(eventMeta);
  return judgeCount === 1
    ? "Enter the official run score for each driver. That score becomes the driver's final run score immediately."
    : `Enter your personal scores for each driver. Your score will be averaged dynamically with the other ${judgeCount - 1} judge${judgeCount === 2 ? "" : "s"} to form the driver's final run score.`;
}

function isBracketReadyToFinalize(state = tournamentState) {
  if (!state?.mainBracket?.rounds?.length) return false;
  const battleStats = getTournamentBattleStats(state);
  if (!battleStats.totalBattles) return false;
  return battleStats.completedBattles >= battleStats.totalBattles;
}

function getEventStatus(eventMeta = activeEventMeta, resultsOverride = null) {
  if (!eventMeta) return EVENT_STATUS_ACTIVE;
  const status = String(eventMeta.status || "").trim().toLowerCase();
  if (status === EVENT_STATUS_ARCHIVED) return EVENT_STATUS_ARCHIVED;
  if (status === EVENT_STATUS_COMPLETED) return EVENT_STATUS_COMPLETED;
  const results = resultsOverride ?? eventMeta.results ?? {};
  if (results.completedAt) return EVENT_STATUS_COMPLETED;
  return EVENT_STATUS_ACTIVE;
}

function isEventCompleted(eventMeta = activeEventMeta) {
  return getEventStatus(eventMeta) === EVENT_STATUS_COMPLETED;
}

function isJudgeAccessLocked(eventMeta = activeEventMeta) {
  const status = getEventStatus(eventMeta);
  return status === EVENT_STATUS_ARCHIVED || status === EVENT_STATUS_COMPLETED;
}

function isArchivedOrCompleted(eventMeta = activeEventMeta) {
  const status = getEventStatus(eventMeta);
  return status === EVENT_STATUS_ARCHIVED || status === EVENT_STATUS_COMPLETED;
}

function isRoleAvailableForEvent(role, eventMeta = activeEventMeta) {
  if (role === "spectator" || role === "admin") return true;
  if (role?.startsWith("j") && isJudgeAccessLocked(eventMeta)) return false;
  return getActiveJudgeRoles(eventMeta).includes(role);
}

function getJudgeSystemLabel(eventMeta = activeEventMeta) {
  const judgeCount = getEventJudgeCount(eventMeta);
  if (isTeamTandemMode(eventMeta)) return "3-Judge Team Tandem | Line / Angle / Proximity";
  if (usesCategoryJudging(eventMeta)) return "3-Judge Line / Angle / Style";
  return judgeCount === 1 ? "1-Judge Scoring" : `${judgeCount}-Judge Cloud Sync`;
}

function getAverageColumnLabel(runNumber, role = currentRole, eventMeta = activeEventMeta) {
  if (role.startsWith("j")) {
    if (usesCategoryJudging(eventMeta)) {
      return `Run ${runNumber} (${getJudgeCategoryConfig(role, eventMeta).shortLabel})`;
    }
    return `Run ${runNumber} (Your Score)`;
  }
  if (isTeamTandemMode(eventMeta)) return `Run ${runNumber} (Team)`;
  if (usesCategoryJudging(eventMeta)) return `Run ${runNumber} (Total)`;
  return getEventJudgeCount(eventMeta) === 1 ? `Run ${runNumber} (Score)` : `Run ${runNumber} (Avg)`;
}

function generateId() { return Math.random().toString(36).substring(2, 11); }

function createDriverSet(count = 1) {
  return Array.from({ length: count }, (_, index) => createEmptyDriver(index + 1));
}

function slugifyEventId(name) {
  return (name || "event")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40) || "event";
}

function makeUniqueEventId(name) {
  const base = slugifyEventId(name);
  let candidate = base;
  let index = 2;
  while (eventDirectory[candidate] || isDeletedEventId(candidate)) {
    candidate = `${base}-${index}`;
    index += 1;
  }
  return candidate;
}

function generateInviteCode() {
  const alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
  const segment = () => Array.from({ length: 3 }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join("");
  return `${segment()}-${segment()}`;
}

function createDefaultVenueConfig(overrides = {}) {
  return {
    enabled: false,
    qrCheckInEnabled: true,
    qrApprovalMode: true,
    qrToken: "",
    qrTokenIssuedAt: null,
    qrTokenExpiresAt: null,
    label: "",
    latitude: null,
    longitude: null,
    radiusMeters: 150,
    closeAt: null,
    ...overrides,
  };
}

function createEmptyJudgeRoleClaims() {
  return {
    j1: null,
    j2: null,
    j3: null,
  };
}

function normalizeJudgeRoleClaimEntry(entry) {
  if (!entry || typeof entry !== "object") return null;
  const deviceId = typeof entry.deviceId === "string" ? entry.deviceId.trim() : "";
  if (!deviceId) return null;
  return {
    deviceId,
    claimedAt: typeof entry.claimedAt === "string" ? entry.claimedAt : null,
    lastSeenAt: typeof entry.lastSeenAt === "string" ? entry.lastSeenAt : (typeof entry.claimedAt === "string" ? entry.claimedAt : null),
  };
}

function normalizeJudgeRoleClaims(claims) {
  const base = createEmptyJudgeRoleClaims();
  JUDGE_ROLE_ORDER.forEach((role) => {
    base[role] = normalizeJudgeRoleClaimEntry(claims?.[role]);
  });
  return base;
}

function parseClaimTimestamp(value) {
  const parsed = value ? Date.parse(value) : Number.NaN;
  return Number.isFinite(parsed) ? parsed : 0;
}

function isJudgeRoleClaimActive(claim, now = Date.now()) {
  if (!claim?.deviceId) return false;
  const lastSeenAt = parseClaimTimestamp(claim.lastSeenAt || claim.claimedAt);
  if (!lastSeenAt) return false;
  return now - lastSeenAt <= JUDGE_ROLE_CLAIM_TTL_MS;
}

function getSanitizedJudgeRoleClaims(eventMeta = activeEventMeta, now = Date.now()) {
  const claims = normalizeJudgeRoleClaims(eventMeta?.judgeRoleClaims);
  JUDGE_ROLE_ORDER.forEach((role) => {
    if (!isJudgeRoleClaimActive(claims[role], now)) {
      claims[role] = null;
    }
  });
  return claims;
}

