async function restoreRound3FromPdf() {
  if (!isWebsiteAdmin) {
    window.alert("Unlock website admin access before using the PDF recovery tool.");
    return;
  }
  if (!activeEventMeta || !activeEventId) {
    window.alert("Open the Round 3 event first.");
    return;
  }
  if (!isRound3PdfRecoveryEvent(activeEventMeta)) {
    window.alert(`This recovery tool is only enabled for ${PDF_RECOVERY_EVENT_NAME}.`);
    return;
  }
  const confirmed = window.confirm("Restore SDC Round 3 from the exported PDF? This will replace the current roster, qualifying scores, and saved podium summary for the selected event.");
  if (!confirmed) return;

  const restoredDrivers = buildRecoveredRound3Drivers();
  const restoredFormatMode = FORMAT_SDC_TOP_16;
  const restoredLowerCount = "16";
  const restoredBracket = createTournamentState(rankDrivers(restoredDrivers), restoredFormatMode, Number(restoredLowerCount));
  const restoredFlow = {
    currentDriverId: null,
    readyRoles: {},
    started: true,
    completed: true,
  };
  const restoredResults = buildRecoveredRound3Results();
  const updatedAt = new Date().toISOString();

  setActiveDriversState(restoredDrivers);
  setActiveEventFormatState(restoredFormatMode);
  setActiveEventLowerCountState(restoredLowerCount);
  setTournamentStateState(restoredBracket);
  setQualifyingFlowState(restoredFlow);
  setActiveEventMetaState({
    ...activeEventMeta,
    status: EVENT_STATUS_COMPLETED,
    updatedAt,
    results: {
      ...restoredResults,
      updatedAt,
    },
  });
  setDeletedEventId(activeEventId, false);
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  const archivedRecord = buildArchivedResultsRecord(activeEventMeta, activeEventMeta.results);
  if (archivedRecord) {
    archivedResultsDirectory[activeEventId] = archivedRecord;
  }
  saveDirectoryCache();
  saveEventStateCache();
  saveArchivedResultsCache();

  if (db) {
    lastLocalPush = Date.now();
    activeEventMeta.syncStamp = lastLocalPush;
    eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
    saveDirectoryCache();

    const publishMeta = cloneEventMeta(activeEventMeta);
    const publishDrivers = JSON.parse(JSON.stringify(appDrivers));
    const publishBracket = JSON.parse(JSON.stringify(tournamentState));
    const publishQualifyingFlow = JSON.parse(JSON.stringify(qualifyingFlow));
    const directoryPayload = buildDirectorySyncPayload({
      [activeEventId]: publishMeta,
    });

    try {
      await Promise.all([
        setDoc(getEventDocRef(activeEventId), {
          ...publishMeta,
          drivers: publishDrivers,
          bracket: publishBracket,
          qualifyingFlow: publishQualifyingFlow,
          formatMode: restoredFormatMode,
          lowerCount: restoredLowerCount,
          syncStamp: lastLocalPush,
        }),
        setDoc(getDirectoryDocRef(), directoryPayload),
        setDoc(getActiveEventSelectionDocRef(), {
          activeEventId,
          eventMeta: cloneEventMeta(directoryPayload.events[activeEventId] || publishMeta),
          syncStamp: lastLocalPush,
        }, { merge: true }),
        setDoc(getArchivedResultsDocRef(), {
          events: getArchivedResultsSnapshot(),
          syncStamp: lastLocalPush,
        }),
      ]);
    } catch (error) {
      console.error("Round 3 PDF restore failed:", error);
      window.alert("The PDF restore could not finish saving to cloud sync. Stay on this event and let me patch the recovery one more time.");
      return;
    }
  }

  renderDriversTable();
  renderBracket();
  renderEventDirectory();
  renderRoleAdminPanel();
  updateEventChrome();
  window.alert("SDC Round 3 was restored from the PDF, including both qualifying runs for every driver.");
}

