function getDriverRegistrationNumber(driver, fallback = null) {
  const candidates = [
    driver?.registrationNumber,
    driver?.registration_number,
    driver?.registrationOrder,
    driver?.registration_order,
    driver?.entryNumber,
    driver?.entry_number,
    driver?.checkInNumber,
    driver?.check_in_number,
    driver?.reg,
    driver?.signUpPosition,
  ];
  for (const candidate of candidates) {
    const parsed = toRegistrationNumber(candidate);
    if (parsed) return parsed;
  }
  return toRegistrationNumber(fallback);
}

function formatDriverRegistrationNumber(driver, fallback = "-") {
  const registrationNumber = getDriverRegistrationNumber(driver);
  return registrationNumber ? String(registrationNumber) : fallback;
}

function normalizeDriverState(driver, index) {
  const normalized = {
    ...createEmptyDriver(),
    ...driver,
  };
  const fallbackRegistrationNumber = Number.isInteger(index + 1) && index >= 0 ? index + 1 : null;
  const storedRegistrationNumber = getDriverRegistrationNumber(normalized, fallbackRegistrationNumber);
  normalized.signUpPosition = Number.isInteger(normalized.signUpPosition) && normalized.signUpPosition > 0
    ? normalized.signUpPosition
    : storedRegistrationNumber;
  normalized.runFlags = {
    run1: normalized.runFlags?.run1 || null,
    run2: normalized.runFlags?.run2 || null,
    runoff: normalized.runFlags?.runoff || null,
  };
  normalized.scores = {
    j1: {
      run1: null, run2: null, runoff: null, ...(normalized.scores?.j1 || {}),
      submitted: { run1: null, run2: null, runoff: null, ...(normalized.scores?.j1?.submitted || {}) },
      deductionHistory: { run1: [], run2: [], runoff: [], ...(normalized.scores?.j1?.deductionHistory || {}) },
    },
    j2: {
      run1: null, run2: null, runoff: null, ...(normalized.scores?.j2 || {}),
      submitted: { run1: null, run2: null, runoff: null, ...(normalized.scores?.j2?.submitted || {}) },
      deductionHistory: { run1: [], run2: [], runoff: [], ...(normalized.scores?.j2?.deductionHistory || {}) },
    },
    j3: {
      run1: null, run2: null, runoff: null, ...(normalized.scores?.j3 || {}),
      submitted: { run1: null, run2: null, runoff: null, ...(normalized.scores?.j3?.submitted || {}) },
      deductionHistory: { run1: [], run2: [], runoff: [], ...(normalized.scores?.j3?.deductionHistory || {}) },
    },
  };
  for (const role of JUDGE_ROLE_ORDER) {
    const judgeScores = normalized.scores[role];
    if (!judgeScores.submitted) {
      judgeScores.submitted = { run1: judgeScores.run1, run2: judgeScores.run2, runoff: judgeScores.runoff };
    }
  }
  normalized.teamName = typeof normalized.teamName === "string" ? normalized.teamName : "";
  normalized.driverNumber = normalized.driverNumber == null ? "" : String(normalized.driverNumber);
  normalized.chassis = typeof normalized.chassis === "string" ? normalized.chassis : "";
  normalized.teamRegistrationId = typeof normalized.teamRegistrationId === "string" ? normalized.teamRegistrationId : "";
  normalized.teamMemberOrder = Number.isInteger(Number(normalized.teamMemberOrder)) ? Number(normalized.teamMemberOrder) : 0;
  normalized.teamMemberCount = Number.isInteger(Number(normalized.teamMemberCount)) ? Number(normalized.teamMemberCount) : 0;
  normalized.registrationNumber = storedRegistrationNumber;
  normalized.reg = storedRegistrationNumber;
  return normalized;
}

function normalizeDriverList(drivers) {
  return (Array.isArray(drivers) ? drivers : []).map((driver, index) => normalizeDriverState(driver, index));
}

function resequenceDrivers(drivers, forceRegistrationNumbers = false) {
  return normalizeDriverList(drivers).map((driver, index) => {
    const nextPosition = index + 1;
    if (!forceRegistrationNumbers) {
      const storedRegistrationNumber = getDriverRegistrationNumber(driver, nextPosition);
      return {
        ...driver,
        registrationNumber: storedRegistrationNumber,
        reg: storedRegistrationNumber,
        signUpPosition: driver.signUpPosition || storedRegistrationNumber,
      };
    }
    return {
      ...driver,
      registrationNumber: nextPosition,
      signUpPosition: nextPosition,
      reg: nextPosition,
    };
  });
}

function driverHasScoreActivity(driver) {
  const scoreValues = Object.values(driver?.scores || {}).flatMap((judgeScores) => Object.values(judgeScores || {}));
  const hasScore = scoreValues.some((value) => value !== null && value !== undefined && value !== "");
  const hasFlag = Object.values(driver?.runFlags || {}).some((value) => Boolean(value));
  return hasScore || hasFlag;
}

function driverHasMeaningfulEntry(driver) {
  const hasName = typeof driver?.name === "string" && driver.name.trim() !== "";
  const hasTeamName = typeof driver?.teamName === "string" && driver.teamName.trim() !== "";
  const hasChassis = typeof driver?.chassis === "string" && driver.chassis.trim() !== "";
  return hasName || hasTeamName || hasChassis || driverHasScoreActivity(driver);
}

function sanitizeLoadedDrivers(drivers) {
  const normalized = resequenceDrivers(Array.isArray(drivers) ? drivers : [], false);
  if (!normalized.length) return createDriverSet();
  if (normalized.some((driver) => driverHasMeaningfulEntry(driver))) {
    return normalized;
  }
  return createDriverSet();
}

function getNextSignUpPosition(drivers) {
  return normalizeDriverList(drivers).reduce((maxValue, driver) => Math.max(maxValue, driver.signUpPosition || 0), 0) + 1;
}

function getVenueConfig(eventMeta = activeEventMeta) {
  return createDefaultVenueConfig(eventMeta?.venueConfig || {});
}

function getVenueProfiles(eventMeta = activeEventMeta) {
  return normalizeVenueProfileList(eventMeta?.venueProfiles);
}

function getVenueProfileById(profileId, eventMeta = activeEventMeta) {
  if (!profileId) return null;
  return getVenueProfiles(eventMeta).find((entry) => entry.id === profileId) || null;
}

function hasValidVenueConfig(eventMeta = activeEventMeta) {
  const venueConfig = getVenueConfig(eventMeta);
  return Boolean(
    venueConfig.enabled
    && Number.isFinite(Number(venueConfig.latitude))
    && Number.isFinite(Number(venueConfig.longitude))
    && Number.isFinite(Number(venueConfig.radiusMeters))
    && Number(venueConfig.radiusMeters) > 0
  );
}

function toRadians(value) {
  return (value * Math.PI) / 180;
}

function calculateDistanceMeters(fromLat, fromLng, toLat, toLng) {
  const earthRadius = 6371000;
  const deltaLat = toRadians(toLat - fromLat);
  const deltaLng = toRadians(toLng - fromLng);
  const sinLat = Math.sin(deltaLat / 2);
  const sinLng = Math.sin(deltaLng / 2);
  const a = (sinLat * sinLat)
    + Math.cos(toRadians(fromLat)) * Math.cos(toRadians(toLat)) * (sinLng * sinLng);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return earthRadius * c;
}

function isValidCoordinatePair(latitude, longitude) {
  return Number.isFinite(latitude)
    && Number.isFinite(longitude)
    && Math.abs(latitude) <= 90
    && Math.abs(longitude) <= 180;
}

function parseVenueLocationInput(rawValue) {
  const text = String(rawValue || "").trim();
  if (!text) return null;
  let decodedText = text;
  try {
    decodedText = decodeURIComponent(text);
  } catch (error) {
    decodedText = text;
  }

  const patterns = [
    /@(?<lat>-?\d{1,2}(?:\.\d+)?),(?<lng>-?\d{1,3}(?:\.\d+)?)/i,
    /!3d(?<lat>-?\d{1,2}(?:\.\d+)?)!4d(?<lng>-?\d{1,3}(?:\.\d+)?)/i,
    /[?&](?:ll|sll|q|query|destination|daddr|near)=\s*(?<lat>-?\d{1,2}(?:\.\d+)?)\s*,\s*(?<lng>-?\d{1,3}(?:\.\d+)?)/i,
    /(?<lat>-?\d{1,2}(?:\.\d+)?)\s*,\s*(?<lng>-?\d{1,3}(?:\.\d+)?)/,
    /(?<lat>-?\d{1,2}(?:\.\d+)?)\s+(?<lng>-?\d{1,3}(?:\.\d+)?)/,
  ];

  for (const pattern of patterns) {
    const match = decodedText.match(pattern);
    if (!match?.groups) continue;
    const latitude = Number.parseFloat(match.groups.lat);
    const longitude = Number.parseFloat(match.groups.lng);
    if (isValidCoordinatePair(latitude, longitude)) {
      return { latitude, longitude };
    }
  }

  const numberMatches = Array.from(decodedText.matchAll(/-?\d+(?:\.\d+)?/g)).map((entry) => Number.parseFloat(entry[0]));
  for (let index = 0; index < numberMatches.length - 1; index += 1) {
    const latitude = numberMatches[index];
    const longitude = numberMatches[index + 1];
    if (isValidCoordinatePair(latitude, longitude)) {
      return { latitude, longitude };
    }
  }

  return null;
}

function updateSelfRegistrationState(status, copy, unlocked, lastDistanceMeters = null) {
  selfRegistrationState = {
    status,
    copy,
    unlocked,
    lastDistanceMeters,
  };
}

function toNumber(value) {
  if (value === "" || value === null || value === undefined) return null;
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function toRegistrationNumber(value) {
  if (value === "" || value === null || value === undefined) return null;
  const parsed = Number.parseInt(value, 10);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
}

function getRunKey(runRef) {
  return normalizeRunKey(runRef);
}

const QUICK_DEDUCTION_VALUES = [1, 2, 5, 10, 20];

function clampJudgeScoreValue(value, role = currentRole, eventMeta = activeEventMeta) {
  const maxScore = getJudgeScoreMax(role, eventMeta);
  const numericValue = Number.isFinite(value) ? value : maxScore;
  return Math.max(0, Math.min(maxScore, Math.round(numericValue * 10) / 10));
}

function getJudgeDraftScoreValue(driver, role, runRef, eventMeta = activeEventMeta) {
  const runKey = getRunKey(runRef);
  const judgeScores = driver?.scores?.[role];
  if (!judgeScores) return getJudgeDefaultRunScore(role, eventMeta);
  if (judgeScores[runKey] !== null && judgeScores[runKey] !== undefined) {
    return clampJudgeScoreValue(judgeScores[runKey], role, eventMeta);
  }
  if (judgeScores.submitted?.[runKey] !== null && judgeScores.submitted?.[runKey] !== undefined) {
    return clampJudgeScoreValue(judgeScores.submitted[runKey], role, eventMeta);
  }
  return getJudgeDefaultRunScore(role, eventMeta);
}

function getJudgeDeductionHistory(driver, role, runRef) {
  const runKey = getRunKey(runRef);
  return Array.isArray(driver?.scores?.[role]?.deductionHistory?.[runKey])
    ? driver.scores[role].deductionHistory[runKey]
    : [];
}

function setJudgeDeductionHistory(driver, role, runRef, nextHistory) {
  const runKey = getRunKey(runRef);
  if (!driver?.scores?.[role]) return;
  if (!driver.scores[role].deductionHistory) {
    driver.scores[role].deductionHistory = { run1: [], run2: [], runoff: [] };
  }
  driver.scores[role].deductionHistory[runKey] = Array.isArray(nextHistory) ? nextHistory : [];
}

function clearJudgeDeductionHistory(driver, role, runRef) {
  setJudgeDeductionHistory(driver, role, runRef, []);
}

function appendJudgeDeductionHistory(driver, role, runRef, label) {
  const history = getJudgeDeductionHistory(driver, role, runRef);
  setJudgeDeductionHistory(driver, role, runRef, [...history, label].slice(-10));
}

function renderDeductionHistory(driver, role, runRef) {
  const history = getJudgeDeductionHistory(driver, role, runRef);
  const runKey = getRunKey(runRef);
  const flag = driver?.runFlags?.[runKey];
  const historyText = history.length ? history.join("  ") : "No deductions yet.";
  return `<div class="judge-score-help">Deductions: ${escapeHtml(historyText)}${flag ? ` | Auto zero: ${escapeHtml(flag)}` : ""}</div>`;
}

function renderScoreDeductionButtons(runKey) {
  return `
    <div class="score-deduction-strip" data-run="${runKey}">
      ${QUICK_DEDUCTION_VALUES.map((value) => `
        <button class="score-deduction-btn" type="button" data-action="apply-deduction" data-col="${runKey}" data-deduction="${value}">
          -${value}
        </button>
      `).join("")}
      <button class="score-deduction-btn" type="button" data-action="apply-deduction" data-col="${runKey}" data-deduction="crash">
        Crash
      </button>
      ${currentRole?.startsWith("j") ? `<button class="score-deduction-btn voice-deduction-btn" type="button" data-action="toggle-voice-deduction" data-col="${runKey}" aria-label="Toggle voice deductions for ${escapeHtml(getRunKey(runKey))}">Voice</button>` : ""}
    </div>
  `;
}

function getSubmittedScoreValue(driver, role, runRef) {
  const runKey = getRunKey(runRef);
  return driver?.scores?.[role]?.submitted?.[runKey] ?? null;
}

function hasPendingJudgeChanges(driver, role) {
  const judgeScores = driver?.scores?.[role];
  if (!judgeScores) return false;
  return ["run1", "run2", "runoff"].some((runKey) => getJudgeDraftScoreValue(driver, role, runKey) !== (judgeScores.submitted?.[runKey] ?? null));
}

function hasPendingJudgeRunChanges(driver, role, runRef) {
  const runKey = getRunKey(runRef);
  const judgeScores = driver?.scores?.[role];
  if (!judgeScores) return false;
  return getJudgeDraftScoreValue(driver, role, runKey) !== (judgeScores.submitted?.[runKey] ?? null);
}

function hasSubmittedJudgeRun(driver, role, runRef) {
  return getSubmittedScoreValue(driver, role, runRef) !== null;
}

function submitJudgeScores(driverId, role = currentRole) {
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !role.startsWith("j") || isJudgeAccessLocked()) return;
  const judgeScores = driver.scores?.[role];
  if (!judgeScores) return;
  judgeScores.run1 = getJudgeDraftScoreValue(driver, role, "run1");
  judgeScores.run2 = getJudgeDraftScoreValue(driver, role, "run2");
  const runoffValue = (judgeScores.runoff !== null && judgeScores.runoff !== undefined)
    || (judgeScores.submitted?.runoff !== null && judgeScores.submitted?.runoff !== undefined)
    ? getJudgeDraftScoreValue(driver, role, "runoff")
    : null;
  judgeScores.runoff = runoffValue;
  judgeScores.submitted = {
    run1: judgeScores.run1,
    run2: judgeScores.run2,
    runoff: runoffValue,
  };
  triggerJudgeSubmissionFeedback(driverId, role, "all");
}

function submitJudgeRun(driverId, runRef, role = currentRole) {
  const runKey = getRunKey(runRef);
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !role.startsWith("j") || isJudgeAccessLocked()) return;
  const judgeScores = driver.scores?.[role];
  if (!judgeScores || !(runKey in judgeScores.submitted)) return;
  judgeScores[runKey] = getJudgeDraftScoreValue(driver, role, runKey);
  judgeScores.submitted[runKey] = judgeScores[runKey];
  triggerJudgeSubmissionFeedback(driverId, role, runKey);
}

function confirmJudgeScoreSubmission(driverId, role = currentRole, runRef = null) {
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !role?.startsWith("j")) return false;
  const judgeScores = driver.scores?.[role];
  if (!judgeScores) return false;
  const driverName = driver.name || "this driver";

  if (runRef) {
    const runKey = getRunKey(runRef);
    const scoreValue = getJudgeDraftScoreValue(driver, role, runKey);
    if (scoreValue === null || scoreValue === undefined) return false;
    const runLabel = runKey === "run1"
      ? getJudgeRunTitle(1, role, activeEventMeta)
      : runKey === "run2"
        ? getJudgeRunTitle(2, role, activeEventMeta)
        : "Runoff";
    return window.confirm(
      `Are you sure you want to submit a score of ${formatScore(scoreValue)} for ${driverName} (${runLabel})?`
    );
  }

  const parts = [];
  parts.push(`${getJudgeRunTitle(1, role, activeEventMeta)}: ${formatScore(getJudgeDraftScoreValue(driver, role, "run1"))}`);
  parts.push(`${getJudgeRunTitle(2, role, activeEventMeta)}: ${formatScore(getJudgeDraftScoreValue(driver, role, "run2"))}`);
  if (judgeScores.runoff !== null && judgeScores.runoff !== undefined) parts.push(`Runoff: ${formatScore(getJudgeDraftScoreValue(driver, role, "runoff"))}`);
  if (!parts.length) return false;
  return window.confirm(
    `Are you sure you want to submit these scores for ${driverName}?\n\n${parts.join("\n")}`
  );
}

function hasSubmittedRequiredRuns(driver, role) {
  const judgeScores = driver?.scores?.[role]?.submitted;
  if (!judgeScores) return false;
  if (isTwinTripleMode(activeEventMeta)) return judgeScores.run1 !== null;
  return judgeScores.run1 !== null && judgeScores.run2 !== null;
}

function haveAllActiveJudgesSubmitted(driver) {
  const activeJudgeRoles = getActiveJudgeRoles(activeEventMeta);
  return activeJudgeRoles.length > 0 && activeJudgeRoles.every((role) => hasSubmittedRequiredRuns(driver, role));
}

function haveAllActiveJudgesSubmittedRun(driver, runRef) {
  const runKey = getRunKey(runRef);
  const activeJudgeRoles = getActiveJudgeRoles(activeEventMeta);
  return activeJudgeRoles.length > 0 && activeJudgeRoles.every((role) => getSubmittedScoreValue(driver, role, runKey) !== null);
}

function maybeAdvanceQualifyingAfterSubmit(driverId) {
  if (!driverId || qualifyingFlow.currentDriverId !== driverId) return false;
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver) return false;
  if (!haveAllActiveJudgesSubmitted(driver)) return false;
  advanceQualifyingDriver();
  return true;
}

function maybeAdvanceQualifyingAfterRunSubmit(driverId, runRef) {
  const runKey = getRunKey(runRef);
  const requiredRunKey = isTwinTripleMode(activeEventMeta) ? "run1" : "run2";
  if (!driverId || qualifyingFlow.currentDriverId !== driverId || runKey !== requiredRunKey) return false;
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver) return false;
  if (!haveAllActiveJudgesSubmittedRun(driver, requiredRunKey)) return false;
  advanceQualifyingDriver();
  return true;
}

function driverHasAllSubmittedRunsForRoles(driver, roles, runKeys) {
  return roles.length > 0 && roles.every((role) => runKeys.every((runKey) => driver?.scores?.[role]?.submitted?.[runKey] !== null));
}

async function syncJudgeSubmission(driverId, role = currentRole, runRef = null) {
  if (!role?.startsWith("j")) {
    publishState();
    return true;
  }
  if (isJudgeAccessLocked()) {
    applyRoleChange("spectator");
    switchView("qualifying");
    return false;
  }
  if (!db || !activeEventId) {
    publishState();
    return true;
  }

  const localDriver = appDrivers.find((entry) => entry.id === driverId);
  if (!localDriver) {
    publishState();
    return false;
  }

  clearTimeout(syncTimeout);
  const runKey = runRef ? getRunKey(runRef) : null;
  const localRoleScores = JSON.parse(JSON.stringify(localDriver.scores?.[role] || {}));
  lastLocalPush = Date.now();
  let transactionResult = null;
  let remoteJudgeLocked = false;
  let lockedRemotePayload = null;
  setJudgeSubmissionInFlightState(true);

  try {
    if (!TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE) {
      const scopedRunKeys = runKey ? [runKey] : ["run1", "run2", "runoff"];
      const writes = scopedRunKeys
        .filter((key) => localRoleScores?.submitted?.[key] !== null && localRoleScores?.submitted?.[key] !== undefined)
        .map((key) => publishScopedJudgeSubmission({
          eventId: activeEventId,
          driverId,
          runKey: key,
          judgeSlot: role,
          score: localRoleScores?.[key],
          submittedScore: localRoleScores?.submitted?.[key],
        }));
      await Promise.all(writes);
      return writes.length > 0;
    }

    await runTransaction(db, async (transaction) => {
      const eventRef = getEventDocRef(activeEventId);
      const eventSnap = await transaction.get(eventRef);
      const remotePayload = eventSnap.exists() ? eventSnap.data() : {};
      const remoteMeta = extractEventMeta(remotePayload, activeEventId) || cloneEventMeta(eventDirectory[activeEventId] || activeEventMeta);
      if (isJudgeAccessLocked(remoteMeta)) {
        remoteJudgeLocked = true;
        lockedRemotePayload = remotePayload;
        return;
      }
      const remoteDrivers = Array.isArray(remotePayload.drivers) && remotePayload.drivers.length
        ? sanitizeLoadedDrivers(remotePayload.drivers)
        : createDriverSet();
      const remoteDriver = remoteDrivers.find((entry) => entry.id === driverId);
      if (!remoteDriver) return;

      if (runKey) {
        remoteDriver.scores[role][runKey] = localRoleScores[runKey] ?? null;
        remoteDriver.scores[role].submitted[runKey] = localRoleScores?.submitted?.[runKey] ?? localRoleScores[runKey] ?? null;
      } else {
        remoteDriver.scores[role] = {
          run1: localRoleScores.run1 ?? null,
          run2: localRoleScores.run2 ?? null,
          runoff: localRoleScores.runoff ?? null,
          submitted: {
            run1: localRoleScores?.submitted?.run1 ?? localRoleScores.run1 ?? null,
            run2: localRoleScores?.submitted?.run2 ?? localRoleScores.run2 ?? null,
            runoff: localRoleScores?.submitted?.runoff ?? localRoleScores.runoff ?? null,
          },
        };
      }

      const activeJudgeRoles = getActiveJudgeRoles(remoteMeta);
      const nextQualifyingFlow = remotePayload.qualifyingFlow || createEmptyQualifyingFlow();
      const remoteTwinComp = isTwinTripleMode(remoteMeta) ? normalizeTwinCompState(twinCompState) : normalizeTwinCompState(remotePayload.twinComp);
      if (isTwinTripleMode(remoteMeta)) {
        Object.assign(nextQualifyingFlow, JSON.parse(JSON.stringify(qualifyingFlow || createEmptyQualifyingFlow())));
      } else if (nextQualifyingFlow.currentDriverId === driverId) {
        const shouldAdvanceAfterAllRuns = !runKey && driverHasAllSubmittedRunsForRoles(remoteDriver, activeJudgeRoles, ["run1", "run2"]);
        const shouldAdvanceAfterRun2 = runKey === "run2" && driverHasAllSubmittedRunsForRoles(remoteDriver, activeJudgeRoles, ["run2"]);
        if (shouldAdvanceAfterAllRuns || shouldAdvanceAfterRun2) {
          const queue = getRegisteredDrivers(remoteDrivers);
          const currentIndex = Math.max(0, queue.findIndex((entry) => entry.id === driverId));
          const nextIndex = currentIndex + 1;
          const nextDriverId = nextIndex < queue.length ? (queue[nextIndex]?.id || null) : null;
          nextQualifyingFlow.currentDriverId = nextDriverId;
          nextQualifyingFlow.readyRoles = {};
          nextQualifyingFlow.started = true;
          nextQualifyingFlow.completed = !nextDriverId;
        }
      }

      const updatedMeta = {
        ...remoteMeta,
        updatedAt: new Date().toISOString(),
        syncStamp: lastLocalPush,
      };

      transaction.set(eventRef, {
        ...remotePayload,
        ...updatedMeta,
        drivers: remoteDrivers,
        bracket: remotePayload.bracket || tournamentState,
        twinComp: remoteTwinComp,
        qualifyingFlow: nextQualifyingFlow,
        formatMode: remotePayload.formatMode || bracketModeSelect.value,
        lowerCount: remotePayload.lowerCount || String(getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0),
        syncStamp: lastLocalPush,
      }, { merge: true });

      if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
        transaction.set(getDirectoryDocRef(), {
          events: getPersistableDirectorySnapshot({
            [activeEventId]: cloneEventMeta({
              ...(eventDirectory[activeEventId] || activeEventMeta || updatedMeta),
              ...updatedMeta,
            }),
          }),
          activeEventId,
          deletedEventIds: getDeletedEventIdsSnapshot(),
          syncStamp: lastLocalPush,
        }, { merge: true });
      }

      transactionResult = {
        remoteDrivers: JSON.parse(JSON.stringify(remoteDrivers)),
        remoteQualifyingFlow: JSON.parse(JSON.stringify(nextQualifyingFlow)),
        remoteTwinComp: remoteTwinComp ? JSON.parse(JSON.stringify(remoteTwinComp)) : null,
        remoteMeta: cloneEventMeta(updatedMeta),
      };
    });

    if (transactionResult) {
      const localJudgeDrafts = captureJudgeDraftScores(role);
      applyActiveEventState({
        drivers: restoreJudgeDraftScores(
          sanitizeLoadedDrivers(transactionResult.remoteDrivers),
          role,
          localJudgeDrafts,
        ),
        qualifyingFlow: transactionResult.remoteQualifyingFlow || createEmptyQualifyingFlow(),
        twinComp: normalizeTwinCompState(transactionResult.remoteTwinComp),
        meta: transactionResult.remoteMeta || activeEventMeta,
      });
      eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
      saveDirectoryCache();
      saveEventStateCache();
    } else if (remoteJudgeLocked) {
      if (lockedRemotePayload) {
        applyRemoteEventState(lockedRemotePayload);
      }
      window.alert("Judging is locked for this event now. Your last submission was not saved.");
      applyRoleChange("spectator");
      switchView("qualifying");
      renderDriversTable();
      return false;
    }
    return true;
  } catch (error) {
    console.error("Judge submission sync failed:", error);
    handleCloudPermissionError(error, role, "judge submission");
    if (TEST_MODE_ENABLED || STANDALONE_DEMO_MODE) publishState();
    return false;
  } finally {
    judgeSubmissionInFlight = false;
  }
}

async function submitCompetitionJudgeVote(side, role = currentRole) {
  if (!role?.startsWith("j") || !tournamentState?.mainBracket?.rounds?.length) return false;
  if (isJudgeAccessLocked()) {
    applyRoleChange("spectator");
    switchView("qualifying");
    return false;
  }

  const applyLocalVote = async () => {
    const result = recordCompetitionJudgeVote(tournamentState, activeEventMeta, role, side);
    if (!result.changed || result.blocked) return false;
    if (result.resolution?.winnerSide && result.entry?.match?.[result.resolution.winnerSide]) {
      maybeTriggerCompetitionWinnerAnimation(result.entry, result.resolution.winnerSide);
    } else if (result.control?.status === "review_hold" || result.control?.reason === "omt" || result.resolution?.omtMajority || result.resolution?.tied) {
      clearWinnerAnimationState();
    }
    await publishStateImmediately();
    renderBracket();
    return true;
  };

  if (!db || !activeEventId || !activeEventMeta) {
    return applyLocalVote();
  }

  clearTimeout(syncTimeout);
  lastLocalPush = Date.now();
  let transactionResult = null;
  let remoteJudgeLocked = false;
  let lockedRemotePayload = null;
  judgeSubmissionInFlight = true;

  try {
    if (!TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE) {
      const result = recordCompetitionJudgeVote(tournamentState, activeEventMeta, role, side);
      if (!result.changed || result.blocked) return false;
      await publishScopedBattleVote({
        eventId: activeEventId,
        battleId: getBattleScopedId(result.entry, result.control?.cycle || 1),
        judgeSlot: role,
        side,
        cycle: result.control?.cycle || 1,
      });
      renderBracket();
      return true;
    }

    await runTransaction(db, async (transaction) => {
      const eventRef = getEventDocRef(activeEventId);
      const eventSnap = await transaction.get(eventRef);
      const remotePayload = eventSnap.exists() ? eventSnap.data() : {};
      const remoteMeta = extractEventMeta(remotePayload, activeEventId) || cloneEventMeta(eventDirectory[activeEventId] || activeEventMeta);
      if (isJudgeAccessLocked(remoteMeta)) {
        remoteJudgeLocked = true;
        lockedRemotePayload = remotePayload;
        return;
      }

      const remoteDrivers = Array.isArray(remotePayload.drivers) && remotePayload.drivers.length
        ? sanitizeLoadedDrivers(remotePayload.drivers)
        : createDriverSet();
      const remoteState = remotePayload.bracket ? upgradeStoredTournamentState(remotePayload.bracket) : null;
      if (!remoteState?.mainBracket?.rounds?.length) return;
      normalizeBracketState(remoteState);

      const result = recordCompetitionJudgeVote(remoteState, remoteMeta, role, side);
      if (!result.changed || result.blocked) return;

      const updatedMeta = {
        ...remoteMeta,
        updatedAt: new Date().toISOString(),
        syncStamp: lastLocalPush,
      };

      transaction.set(eventRef, {
        ...remotePayload,
        ...updatedMeta,
        drivers: remoteDrivers,
        bracket: remoteState,
        qualifyingFlow: remotePayload.qualifyingFlow || createEmptyQualifyingFlow(),
        formatMode: remotePayload.formatMode || bracketModeSelect.value,
        lowerCount: remotePayload.lowerCount || String(getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0),
        syncStamp: lastLocalPush,
      }, { merge: true });

      if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
        transaction.set(getDirectoryDocRef(), {
          events: getPersistableDirectorySnapshot({
            [activeEventId]: cloneEventMeta({
              ...(eventDirectory[activeEventId] || activeEventMeta || updatedMeta),
              ...updatedMeta,
            }),
          }),
          activeEventId,
          deletedEventIds: getDeletedEventIdsSnapshot(),
          syncStamp: lastLocalPush,
        }, { merge: true });
      }

      transactionResult = {
        remoteBracket: JSON.parse(JSON.stringify(remoteState)),
        remoteMeta: cloneEventMeta(updatedMeta),
        resolution: result.resolution,
        entry: cloneCompetitionEntrySnapshot(result.entry),
      };
    });

    if (transactionResult) {
      applyActiveEventState({
        bracket: upgradeStoredTournamentState(transactionResult.remoteBracket),
        meta: transactionResult.remoteMeta || activeEventMeta,
      }, { syncQualifying: false });
      eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
      saveDirectoryCache();
      saveEventStateCache();
      if (transactionResult.resolution?.winnerSide && transactionResult.entry?.match?.[transactionResult.resolution.winnerSide]) {
        maybeTriggerCompetitionWinnerAnimation(transactionResult.entry, transactionResult.resolution.winnerSide);
      } else if (getCompetitionJudgeControl(tournamentState).status === "review_hold" || getCompetitionJudgeControl(tournamentState).reason === "omt" || transactionResult.resolution?.omtMajority || transactionResult.resolution?.tied) {
        clearWinnerAnimationState();
      }
      // The transaction already committed the shared event state.
      // Avoid a second full-event write from a judge device here.
      renderBracket();
      return true;
    }

    if (remoteJudgeLocked) {
      if (lockedRemotePayload) {
        applyRemoteEventState(lockedRemotePayload);
      }
      applyRoleChange("spectator");
      switchView("qualifying");
      renderDriversTable();
      return false;
    }

    return false;
  } catch (error) {
    console.error("Competition judge vote sync failed:", error);
    if (handleCloudPermissionError(error, role, "battle vote")) return false;
    return applyLocalVote();
  } finally {
    setJudgeSubmissionInFlightState(false);
  }
}

async function submitCompetitionJudgeScorecard(scoreSubmission, role = currentRole) {
  if (!isTeamTandemMode(activeEventMeta) || !role?.startsWith("j") || !tournamentState?.mainBracket?.rounds?.length) return false;
  if (isJudgeAccessLocked()) {
    applyRoleChange("spectator");
    switchView("qualifying");
    return false;
  }

  const localResolution = getCompetitionDecisionResolution(getCompetitionJudgeControl(tournamentState), activeEventMeta);
  const normalizedSubmission = {
    side: scoreSubmission?.side === "right"
      ? "right"
      : scoreSubmission?.side === "left"
        ? "left"
        : localResolution.currentSide,
    score: Number(scoreSubmission?.score),
  };
  if (!normalizedSubmission.side || !Number.isFinite(normalizedSubmission.score)) {
    return false;
  }

  const applyLocalScorecard = async () => {
    const result = recordCompetitionJudgeScorecard(tournamentState, activeEventMeta, role, normalizedSubmission);
    if (!result.changed || result.blocked) return false;
    if (result.resolution?.winnerSide && result.entry?.match?.[result.resolution.winnerSide]) {
      maybeTriggerCompetitionWinnerAnimation(result.entry, result.resolution.winnerSide);
    } else if (result.control?.status === "review_hold" || result.control?.reason === "omt" || result.resolution?.omtMajority || result.resolution?.tied) {
      clearWinnerAnimationState();
    }
    await publishStateImmediately();
    renderBracket();
    return true;
  };

  if (!db || !activeEventId || !activeEventMeta) {
    return applyLocalScorecard();
  }

  clearTimeout(syncTimeout);
  lastLocalPush = Date.now();
  let transactionResult = null;
  let remoteJudgeLocked = false;
  let lockedRemotePayload = null;
  setJudgeSubmissionInFlightState(true);

  try {
    if (!TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE) {
      const result = recordCompetitionJudgeScorecard(tournamentState, activeEventMeta, role, normalizedSubmission);
      if (!result.changed || result.blocked) return false;
      await publishScopedBattleVote({
        eventId: activeEventId,
        battleId: getBattleScopedId(result.entry, result.control?.cycle || 1),
        judgeSlot: role,
        side: normalizedSubmission.side,
        scorecard: {
          side: normalizedSubmission.side,
          score: normalizedSubmission.score,
        },
        cycle: result.control?.cycle || 1,
      });
      renderBracket();
      return true;
    }

    await runTransaction(db, async (transaction) => {
      const eventRef = getEventDocRef(activeEventId);
      const eventSnap = await transaction.get(eventRef);
      const remotePayload = eventSnap.exists() ? eventSnap.data() : {};
      const remoteMeta = extractEventMeta(remotePayload, activeEventId) || cloneEventMeta(eventDirectory[activeEventId] || activeEventMeta);
      if (isJudgeAccessLocked(remoteMeta)) {
        remoteJudgeLocked = true;
        lockedRemotePayload = remotePayload;
        return;
      }

      const remoteDrivers = Array.isArray(remotePayload.drivers) && remotePayload.drivers.length
        ? sanitizeLoadedDrivers(remotePayload.drivers)
        : TEST_MODE_ENABLED && Array.isArray(drivers) && drivers.length
          ? sanitizeLoadedDrivers(drivers)
          : createDriverSet();
      const localSeededStateFallback = TEST_MODE_ENABLED && tournamentState?.mainBracket?.rounds?.length
        ? upgradeStoredTournamentState(JSON.parse(JSON.stringify(tournamentState)))
        : null;
      const remoteState = remotePayload.bracket ? upgradeStoredTournamentState(remotePayload.bracket) : localSeededStateFallback;
      if (!remoteState?.mainBracket?.rounds?.length) return;
      normalizeBracketState(remoteState);

      const result = recordCompetitionJudgeScorecard(remoteState, remoteMeta, role, normalizedSubmission);
      if (!result.changed || result.blocked) return;

      const updatedMeta = {
        ...remoteMeta,
        updatedAt: new Date().toISOString(),
        syncStamp: lastLocalPush,
      };

      transaction.set(eventRef, {
        ...remotePayload,
        ...updatedMeta,
        drivers: remoteDrivers,
        bracket: remoteState,
        qualifyingFlow: remotePayload.qualifyingFlow || createEmptyQualifyingFlow(),
        formatMode: remotePayload.formatMode || bracketModeSelect.value,
        lowerCount: remotePayload.lowerCount || String(getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0),
        syncStamp: lastLocalPush,
      }, { merge: true });

      if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
        transaction.set(getDirectoryDocRef(), {
          events: getPersistableDirectorySnapshot({
            [activeEventId]: cloneEventMeta({
              ...(eventDirectory[activeEventId] || activeEventMeta || updatedMeta),
              ...updatedMeta,
            }),
          }),
          activeEventId,
          deletedEventIds: getDeletedEventIdsSnapshot(),
          syncStamp: lastLocalPush,
        }, { merge: true });
      }

      transactionResult = {
        remoteBracket: JSON.parse(JSON.stringify(remoteState)),
        remoteMeta: cloneEventMeta(updatedMeta),
        resolution: result.resolution,
        entry: cloneCompetitionEntrySnapshot(result.entry),
      };
    });

    if (transactionResult) {
      applyActiveEventState({
        bracket: upgradeStoredTournamentState(transactionResult.remoteBracket),
        meta: transactionResult.remoteMeta || activeEventMeta,
      }, { syncQualifying: false });
      eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
      saveDirectoryCache();
      saveEventStateCache();
      if (transactionResult.resolution?.winnerSide && transactionResult.entry?.match?.[transactionResult.resolution.winnerSide]) {
        maybeTriggerCompetitionWinnerAnimation(transactionResult.entry, transactionResult.resolution.winnerSide);
      } else if (getCompetitionJudgeControl(tournamentState).status === "review_hold" || getCompetitionJudgeControl(tournamentState).reason === "omt" || transactionResult.resolution?.omtMajority || transactionResult.resolution?.tied) {
        clearWinnerAnimationState();
      }
      // The transaction already committed the shared event state.
      // Avoid a second full-event write from a judge device here.
      renderBracket();
      return true;
    }

    if (remoteJudgeLocked) {
      if (lockedRemotePayload) {
        applyRemoteEventState(lockedRemotePayload);
      }
      applyRoleChange("spectator");
      switchView("qualifying");
      renderDriversTable();
      return false;
    }

    return false;
  } catch (error) {
    console.error("Competition judge scorecard sync failed:", error);
    if (handleCloudPermissionError(error, role, "battle scorecard")) return false;
    return applyLocalScorecard();
  } finally {
    setJudgeSubmissionInFlightState(false);
  }
}

async function requestCompetitionDecisionReview() {
  if (!adminCanEdit() || !tournamentState?.mainBracket?.rounds?.length) return false;
  const control = getCompetitionJudgeControl();
  if (control.status !== "admin_decision" || !control.entry) return false;
  tournamentState.competitionJudgeControl = {
    ...control,
    status: "review_hold",
    reason: "contest",
    updatedAt: new Date().toISOString(),
  };
  clearWinnerAnimationState();
  await publishStateImmediately();
  renderBracket();
  return true;
}

async function continueCompetitionFlow() {
  if (!adminCanEdit() || !tournamentState?.mainBracket?.rounds?.length) return false;
  const control = getCompetitionJudgeControl();
  if (!control.entry) return false;

  if (control.status === "admin_decision") {
    clearCompetitionJudgeControl(tournamentState);
  } else if (control.status === "review_hold" && control.reason === "contest") {
    clearCompetitionJudgeControl(tournamentState);
  } else if (control.status === "review_hold") {
    tournamentState.competitionJudgeControl = {
      ...buildCompetitionJudgeControlForEntry(control.entry, Math.max(control.cycle + 1, 2)),
      reason: null,
    };
  } else {
    return false;
  }

  await publishStateImmediately();
  renderBracket();
  return true;
}

function getJudgeSubmitButtonLabel(driver, role = currentRole) {
  if (!driver || !role?.startsWith("j")) return "Submit Scores";
  if (hasPendingJudgeChanges(driver, role)) return "Submit Scores";
  if (driver.id === qualifyingFlow.currentDriverId && !haveAllActiveJudgesSubmitted(driver)) {
    return "Waiting for other judges";
  }
  return "Re-submit to update";
}

function isJudgeSubmitWaiting(driver, role = currentRole) {
  return getJudgeSubmitButtonLabel(driver, role) === "Waiting for other judges";
}

function captureJudgeDraftScores(role = currentRole) {
  if (!role?.startsWith("j")) return new Map();
  const drafts = new Map();
  appDrivers.forEach((driver) => {
    const judgeScores = driver?.scores?.[role];
    if (!judgeScores) return;
    const hasPending = ["run1", "run2", "runoff"].some((runKey) => (judgeScores[runKey] ?? null) !== (judgeScores.submitted?.[runKey] ?? null));
    if (!hasPending) return;
    drafts.set(driver.id, {
      run1: judgeScores.run1,
      run2: judgeScores.run2,
      runoff: judgeScores.runoff,
    });
  });
  return drafts;
}

function applyJudgeScoreDeduction(driverId, runRef, deduction, role = currentRole) {
  const runKey = getRunKey(runRef);
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !role?.startsWith("j")) return false;
  if (deduction === "crash") {
    driver.scores[role][runKey] = 0;
    driver.runFlags[runKey] = "Crash";
    appendJudgeDeductionHistory(driver, role, runKey, "Crash");
    return true;
  }
  const numericDeduction = Number(deduction);
  if (!Number.isFinite(numericDeduction)) return false;
  const nextValue = clampJudgeScoreValue(getJudgeDraftScoreValue(driver, role, runKey) - numericDeduction, role, activeEventMeta);
  driver.scores[role][runKey] = nextValue;
  if (driver.runFlags?.[runKey]) {
    driver.runFlags[runKey] = null;
  }
  appendJudgeDeductionHistory(driver, role, runKey, `-${numericDeduction}`);
  return true;
}

function getSpeechRecognitionConstructor() {
  if (typeof window === "undefined") return null;
  return window.SpeechRecognition || window.webkitSpeechRecognition || null;
}

function parseSpokenNumber(value) {
  const text = String(value || "").toLowerCase().replace(/-/g, " ").replace(/[^\w.\s]/g, " ").trim();
  const numericMatch = text.match(/\d+(?:\.\d+)?/);
  if (numericMatch) {
    const direct = Number.parseFloat(numericMatch[0]);
    if (Number.isFinite(direct)) return direct;
  }
  const words = new Map([
    ["zero", 0], ["oh", 0], ["one", 1], ["two", 2], ["three", 3], ["four", 4], ["for", 4],
    ["five", 5], ["six", 6], ["seven", 7], ["eight", 8], ["ate", 8], ["nine", 9], ["ten", 10],
    ["eleven", 11], ["twelve", 12], ["thirteen", 13], ["fourteen", 14], ["fifteen", 15],
    ["sixteen", 16], ["seventeen", 17], ["eighteen", 18], ["nineteen", 19],
    ["twenty", 20], ["thirty", 30], ["forty", 40], ["fourty", 40], ["fifty", 50],
    ["sixty", 60], ["seventy", 70], ["eighty", 80], ["ninety", 90], ["hundred", 100],
  ]);
  let current = 0;
  let matched = false;
  text.split(/\s+/).forEach((token) => {
    if (!words.has(token)) return;
    matched = true;
    const wordValue = words.get(token);
    current = wordValue === 100 ? Math.max(1, current) * 100 : current + wordValue;
  });
  return matched ? current : null;
}

function getSpokenNumberTokens(value) {
  const text = String(value || "").toLowerCase().replace(/-/g, " ").replace(/[^\w.\s]/g, " ").trim();
  if (!text) return [];
  const words = new Map([
    ["zero", 0], ["oh", 0], ["one", 1], ["two", 2], ["three", 3], ["four", 4], ["for", 4],
    ["five", 5], ["six", 6], ["seven", 7], ["eight", 8], ["ate", 8], ["nine", 9], ["ten", 10],
    ["eleven", 11], ["twelve", 12], ["thirteen", 13], ["fourteen", 14], ["fifteen", 15],
    ["sixteen", 16], ["seventeen", 17], ["eighteen", 18], ["nineteen", 19],
    ["twenty", 20], ["thirty", 30], ["forty", 40], ["fourty", 40], ["fifty", 50],
    ["sixty", 60], ["seventy", 70], ["eighty", 80], ["ninety", 90],
  ]);
  const tokens = [];
  const tokenRegex = /\d+(?:\.\d+)?|[a-z]+/g;
  let match;
  while ((match = tokenRegex.exec(text)) !== null) {
    const raw = match[0];
    const numeric = Number.parseFloat(raw);
    if (Number.isFinite(numeric) && /^\d/.test(raw)) {
      tokens.push({ index: match.index, value: numeric });
      continue;
    }
    if (words.has(raw)) {
      tokens.push({ index: match.index, value: words.get(raw) });
    }
  }
  return tokens;
}

function addVoiceDeductionCommands(commands, segment, baseIndex = 0) {
  getSpokenNumberTokens(segment).forEach((token) => {
    commands.push({ index: baseIndex + token.index, type: "deduction", value: token.value });
  });
}

function parseJudgeVoiceCommands(transcript) {
  const normalized = String(transcript || "").toLowerCase().trim();
  if (!normalized) return [];
  const commands = [];
  const crashRegex = /\bcrash\b/g;
  let crashMatch;
  while ((crashMatch = crashRegex.exec(normalized)) !== null) {
    commands.push({ index: crashMatch.index, type: "deduction", value: "crash" });
  }
  const setRegex = /\b(?:set|score|make it|make)\s+(?:score\s+)?([a-z0-9.\s-]+)/g;
  let setMatch;
  while ((setMatch = setRegex.exec(normalized)) !== null) {
    const value = parseSpokenNumber(setMatch[1]);
    if (Number.isFinite(value)) commands.push({ index: setMatch.index, type: "set", value });
  }
  const leadingDeductionRegex = /\b(?:minus|deduct|take|drop|subtract)\s+([a-z0-9.]+)/g;
  let leadingDeductionMatch;
  while ((leadingDeductionMatch = leadingDeductionRegex.exec(normalized)) !== null) {
    const value = parseSpokenNumber(leadingDeductionMatch[1]);
    if (Number.isFinite(value)) commands.push({ index: leadingDeductionMatch.index, type: "deduction", value });
  }
  const deductionSegmentRegex = /\b(?:minus|deduct|take|drop|subtract)\s+([a-z0-9.\s,]+?)(?=\b(?:minus|deduct|take|drop|subtract|set|score|make it|make|crash)\b|$)/g;
  let deductionSegmentMatch;
  while ((deductionSegmentMatch = deductionSegmentRegex.exec(normalized)) !== null) {
    addVoiceDeductionCommands(commands, deductionSegmentMatch[1], deductionSegmentMatch.index);
  }
  const trailingDeductionRegex = /\b([a-z0-9.]+)\s+(?:off|deduction)\b/g;
  let trailingDeductionMatch;
  while ((trailingDeductionMatch = trailingDeductionRegex.exec(normalized)) !== null) {
    const value = parseSpokenNumber(trailingDeductionMatch[1]);
    if (Number.isFinite(value)) commands.push({ index: trailingDeductionMatch.index, type: "deduction", value });
  }
  if (commands.length) {
    commands.sort((left, right) => left.index - right.index);
    const seen = new Set();
    return commands.filter((command) => {
      const key = `${command.index}:${command.type}:${command.value}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    }).map((command) => ({
      type: command.type,
      value: command.value,
      sourceKey: `${command.index}:${command.type}:${command.value}`,
    }));
  }
  const spokenNumbers = getSpokenNumberTokens(normalized);
  if (spokenNumbers.length) {
    return spokenNumbers.map((token) => ({ type: "deduction", value: token.value, sourceKey: `${token.index}:deduction:${token.value}` }));
  }
  return [];
}

function parseJudgeVoiceCommand(transcript) {
  const commands = parseJudgeVoiceCommands(transcript);
  return commands.length ? commands[commands.length - 1] : null;
}

function normalizeVoiceAiCommands(commands) {
  if (!Array.isArray(commands)) return [];
  return commands.map((entry, index) => {
    const type = entry?.type === "set" ? "set" : "deduction";
    const rawValue = type === "deduction" && String(entry?.value || "").toLowerCase() === "crash"
      ? "crash"
      : Number(entry?.value);
    if (rawValue !== "crash" && !Number.isFinite(rawValue)) return null;
    return {
      type,
      value: rawValue,
      sourceKey: `ai:${index}:${type}:${rawValue}`,
    };
  }).filter(Boolean);
}

async function parseJudgeVoiceCommandsWithAi(transcript, context = {}) {
  const endpoint = String(CLIENT_VOICE_AI?.endpoint || "").trim();
  if (!CLIENT_VOICE_AI?.enabled || !endpoint || !transcript) return [];
  try {
    const response = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        transcript,
        maxScore: getJudgeScoreMax(context.role || currentRole, activeEventMeta),
        currentScore: Number.isFinite(Number(context.currentScore)) ? Number(context.currentScore) : null,
      }),
    });
    if (!response.ok) throw new Error(`Voice AI returned ${response.status}`);
    const payload = await response.json();
    return normalizeVoiceAiCommands(payload?.commands);
  } catch (error) {
    console.warn("Voice AI parsing unavailable; using local parser.", error);
    return [];
  }
}

let activeVoiceRecognition = null;
let activeVoiceSession = null;

function getVoiceSessionKey(driverId, runKey, role) {
  return `${String(role || "")}:${String(driverId || "")}:${String(runKey || "")}`;
}

function clearVoiceButtonState(button) {
  if (!button) return;
  button.classList.remove("is-listening");
  button.textContent = "Voice";
  button.setAttribute("aria-label", "Start voice deductions");
  button.setAttribute("title", "Keep voice deductions listening");
}

function setVoiceButtonListening(button) {
  if (!button) return;
  button.classList.add("is-listening");
  button.textContent = "Voice On";
  button.setAttribute("aria-label", "Stop voice deductions");
  button.setAttribute("title", "Listening. Tap to stop voice deductions.");
}

async function processRecordedJudgeVoiceSession(session) {
  if (!session || session.processedRecording) return false;
  session.processedRecording = true;
  const recordedResults = [...(session.recordedResults?.values?.() || [])]
    .filter((entry) => String(entry?.transcript || "").trim())
    .sort((left, right) => (left.order || 0) - (right.order || 0));
  const finalResults = recordedResults.filter((entry) => entry.isFinal);
  const lastFinalOrder = finalResults.reduce((maxOrder, entry) => Math.max(maxOrder, entry.order || 0), 0);
  const trailingInterimResults = finalResults.length
    ? recordedResults.filter((entry) => !entry.isFinal && (entry.order || 0) > lastFinalOrder)
    : [];
  const transcript = (finalResults.length ? [...finalResults, ...trailingInterimResults] : recordedResults)
    .map((entry) => entry.transcript)
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
  const driver = appDrivers.find((entry) => entry.id === session.driverId);
  const currentScore = driver ? getJudgeDraftScoreValue(driver, session.role, session.runKey) : null;
  const aiCommands = await parseJudgeVoiceCommandsWithAi(transcript, {
    role: session.role,
    currentScore,
  });
  const commands = aiCommands.length ? aiCommands : parseJudgeVoiceCommands(transcript);
  if (!commands.length) {
    if (transcript) {
      window.alert(`Voice recorded "${transcript}", but no deduction command was found. Try phrases like "minus two", "five off", or "crash".`);
    }
    return false;
  }
  let applied = false;
  commands.forEach((command) => {
    if (applyJudgeVoiceCommand(command, transcript, session)) {
      applied = true;
    }
  });
  return applied;
}

function stopJudgeVoiceDeduction(options = {}) {
  const shouldProcess = options.process !== false;
  const session = activeVoiceSession;
  activeVoiceSession = null;
  if (session) {
    session.stopRequested = true;
    clearVoiceButtonState(session.button);
  }
  if (activeVoiceRecognition) {
    try { activeVoiceRecognition.stop(); } catch (error) {}
  }
  activeVoiceRecognition = null;
  if (session && shouldProcess) {
    window.setTimeout(() => processRecordedJudgeVoiceSession(session), 250);
  }
}

function applyJudgeVoiceCommand(command, transcript, session) {
  if (!command || !session) return false;
  const driver = appDrivers.find((entry) => entry.id === session.driverId);
  if (!driver || !session.role?.startsWith("j")) return false;
  const now = Date.now();
  const signature = `${command.sourceKey || `${command.type}:${command.value}`}:${session.driverId}:${session.runKey}`;
  if (session.lastCommandSignature === signature && now - session.lastCommandAt < 900) {
    return false;
  }
  session.lastCommandSignature = signature;
  session.lastCommandAt = now;
  const readinessCleared = session.driverId === qualifyingFlow.currentDriverId && clearQualifyingReady(session.role);
  if (command.type === "set") {
    driver.scores[session.role][session.runKey] = clampJudgeScoreValue(command.value, session.role, activeEventMeta);
    driver.runFlags[session.runKey] = null;
    appendJudgeDeductionHistory(driver, session.role, session.runKey, `Voice set ${formatScore(command.value)}`);
  } else {
    applyJudgeScoreDeduction(session.driverId, session.runKey, command.value, session.role);
  }
  if (readinessCleared) publishState();
  refreshJudgeDraftUi(session.container, driver, session.role);
  session.lastTranscript = transcript;
  return true;
}

function startJudgeVoiceDeduction(button, container, runRef, role = currentRole) {
  const Recognition = getSpeechRecognitionConstructor();
  if (!Recognition) {
    window.alert("Voice dictation is not available in this browser. On iPhone, try Safari with microphone permissions enabled.");
    return;
  }
  const driverId = container?.dataset?.id;
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !role?.startsWith("j")) return;
  const runKey = getRunKey(runRef);
  const sessionKey = getVoiceSessionKey(driverId, runKey, role);
  if (activeVoiceSession?.key === sessionKey) {
    stopJudgeVoiceDeduction();
    return;
  }
  stopJudgeVoiceDeduction();
  const session = {
    key: sessionKey,
    driverId,
    runKey,
    role,
    button,
    container,
    stopRequested: false,
    processedRecording: false,
    recognitionRunId: 0,
    recordedResultOrder: 0,
    recordedResults: new Map(),
    lastCommandSignature: "",
    lastCommandAt: 0,
    lastTranscript: "",
    lastProcessedResultIndex: -1,
    processedResultCommands: new Map(),
  };
  activeVoiceSession = session;
  setVoiceButtonListening(button);

  const startRecognition = () => {
    if (activeVoiceSession !== session || session.stopRequested) return;
    const recognition = new Recognition();
    const recognitionRunId = session.recognitionRunId + 1;
    session.recognitionRunId = recognitionRunId;
    activeVoiceRecognition = recognition;
    recognition.lang = "en-US";
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.maxAlternatives = 1;
    recognition.onresult = (event) => {
      for (let index = event.resultIndex || 0; index < event.results.length; index += 1) {
        const result = event.results[index];
        const transcript = result?.[0]?.transcript || "";
        if (!String(transcript || "").trim()) continue;
        const key = `${recognitionRunId}:${index}`;
        const existing = session.recordedResults.get(key);
        session.recordedResults.set(key, {
          transcript,
          isFinal: Boolean(result?.isFinal),
          order: existing?.order || ++session.recordedResultOrder,
        });
      }
    };
    recognition.onerror = (event) => {
      if (activeVoiceSession !== session || session.stopRequested) return;
      if (["no-speech", "aborted"].includes(event?.error)) return;
      if (["not-allowed", "service-not-allowed"].includes(event?.error)) {
        window.alert("Voice dictation needs microphone permission before it can stay on.");
        stopJudgeVoiceDeduction({ process: false });
        return;
      }
      console.warn("Voice dictation error", event?.error || event);
    };
    recognition.onend = () => {
      if (activeVoiceRecognition === recognition) activeVoiceRecognition = null;
      if (activeVoiceSession !== session || session.stopRequested) {
        clearVoiceButtonState(button);
        return;
      }
      window.setTimeout(startRecognition, 120);
    };
    try {
      recognition.start();
    } catch (error) {
      if (activeVoiceSession === session && !session.stopRequested) {
        window.setTimeout(startRecognition, 250);
      }
    }
  };

  startRecognition();
}

function toggleJudgeVoiceDeduction(button, container, runRef, role = currentRole) {
  const driverId = container?.dataset?.id;
  const runKey = getRunKey(runRef);
  if (activeVoiceSession?.key === getVoiceSessionKey(driverId, runKey, role)) {
    stopJudgeVoiceDeduction();
    return;
  }
  startJudgeVoiceDeduction(button, container, runRef, role);
}

function refreshJudgeDraftUi(container, driver, role = currentRole) {
  if (!container || !driver || !role?.startsWith("j")) return;

  ["r1", "r2", "runoff"].forEach((col) => {
    const input = container.querySelector(`.score-input[data-col="${col}"]`);
    if (!input) return;
    const runKey = col === "r1" ? "run1" : col === "r2" ? "run2" : "runoff";
    if (runKey === "runoff") {
      const runoffValue = driver.scores?.[role]?.runoff;
      input.max = String(getJudgeScoreMax(role, activeEventMeta));
      input.placeholder = getJudgeScorePlaceholder(role, activeEventMeta);
      input.value = runoffValue === null || runoffValue === undefined ? "" : String(clampJudgeScoreValue(runoffValue, role, activeEventMeta));
      return;
    }
    input.max = String(getJudgeScoreMax(role, activeEventMeta));
    input.placeholder = getJudgeScorePlaceholder(role, activeEventMeta);
    input.value = String(getJudgeDraftScoreValue(driver, role, runKey));
  });

  ["r1", "r2", "runoff"].forEach((col) => {
    const historyEl = container.querySelector(`.judge-deduction-history[data-col="${col}"]`);
    if (!historyEl) return;
    const runKey = col === "r1" ? "run1" : col === "r2" ? "run2" : "runoff";
    historyEl.innerHTML = renderDeductionHistory(driver, role, runKey);
  });

  const submitButton = container.querySelector("[data-action='submit-judge-scores']");
  if (submitButton) {
    submitButton.textContent = getJudgeSubmitButtonLabel(driver, role);
    submitButton.disabled = isJudgeSubmitWaiting(driver, role);
  }

  const runSubmitButton = container.querySelector("[data-action='submit-judge-run']");
  if (runSubmitButton) {
    const runKey = runSubmitButton.dataset.run;
    const runValue = getJudgeDraftScoreValue(driver, role, runKey);
    const isPending = hasPendingJudgeRunChanges(driver, role, runKey);
    const isSubmitted = hasSubmittedJudgeRun(driver, role, runKey);
    runSubmitButton.disabled = runValue === null || (isSubmitted && !isPending);
    runSubmitButton.textContent = isPending || !isSubmitted
      ? `Submit ${runKey === "run1" ? "Run 1" : "Run 2"}`
      : `Waiting For ${runKey === "run1" ? "Run 1" : "Run 2"} Scores`;
  }
}

function restoreJudgeDraftScores(drivers, role, drafts) {
  if (!role?.startsWith("j") || !(drafts instanceof Map) || !drafts.size) return drivers;
  return drivers.map((driver) => {
    const draft = drafts.get(driver.id);
    if (!draft) return driver;
    return {
      ...driver,
      scores: {
        ...driver.scores,
        [role]: {
          ...driver.scores[role],
          run1: draft.run1,
          run2: draft.run2,
          runoff: draft.runoff,
        },
      },
    };
  });
}

function getRunAverage(driver, runRef, eventMeta = activeEventMeta) {
  return calculateRunAverage(driver, runRef, {
    activeRoles: getActiveJudgeRoles(eventMeta),
    categoryJudging: usesCategoryJudging(eventMeta),
  });
}

function getLiveRunAverage(driver, runRef, eventMeta = activeEventMeta) {
  return calculateLiveRunAverage(driver, runRef, {
    activeRoles: getActiveJudgeRoles(eventMeta),
    categoryJudging: usesCategoryJudging(eventMeta),
  });
}

function parseAdminJudgeRoleChoice(inputValue, activeRoles) {
  if (!inputValue) return null;
  const normalized = String(inputValue).trim().toLowerCase();
  if (!normalized) return null;
  if (activeRoles.includes(normalized)) return normalized;
  const numeric = Number.parseInt(normalized, 10);
  if (Number.isFinite(numeric)) {
    const mappedRole = `j${numeric}`;
    if (activeRoles.includes(mappedRole)) return mappedRole;
  }
  const matchedRole = activeRoles.find((role) => getRoleDisplayName(role).toLowerCase() === normalized);
  return matchedRole || null;
}

function parseAdminRunChoice(inputValue, includeRunoff = false) {
  if (!inputValue) return null;
  const normalized = String(inputValue).trim().toLowerCase();
  if (!normalized) return null;
  if (normalized === "1" || normalized === "run1" || normalized === "run 1" || normalized === "r1") return "run1";
  if (normalized === "2" || normalized === "run2" || normalized === "run 2" || normalized === "r2") return "run2";
  if (includeRunoff && (normalized === "3" || normalized === "runoff" || normalized === "top runoff")) return "runoff";
  return null;
}

function getAdminScoreRunLabel(runKey) {
  return runKey === "run1" ? "Run 1" : runKey === "run2" ? "Run 2" : "Runoff";
}

function getAdminScoreEditDriver() {
  return appDrivers.find((entry) => entry.id === adminScoreEditDriverId) || null;
}

function hideAdminScoreEditModal() {
  closeModal(adminScoreEditModal);
  adminScoreEditDriverId = null;
  if (adminScoreEditError) adminScoreEditError.style.display = "none";
  if (adminScoreValueInput) adminScoreValueInput.value = "";
}

function syncAdminScoreEditModal() {
  const driver = getAdminScoreEditDriver();
  if (!driver || !adminScoreEditModal) return;
  const activeRoles = getActiveJudgeRoles(activeEventMeta);
  const existingRoleValue = adminScoreJudgeSelect?.value || activeRoles[0] || "";
  if (adminScoreJudgeSelect) {
    adminScoreJudgeSelect.innerHTML = activeRoles.map((role) => `<option value="${role}">${escapeHtml(getRoleDisplayName(role))}</option>`).join("");
    adminScoreJudgeSelect.value = activeRoles.includes(existingRoleValue) ? existingRoleValue : (activeRoles[0] || "");
  }
  const selectedRole = adminScoreJudgeSelect?.value || activeRoles[0] || "";
  const showRunoffOption = Boolean(driver?.scores?.[selectedRole]?.runoff !== null || driver?.scores?.[selectedRole]?.submitted?.runoff !== null);
  const availableRuns = [
    { value: "run1", label: "Run 1" },
    { value: "run2", label: "Run 2" },
    ...(showRunoffOption ? [{ value: "runoff", label: "Runoff" }] : []),
  ];
  const existingRunValue = adminScoreRunSelect?.value || "run1";
  if (adminScoreRunSelect) {
    adminScoreRunSelect.innerHTML = availableRuns.map((run) => `<option value="${run.value}">${run.label}</option>`).join("");
    adminScoreRunSelect.value = availableRuns.some((run) => run.value === existingRunValue) ? existingRunValue : availableRuns[0].value;
  }
  const selectedRun = adminScoreRunSelect?.value || "run1";
  const judgeScores = driver?.scores?.[selectedRole];
  const currentValue = judgeScores?.submitted?.[selectedRun] ?? judgeScores?.[selectedRun] ?? null;
  const currentAverage = selectedRun === "runoff" ? getRunAverage(driver, "runoff") : getRunAverage(driver, selectedRun === "run1" ? 1 : 2);
  const scoreCap = getJudgeScoreMax(selectedRole, activeEventMeta);
  if (adminScoreEditTitle) adminScoreEditTitle.textContent = `Edit Judge Score: ${driver.name || "Unnamed Driver"}`;
  if (adminScoreEditCopy) adminScoreEditCopy.textContent = `Correct a submitted ${getAdminScoreRunLabel(selectedRun)} score for ${getRoleDisplayName(selectedRole)}${usesCategoryJudging(activeEventMeta) ? ` (${getJudgeCategoryConfig(selectedRole, activeEventMeta).label})` : ""}.`;
  if (adminScoreEditContext) {
    adminScoreEditContext.textContent = `Current saved score: ${formatScore(currentValue)}. Live ${usesCategoryJudging(activeEventMeta) ? "total" : "average"} for ${getAdminScoreRunLabel(selectedRun)}: ${formatScore(currentAverage)}.`;
  }
  if (adminScoreValueInput) {
    adminScoreValueInput.max = String(scoreCap);
    adminScoreValueInput.value = currentValue === null ? "" : String(currentValue);
    adminScoreValueInput.placeholder = currentValue === null ? `0 - ${formatScore(scoreCap)}` : `Current: ${formatScore(currentValue)}`;
  }
  if (adminScoreEditError) {
    adminScoreEditError.textContent = `Enter a valid score from 0 to ${formatScore(scoreCap)}, or use Clear Score.`;
    adminScoreEditError.style.display = "none";
  }
}

function showAdminScoreEditModal(driverId) {
  if (!adminCanEdit()) return;
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver) return;
  const activeRoles = getActiveJudgeRoles(activeEventMeta);
  if (!activeRoles.length) {
    window.alert("No active judges are configured for this event.");
    return;
  }
  adminScoreEditDriverId = driverId;
  syncAdminScoreEditModal();
  openModal(adminScoreEditModal, adminScoreValueInput || adminScoreJudgeSelect);
}

async function commitAdminScoreEdit(clearValue = false) {
  if (!adminCanEdit()) return;
  const driver = getAdminScoreEditDriver();
  const selectedRole = adminScoreJudgeSelect?.value || "";
  const runKey = adminScoreRunSelect?.value || "run1";
  if (!driver || !selectedRole || !runKey) return;
  const judgeScores = driver?.scores?.[selectedRole];
  if (!judgeScores?.submitted) return;

  let nextValue = null;
  if (!clearValue) {
    const parsedValue = toNumber(adminScoreValueInput?.value ?? "");
    if (parsedValue === null) {
      if (adminScoreEditError) adminScoreEditError.style.display = "block";
      return;
    }
    nextValue = clampJudgeScoreValue(parsedValue, selectedRole, activeEventMeta);
  }

  judgeScores[runKey] = nextValue;
  judgeScores.submitted[runKey] = nextValue;
  if (nextValue !== null && driver.runFlags?.[runKey]) {
    driver.runFlags[runKey] = null;
  }

  if (driver.id === qualifyingFlow.currentDriverId) {
    if (isTwinTripleMode(activeEventMeta) && runKey === "run1" && haveAllActiveJudgesSubmittedRun(driver, "run1")) {
      advanceQualifyingDriver();
    } else if (runKey === "run2" && haveAllActiveJudgesSubmittedRun(driver, "run2")) {
      advanceQualifyingDriver();
    } else if (haveAllActiveJudgesSubmitted(driver)) {
      advanceQualifyingDriver();
    }
  }

  invalidateBracketFromAdminChanges();
  await publishStateImmediately();
  hideAdminScoreEditModal();
  renderDriversTable();
}

async function editJudgeScoreByAdmin(driverId) {
  showAdminScoreEditModal(driverId);
}

function getBestScore(r1Avg, r2Avg) {
  return getBestQualifyingScore(r1Avg, r2Avg);
}

function getSecondaryScore(r1Avg, r2Avg) {
  return getSecondaryQualifyingScore(r1Avg, r2Avg);
}

function createEmptyTwinCompState() {
  return {
    version: 1,
    status: "setup",
    roundNumber: 0,
    currentRoundId: null,
    teams: [],
    rounds: [],
    latestScore: null,
    winnerId: null,
    winnerName: null,
    completedAt: null,
  };
}

const CONTEST_DECISION_SECONDS = 15;
const OMT_OVERLAY_SECONDS = 7;
const WINNER_REVEAL_SECONDS = 30;

function normalizeTwinCompTeam(team, index = 0) {
  const eliminationLimit = getTwinCompEliminationLimit();
  const points = Math.max(0, Math.min(eliminationLimit, Number.parseInt(team?.eliminationPoints ?? 0, 10) || 0));
  return {
    id: String(team?.id || generateId()),
    seed: Number.isInteger(Number(team?.seed)) && Number(team.seed) > 0 ? Number(team.seed) : index + 1,
    name: String(team?.name || `Team ${index + 1}`).trim() || `Team ${index + 1}`,
    roundScores: Array.isArray(team?.roundScores) ? team.roundScores.map((score) => ({
      round: Number(score?.round || 0),
      score: Number.isFinite(Number(score?.score)) ? Number(score.score) : null,
      run1: Number.isFinite(Number(score?.run1)) ? Number(score.run1) : null,
      run2: Number.isFinite(Number(score?.run2)) ? Number(score.run2) : null,
      scoredAt: score?.scoredAt || null,
    })) : [],
    memberCount: Number.isFinite(Number(team?.memberCount || team?.teamMemberCount))
      ? Number(team.memberCount || team.teamMemberCount)
      : (Array.isArray(team?.tandemMembers) ? team.tandemMembers.length : 0),
    tandemMembers: Array.isArray(team?.tandemMembers) ? team.tandemMembers.map(String).filter(Boolean) : [],
    eliminationPoints: points,
    active: team?.active !== false && points < eliminationLimit,
    roundEliminated: Number.isInteger(Number(team?.roundEliminated)) ? Number(team.roundEliminated) : null,
  };
}

function normalizeTwinCompState(state) {
  if (!state || typeof state !== "object") return null;
  const base = createEmptyTwinCompState();
  const teams = Array.isArray(state.teams) ? state.teams.map(normalizeTwinCompTeam) : [];
  const rounds = Array.isArray(state.rounds) ? state.rounds.map((round, index) => ({
    id: String(round?.id || `round-${index + 1}`),
    number: Number.isInteger(Number(round?.number)) && Number(round.number) > 0 ? Number(round.number) : index + 1,
    status: ["live", "scored", "review", "finalized"].includes(round?.status) ? round.status : "live",
    teamIds: Array.isArray(round?.teamIds) ? round.teamIds.map(String) : [],
    currentTeamId: round?.currentTeamId ? String(round.currentTeamId) : null,
    scores: round?.scores && typeof round.scores === "object" ? round.scores : {},
    pointAssignments: Array.isArray(round?.pointAssignments) ? round.pointAssignments.map(String) : [],
    tieReviewRequired: Boolean(round?.tieReviewRequired),
    finalizedAt: round?.finalizedAt || null,
  })) : [];
  return {
    ...base,
    ...state,
    status: ["setup", "live", "round_complete", "review", "complete"].includes(state.status) ? state.status : base.status,
    roundNumber: Number.isInteger(Number(state.roundNumber)) ? Number(state.roundNumber) : rounds.length,
    currentRoundId: state.currentRoundId || null,
    teams,
    rounds,
    latestScore: state.latestScore || null,
    winnerId: state.winnerId || null,
    winnerName: state.winnerName || null,
    completedAt: state.completedAt || null,
  };
}

function getTwinCompState(state = twinCompState) {
  return normalizeTwinCompState(state) || createEmptyTwinCompState();
}

function getTwinCompCurrentRound(state = twinCompState) {
  const normalized = getTwinCompState(state);
  return normalized.rounds.find((round) => round.id === normalized.currentRoundId) || normalized.rounds[normalized.rounds.length - 1] || null;
}

function getTwinCompActiveTeams(state = twinCompState) {
  const eliminationLimit = getTwinCompEliminationLimit();
  return getTwinCompState(state).teams.filter((team) => team.active && team.eliminationPoints < eliminationLimit);
}

function syncTwinCompTeamsFromRoster() {
  const state = getTwinCompState();
  const existingById = new Map(state.teams.map((team) => [team.id, team]));
  const existingByName = new Map(state.teams.map((team) => [normalizeDriverName(team.name || ""), team]).filter(([name]) => Boolean(name)));
  const rosterTeams = getTeamTandemRosterEntries(appDrivers).map((entry, index) => {
    const leader = entry.members[0] || null;
    const teamId = leader?.id || entry.id;
    const existing = existingById.get(teamId) || existingById.get(entry.id) || existingByName.get(normalizeDriverName(entry.teamName || ""));
    return normalizeTwinCompTeam({
      ...existing,
      id: teamId,
      seed: existing?.seed || entry.signUpPosition || index + 1,
      name: String(entry.teamName || `Team ${index + 1}`).trim(),
      memberCount: entry.memberCount,
      tandemMembers: entry.memberNames,
    }, index);
  });
  const nextState = {
    ...state,
    teams: rosterTeams,
    status: state.status === "setup" && rosterTeams.length ? "setup" : state.status,
  };
  setTwinCompStateState(nextState, { syncQualifying: false });
  return twinCompState;
}

function resetDriverQualifyingScores(driver) {
  if (!driver) return;
  driver.runFlags = { run1: null, run2: null, runoff: null };
  for (const role of JUDGE_ROLE_ORDER) {
    driver.scores[role] = {
      run1: null,
      run2: null,
      runoff: null,
      submitted: { run1: null, run2: null, runoff: null },
      deductionHistory: { run1: [], run2: [], runoff: [] },
    };
  }
}

function startTwinCompRound(options = {}) {
  if (!adminCanEdit() || !isTwinTripleMode(activeEventMeta)) return false;
  syncTwinCompTeamsFromRoster();
  const state = getTwinCompState();
  const currentRound = getTwinCompCurrentRound(state);
  if (currentRound && currentRound.status !== "finalized") return false;
  const activeTeams = getTwinCompActiveTeams(state);
  if (activeTeams.length <= 1) return false;
  const orderedTeams = options.randomizeOrder ? shuffleEntries(activeTeams) : activeTeams;
  const roundNumber = (state.roundNumber || state.rounds.length || 0) + 1;
  orderedTeams.forEach((team) => resetDriverQualifyingScores(appDrivers.find((driver) => driver.id === team.id)));
  const round = {
    id: `twin-round-${roundNumber}-${Date.now()}`,
    number: roundNumber,
    status: "live",
    teamIds: orderedTeams.map((team) => team.id),
    currentTeamId: orderedTeams[0]?.id || null,
    scores: {},
    pointAssignments: [],
    tieReviewRequired: false,
    finalizedAt: null,
  };
  setTwinCompStateState({
    ...state,
    status: "live",
    roundNumber,
    currentRoundId: round.id,
    rounds: [...state.rounds, round],
  }, { syncQualifying: false });
  setQualifyingFlowState({
    currentDriverId: round.currentTeamId,
    readyRoles: {},
    started: true,
    completed: false,
  }, { syncQualifying: false });
  setJudgeLaneIndexState(0);
  return true;
}

function randomizeTwinCompRunOrder() {
  if (!adminCanEdit() || !isTwinTripleMode(activeEventMeta)) return false;
  syncTwinCompTeamsFromRoster();
  const state = getTwinCompState();
  const round = getTwinCompCurrentRound(state);
  if (!round || round.status === "finalized") {
    return startTwinCompRound({ randomizeOrder: true });
  }
  if (round.status !== "live") {
    window.alert("Finalize the current Twin Comp round before randomizing the next run order.");
    return false;
  }
  const hasLockedScores = Object.values(round.scores || {}).some((score) => Number.isFinite(Number(score?.score)));
  if (hasLockedScores) {
    window.alert("This round already has locked scores. Randomize before the first team is scored.");
    return false;
  }
  const shuffledTeamIds = shuffleEntries(round.teamIds || []);
  const nextRound = {
    ...round,
    teamIds: shuffledTeamIds,
    currentTeamId: shuffledTeamIds[0] || null,
  };
  setTwinCompStateState({
    ...state,
    rounds: state.rounds.map((entry) => entry.id === round.id ? nextRound : entry),
  }, { syncQualifying: false });
  setQualifyingFlowState({
    currentDriverId: nextRound.currentTeamId,
    readyRoles: {},
    started: true,
    completed: false,
  }, { syncQualifying: false });
  setJudgeLaneIndexState(0);
  return true;
}

function getTwinCompTeamRoundScore(teamId, round = getTwinCompCurrentRound()) {
  if (!round?.scores) return null;
  const score = round.scores[String(teamId)];
  return Number.isFinite(Number(score?.score)) ? score : null;
}

function captureTwinCompCurrentRun(driverId = qualifyingFlow?.currentDriverId) {
  if (!isTwinTripleMode(activeEventMeta) || !driverId) return false;
  const state = getTwinCompState();
  const round = getTwinCompCurrentRound(state);
  if (!round || round.status !== "live" || !round.teamIds.includes(driverId)) return false;
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver || !haveAllActiveJudgesSubmittedRun(driver, "run1")) return false;
  const run1 = getRunAverage(driver, 1);
  const run2 = null;
  const score = run1;
  if (!Number.isFinite(Number(score))) return false;
  const scoredAt = new Date().toISOString();
  const nextRound = {
    ...round,
    scores: {
      ...(round.scores || {}),
      [driverId]: { teamId: driverId, run1, run2, score, scoredAt },
    },
  };
  const scoredCount = nextRound.teamIds.filter((teamId) => getTwinCompTeamRoundScore(teamId, nextRound)).length;
  if (scoredCount >= nextRound.teamIds.length) {
    nextRound.status = "scored";
  }
  const nextTeams = state.teams.map((team) => {
    if (team.id !== driverId) return team;
    const filteredScores = (team.roundScores || []).filter((entry) => entry.round !== round.number);
    return {
      ...team,
      roundScores: [...filteredScores, { round: round.number, run1, run2, score, scoredAt }],
    };
  });
  setTwinCompStateState({
    ...state,
    status: nextRound.status === "scored" ? "round_complete" : "live",
    latestScore: { teamId: driverId, teamName: driver.name, round: round.number, run1, run2, score, scoredAt },
    rounds: state.rounds.map((entry) => entry.id === round.id ? nextRound : entry),
    teams: nextTeams,
  }, { syncQualifying: false });
  return true;
}

function getTwinCompPointCandidates(round) {
  const scores = Object.values(round?.scores || {})
    .filter((entry) => Number.isFinite(Number(entry?.score)))
    .sort((left, right) => Number(left.score) - Number(right.score));
  const pointCount = Math.max(0, Math.min(getTwinCompRoundPointCount(round), scores.length - 1));
  const base = scores.slice(0, pointCount);
  const cutoff = base.length ? Number(base[base.length - 1].score) : null;
  const tiedAtCutoff = cutoff === null ? [] : scores.filter((entry) => Number(entry.score) === cutoff);
  const tieReviewRequired = pointCount > 0 && scores.length > pointCount && tiedAtCutoff.length > 1 && scores.findIndex((entry) => Number(entry.score) === cutoff) <= pointCount - 1 && scores.filter((entry) => Number(entry.score) < cutoff).length < pointCount;
  return { baseTeamIds: base.map((entry) => entry.teamId), tieReviewRequired, cutoff };
}

function finalizeTwinCompRound(overrideTeamIds = null) {
  if (!adminCanEdit() || !isTwinTripleMode(activeEventMeta)) return false;
  const state = getTwinCompState();
  const round = getTwinCompCurrentRound(state);
  if (!round || !["scored", "review"].includes(round.status)) return false;
  const missing = round.teamIds.filter((teamId) => !getTwinCompTeamRoundScore(teamId, round));
  if (missing.length) {
    window.alert("Every active team needs a locked score before this round can be finalized.");
    return false;
  }
  const candidates = getTwinCompPointCandidates(round);
  const pointCount = getTwinCompRoundPointCount(round);
  const selectedIds = Array.isArray(overrideTeamIds) ? overrideTeamIds.map(String).filter((teamId) => round.teamIds.includes(teamId)).slice(0, pointCount) : candidates.baseTeamIds;
  if (candidates.tieReviewRequired && !Array.isArray(overrideTeamIds)) {
    const names = round.teamIds
      .filter((teamId) => Number(round.scores?.[teamId]?.score) === candidates.cutoff)
      .map((teamId) => state.teams.find((team) => team.id === teamId)?.name || "Team")
      .join(", ");
    const confirmed = window.confirm(`Tie at the elimination cutoff: ${names}. Apply elimination points to the currently selected cutoff teams as shown? Cancel to review standings first.`);
    if (!confirmed) {
      setTwinCompStateState({
        ...state,
        status: "review",
        rounds: state.rounds.map((entry) => entry.id === round.id ? { ...round, status: "review", tieReviewRequired: true } : entry),
      }, { syncQualifying: false });
      return false;
    }
  }
  const finalizedRoundNumber = round.number;
  let activeCount = 0;
  let winner = null;
  const nextTeams = state.teams.map((team) => {
    if (!selectedIds.includes(team.id) || !team.active) {
      if (team.active) {
        activeCount += 1;
        winner = team;
      }
      return team;
    }
    const eliminationLimit = getTwinCompEliminationLimit();
    const nextPoints = Math.min(eliminationLimit, Number(team.eliminationPoints || 0) + 1);
    const active = nextPoints < eliminationLimit;
    if (active) {
      activeCount += 1;
      winner = { ...team, eliminationPoints: nextPoints, active };
    }
    return {
      ...team,
      eliminationPoints: nextPoints,
      active,
      roundEliminated: active ? team.roundEliminated : (team.roundEliminated || finalizedRoundNumber),
    };
  });
  const completedAt = activeCount <= 1 ? new Date().toISOString() : null;
  setTwinCompStateState({
    ...state,
    status: completedAt ? "complete" : "setup",
    teams: nextTeams,
    rounds: state.rounds.map((entry) => entry.id === round.id ? {
      ...round,
      status: "finalized",
      pointAssignments: selectedIds,
      tieReviewRequired: candidates.tieReviewRequired,
      finalizedAt: new Date().toISOString(),
    } : entry),
    winnerId: completedAt ? winner?.id || null : null,
    winnerName: completedAt ? winner?.name || null : null,
    completedAt,
  }, { syncQualifying: false });
  setQualifyingFlowState({ currentDriverId: null, readyRoles: {}, started: true, completed: true }, { syncQualifying: false });
  return true;
}

function resetTwinCompEvent() {
  if (!adminCanEdit()) return false;
  setTwinCompStateState(null, { syncQualifying: false });
  setQualifyingFlowState(createEmptyQualifyingFlow(), { syncQualifying: false });
  getRegisteredDrivers(appDrivers).forEach(resetDriverQualifyingScores);
  return true;
}

function getTwinCompStandings(state = twinCompState) {
  return [...getTwinCompState(state).teams].sort((left, right) => {
    if (left.active !== right.active) return left.active ? -1 : 1;
    if (left.eliminationPoints !== right.eliminationPoints) return left.eliminationPoints - right.eliminationPoints;
    const leftScore = left.roundScores?.length ? Number(left.roundScores[left.roundScores.length - 1].score) : -Infinity;
    const rightScore = right.roundScores?.length ? Number(right.roundScores[right.roundScores.length - 1].score) : -Infinity;
    if (leftScore !== rightScore) return rightScore - leftScore;
    return left.seed - right.seed;
  });
}

function getTwinCompTeamAverageScore(team) {
  const scores = Array.isArray(team?.roundScores)
    ? team.roundScores
      .map((entry) => Number(entry?.score))
      .filter((score) => Number.isFinite(score))
    : [];
  if (!scores.length) return null;
  return scores.reduce((sum, score) => sum + score, 0) / scores.length;
}

function getTwinCompPodiumTeams(state = twinCompState) {
  return [...getTwinCompState(state).teams]
    .sort((left, right) => {
      const leftPoints = Number(left?.eliminationPoints || 0);
      const rightPoints = Number(right?.eliminationPoints || 0);
      if (leftPoints !== rightPoints) return leftPoints - rightPoints;
      const leftAverage = getTwinCompTeamAverageScore(left);
      const rightAverage = getTwinCompTeamAverageScore(right);
      const leftAverageSort = leftAverage === null ? -Infinity : leftAverage;
      const rightAverageSort = rightAverage === null ? -Infinity : rightAverage;
      if (leftAverageSort !== rightAverageSort) return rightAverageSort - leftAverageSort;
      const leftLatest = left.roundScores?.length ? Number(left.roundScores[left.roundScores.length - 1].score) : -Infinity;
      const rightLatest = right.roundScores?.length ? Number(right.roundScores[right.roundScores.length - 1].score) : -Infinity;
      if (leftLatest !== rightLatest) return rightLatest - leftLatest;
      return Number(left.seed || 0) - Number(right.seed || 0);
    })
    .slice(0, 3);
}

let twinPodiumRevealState = {
  signature: null,
  dismissedSignature: null,
  revealed: {},
};
let mainPodiumRevealState = {
  signature: null,
  dismissedSignature: null,
  revealed: {},
};

function getTwinCompPodiumSignature(state = twinCompState) {
  const normalized = getTwinCompState(state);
  const podiumTeams = getTwinCompPodiumTeams(normalized);
  return [
    activeEventId || "local",
    normalized.completedAt || normalized.winnerId || normalized.status,
    ...podiumTeams.map((team) => `${team?.id || "none"}:${team?.eliminationPoints ?? "-"}:${formatScore(getTwinCompTeamAverageScore(team))}`),
  ].join("|");
}

function renderTwinCompPodiumRevealButton(placeNumber, team) {
  const revealed = Boolean(twinPodiumRevealState.revealed?.[placeNumber]);
  const canReveal = placeNumber === 3
    || Boolean(twinPodiumRevealState.revealed?.[placeNumber + 1]);
  const average = getTwinCompTeamAverageScore(team);
  return `
    <button class="podium-reveal-button ${revealed ? "is-revealed" : ""}" type="button" data-action="twin-podium-reveal" data-place="${placeNumber}" ${canReveal || revealed ? "" : "disabled"}>
      <span class="podium-reveal-place">${placeNumber}${placeNumber === 1 ? "st" : placeNumber === 2 ? "nd" : "rd"} Place</span>
      ${revealed ? `
        <strong class="podium-reveal-team">${escapeHtml(team?.name || "Team")}</strong>
        <small class="podium-reveal-meta">${team?.active ? `${team.eliminationPoints || 0}/${getTwinCompEliminationLimit()} Elim` : `Eliminated R${team?.roundEliminated || "-"}`} | Avg ${formatScore(average)}</small>
      ` : `
        <strong class="podium-reveal-prompt">${canReveal ? "Click To Reveal Winner" : "Reveal Previous Place First"}</strong>
      `}
    </button>
  `;
}

function renderTwinCompPodiumRevealModal(state = twinCompState) {
  const modal = document.getElementById("twinPodiumRevealModal");
  const stage = document.getElementById("twinPodiumRevealStage");
  if (!modal || !stage) return;
  const podiumTeams = getTwinCompPodiumTeams(state);
  stage.innerHTML = [
    renderTwinCompPodiumRevealButton(1, podiumTeams[0]),
    renderTwinCompPodiumRevealButton(2, podiumTeams[1]),
    renderTwinCompPodiumRevealButton(3, podiumTeams[2]),
  ].join("");
}

function maybeOpenTwinCompPodiumReveal(state = twinCompState) {
  if (!adminCanEdit() || !isTwinTripleMode(activeEventMeta)) return;
  const normalized = getTwinCompState(state);
  if (normalized.status !== "complete" || !normalized.winnerId) return;
  const signature = getTwinCompPodiumSignature(normalized);
  if (twinPodiumRevealState.dismissedSignature === signature) return;
  if (twinPodiumRevealState.signature !== signature) {
    twinPodiumRevealState = {
      signature,
      dismissedSignature: twinPodiumRevealState.dismissedSignature,
      revealed: {},
    };
  }
  renderTwinCompPodiumRevealModal(normalized);
  openModal(document.getElementById("twinPodiumRevealModal"));
}

function isTwinCompPodiumFullyRevealed() {
  return [1, 2, 3].every((place) => Boolean(twinPodiumRevealState.revealed?.[place]));
}

function renderTwinCompPodiumCard(placeLabel, team, fallbackText, revealDelay = 0, shouldReveal = false) {
  if (!team) {
    return `
      <article class="podium-card ${shouldReveal ? "podium-reveal" : ""}" style="${shouldReveal ? `--podium-delay:${revealDelay}ms;` : ""}">
        <span>${placeLabel}</span>
        <strong>${fallbackText}</strong>
        <small>Waiting for result</small>
      </article>
    `;
  }
  const average = getTwinCompTeamAverageScore(team);
  const status = team.active ? `${team.eliminationPoints || 0}/${getTwinCompEliminationLimit()} Elim` : `Eliminated R${team.roundEliminated || "-"}`;
  return `
    <article class="podium-card ${shouldReveal ? "podium-reveal" : ""}" style="${shouldReveal ? `--podium-delay:${revealDelay}ms;` : ""}">
      <span>${placeLabel}</span>
      <strong>#${escapeHtml(team.seed || "-")} ${escapeHtml(team.name || "Team")}</strong>
      <small>${escapeHtml(status)} | Avg ${formatScore(average)}</small>
    </article>
  `;
}

function renderTwinCompStandingsList(state = twinCompState, options = {}) {
  const standings = getTwinCompStandings(state);
  if (!standings.length) return `<div class="empty-state">Add teams in registration to build Twin Comp standings.</div>`;
  const compact = Boolean(options.compact);
  const eliminationLimit = getTwinCompEliminationLimit();
  return `
    <ol class="qualifying-results-simple">
      ${standings.map((team, index) => {
        const latest = team.roundScores?.length ? team.roundScores[team.roundScores.length - 1] : null;
        const status = team.active ? `${team.eliminationPoints}/${eliminationLimit} Elim` : `Eliminated R${team.roundEliminated || "-"}`;
        return `
          <li class="${team.active ? "" : "is-dimmed"}">
            <div class="standings-row-main">
              <span class="standings-rank">${index + 1}</span>
              <span class="standings-driver-name">${escapeHtml(team.name)}</span>
              <span class="standings-score">${escapeHtml(status)}</span>
            </div>
            ${compact ? "" : `<div class="helper-text">${escapeHtml(team.tandemMembers?.length ? team.tandemMembers.join(", ") : `${team.memberCount || 1} driver${Number(team.memberCount || 1) === 1 ? "" : "s"}`)} | Latest: ${formatScore(latest?.score ?? null)}${team.active ? "" : " | Out"}</div>`}
          </li>
        `;
      }).join("")}
    </ol>
  `;
}

function renderTwinCompAdminControls(state = twinCompState) {
  if (!adminCanEdit()) return "";
  const normalized = getTwinCompState(state);
  const round = getTwinCompCurrentRound(normalized);
  const activeTeams = getTwinCompActiveTeams(normalized);
  const canStart = activeTeams.length > 1 && ["setup", "round_complete", "review"].includes(normalized.status) && (!round || round.status === "finalized");
  const canFinalize = round && ["scored", "review"].includes(round.status);
  const finalizeLabel = `Finalize Round & Apply ${getTwinCompRoundPointLabel(round)} Points`;
  return `
    <div class="button-row" style="margin-top: 14px;">
      <button class="button button-accent" type="button" data-action="twin-start-round" ${canStart ? "" : "disabled"}>${normalized.rounds.length ? "Start Next Round" : "Start Round"}</button>
      <button class="button button-secondary" type="button" data-action="twin-finalize-round" ${canFinalize ? "" : "disabled"}>${finalizeLabel}</button>
      <button class="button button-secondary" type="button" data-action="twin-sync-teams">Sync Teams From Roster</button>
      <button class="button button-danger" type="button" data-action="twin-reset">Reset Twin Comp</button>
    </div>
  `;
}

function renderTwinCompJudgePanel() {
  const queue = getQualifyingDriverQueue();
  const phase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const totalTeams = queue.length || getTwinCompActiveTeams().length || getRegisteredDrivers(appDrivers).length;
  if (phase !== "live") {
    return renderJudgeLaneStateCard(phase, totalTeams);
  }
  if (queue.length) {
    setJudgeLaneIndexState(Math.max(0, Math.min(judgeLaneIndex, queue.length - 1)));
  } else {
    setJudgeLaneIndexState(0);
  }
  const laneDriver = queue[judgeLaneIndex];
  if (!laneDriver) {
    return `<div class="empty-state">Start a Twin Comp round, then judges can score the current team here.</div>`;
  }
  return renderJudgeLaneCard(
    laneDriver,
    judgeLaneIndex,
    queue.length,
    getLiveRunAverage(laneDriver, 1),
    getLiveRunAverage(laneDriver, 2),
    new Set(),
  );
}

function renderTwinCompBoard() {
  const state = getTwinCompState();
  const round = getTwinCompCurrentRound(state);
  const currentDriver = getCurrentQualifyingDriver();
  const activeTeams = getTwinCompActiveTeams(state);
  const latest = state.latestScore;
  const winner = state.winnerName || (state.winnerId ? state.teams.find((team) => team.id === state.winnerId)?.name : null);
  const eliminationLimit = getTwinCompEliminationLimit();
  const showTwinPodium = state.teams.length >= 3 && (activeTeams.length <= 3 || state.status === "complete");
  const podiumTeams = showTwinPodium ? getTwinCompPodiumTeams(state) : [];
  const podiumSignature = podiumTeams.map((team) => `${team?.id || "none"}:${team?.eliminationPoints ?? "-"}:${formatScore(getTwinCompTeamAverageScore(team))}`).join("|");
  const shouldRevealPodium = showTwinPodium && lastPodiumSignature !== null && podiumSignature !== lastPodiumSignature;
  if (showTwinPodium) {
    lastPodiumSignature = podiumSignature;
  } else {
    lastPodiumSignature = null;
  }
  const roundScores = round?.teamIds?.map((teamId) => {
    const team = state.teams.find((entry) => entry.id === teamId);
    const score = getTwinCompTeamRoundScore(teamId, round);
    return { team, score };
  }) || [];
  const scoreRows = roundScores.map(({ team, score }) => `
    <tr>
      <td>${escapeHtml(team?.name || "Team")}</td>
      <td><strong>${formatScore(score?.score ?? null)}</strong></td>
      <td>${team?.eliminationPoints ?? 0}/${eliminationLimit}</td>
      <td>${score ? "Locked" : "Waiting"}${team?.memberCount ? ` | ${team.memberCount} drivers` : ""}</td>
    </tr>
  `).join("");
  const pointCount = getTwinCompRoundPointCount(round || activeTeams.length);
  const pointLabel = getTwinCompRoundPointLabel(round || activeTeams.length);
  const tiedReview = round?.tieReviewRequired ? `<div class="command-center-note warning">Tie detected around the ${pointLabel} cutoff. Admin review is required before applying elimination points.</div>` : "";
  const adminBoardControls = adminCanEdit() ? `
    <div class="command-center-note">
      <strong>${state.status === "round_complete" ? "Finalize This Round" : round?.status === "finalized" && state.status !== "complete" ? "Start Next Round" : "Twin Comp Control"}</strong><br>
      ${state.status === "round_complete"
        ? `All teams are locked for Round ${round?.number || "-"}. Finalize to apply ${pointLabel} elimination points, then start the next round.`
        : round?.status === "finalized" && state.status !== "complete"
          ? `Round ${round?.number || "-"} is finalized. Start the next round when ready.`
          : `Run each active team once, then finalize the round to apply ${pointLabel} elimination points.`}
      ${renderTwinCompAdminControls(state)}
    </div>
  ` : "";

  document.getElementById("summaryStrip").innerHTML = `
    <article class="summary-card"><span>Mode</span><strong>Twin Comp</strong></article>
    <article class="summary-card"><span>Round</span><strong>${round?.number || Math.max(state.roundNumber || 0, 1)}</strong></article>
    <article class="summary-card"><span>Active Teams</span><strong>${activeTeams.length}</strong></article>
    <article class="summary-card"><span>Latest Score</span><strong>${latest ? `${escapeHtml(latest.teamName)} ${formatScore(Number(latest.score))}` : "-"}</strong></article>
  `;
  document.getElementById("battleFlowPanel")?.classList.remove("hidden");
  const battleFlowStatus = document.getElementById("battleFlowStatus");
  if (battleFlowStatus) battleFlowStatus.textContent = state.status === "complete" ? "Complete" : `${getTwinCompEliminationLimit()}x Elim`;
  const battleFlowContent = document.getElementById("battleFlowContent");
  if (battleFlowContent) battleFlowContent.innerHTML = `
    <div class="battle-flow-empty">
      <strong>${winner ? `Winner: ${escapeHtml(winner)}` : state.status === "round_complete" ? "Round Complete - Finalize Results" : currentDriver ? `Current Team: ${escapeHtml(currentDriver.teamName || currentDriver.name || "Team")}` : "Waiting for next round"}</strong>
      <small>${round ? `Round ${round.number} | The ${pointLabel} receive 1 elimination point. Teams are eliminated at ${eliminationLimit} points.` : "Start a round after teams are added."}</small>
    </div>
    ${renderTwinCompAdminControls(state)}
  `;
  document.getElementById("competitionReviewBanner").classList.toggle("hidden", !round?.tieReviewRequired);
  document.getElementById("competitionReviewBanner").innerHTML = tiedReview;
  document.getElementById("competitionDecisionPanel").classList.add("hidden");
  const competitionJudgePanel = document.getElementById("competitionJudgePanel");
  if (currentRole?.startsWith("j")) {
    competitionJudgePanel.classList.remove("hidden");
    competitionJudgePanel.innerHTML = renderTwinCompJudgePanel();
  } else {
    competitionJudgePanel.classList.add("hidden");
    competitionJudgePanel.innerHTML = "";
  }
  document.getElementById("competitionBracketTabs").classList.add("hidden");
  document.getElementById("lowerBracketPage").classList.add("hidden");
  document.getElementById("mainBracketPage").classList.add("is-active");
  document.getElementById("mainBracketTitle").textContent = activeEventMeta?.name || getTwinCompModeTitle();
  document.getElementById("mainBracketCurrentBattle").innerHTML = currentDriver ? `<div class="battle-flow-title">${escapeHtml(currentDriver.teamName || currentDriver.name || "Team")}</div><div class="battle-flow-meta">Now Running</div>` : "";
  document.getElementById("mainBracketNextBattle").innerHTML = winner ? `<div class="battle-flow-title">${escapeHtml(winner)}</div><div class="battle-flow-meta">Winner</div>` : "";
  document.getElementById("bracketBoard").innerHTML = `
    <div class="qualifying-layout" style="width:100%;">
      <section class="panel">
        <div class="panel-header">
          <div>
            <p class="section-kicker">Round Scores</p>
            <h2>Round ${round?.number || "-"}</h2>
          </div>
        </div>
        ${adminBoardControls}
        <div class="table-wrap">
          <table>
            <thead><tr><th>Team</th><th>Score</th><th>Elim</th><th>Status</th></tr></thead>
            <tbody>${scoreRows || `<tr><td colspan="4">Start a round to score active teams.</td></tr>`}</tbody>
          </table>
        </div>
      </section>
      <aside class="qualifying-side-column">
        <section class="panel">
          <div class="panel-header"><div><p class="section-kicker">Standings</p><h2>${escapeHtml(getTwinCompEliminationLabel())}</h2></div></div>
          ${renderTwinCompStandingsList(state)}
        </section>
      </aside>
    </div>
  `;
  const championBanner = document.getElementById("championBanner");
  championBanner.classList.toggle("hidden", !showTwinPodium && !winner);
  championBanner.classList.toggle("is-revealing", shouldRevealPodium);
  championBanner.innerHTML = showTwinPodium ? `
    <span>${winner ? "Final Podium" : "Podium Watch"}</span>
    <strong>${winner ? `Winner: ${escapeHtml(winner)}` : "Last 3 Teams"}</strong>
    <div class="podium-grid">
      ${renderTwinCompPodiumCard("1st Place", podiumTeams[0], "Waiting for leader", 60, shouldRevealPodium)}
      ${renderTwinCompPodiumCard("2nd Place", podiumTeams[1], "Waiting for second", 150, shouldRevealPodium)}
      ${renderTwinCompPodiumCard("3rd Place", podiumTeams[2], "Waiting for third", 240, shouldRevealPodium)}
    </div>
    <small>Ranked by fewest elimination points. Ties use average score from completed rounds.</small>
    ${winner && adminCanEdit() ? `<div class="button-row" style="justify-content:center; margin-top:16px;"><button class="button button-accent" type="button" data-action="twin-show-podium-reveal">Reveal Podium</button></div>` : ""}
  ` : winner ? `<strong>${escapeHtml(winner)}</strong><span>Twin Comp Winner</span>` : "";
  maybeOpenTwinCompPodiumReveal(state);
  document.getElementById("emptyBracketState").classList.add("hidden");
}

function formatDateTimeForExport(value) {
  if (!value) return "Not completed";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(parsed);
}

function cloneDriver(driver) {
  return driver ? {
    id: driver.id,
    seed: driver.seed,
    name: driver.name,
    teamName: driver.teamName || "",
    chassis: driver.chassis || "",
    registrationNumber: getDriverRegistrationNumber(driver),
    signUpPosition: driver.signUpPosition,
    run1: driver.run1,
    run2: driver.run2,
    bestScore: driver.bestScore,
    memberCount: Number(driver.memberCount || driver.teamMemberCount || driver.tandemMembers?.length || 0),
    tandemBonusPoints: Number(driver.tandemBonusPoints || 0),
    tandemMembers: Array.isArray(driver.tandemMembers) ? [...driver.tandemMembers] : [],
    tandemType: driver.tandemType || null,
  } : null;
}

function cloneMatch(match) {
  return {
    left: cloneDriver(match.left),
    right: cloneDriver(match.right),
    winner: cloneDriver(match.winner),
    winnerMode: match.winnerMode ?? null,
    lockedLeft: Boolean(match.lockedLeft),
    lockedRight: Boolean(match.lockedRight),
    nextMatchIndex: match.nextMatchIndex ?? null,
    nextSlot: match.nextSlot ?? null,
  };
}

function createEmptyMatch() {
  return {
    left: null,
    right: null,
    winner: null,
    winnerMode: null,
    lockedLeft: false,
    lockedRight: false,
    nextMatchIndex: null,
    nextSlot: null,
  };
}

function getQualifierSeedValue(driver) {
  const seed = Number(driver?.seed);
  return Number.isFinite(seed) && seed > 0 ? seed : Number.POSITIVE_INFINITY;
}

function shouldLeadOver(leftDriver, rightDriver) {
  const leftSeed = getQualifierSeedValue(leftDriver);
  const rightSeed = getQualifierSeedValue(rightDriver);
  if (leftSeed !== rightSeed) return leftSeed < rightSeed;
  const leftBest = Number(leftDriver?.bestScore);
  const rightBest = Number(rightDriver?.bestScore);
  if (Number.isFinite(leftBest) && Number.isFinite(rightBest) && leftBest !== rightBest) {
    return leftBest > rightBest;
  }
  const leftRegistration = Number(getDriverRegistrationNumber(leftDriver, Number.POSITIVE_INFINITY));
  const rightRegistration = Number(getDriverRegistrationNumber(rightDriver, Number.POSITIVE_INFINITY));
  if (Number.isFinite(leftRegistration) && Number.isFinite(rightRegistration) && leftRegistration !== rightRegistration) {
    return leftRegistration < rightRegistration;
  }
  return true;
}

function orientMatchLeadChase(match) {
  const left = cloneDriver(match?.left);
  const right = cloneDriver(match?.right);
  if (!left || !right || match?.lockedLeft || match?.lockedRight) {
    return {
      ...match,
      left,
      right,
      winner: cloneDriver(match?.winner),
    };
  }
  if (shouldLeadOver(left, right)) {
    return {
      ...match,
      left,
      right,
      winner: cloneDriver(match?.winner),
    };
  }
  return {
    ...match,
    left: right,
    right: left,
    winner: cloneDriver(match?.winner),
  };
}

function participantKey(driver) {
  return driver ? `${driver.seed}-${getDriverRegistrationNumber(driver, "-")}-${driver.name}` : "";
}

function buildSlotSignature(bracketKey, roundIndex, matchIndex, side, driver) {
  return driver ? `${bracketKey}:${roundIndex}:${matchIndex}:${side}:${participantKey(driver)}` : "";
}

function clearWinnerAnimationState() {
  if (winnerAnimationTimer) {
    clearTimeout(winnerAnimationTimer);
    winnerAnimationTimer = null;
  }
  winnerAnimationState = null;
  if (winnerRevealOverlay) {
    winnerRevealOverlay.classList.add("hidden");
    winnerRevealOverlay.innerHTML = "";
  }
}

function triggerWinnerAnimation(state) {
  clearWinnerAnimationState();
  winnerAnimationState = state;
  winnerAnimationTimer = setTimeout(() => {
    winnerAnimationState = null;
    winnerAnimationTimer = null;
    if (winnerRevealOverlay) {
      winnerRevealOverlay.classList.add("hidden");
      winnerRevealOverlay.innerHTML = "";
    }
    if (document.getElementById("view-bracket")?.classList.contains("is-active")) {
      renderBracket();
    }
  }, WINNER_REVEAL_SECONDS * 1000);
}

function buildWinnerAnimationState(bracketKey, roundIndex, matchIndex, side, selectedDriver) {
  if (!selectedDriver) return null;
  const selected = {
    bracketKey,
    roundIndex,
    matchIndex,
    side,
    signature: buildSlotSignature(bracketKey, roundIndex, matchIndex, side, selectedDriver),
    name: selectedDriver.name || "Winner",
    seed: selectedDriver.seed || "",
    meta: getBracketParticipantSecondaryLine(selectedDriver),
  };
  let target = null;

  if (bracketKey === "third") {
    return { selected, target: null };
  }

  if (
    bracketKey === "lower"
    && tournamentState?.lowerBracket?.rounds
    && roundIndex === tournamentState.lowerBracket.rounds.length - 1
    && tournamentState.lowerBracket.feedsInto
  ) {
    const feed = tournamentState.lowerBracket.feedsInto;
    target = {
      bracketKey: "main",
      roundIndex: 0,
      matchIndex: feed.matchIndex,
      side: feed.side,
      signature: buildSlotSignature("main", 0, feed.matchIndex, feed.side, selectedDriver),
    };
    return { selected, target };
  }

  const rounds = bracketKey === "lower"
    ? tournamentState?.lowerBracket?.rounds
    : tournamentState?.mainBracket?.rounds;
  const match = rounds?.[roundIndex]?.matches?.[matchIndex];
  if (match && roundIndex < (rounds?.length || 0) - 1) {
    const nextMatchIndex = match.nextMatchIndex ?? Math.floor(matchIndex / 2);
    const nextSlot = match.nextSlot ?? (matchIndex % 2 === 0 ? "left" : "right");
    target = {
      bracketKey,
      roundIndex: roundIndex + 1,
      matchIndex: nextMatchIndex,
      side: nextSlot,
      signature: buildSlotSignature(bracketKey, roundIndex + 1, nextMatchIndex, nextSlot, selectedDriver),
    };
  }

  return { selected, target };
}

function triggerJudgeSubmissionFeedback(driverId, role = currentRole, runKey = "all") {
  if (!driverId || !role?.startsWith("j")) return;
  if (judgeSubmissionFeedbackTimer) {
    clearTimeout(judgeSubmissionFeedbackTimer);
  }
  judgeSubmissionFeedback = { driverId, role, runKey, stamp: Date.now() };
  judgeSubmissionFeedbackTimer = setTimeout(() => {
    judgeSubmissionFeedback = null;
    judgeSubmissionFeedbackTimer = null;
    renderDriversTable();
  }, 760);
}

function isJudgeSubmissionFeedbackActive(driverId, role = currentRole, runKey = "all") {
  return Boolean(
    judgeSubmissionFeedback
    && judgeSubmissionFeedback.driverId === driverId
    && judgeSubmissionFeedback.role === role
    && (judgeSubmissionFeedback.runKey === "all" || judgeSubmissionFeedback.runKey === runKey)
  );
}

function normalizePdfText(value) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[^\x20-\x7E]/g, "")
    .trim();
}

function escapePdfText(value) {
  return normalizePdfText(value)
    .replaceAll("\\", "\\\\")
    .replaceAll("(", "\\(")
    .replaceAll(")", "\\)");
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("Unable to read blob as data URL."));
    reader.readAsDataURL(blob);
  });
}

async function getResultsPdfLogoDataUrl() {
  if (!resultsPdfLogoDataUrlPromise) {
    resultsPdfLogoDataUrlPromise = (async () => {
      try {
        const response = await fetch(CLIENT_BRANDING.logoPrimary || "./assets/rcdriftsync-logo-transparent.png", { cache: "force-cache" });
        if (!response.ok) throw new Error(`Logo request failed with ${response.status}`);
        const blob = await response.blob();
        return await blobToDataUrl(blob);
      } catch (error) {
        console.warn("Results PDF logo unavailable", error);
        return null;
      }
    })();
  }
  return await resultsPdfLogoDataUrlPromise;
}

function padPdfCell(value, width, align = "left") {
  const text = normalizePdfText(value);
  const clipped = text.length > width ? `${text.slice(0, Math.max(width - 3, 0))}...` : text;
  return align === "right" ? clipped.padStart(width, " ") : clipped.padEnd(width, " ");
}

function buildResultsPdfLines(eventMeta, results, rankedDrivers) {
  const lines = [];
  const addLine = (line = "") => lines.push(normalizePdfText(line));
  const addSeparator = (length = 96) => addLine("-".repeat(length));
  const rankedLookup = new Map(rankedDrivers.map((driver) => [`${driver.seed}:${driver.name}`, driver]));
  const resolvePlacedDriver = (seed, name) => {
    if (!seed || !name) return null;
    return rankedLookup.get(`${seed}:${name}`) || { seed, name, bestScore: null, teamName: "" };
  };
  const formatPlacedDriverLine = (label, seed, name, fallback) => {
    const driver = resolvePlacedDriver(seed, name);
    if (!driver) return `${label}: ${fallback}`;
    const teamText = driver.teamName?.trim() ? ` | Team ${driver.teamName.trim()}` : "";
    return `${label}: #${driver.seed} ${driver.name} | Qual ${formatScore(driver.bestScore ?? null)}${teamText}`;
  };

  addLine((CLIENT_BRANDING.pdfHeaderTitle || CLIENT_BRANDING.venueName || "RC DRIFT SYNC").toUpperCase());
  addLine("COMPETITION RESULTS");
  addSeparator();
  addLine(`Event: ${eventMeta.name || "Event Results"}`);
  addLine(`Date: ${formatEventDate(eventMeta.date)}`);
  addLine(`Format: ${results.planDescription || "Waiting for qualifying scores."}`);
  addLine(`Total Drivers: ${results.totalDrivers || rankedDrivers.length || 0}`);
  addLine(`Qualified Drivers: ${results.qualifiedCount || 0}`);
  addLine(`Completed: ${formatDateTimeForExport(results.completedAt || results.updatedAt)}`);
  addLine("");
  addLine("TOP RESULTS");
  addSeparator();
  addLine(formatPlacedDriverLine("1st Place", results.championSeed, results.championName, "Waiting for winner"));
  addLine(formatPlacedDriverLine("2nd Place", results.runnerUpSeed, results.runnerUpName, "Waiting for finalist"));
  addLine(formatPlacedDriverLine("3rd Place", results.thirdPlaceSeed, results.thirdPlaceName, "Waiting for 3rd place battle"));
  addLine(formatPlacedDriverLine("4th Place", results.fourthPlaceSeed, results.fourthPlaceName, "Waiting for 4th place result"));
  addLine("");
  addLine("QUALIFYING STANDINGS");
  addSeparator();

  const tableHeader = [
    padPdfCell("POS", 4),
    padPdfCell("REG", 5),
    padPdfCell("DRIVER", 24),
    padPdfCell("TEAM", 18),
    padPdfCell("CHASSIS", 14),
    padPdfCell("RUN1", 6, "right"),
    padPdfCell("RUN2", 6, "right"),
    padPdfCell("BEST", 6, "right"),
  ].join(" ");

  addLine(tableHeader);
  addSeparator();

  if (!rankedDrivers.length) {
    addLine("No standings available yet.");
  } else {
    rankedDrivers.forEach((driver, index) => {
      const run1 = driver.run1 ?? null;
      const run2 = driver.run2 ?? null;
      const best = driver.bestScore ?? getBestScore(run1, run2);
      addLine([
        padPdfCell(index + 1, 4),
        padPdfCell(formatDriverRegistrationNumber(driver), 5),
        padPdfCell(driver.name || "Unnamed Driver", 24),
        padPdfCell(driver.teamName || "-", 18),
        padPdfCell(driver.chassis || "-", 14),
        padPdfCell(formatScore(run1), 6, "right"),
        padPdfCell(formatScore(run2), 6, "right"),
        padPdfCell(formatScore(best), 6, "right"),
      ].join(" "));
    });
  }

  addLine("");
  addLine(`Generated ${formatDateTimeForExport(new Date().toISOString())}`);
  return { lines, tableHeader };
}

function buildPdfFromTextPagesLegacy(pages) {
  const pageWidth = 595.28;
  const pageHeight = 841.89;
  const marginLeft = 36;
  const marginTop = 44;
  const lineHeight = 13;

  const objects = [];
  const pushObject = (content) => {
    objects.push(content);
    return objects.length;
  };

  const pagesId = pushObject("");
  const fontId = pushObject("<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>");
  const pageIds = [];

  pages.forEach((lines) => {
    const commands = lines.map((line, index) => {
      const y = pageHeight - (marginTop + (index * lineHeight));
      return `BT\n/F1 10 Tf\n1 0 0 1 ${marginLeft.toFixed(2)} ${y.toFixed(2)} Tm\n(${escapePdfText(line)}) Tj\nET`;
    }).join("\n");
    const stream = `${commands}\n`;
    const contentId = pushObject(`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);
    const pageId = pushObject(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`);
    pageIds.push(pageId);
  });

  objects[pagesId - 1] = `<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] >>`;
  const catalogId = pushObject(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((object, index) => {
    offsets.push(pdf.length);
    pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
  });
  const xrefOffset = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += "0000000000 65535 f \n";
  offsets.slice(1).forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root ${catalogId} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return new Blob([pdf], { type: "application/pdf" });
}

function buildPdfFromTextPages(pages) {
  const JsPdfCtor = window?.jspdf?.jsPDF;
  if (!JsPdfCtor) {
    return buildPdfFromTextPagesLegacy(pages);
  }

  try {
    const doc = new JsPdfCtor({
      orientation: "portrait",
      unit: "pt",
      format: "letter",
      compress: true,
    });
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const marginLeft = 36;
    const marginTop = 44;
    const lineHeight = 13;

    doc.setFont("courier", "normal");
    doc.setFontSize(10);

    pages.forEach((lines, pageIndex) => {
      if (pageIndex > 0) doc.addPage("letter", "portrait");
      lines.forEach((line, lineIndex) => {
        const y = marginTop + (lineIndex * lineHeight);
        if (y > pageHeight - 36) return;
        doc.text(String(line ?? ""), marginLeft, y, {
          baseline: "alphabetic",
          maxWidth: pageWidth - (marginLeft * 2),
        });
      });
    });

    return doc.output("blob");
  } catch (error) {
    console.warn("jsPDF generation failed, falling back to legacy PDF builder", error);
    return buildPdfFromTextPagesLegacy(pages);
  }
}

async function buildResultsPdfBlob(eventMeta, results, rankedDrivers) {
  const JsPdfCtor = window?.jspdf?.jsPDF;
  if (!JsPdfCtor) {
    const { lines, tableHeader } = buildResultsPdfLines(eventMeta, results, rankedDrivers);
    const maxLinesPerPage = 54;
    const pages = [];
    let pageLines = [];
    let standingsContinued = false;

    const flushPage = () => {
      if (pageLines.length) pages.push(pageLines);
      pageLines = [];
    };

    lines.forEach((line) => {
      if (pageLines.length >= maxLinesPerPage) {
        flushPage();
        if (standingsContinued) {
          pageLines.push("QUALIFYING STANDINGS (CONT.)");
          pageLines.push("-".repeat(96));
          pageLines.push(tableHeader);
          pageLines.push("-".repeat(96));
        }
      }
      pageLines.push(line);
      if (line === "QUALIFYING STANDINGS") standingsContinued = true;
    });
    flushPage();
    return buildPdfFromTextPages(pages);
  }

  const doc = new JsPdfCtor({
    orientation: "portrait",
    unit: "pt",
    format: "letter",
    compress: true,
  });

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const marginX = 38;
  const contentWidth = pageWidth - (marginX * 2);
  const footerY = pageHeight - 22;
  const cardGap = 12;
  const sectionGap = 18;
  const logoDataUrl = await getResultsPdfLogoDataUrl();
  const generatedAtLabel = formatDateTimeForExport(new Date().toISOString());
  let cursorY = 34;

  const truncatePdfWidth = (value, width) => {
    const safe = normalizePdfText(value || "-");
    if (!safe) return "-";
    if (doc.getTextWidth(safe) <= width) return safe;
    let base = safe;
    while (base.length > 1 && doc.getTextWidth(`${base}...`) > width) {
      base = base.slice(0, -1);
    }
    return `${base}...`;
  };

  const drawSectionHeader = (title) => {
    doc.setFillColor(10, 10, 10);
    doc.roundedRect(marginX, cursorY, contentWidth, 22, 8, 8, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.text(normalizePdfText(title).toUpperCase(), marginX + 12, cursorY + 14);
    cursorY += 32;
  };

  const drawInfoCard = (x, y, w, h, label, value) => {
    doc.setDrawColor(24, 24, 24);
    doc.setFillColor(252, 252, 252);
    doc.roundedRect(x, y, w, h, 10, 10, "FD");
    doc.setTextColor(110, 110, 110);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.text(normalizePdfText(label).toUpperCase(), x + 12, y + 16);
    doc.setTextColor(18, 18, 18);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    const lines = doc.splitTextToSize(normalizePdfText(value || "-"), w - 24).slice(0, 2);
    lines.forEach((line, lineIndex) => {
      doc.text(line, x + 12, y + 34 + (lineIndex * 14));
    });
  };

  const drawPodiumCard = (x, y, w, h, place, driver, fallback) => {
    doc.setDrawColor(20, 20, 20);
    doc.setFillColor(place === "1st Place" ? 245 : 251, place === "1st Place" ? 245 : 251, place === "1st Place" ? 245 : 251);
    doc.roundedRect(x, y, w, h, 12, 12, "FD");
    doc.setTextColor(95, 95, 95);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.text(normalizePdfText(place).toUpperCase(), x + 12, y + 16);
    doc.setTextColor(12, 12, 12);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    const primary = driver
      ? `#${driver.seed} ${normalizePdfText(driver.name)}`
      : normalizePdfText(fallback);
    doc.text(doc.splitTextToSize(primary, w - 24).slice(0, 2), x + 12, y + 34);
    doc.setTextColor(110, 110, 110);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    const secondary = driver?.teamName?.trim()
      ? `Team ${normalizePdfText(driver.teamName.trim())}`
      : driver
        ? `Qual ${formatScore(driver.bestScore ?? null)}`
        : "Waiting for result";
    const tertiary = driver?.teamName?.trim()
      ? `Qual ${formatScore(driver.bestScore ?? null)}`
      : "";
    doc.text(doc.splitTextToSize(secondary, w - 24).slice(0, 2), x + 12, y + h - 28);
    if (tertiary) {
      doc.text(doc.splitTextToSize(tertiary, w - 24).slice(0, 1), x + 12, y + h - 14);
    }
  };

  const rowHeights = {
    header: 24,
    body: 22,
  };
  const tableColumns = [
    { key: "pos", label: "Pos", width: 28, align: "center" },
    { key: "reg", label: "Reg", width: 34, align: "center" },
    { key: "driver", label: "Driver", width: 148, align: "left" },
    { key: "team", label: "Team", width: 96, align: "left" },
    { key: "chassis", label: "Chassis", width: 92, align: "left" },
    { key: "run1", label: "Run 1", width: 44, align: "right" },
    { key: "run2", label: "Run 2", width: 44, align: "right" },
    { key: "best", label: "Best", width: 44, align: "right" },
  ];

  const drawTableHeader = () => {
    let x = marginX;
    doc.setFillColor(14, 14, 14);
    doc.roundedRect(marginX, cursorY, contentWidth, rowHeights.header, 8, 8, "F");
    tableColumns.forEach((column) => {
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8.5);
      const textX = column.align === "right"
        ? x + column.width - 8
        : column.align === "center"
          ? x + (column.width / 2)
          : x + 8;
      doc.text(column.label.toUpperCase(), textX, cursorY + 15, {
        align: column.align === "right" ? "right" : column.align === "center" ? "center" : "left",
      });
      x += column.width;
    });
    cursorY += rowHeights.header + 8;
  };

  const drawTableRow = (row, rowIndex) => {
    let x = marginX;
    doc.setDrawColor(222, 222, 222);
    doc.setFillColor(rowIndex % 2 === 0 ? 253 : 245, rowIndex % 2 === 0 ? 253 : 245, rowIndex % 2 === 0 ? 253 : 245);
    doc.roundedRect(marginX, cursorY, contentWidth, rowHeights.body, 6, 6, "FD");
    tableColumns.forEach((column) => {
      const rawText = row[column.key] ?? "-";
      doc.setTextColor(18, 18, 18);
      doc.setFont("helvetica", column.key === "driver" ? "bold" : "normal");
      doc.setFontSize(9);
      const availableWidth = column.width - 14;
      const displayText = truncatePdfWidth(rawText, availableWidth);
      const textX = column.align === "right"
        ? x + column.width - 7
        : column.align === "center"
          ? x + (column.width / 2)
          : x + 7;
      doc.text(displayText, textX, cursorY + 14, {
        align: column.align === "right" ? "right" : column.align === "center" ? "center" : "left",
      });
      x += column.width;
    });
    cursorY += rowHeights.body + 6;
  };

  const beginNewPage = (repeatStandingsHeader = false) => {
    doc.addPage("letter", "portrait");
    cursorY = 30;
    doc.setDrawColor(222, 222, 222);
    doc.line(marginX, cursorY + 36, pageWidth - marginX, cursorY + 36);
    if (logoDataUrl) {
      try {
        const props = doc.getImageProperties(logoDataUrl);
        const ratio = props.width / props.height;
        const logoW = 138;
        const logoH = logoW / ratio;
        doc.addImage(logoDataUrl, "PNG", marginX, cursorY, logoW, logoH, undefined, "FAST");
      } catch (error) {
        console.warn("Unable to add results PDF logo on additional page", error);
      }
    }
    doc.setTextColor(30, 30, 30);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.text(normalizePdfText(eventMeta.name || "Competition Results"), pageWidth - marginX, cursorY + 16, { align: "right" });
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(110, 110, 110);
    doc.text("Qualifying Standings", pageWidth - marginX, cursorY + 30, { align: "right" });
    cursorY += 52;
    if (repeatStandingsHeader) {
      drawSectionHeader("Qualifying Standings");
      drawTableHeader();
    }
  };

  if (logoDataUrl) {
    try {
      const props = doc.getImageProperties(logoDataUrl);
      const ratio = props.width / props.height;
      const logoW = Math.min(220, contentWidth * 0.45);
      const logoH = logoW / ratio;
      doc.addImage(logoDataUrl, "PNG", (pageWidth - logoW) / 2, cursorY, logoW, logoH, undefined, "FAST");
      cursorY += logoH + 12;
    } catch (error) {
      console.warn("Unable to add results PDF logo", error);
      cursorY += 12;
    }
  }

  doc.setTextColor(12, 12, 12);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);
  doc.text("Competition Results", pageWidth / 2, cursorY, { align: "center" });
  cursorY += 16;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.setTextColor(110, 110, 110);
  doc.text(normalizePdfText(formatEventDate(eventMeta.date)), pageWidth / 2, cursorY, { align: "center" });
  cursorY += 16;
  doc.setDrawColor(22, 22, 22);
  doc.line(marginX, cursorY, pageWidth - marginX, cursorY);
  cursorY += sectionGap;

  drawSectionHeader("Event Summary");
  const summaryCards = [
    ["Event", eventMeta.name || "Event Results"],
    ["Date", formatEventDate(eventMeta.date)],
    ["Format", results.planDescription || "Waiting for qualifying scores."],
    ["Completed", formatDateTimeForExport(results.completedAt || results.updatedAt)],
    ["Total Drivers", String(results.totalDrivers || rankedDrivers.length || 0)],
    ["Qualified Drivers", String(results.qualifiedCount || 0)],
  ];
  const summaryCardWidth = (contentWidth - cardGap) / 2;
  const summaryCardHeight = 56;
  summaryCards.forEach(([label, value], index) => {
    const col = index % 2;
    const row = Math.floor(index / 2);
    drawInfoCard(
      marginX + (col * (summaryCardWidth + cardGap)),
      cursorY + (row * (summaryCardHeight + 10)),
      summaryCardWidth,
      summaryCardHeight,
      label,
      value,
    );
  });
  cursorY += (Math.ceil(summaryCards.length / 2) * (summaryCardHeight + 10)) - 10 + sectionGap;

  drawSectionHeader("Top Results");
  const rankedLookup = new Map(rankedDrivers.map((driver) => [`${driver.seed}:${driver.name}`, driver]));
  const podiumCards = [
    ["1st Place", results.championName ? (rankedLookup.get(`${results.championSeed}:${results.championName}`) || { seed: results.championSeed, name: results.championName, bestScore: null, teamName: "" }) : null, "Waiting for winner"],
    ["2nd Place", results.runnerUpName ? (rankedLookup.get(`${results.runnerUpSeed}:${results.runnerUpName}`) || { seed: results.runnerUpSeed, name: results.runnerUpName, bestScore: null, teamName: "" }) : null, "Waiting for finalist"],
    ["3rd Place", results.thirdPlaceName ? (rankedLookup.get(`${results.thirdPlaceSeed}:${results.thirdPlaceName}`) || { seed: results.thirdPlaceSeed, name: results.thirdPlaceName, bestScore: null, teamName: "" }) : null, "Waiting for 3rd place battle"],
    ["4th Place", results.fourthPlaceName ? (rankedLookup.get(`${results.fourthPlaceSeed}:${results.fourthPlaceName}`) || { seed: results.fourthPlaceSeed, name: results.fourthPlaceName, bestScore: null, teamName: "" }) : null, "Waiting for 4th place result"],
  ];
  const podiumWidth = (contentWidth - cardGap) / 2;
  const podiumHeight = 84;
  podiumCards.forEach(([place, driver, fallback], index) => {
    const col = index % 2;
    const row = Math.floor(index / 2);
    drawPodiumCard(
      marginX + (col * (podiumWidth + cardGap)),
      cursorY + (row * (podiumHeight + 10)),
      podiumWidth,
      podiumHeight,
      place,
      driver,
      fallback,
    );
  });
  cursorY += (Math.ceil(podiumCards.length / 2) * (podiumHeight + 10)) - 10 + sectionGap;

  drawSectionHeader("Qualifying Standings");
  drawTableHeader();

  const tableRows = rankedDrivers.length
    ? rankedDrivers.map((driver, index) => {
        const run1 = driver.run1 ?? null;
        const run2 = driver.run2 ?? null;
        const best = driver.bestScore ?? getBestScore(run1, run2);
        return {
          pos: String(index + 1),
          reg: formatDriverRegistrationNumber(driver),
          driver: normalizePdfText(driver.name || "Unnamed Driver"),
          team: normalizePdfText(driver.teamName || "-"),
          chassis: normalizePdfText(driver.chassis || "-"),
          run1: formatScore(run1),
          run2: formatScore(run2),
          best: formatScore(best),
        };
      })
    : [{
        pos: "-",
        reg: "-",
        driver: "No standings available yet.",
        team: "-",
        chassis: "-",
        run1: "-",
        run2: "-",
        best: "-",
      }];

  tableRows.forEach((row, index) => {
    if (cursorY + rowHeights.body + 28 > footerY) {
      beginNewPage(true);
    }
    drawTableRow(row, index);
  });

  const pageCount = doc.getNumberOfPages();
  for (let pageIndex = 1; pageIndex <= pageCount; pageIndex += 1) {
    doc.setPage(pageIndex);
    doc.setDrawColor(224, 224, 224);
    doc.line(marginX, footerY - 8, pageWidth - marginX, footerY - 8);
    doc.setTextColor(110, 110, 110);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(`Generated ${generatedAtLabel}`, marginX, footerY);
    doc.text(`Page ${pageIndex} of ${pageCount}`, pageWidth - marginX, footerY, { align: "right" });
  }

  return doc.output("blob");
}

function triggerPdfDownload(blob, fileName) {
  if (!blob) return false;
  const previewShown = showPdfPreview(
    blob,
    fileName,
    prefersPdfPreviewModal()
      ? "The PDF was generated successfully. Use Download PDF or Open PDF below."
      : "The PDF was generated successfully. Use Download PDF or Open PDF below."
  );
  if (!prefersPdfPreviewModal()) {
    startDirectBlobDownload(blob, fileName);
  }
  return previewShown;
}

async function exportResultsPdf() {
  try {
    if (!activeEventMeta) {
      window.alert("Select an event before exporting results.");
      return;
    }
    const liveResults = buildEventResults();
    const results = {
      ...(activeEventMeta.results || buildEmptyEventResults()),
      ...liveResults,
    };
    const rankedDrivers = rankDrivers(appDrivers);
    const blob = await buildResultsPdfBlob(activeEventMeta, results, rankedDrivers);
    if (!(blob instanceof Blob) || !blob.size) {
      window.alert("The PDF file could not be generated for this event.");
      return;
    }
    const safeFileName = `${(activeEventMeta.name || "event-results").replace(/[<>:"/\\|?*]+/g, "").trim().replace(/\s+/g, "-").toLowerCase() || "event-results"}-results.pdf`;
    const downloadStarted = triggerPdfDownload(blob, safeFileName);
    if (!downloadStarted) {
      window.alert("PDF export could not start on this browser yet.");
    }
  } catch (error) {
    console.error("Results PDF export failed", error);
    window.alert(`Results PDF export failed: ${error?.message || "Unknown error"}`);
  }
}

function nextPowerOfTwo(value) {
  return nextPowerOfTwoValue(value);
}

function previousPowerOfTwo(value) {
  return previousPowerOfTwoValue(value);
}

function getRoundName(size) {
  return getBracketRoundName(size);
}

function getBracketSeedOrder(bracketSize) {
  return getSeedOrderForBracket(bracketSize);
}

function createRoundShells(bracketSize) {
  const rounds = [];
  for (let size = bracketSize; size >= 2; size /= 2) {
    rounds.push({
      name: getRoundName(size),
      matches: Array.from({ length: size / 2 }, () => createEmptyMatch()),
    });
  }
  return rounds;
}

function createRoundsFromOpeningMatches(bracketSize, openingMatches) {
  const rounds = createRoundShells(bracketSize);
  rounds[0].matches = openingMatches.map(cloneMatch);
  return rounds;
}

function rankDrivers(driversStateList) {
  return rankDriversByQualifying(driversStateList, {
    normalizeDrivers: normalizeDriverList,
    getRegistrationNumber: getDriverRegistrationNumber,
    activeRoles: getActiveJudgeRoles(activeEventMeta),
    categoryJudging: usesCategoryJudging(activeEventMeta),
  });
}

function getEnteredDriverCount(driversStateList) {
  return (Array.isArray(driversStateList) ? driversStateList : []).filter((driver) => {
    return driverHasMeaningfulEntry(driver);
  }).length;
}

function createStandardOpeningMatches(drivers, bracketSize) {
  const seedOrder = getBracketSeedOrder(bracketSize);
  const slots = seedOrder.map((seedNumber) => cloneDriver(drivers[seedNumber - 1] ?? null));
  const matches = [];
  for (let index = 0; index < bracketSize / 2; index += 1) {
    matches.push(orientMatchLeadChase({ left: slots[index * 2], right: slots[index * 2 + 1], winner: null }));
  }
  return matches;
}

function createHighVsLowOpeningMatches(drivers, bracketSize) {
  const matches = [];
  for (let matchIndex = 0; matchIndex < bracketSize / 2; matchIndex += 1) {
    const leftDriver = cloneDriver(drivers[matchIndex] ?? null);
    const rightDriver = cloneDriver(drivers[bracketSize - 1 - matchIndex] ?? null);
    matches.push(orientMatchLeadChase({ left: leftDriver, right: rightDriver, winner: null }));
  }
  return matches;
}

function createSeededOpeningMatches(seedAssignments, bracketSize) {
  const seedOrder = getBracketSeedOrder(bracketSize);
  const slots = seedOrder.map((seedNumber) => cloneDriver(seedAssignments[seedNumber] ?? null));
  const matches = [];
  for (let index = 0; index < bracketSize / 2; index += 1) {
    matches.push(orientMatchLeadChase({ left: slots[index * 2], right: slots[index * 2 + 1], winner: null }));
  }
  return matches;
}

function findFeedTarget(openingMatches) {
  for (let matchIndex = 0; matchIndex < openingMatches.length; matchIndex += 1) {
    const match = openingMatches[matchIndex];
    if (!match.left) return { matchIndex, side: "left" };
    if (!match.right) return { matchIndex, side: "right" };
  }
  return { matchIndex: 0, side: "right" };
}

function getSdcPlayInSeed(bracketSize) {
  return Math.max(2, bracketSize - 1);
}

function isSdcFormat(format) {
  return [
    FORMAT_SDC,
    FORMAT_SDC_TOP_8,
    FORMAT_SDC_TOP_16,
    FORMAT_SDC_TOP_32,
  ].includes(format);
}

function getRequestedSdcMainBracketSize(format) {
  if (format === FORMAT_SDC_TOP_8) return 8;
  if (format === FORMAT_SDC_TOP_16) return 16;
  if (format === FORMAT_SDC_TOP_32) return 32;
  return null;
}

function getSdcFeedTarget(bracketSize) {
  const seedOrder = getBracketSeedOrder(bracketSize);
  const playInSeed = getSdcPlayInSeed(bracketSize);
  for (let matchIndex = 0; matchIndex < bracketSize / 2; matchIndex += 1) {
    const leftSeed = seedOrder[matchIndex * 2];
    const rightSeed = seedOrder[matchIndex * 2 + 1];
    if (leftSeed === playInSeed) return { matchIndex, side: "left" };
    if (rightSeed === playInSeed) return { matchIndex, side: "right" };
  }
  return { matchIndex: 0, side: "right" };
}

function createSdcMainOpeningMatches(directDrivers, bracketSize) {
  const seedAssignments = {};
  for (let seed = 1; seed <= bracketSize - 2; seed += 1) {
    seedAssignments[seed] = directDrivers[seed - 1] ?? null;
  }
  seedAssignments[bracketSize] = directDrivers[bracketSize - 2] ?? null;

  const matches = createSeededOpeningMatches(seedAssignments, bracketSize);
  return {
    matches,
    feedTarget: getSdcFeedTarget(bracketSize),
  };
}

function createSdc24MainBracket(directDrivers) {
  const seedMap = {};
  for (let seed = 1; seed <= 22; seed += 1) {
    seedMap[seed] = cloneDriver(directDrivers[seed - 1] ?? null);
  }
  seedMap[24] = cloneDriver(directDrivers[22] ?? null);

  const rounds = [
    {
      name: "Top 24",
      matches: [
        orientMatchLeadChase({ left: seedMap[9], right: seedMap[24], winner: null, winnerMode: null, nextMatchIndex: 1, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        orientMatchLeadChase({ left: seedMap[12], right: seedMap[21], winner: null, winnerMode: null, nextMatchIndex: 3, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        orientMatchLeadChase({ left: seedMap[13], right: seedMap[20], winner: null, winnerMode: null, nextMatchIndex: 2, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        orientMatchLeadChase({ left: seedMap[16], right: seedMap[17], winner: null, winnerMode: null, nextMatchIndex: 0, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        { left: seedMap[10], right: null, winner: null, winnerMode: null, nextMatchIndex: 5, nextSlot: "right", lockedLeft: false, lockedRight: false },
        orientMatchLeadChase({ left: seedMap[11], right: seedMap[22], winner: null, winnerMode: null, nextMatchIndex: 7, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        orientMatchLeadChase({ left: seedMap[14], right: seedMap[19], winner: null, winnerMode: null, nextMatchIndex: 6, nextSlot: "right", lockedLeft: false, lockedRight: false }),
        orientMatchLeadChase({ left: seedMap[15], right: seedMap[18], winner: null, winnerMode: null, nextMatchIndex: 4, nextSlot: "right", lockedLeft: false, lockedRight: false }),
      ],
    },
    {
      name: "Top 16",
      matches: [
        { left: seedMap[1], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[8], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[4], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[5], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[2], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[7], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[3], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
        { left: seedMap[6], right: null, winner: null, winnerMode: null, lockedLeft: true, lockedRight: false },
      ],
    },
    ...createRoundShells(8),
  ];

  return {
    rounds,
    feedTarget: { matchIndex: 4, side: "right" },
  };
}

function createLowerMainOpeningMatches(directDrivers, bracketSize) {
  const matches = [];
  let lowIndex = 0;
  let highIndex = directDrivers.length - 1;

  for (let matchIndex = 0; matchIndex < bracketSize / 2; matchIndex += 1) {
    if (matchIndex === 1) {
      matches.push({
        left: cloneDriver(directDrivers[lowIndex] ?? null),
        right: null,
        winner: null,
      });
      lowIndex += 1;
      continue;
    }

    const leftDriver = lowIndex <= highIndex ? cloneDriver(directDrivers[lowIndex]) : null;
    lowIndex += 1;
    let rightDriver = null;
    if (lowIndex <= highIndex) {
      rightDriver = cloneDriver(directDrivers[highIndex]);
      highIndex -= 1;
    }
    matches.push(orientMatchLeadChase({ left: leftDriver, right: rightDriver, winner: null }));
  }
  return matches;
}

function createSdcDirectQualifiers(limitedDrivers, mainBracketSize) {
  const playInSeed = getSdcPlayInSeed(mainBracketSize);
  const directQualifiers = limitedDrivers.slice(0, mainBracketSize - 1).map(cloneDriver);
  return directQualifiers.map((driver, index) => ({
    ...driver,
    seed: index + 1 >= playInSeed ? index + 2 : index + 1,
  }));
}

function normalizePreferredFormat(preferredFormat) {
  if (preferredFormat === FORMAT_SDC_TOP_8) return FORMAT_SDC_TOP_8;
  if (preferredFormat === FORMAT_SDC_TOP_16) return FORMAT_SDC_TOP_16;
  if (preferredFormat === FORMAT_SDC_TOP_32) return FORMAT_SDC_TOP_32;
  if (preferredFormat === FORMAT_SDC) return FORMAT_SDC_TOP_32;
  return FORMAT_CLASSIC;
}

function getValidLowerBracketCounts(fieldCount) {
  const validCounts = [];
  for (let mainBracketSize = previousPowerOfTwo(fieldCount); mainBracketSize >= 2; mainBracketSize /= 2) {
    const lowerCount = fieldCount - (mainBracketSize - 1);
    if (lowerCount >= 2 && lowerCount < fieldCount) {
      validCounts.push(lowerCount);
    }
  }
  return [...new Set(validCounts)].sort((left, right) => left - right);
}

function resolveLowerBracketCount(fieldCount, requestedCount) {
  const validCounts = getValidLowerBracketCounts(fieldCount);
  if (!validCounts.length) return { lowerBracketCount: 0, validCounts: [] };
  const fallback = validCounts[0];
  if (!requestedCount || Number.isNaN(requestedCount)) {
    return { lowerBracketCount: fallback, validCounts };
  }

  let bestCount = validCounts[0];
  let bestDistance = Math.abs(requestedCount - bestCount);
  validCounts.forEach((count) => {
    const distance = Math.abs(requestedCount - count);
    if (distance < bestDistance || (distance === bestDistance && count > bestCount)) {
      bestCount = count;
      bestDistance = distance;
    }
  });
  return { lowerBracketCount: bestCount, validCounts };
}

function getValidSdcMainBracketSizes(fieldCount) {
  const validSizes = [];
  [8, 16, 24, 32].forEach((size) => {
    if (size <= fieldCount) validSizes.push(size);
  });
  return validSizes;
}

function resolveSdcMainBracketSize(fieldCount, requestedSize) {
  const validSizes = getValidSdcMainBracketSizes(fieldCount);
  if (!validSizes.length) return { mainBracketSize: 0, validSizes: [] };
  const fallback = validSizes[validSizes.length - 1];
  if (!requestedSize || Number.isNaN(requestedSize)) {
    return { mainBracketSize: fallback, validSizes };
  }

  let bestSize = validSizes[0];
  let bestDistance = Math.abs(requestedSize - bestSize);
  validSizes.forEach((size) => {
    const distance = Math.abs(requestedSize - size);
    if (distance < bestDistance || (distance === bestDistance && size > bestSize)) {
      bestSize = size;
      bestDistance = distance;
    }
  });
  return { mainBracketSize: bestSize, validSizes };
}

function getCompetitionPlan(fieldCount, preferredFormat = FORMAT_CLASSIC, customLowerCount = 0) {
  preferredFormat = normalizePreferredFormat(preferredFormat);
  const qualifiedCount = Math.max(0, fieldCount);
  if (qualifiedCount < 2) {
    return {
      qualifiedCount, preferredFormat, resolvedFormat: FORMAT_CLASSIC,
      mainBracketSize: 0, usesLowerBracket: false, lowerBracketSize: 0,
      lowerBracketCount: 0, directMainCount: 0,
      description: "Need at least 2 scored drivers.",
    };
  }

  if (isSdcFormat(preferredFormat) && qualifiedCount >= 3) {
    const requestedMainBracketSize = getRequestedSdcMainBracketSize(preferredFormat);
    const resolution = resolveSdcMainBracketSize(qualifiedCount, requestedMainBracketSize || (customLowerCount > 0 ? customLowerCount : null));
    const mainBracketSize = resolution.mainBracketSize;
    if (!mainBracketSize) {
      return {
        qualifiedCount, preferredFormat, resolvedFormat: FORMAT_CLASSIC,
        mainBracketSize: nextPowerOfTwo(qualifiedCount), usesLowerBracket: false, lowerBracketSize: 0, lowerBracketCount: 0,
        directMainCount: qualifiedCount, validLowerCounts: [], validMainBracketSizes: [],
        description: `Need at least ${requestedMainBracketSize || 8} drivers for this SDC bracket format.`,
      };
    }
    const directMainCount = Math.max(0, mainBracketSize - 1);
    const lowerBracketCount = Math.max(0, qualifiedCount - directMainCount);
    const lowerBracketSize = lowerBracketCount <= 1 ? 2 : nextPowerOfTwo(lowerBracketCount);
    const normalizedRequested = requestedMainBracketSize && requestedMainBracketSize !== mainBracketSize;

    return {
      qualifiedCount, preferredFormat, resolvedFormat: FORMAT_SDC, mainBracketSize,
      usesLowerBracket: true, lowerBracketSize, lowerBracketCount, directMainCount,
      validMainBracketSizes: resolution.validSizes, validLowerCounts: [],
      description: normalizedRequested
        ? `SDC Top ${mainBracketSize} selected. ${lowerBracketCount} driver${lowerBracketCount === 1 ? "" : "s"} in the lower bracket; winner fills seed ${getSdcPlayInSeed(mainBracketSize)} against the #2 qualifier.`
        : `SDC Top ${mainBracketSize}. ${lowerBracketCount} driver${lowerBracketCount === 1 ? "" : "s"} in the lower bracket; winner fills seed ${getSdcPlayInSeed(mainBracketSize)} against the #2 qualifier.`,
    };
  }

  const mainBracketSize = nextPowerOfTwo(qualifiedCount);
  const byes = mainBracketSize - qualifiedCount;
  return {
    qualifiedCount, preferredFormat, resolvedFormat: FORMAT_CLASSIC,
    mainBracketSize, usesLowerBracket: false, lowerBracketSize: 0, lowerBracketCount: 0,
    directMainCount: qualifiedCount, validLowerCounts: [], validMainBracketSizes: [],
    description: byes > 0 ? `Classic Top ${mainBracketSize} (${byes} byes).` : `Classic Top ${mainBracketSize}.`,
  };
}

function createTournamentState(qualifiedDrivers, preferredFormat = FORMAT_CLASSIC, customLowerCount = 0) {
  const teamTandemBracket = Array.isArray(qualifiedDrivers) && qualifiedDrivers.some((driver) => isTeamTandemParticipant(driver));
  preferredFormat = teamTandemBracket ? FORMAT_CLASSIC : normalizePreferredFormat(preferredFormat);
  const plan = teamTandemBracket
    ? getTeamTandemCompetitionPlan(qualifiedDrivers.length)
    : getCompetitionPlan(qualifiedDrivers.length, preferredFormat, customLowerCount);
  const limitedDrivers = qualifiedDrivers.slice(0, plan.qualifiedCount).map(cloneDriver);

  let lowerBracket = null;
  let mainOpeningMatches;
  let mainRounds = null;

  if (plan.usesLowerBracket) {
    const directQualifiers = plan.resolvedFormat === FORMAT_SDC
      ? createSdcDirectQualifiers(limitedDrivers, plan.mainBracketSize)
      : limitedDrivers.slice(0, plan.directMainCount);
    const lowerParticipants = limitedDrivers.slice(plan.directMainCount);
    const lowerOpeningMatches = createHighVsLowOpeningMatches(lowerParticipants, plan.lowerBracketSize);
    const sdcOpening = plan.resolvedFormat === FORMAT_SDC
      ? (plan.mainBracketSize === 24
        ? createSdc24MainBracket(directQualifiers)
        : createSdcMainOpeningMatches(directQualifiers, plan.mainBracketSize))
      : null;

    lowerBracket = {
      title: `Lower Bracket Play-In (${lowerParticipants.length} drivers)`,
      rounds: createRoundsFromOpeningMatches(
        plan.lowerBracketSize,
        lowerOpeningMatches
      ),
      feedsInto: sdcOpening?.feedTarget || { matchIndex: 1, side: "right" },
    };
    mainOpeningMatches = sdcOpening?.matches || createLowerMainOpeningMatches(directQualifiers, plan.mainBracketSize);
    mainRounds = sdcOpening?.rounds || null;
  } else {
    mainOpeningMatches = createHighVsLowOpeningMatches(limitedDrivers, plan.mainBracketSize);
  }

  return {
    version: APP_STATE_VERSION,
    createdAt: new Date().toISOString(),
    preferredFormat,
    customLowerCount,
    qualifiedDrivers: limitedDrivers,
    plan,
    lowerBracket,
    manualBracketOrder: {
      mainRound0: false,
      lowerRound0: false,
    },
    mainBracket: {
      title: getRoundName(plan.mainBracketSize),
      rounds: mainRounds || createRoundsFromOpeningMatches(plan.mainBracketSize, mainOpeningMatches),
      thirdPlaceMatch: plan.mainBracketSize >= 4 ? createEmptyMatch() : null,
    },
    competitionJudgeControl: createEmptyCompetitionJudgeControl(),
  };
}

function normalizeBracketRounds(rounds, pendingFeed = null) {
  const normalizedRounds = rounds.map((round, roundIndex) => ({
    name: round.name,
    matches: round.matches.map((match, matchIndex) => {
      if (roundIndex === 0) return cloneMatch(match);
      return {
        left: match.lockedLeft ? cloneDriver(round.matches[matchIndex]?.left) : null,
        right: match.lockedRight ? cloneDriver(round.matches[matchIndex]?.right) : null,
        winner: cloneDriver(round.matches[matchIndex]?.winner),
        winnerMode: round.matches[matchIndex]?.winnerMode ?? null,
        lockedLeft: Boolean(round.matches[matchIndex]?.lockedLeft),
        lockedRight: Boolean(round.matches[matchIndex]?.lockedRight),
        nextMatchIndex: round.matches[matchIndex]?.nextMatchIndex ?? null,
        nextSlot: round.matches[matchIndex]?.nextSlot ?? null,
      };
    }),
  }));

  for (let roundIndex = 0; roundIndex < normalizedRounds.length; roundIndex += 1) {
    normalizedRounds[roundIndex].matches = normalizedRounds[roundIndex].matches.map((match, matchIndex) => {
      const orientedMatch = orientMatchLeadChase(match);
      const left = cloneDriver(orientedMatch.left);
      const right = cloneDriver(orientedMatch.right);
      let winner = null;

      const isPendingLeft = pendingFeed && roundIndex === 0 && matchIndex === pendingFeed.matchIndex && pendingFeed.side === 'left';
      const isPendingRight = pendingFeed && roundIndex === 0 && matchIndex === pendingFeed.matchIndex && pendingFeed.side === 'right';

      // ONLY AUTO ADVANCE BYES IN ROUND 0
      if (roundIndex === 0) {
        if (left && !right && !isPendingRight) {
          winner = cloneDriver(left);
          return { ...orientedMatch, left, right, winner, winnerMode: "auto" };
        } else if (!left && right && !isPendingLeft) {
          winner = cloneDriver(right);
          return { ...orientedMatch, left, right, winner, winnerMode: "auto" };
        }
      }

      if (left && right && orientedMatch.winnerMode === "manual" &&
          (participantKey(orientedMatch.winner) === participantKey(left) || participantKey(orientedMatch.winner) === participantKey(right))) {
        winner = cloneDriver(orientedMatch.winner);
        return { ...orientedMatch, left, right, winner, winnerMode: "manual" };
      }
      return { ...orientedMatch, left, right, winner: null, winnerMode: null };
    });

    if (roundIndex === normalizedRounds.length - 1) continue;

    normalizedRounds[roundIndex].matches.forEach((match, matchIndex) => {
      if (!match.winner) return;
      const nextMatchIndex = match.nextMatchIndex ?? Math.floor(matchIndex / 2);
      const nextMatch = normalizedRounds[roundIndex + 1].matches[nextMatchIndex];
      const nextSlot = match.nextSlot ?? (matchIndex % 2 === 0 ? "left" : "right");
      const nextLockKey = nextSlot === "right" ? "lockedRight" : "lockedLeft";
      if (nextMatch[nextLockKey]) return;
      nextMatch[nextSlot] = cloneDriver(match.winner);
    });
  }
  return normalizedRounds;
}

function getBracketWinner(rounds) {
  const lastRound = rounds[rounds.length - 1];
  return lastRound?.matches?.[0]?.winner ? cloneDriver(lastRound.matches[0].winner) : null;
}

