function openingMatchesMatch(actualMatches, expectedMatches) {
  if (!Array.isArray(actualMatches) || actualMatches.length !== expectedMatches.length) {
    return false;
  }

  return actualMatches.every((match, index) =>
    participantKey(match?.left) === participantKey(expectedMatches[index]?.left)
    && participantKey(match?.right) === participantKey(expectedMatches[index]?.right)
  );
}

function openingMatchesMatchWithFeedAllowance(actualMatches, expectedMatches, feedTarget = null) {
  if (!Array.isArray(actualMatches) || actualMatches.length !== expectedMatches.length) {
    return false;
  }

  return actualMatches.every((match, index) => {
    const expectedMatch = expectedMatches[index];
    if (!expectedMatch) return false;

    const leftMatches = !feedTarget || index !== feedTarget.matchIndex || feedTarget.side !== "left"
      ? participantKey(match?.left) === participantKey(expectedMatch?.left)
      : true;
    const rightMatches = !feedTarget || index !== feedTarget.matchIndex || feedTarget.side !== "right"
      ? participantKey(match?.right) === participantKey(expectedMatch?.right)
      : true;

    return leftMatches && rightMatches;
  });
}

function getOpeningMatchParticipantKeys(matches, ignoredSlot = null) {
  if (!Array.isArray(matches)) return [];
  const keys = [];
  matches.forEach((match, matchIndex) => {
    ["left", "right"].forEach((side) => {
      if (ignoredSlot && ignoredSlot.matchIndex === matchIndex && ignoredSlot.side === side) return;
      const key = participantKey(match?.[side]);
      if (key) keys.push(key);
    });
  });
  return keys.sort();
}

function openingMatchesUseSameParticipants(actualMatches, expectedMatches, ignoredSlot = null) {
  const actualKeys = getOpeningMatchParticipantKeys(actualMatches, ignoredSlot);
  const expectedKeys = getOpeningMatchParticipantKeys(expectedMatches, ignoredSlot);
  if (actualKeys.length !== expectedKeys.length) {
    return false;
  }
  return actualKeys.every((key, index) => key === expectedKeys[index]);
}

function shouldRebuildTournamentState(state) {
  if (!state?.mainBracket?.rounds?.length) {
    return true;
  }

  const rebuiltState = createTournamentState(
    state.qualifiedDrivers,
    normalizePreferredFormat(state.preferredFormat || FORMAT_CLASSIC),
    state.customLowerCount || 0,
  );

  if (state.mainBracket.rounds.length !== rebuiltState.mainBracket.rounds.length) {
    return true;
  }

  const mainFeedTarget = rebuiltState.lowerBracket?.feedsInto || state.lowerBracket?.feedsInto || null;
  if (!openingMatchesMatchWithFeedAllowance(
    state.mainBracket.rounds[0]?.matches,
    rebuiltState.mainBracket.rounds[0].matches,
    mainFeedTarget,
  )) {
    const allowManualMainOrder = Boolean(state.manualBracketOrder?.mainRound0)
      && openingMatchesUseSameParticipants(
        state.mainBracket.rounds[0]?.matches,
        rebuiltState.mainBracket.rounds[0].matches,
        mainFeedTarget,
      );
    if (!allowManualMainOrder) {
      return true;
    }
  }

  if (Boolean(state.lowerBracket) !== Boolean(rebuiltState.lowerBracket)) {
    return true;
  }

  if (rebuiltState.lowerBracket) {
    if (!state.lowerBracket?.rounds?.length) {
      return true;
    }

    if (state.lowerBracket.rounds.length !== rebuiltState.lowerBracket.rounds.length) {
      return true;
    }

    if (!openingMatchesMatch(state.lowerBracket.rounds[0]?.matches, rebuiltState.lowerBracket.rounds[0].matches)) {
      const allowManualLowerOrder = Boolean(state.manualBracketOrder?.lowerRound0)
        && openingMatchesUseSameParticipants(
          state.lowerBracket.rounds[0]?.matches,
          rebuiltState.lowerBracket.rounds[0].matches,
        );
      if (!allowManualLowerOrder) {
        return true;
      }
    }
  }

  return false;
}

function upgradeStoredTournamentState(state) {
  if (!state || !Array.isArray(state.qualifiedDrivers) || state.qualifiedDrivers.length < 2) {
    return state;
  }

  const rebuiltState = createTournamentState(
    state.qualifiedDrivers,
    normalizePreferredFormat(state.preferredFormat || FORMAT_CLASSIC),
    state.customLowerCount || 0,
  );

  if (state.version === APP_STATE_VERSION && !shouldRebuildTournamentState(state)) {
    return {
      ...state,
      competitionJudgeControl: normalizeCompetitionJudgeControl(state.competitionJudgeControl),
    };
  }

  return {
    ...rebuiltState,
    competitionJudgeControl: normalizeCompetitionJudgeControl(state.competitionJudgeControl),
  };
}

function isEventReadOnly() {
  return isArchivedOrCompleted(activeEventMeta);
}

function productionCloudClaimsRequired() {
  if (LOCAL_EVENT_DATA_MODE) return false;
  return Boolean(db && auth?.currentUser && !TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE && !QA_OFFLINE_MODE);
}

function roleCanUseProductionWrites(role = currentRole) {
  if (!productionCloudClaimsRequired()) return true;
  return true;
}

async function refreshCloudClaims(force = false) {
  const result = await refreshUserClaims({
    auth,
    force,
    previousClaims: cloudClaimsSnapshot,
    onError: (error) => console.error("Cloud claim refresh failed:", error),
  });
  if (result?.error) {
    return cloudClaimsSnapshot;
  }
  if (!result?.claims) {
    cloudClaimsSnapshot = null;
    cloudClaimsLoadedAt = 0;
    return null;
  }
  cloudClaimsSnapshot = result.claims;
  cloudClaimsLoadedAt = result.loadedAt;
  syncNetworkStatusIndicator();
  syncNativeStreamControlUi();
  setupTech1SpecialEventSync();
  return cloudClaimsSnapshot;
}

function showRoleAuthorizationNotice(role = currentRole, context = "") {
  const locallyUnlocked = Boolean(activeEventId && role && role !== "spectator" && isRoleUnlockedForEvent(activeEventId, role));
  const message = getRoleAuthorizationMessage(role);
  const key = `${activeEventId || "global"}:${role || "role"}:${context || "write"}`;
  const statusEl = document.getElementById("syncStatus");
  if (locallyUnlocked) {
    if (statusEl) {
      statusEl.textContent = "Event Admin Unlocked";
      statusEl.classList.remove("offline-protected", "connecting");
      statusEl.classList.add("online");
    }
    return;
  }
  if (statusEl) {
    statusEl.textContent = "Role Access Needed";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
  }
  const streamStatusEl = document.getElementById("streamerNativeStatus");
  if (streamStatusEl && normalizeCloudRoleName(role) === "streamOperator") {
    streamStatusEl.textContent = message;
    streamStatusEl.dataset.tone = "error";
  }
  if (lastAuthorizationNoticeKey !== key) {
    lastAuthorizationNoticeKey = key;
    window.alert(message);
  }
}

function handleCloudPermissionError(error, role = currentRole, context = "") {
  if (!isPermissionDeniedError(error)) return false;
  showRoleAuthorizationNotice(role, context);
  return true;
}

function tech1StaffCanManageSpecialEvent() {
  if (isWebsiteAdmin || currentRole === "admin" || isRoleUnlockedForEvent(activeEventId, "admin")) return true;
  if (isEventAdminBrowserUnlocked()) return true;
  if (!productionCloudClaimsRequired()) {
    return Boolean(isWebsiteAdmin || currentRole === "admin" || TEST_MODE_ENABLED);
  }
  if (!cloudClaimsSnapshot || !cloudClaimsLoadedAt) return false;
  const eventId = getActiveTech1SpecialEventId();
  return cloudClaimsIncludeRole("owner", eventId, cloudClaimsSnapshot)
    || cloudClaimsIncludeRole("websiteAdmin", eventId, cloudClaimsSnapshot)
    || cloudClaimsIncludeRole("eventAdmin", eventId, cloudClaimsSnapshot)
    || cloudClaimsIncludeRole("admin", eventId, cloudClaimsSnapshot);
}

function tech1JudgeOneCanRevealPodium() {
  return Boolean(
    isTech1AnniversaryMode(activeEventMeta)
    && currentRole === "j1"
    && !isEventReadOnly()
    && roleCanUseProductionWrites("j1")
  );
}

function canControlTech1PodiumReveal() {
  return Boolean(tech1StaffCanManageSpecialEvent() || tech1JudgeOneCanRevealPodium());
}

function handleTech1PermissionError(error, context = "manage Tech 1 Drift Anniversary mode") {
  if (!isPermissionDeniedError(error)) return false;
  showRoleAuthorizationNotice("eventAdmin", context);
  setTech1DeskStatus(
    isRoleUnlockedForEvent(activeEventId, "admin")
      ? "Event Admin is unlocked, but this save was rejected by cloud rules. Refresh once; if it repeats, redeploy the current Firestore rules."
      : "This browser is not unlocked for Event Admin. Enter the event admin password, then try Save Driver again.",
    "error",
  );
  const statusEl = document.getElementById("tech1RegistrationStatus");
  if (statusEl) {
    statusEl.textContent = isRoleUnlockedForEvent(activeEventId, "admin")
      ? "Event Admin is unlocked on this browser. If this action did not save, refresh once and try again."
      : "Your account is not authorized for this event role. Ask the event owner to assign access, then refresh your session.";
  }
  return true;
}

function userCanEdit() {
  return currentRole !== "spectator" && !isEventReadOnly() && roleCanUseProductionWrites(currentRole);
}

function registrationCanEdit() {
  if (currentRole !== "admin" || !roleCanUseProductionWrites("eventAdmin")) return false;
  return getEventStatus(activeEventMeta) !== EVENT_STATUS_ARCHIVED;
}

function adminCanEdit() {
  return currentRole === "admin" && !isEventReadOnly() && roleCanUseProductionWrites("eventAdmin");
}

function websiteAdminCanEditVenueSettings() {
  return websiteAdminCanUseProductionWrites();
}

function websiteAdminCanManageVenueProfiles() {
  return Boolean(websiteAdminCanUseProductionWrites() && createEventModalMode === "edit" && activeEventMeta && !isEventReadOnly());
}

function websiteAdminCanUseProductionWrites() {
  return Boolean(isWebsiteAdmin && roleCanUseProductionWrites("websiteAdmin"));
}

function cloneEventMeta(meta) {
  return meta ? JSON.parse(JSON.stringify(meta)) : null;
}

function extractEventMeta(payload, fallbackId = activeEventId) {
  const normalizedMeta = normalizeLegacyEventPayload(payload, {
    activeEventId: fallbackId,
    normalizeJudgingMode,
    normalizeJudgeCountForMode,
    normalizeCompetitionMode,
    normalizeEventBannerSource,
    buildDefaultRoleNames,
    createDefaultVenueConfig,
    normalizeVenueProfileList,
    normalizePendingRegistrationList,
    getSanitizedJudgeRoleClaims,
    buildEmptyEventResults,
    activeStatus: EVENT_STATUS_ACTIVE,
    completedStatus: EVENT_STATUS_COMPLETED,
    archivedStatus: EVENT_STATUS_ARCHIVED,
  });
  return normalizeEventCompetitionModeState(normalizedMeta);
}

function getRoleDisplayName(role, eventMeta = activeEventMeta) {
  if (role === "spectator") return ROLE_LABELS.spectator;
  if (role === "admin") return eventMeta?.roleNames?.admin || ROLE_LABELS.admin;
  return eventMeta?.roleNames?.[role] || ROLE_LABELS[role] || role;
}

function getTournamentBattleStats(state = tournamentState) {
  return calculateTournamentBattleStats(state);
}

function buildEventResults() {
  if (isTwinTripleMode(activeEventMeta)) {
    const state = getTwinCompState();
    const winner = state.winnerId ? state.teams.find((team) => team.id === state.winnerId) : null;
    const standings = getTwinCompPodiumTeams(state);
    const runnerUp = standings.find((team) => team.id !== winner?.id) || null;
    const previousCompletedAt = activeEventMeta?.results?.completedAt || null;
    const currentStatus = String(activeEventMeta?.status || "").trim().toLowerCase();
    const completedAt = (state.status === "complete" || currentStatus === EVENT_STATUS_COMPLETED || currentStatus === EVENT_STATUS_ARCHIVED)
      ? state.completedAt || previousCompletedAt || new Date().toISOString()
      : null;
    return {
      championName: winner?.name || state.winnerName || null,
      championSeed: winner?.seed || null,
      runnerUpName: runnerUp?.name || null,
      runnerUpSeed: runnerUp?.seed || null,
      thirdPlaceName: standings[2]?.name || null,
      thirdPlaceSeed: standings[2]?.seed || null,
      fourthPlaceName: standings[3]?.name || null,
      fourthPlaceSeed: standings[3]?.seed || null,
      topQualifierName: null,
      topQualifierSeed: null,
      topQualifierScore: null,
      averageBestScore: null,
      totalBattles: state.rounds.length,
      completedBattles: state.rounds.filter((round) => round.status === "finalized").length,
      qualifiedCount: state.teams.length,
      totalDrivers: getRegisteredDrivers(appDrivers).length,
      planDescription: `Twin Comp ${getTwinCompEliminationAdjective()} event. The bottom half of scored active teams receive one elimination point each finalized round. Teams are eliminated at ${getTwinCompEliminationLimit()} points.`,
      updatedAt: new Date().toISOString(),
      completedAt,
    };
  }
  const teamTandemMode = isTeamTandemMode(activeEventMeta);
  const rankedDrivers = teamTandemMode ? buildTeamTandemOrderedParticipants(appDrivers) : rankDrivers(appDrivers);
  const champion = tournamentState?.mainBracket ? getBracketWinner(tournamentState.mainBracket.rounds) : null;
  const finalMatch = tournamentState?.mainBracket?.rounds?.[tournamentState.mainBracket.rounds.length - 1]?.matches?.[0] || null;
  const runnerUp = getMatchLoser(finalMatch);
  const thirdPlace = tournamentState?.mainBracket?.thirdPlaceMatch?.winner || null;
  const fourthPlace = getMatchLoser(tournamentState?.mainBracket?.thirdPlaceMatch || null);
  const topQualifier = teamTandemMode ? null : (rankedDrivers[0] || null);
  const scorableDrivers = teamTandemMode ? [] : rankedDrivers.filter((driver) => Number.isFinite(Number(driver.bestScore)));
  const averageBestScore = scorableDrivers.length
    ? scorableDrivers.reduce((sum, driver) => sum + Number(driver.bestScore || 0), 0) / scorableDrivers.length
    : null;
  const battleStats = getTournamentBattleStats(tournamentState);
  const previousResults = activeEventMeta?.results || buildEmptyEventResults();
  if (!champion && previousResults?.manualOverride) {
    return {
      ...buildEmptyEventResults(),
      ...previousResults,
      topQualifierName: topQualifier?.name || previousResults.topQualifierName || null,
      topQualifierSeed: topQualifier?.seed || previousResults.topQualifierSeed || null,
      topQualifierScore: topQualifier?.bestScore ?? previousResults.topQualifierScore ?? null,
      averageBestScore,
      totalBattles: battleStats.totalBattles || previousResults.totalBattles || 0,
      completedBattles: previousResults.completedBattles ?? battleStats.completedBattles ?? 0,
      qualifiedCount: Math.max(
        Number(previousResults.qualifiedCount || 0),
        Number(tournamentState?.qualifiedDrivers?.length || 0),
        Number(rankedDrivers.length || 0)
      ),
      totalDrivers: rankedDrivers.length || previousResults.totalDrivers || 0,
      planDescription: previousResults.planDescription || tournamentState?.plan?.description || (teamTandemMode ? "Waiting for the randomized Team Tandem bracket." : "Waiting for qualifying scores."),
      updatedAt: new Date().toISOString(),
      completedAt: previousResults.completedAt || previousResults.updatedAt || null,
    };
  }
  const previousCompletedAt = activeEventMeta?.results?.completedAt || null;
  const currentStatus = String(activeEventMeta?.status || "").trim().toLowerCase();
  const completedAt = (currentStatus === EVENT_STATUS_COMPLETED || currentStatus === EVENT_STATUS_ARCHIVED)
    ? previousCompletedAt || new Date().toISOString()
    : null;
  return {
    championName: champion?.name || null,
    championSeed: champion?.seed || null,
    runnerUpName: runnerUp?.name || null,
    runnerUpSeed: runnerUp?.seed || null,
    thirdPlaceName: thirdPlace?.name || null,
    thirdPlaceSeed: thirdPlace?.seed || null,
    fourthPlaceName: fourthPlace?.name || null,
    fourthPlaceSeed: fourthPlace?.seed || null,
    topQualifierName: topQualifier?.name || null,
    topQualifierSeed: topQualifier?.seed || null,
    topQualifierScore: topQualifier?.bestScore ?? null,
    averageBestScore,
    totalBattles: battleStats.totalBattles,
    completedBattles: battleStats.completedBattles,
    qualifiedCount: tournamentState?.qualifiedDrivers?.length || 0,
    totalDrivers: rankedDrivers.length,
    planDescription: tournamentState?.plan?.description || (teamTandemMode ? "Waiting for the randomized Team Tandem bracket." : "Waiting for qualifying scores."),
    updatedAt: new Date().toISOString(),
    completedAt,
  };
}

function reconcileActiveEventLifecycle(nextResults = buildEventResults()) {
  if (!activeEventMeta || !activeEventId) {
    return {
      results: nextResults,
      status: EVENT_STATUS_ACTIVE,
      archivedResultsChanged: false,
    };
  }
  const results = nextResults ?? buildEventResults();
  const nextStatus = getEventStatus({ ...activeEventMeta, results }, results);
  const shouldRemoveArchivedRecord = nextStatus === EVENT_STATUS_ACTIVE && Boolean(archivedResultsDirectory[activeEventId]);

  setActiveEventMetaState({
    ...activeEventMeta,
    status: nextStatus,
    results,
  }, { syncQualifying: false });
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);

  if (shouldRemoveArchivedRecord) {
    delete archivedResultsDirectory[activeEventId];
  }

  return {
    results,
    status: nextStatus,
    archivedResultsChanged: shouldRemoveArchivedRecord,
  };
}

function getLegacyLocalEventState() {
  const storedDrivers = localStorage.getItem("rc-drift-drivers-v7") || localStorage.getItem("rc-drift-drivers-v6");
  const storedBracket = localStorage.getItem("rc-drift-bracket-state-v7") || localStorage.getItem("rc-drift-bracket-state-v6");
  const payload = {};
  if (storedDrivers) {
    try { payload.drivers = JSON.parse(storedDrivers); } catch (e) {}
  }
  if (storedBracket) {
    try { payload.bracket = upgradeStoredTournamentState(JSON.parse(storedBracket)); } catch (e) {}
  }
  return payload;
}

function readEventStateCache(eventId) {
  const cached = localStorage.getItem(getEventStateStorageKey(eventId));
  if (cached) {
    try {
      return JSON.parse(cached);
    } catch (e) {}
  }
  if (eventId === DEFAULT_EVENT_ID) {
    return getLegacyLocalEventState();
  }
  return null;
}

function getQualifyingDriverQueue(drivers = appDrivers) {
  if (isTwinTripleMode(activeEventMeta)) {
    const round = getTwinCompCurrentRound();
    if (round && ["live", "scored", "review"].includes(round.status) && Array.isArray(round.teamIds) && round.teamIds.length) {
      const byId = new Map(drivers.map((driver) => [driver.id, driver]));
      return round.teamIds.map((teamId) => byId.get(teamId)).filter(Boolean);
    }
    const activeIds = new Set(getTwinCompActiveTeams().map((team) => team.id));
    if (activeIds.size) return getRegisteredDrivers(drivers).filter((driver) => activeIds.has(driver.id));
  }
  return getRegisteredDrivers(drivers);
}

function getQualifyingFlowPhase(flow = qualifyingFlow, drivers = appDrivers) {
  const queue = getQualifyingDriverQueue(drivers);
  if (!queue.length) return "empty";
  if (flow?.completed) return "complete";
  if (!flow?.started || !flow?.currentDriverId) return "waiting";
  return "live";
}

function deriveSyncedQualifyingFlowState(flow = qualifyingFlow, drivers = appDrivers, eventMeta = activeEventMeta) {
  const queue = getQualifyingDriverQueue(drivers);
  const activeJudgeRoles = getActiveJudgeRoles(eventMeta);
  const previousCurrentId = flow?.currentDriverId || null;
  const previousReadyRoles = flow?.readyRoles || {};
  const previousStarted = Boolean(flow?.started);
  const previousCompleted = Boolean(flow?.completed);

  if (!queue.length) {
    return {
      flow: createEmptyQualifyingFlow(),
      judgeLaneIndex: 0,
    };
  }

  if (previousCompleted) {
    return {
      flow: {
        currentDriverId: null,
        readyRoles: {},
        started: true,
        completed: true,
      },
      judgeLaneIndex: Math.max(0, queue.length - 1),
    };
  }

  if (!previousStarted) {
    return {
      flow: {
        currentDriverId: null,
        readyRoles: {},
        started: false,
        completed: false,
      },
      judgeLaneIndex: 0,
    };
  }

  const queueIds = new Set(queue.map((driver) => driver.id));
  const currentDriverId = queueIds.has(previousCurrentId) ? previousCurrentId : queue[0].id;
  const readyRoles = {};
  activeJudgeRoles.forEach((role) => {
    if (previousReadyRoles?.[role]) readyRoles[role] = true;
  });
  const queueIndex = queue.findIndex((driver) => driver.id === currentDriverId);

  return {
    flow: {
      currentDriverId,
      readyRoles,
      started: true,
      completed: false,
    },
    judgeLaneIndex: queueIndex > -1 ? queueIndex : 0,
  };
}

function syncQualifyingFlowState() {
  const previousCurrentId = qualifyingFlow?.currentDriverId || null;
  const previousReadyRoles = qualifyingFlow?.readyRoles || {};
  const previousStarted = Boolean(qualifyingFlow?.started);
  const previousCompleted = Boolean(qualifyingFlow?.completed);
  const nextState = deriveSyncedQualifyingFlowState(qualifyingFlow, appDrivers, activeEventMeta);
  setQualifyingFlowState(nextState.flow, { syncQualifying: false });
  setJudgeLaneIndexState(nextState.judgeLaneIndex);
  return previousCurrentId !== qualifyingFlow.currentDriverId
    || JSON.stringify(previousReadyRoles) !== JSON.stringify(qualifyingFlow.readyRoles || {})
    || previousStarted !== Boolean(qualifyingFlow.started)
    || previousCompleted !== Boolean(qualifyingFlow.completed);
}

function getCurrentQualifyingDriver() {
  syncQualifyingFlowState();
  return appDrivers.find((driver) => driver.id === qualifyingFlow.currentDriverId) || null;
}

function clearQualifyingReady(role) {
  if (!role?.startsWith("j") || !qualifyingFlow?.readyRoles?.[role]) return false;
  const nextReadyRoles = { ...(qualifyingFlow.readyRoles || {}) };
  delete nextReadyRoles[role];
  setQualifyingFlowState({
    ...qualifyingFlow,
    readyRoles: nextReadyRoles,
  }, { syncQualifying: false });
  return true;
}

function advanceQualifyingDriver() {
  if (isTwinTripleMode(activeEventMeta)) {
    captureTwinCompCurrentRun(qualifyingFlow?.currentDriverId);
  }
  const queue = getQualifyingDriverQueue();
  if (!queue.length) {
    setQualifyingFlowState(createEmptyQualifyingFlow(), { syncQualifying: false });
    return;
  }

  const currentIndex = Math.max(0, queue.findIndex((driver) => driver.id === qualifyingFlow.currentDriverId));
  const nextIndex = currentIndex + 1;
  if (nextIndex >= queue.length) {
    setQualifyingFlowState({
      currentDriverId: null,
      readyRoles: {},
      started: true,
      completed: true,
    }, { syncQualifying: false });
    setJudgeLaneIndexState(Math.max(0, queue.length - 1));
    if (!isTwinTripleMode(activeEventMeta)) {
      maybeAutoBuildBracket();
    }
    return;
  }
  setQualifyingFlowState({
    currentDriverId: queue[nextIndex]?.id || null,
    readyRoles: {},
    started: true,
    completed: false,
  }, { syncQualifying: false });
  setJudgeLaneIndexState(nextIndex);
}

function completeQualifyingFlowForCompetition() {
  const queue = getQualifyingDriverQueue();
  if (!queue.length) {
    setQualifyingFlowState(createEmptyQualifyingFlow(), { syncQualifying: false });
    setJudgeLaneIndexState(0);
    return false;
  }

  const alreadyComplete = Boolean(qualifyingFlow?.completed)
    && !qualifyingFlow?.currentDriverId
    && !Object.keys(qualifyingFlow?.readyRoles || {}).length;

  setQualifyingFlowState({
    currentDriverId: null,
    readyRoles: {},
    started: true,
    completed: true,
  }, { syncQualifying: false });
  setJudgeLaneIndexState(Math.max(0, queue.length - 1));
  return !alreadyComplete;
}

function getBracketReturnView() {
  if (isTech1AnniversaryMode(activeEventMeta)) {
    return getTech1NoQualifyingFallbackView(currentRole);
  }
  return currentRole === "admin" ? "registration" : "qualifying";
}

function syncBracketReturnControls() {
  const returnView = getBracketReturnView();
  const label = returnView === "registration" ? "Back To Registration" : "Back To Qualifying";
  const title = returnView === "registration" ? "Back to registration" : "Back to qualifying";
  const buttonIds = ["backToQualifyingBtn", "mobileBackToQualifyingBtn", "inlineBackToQualifyingBtn"];
  buttonIds.forEach((buttonId) => {
    const button = document.getElementById(buttonId);
    if (!button) return;
    button.textContent = label;
    button.setAttribute("title", title);
    button.setAttribute("aria-label", title);
  });
}

function invalidateBracketFromAdminChanges() {
  if (!tournamentState?.mainBracket?.rounds?.length) return false;
  setTournamentStateState(null, { syncQualifying: false });
  applyUiState({
    activeCompetitionBracketPage: "main",
    lowerBracketAutoAdvancedToMain: false,
  });
  lastBattleFlowSignature = null;
  lastPodiumSignature = null;
  clearWinnerAnimationState();
  saveBracketPagePreference(activeEventId, activeCompetitionBracketPage);
  if (launchWarning) {
    launchWarning.style.display = "block";
    launchWarning.textContent = "Roster updated. Launch the bracket again to rebuild it from the latest drivers.";
  }
  return true;
}

function startQualifyingFlow() {
  if (isTwinTripleMode(activeEventMeta)) {
    return startTwinCompRound();
  }
  const queue = getQualifyingDriverQueue();
  if (!queue.length) return false;
  if (activeEventMeta) {
    setActiveEventMetaState({
      ...activeEventMeta,
      venueConfig: {
        ...getVenueConfig(),
        enabled: false,
      },
    }, { syncQualifying: false });
    eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  }
  setQualifyingFlowState({
    currentDriverId: queue[0]?.id || null,
    readyRoles: {},
    started: true,
    completed: false,
  }, { syncQualifying: false });
  setJudgeLaneIndexState(0);
  return true;
}

function canRandomizeQualifyingOrder(flow = qualifyingFlow, drivers = appDrivers, eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) return false;
  if (getQualifyingDriverQueue(drivers).length < 2) return false;
  return getQualifyingFlowPhase(flow, drivers) === "waiting";
}

async function randomizeQualifyingOrder() {
  if (!adminCanEdit()) return false;
  if (!canRandomizeQualifyingOrder(qualifyingFlow, appDrivers, activeEventMeta)) return false;
  const randomizedDrivers = shuffleEntriesForVisibleOrder(getRegisteredDrivers(appDrivers));
  if (randomizedDrivers.length < 2) return false;
  const randomizedIds = new Set(randomizedDrivers.map((driver) => driver.id));
  const untouchedDrivers = normalizeDriverList(appDrivers).filter((driver) => !randomizedIds.has(driver.id));
  setActiveDriversState(normalizeDriverList([...randomizedDrivers, ...untouchedDrivers]));
  invalidateBracketFromAdminChanges();
  await publishStateImmediately();
  renderDriversTable();
  return true;
}

function markQualifyingRoleReady(role) {
  if (!role?.startsWith("j")) return false;
  syncQualifyingFlowState();
  setQualifyingFlowState({
    ...qualifyingFlow,
    readyRoles: {
      ...(qualifyingFlow.readyRoles || {}),
      [role]: true,
    },
  }, { syncQualifying: false });

  const activeJudgeRoles = getActiveJudgeRoles(activeEventMeta);
  const allReady = activeJudgeRoles.length > 0 && activeJudgeRoles.every((judgeRole) => qualifyingFlow.readyRoles?.[judgeRole]);
  if (allReady) {
    advanceQualifyingDriver();
  }
  return true;
}

function saveEventStateCache() {
  if (STANDALONE_DEMO_MODE) return;
  if (!activeEventId || !activeEventMeta) return;
  syncQualifyingFlowState();
  const persistedState = getPersistableActiveEventState();
  localStorage.setItem(getEventStateStorageKey(activeEventId), JSON.stringify({
    drivers: persistedState.drivers,
    bracket: persistedState.bracket,
    twinComp: persistedState.twinComp,
    qualifyingFlow: persistedState.qualifyingFlow,
    formatMode: persistedState.formatMode,
    lowerCount: persistedState.lowerCount,
    meta: persistedState.meta,
  }));

  if (activeEventId === DEFAULT_EVENT_ID) {
    localStorage.setItem("rc-drift-drivers-v7", JSON.stringify(persistedState.drivers));
    localStorage.removeItem("rc-drift-drivers-v6");
    if (persistedState.bracket) {
      localStorage.setItem("rc-drift-bracket-state-v7", JSON.stringify(persistedState.bracket));
      localStorage.removeItem("rc-drift-bracket-state-v6");
    }
  }
}

function saveDirectoryCache() {
  if (STANDALONE_DEMO_MODE) return;
  localStorage.setItem(EVENT_DIRECTORY_STORAGE_KEY, JSON.stringify(eventDirectory));
  localStorage.setItem(DELETED_EVENT_IDS_STORAGE_KEY, JSON.stringify(getDeletedEventIdsSnapshot()));
  if (activeEventId) {
    localStorage.setItem(ACTIVE_EVENT_STORAGE_KEY, activeEventId);
  }
}

function normalizeArchivedResultsRecord(record, fallbackId = "") {
  return normalizeArchivedResultsRecordPayload(record, fallbackId, {
    completedStatus: EVENT_STATUS_COMPLETED,
  });
}

function getArchivedResultsSnapshot(recordMap = archivedResultsDirectory) {
  return getArchivedResultsSnapshotPayload(recordMap, {
    completedStatus: EVENT_STATUS_COMPLETED,
  });
}

function saveArchivedResultsCache() {
  localStorage.setItem(ARCHIVED_RESULTS_STORAGE_KEY, JSON.stringify(getArchivedResultsSnapshot()));
}

function buildArchivedResultsRecord(eventMeta = activeEventMeta, results = buildEventResults()) {
  return buildArchivedResultsRecordPayload(eventMeta, results, {
    eventStatus: getEventStatus(eventMeta),
    archivedStatus: EVENT_STATUS_ARCHIVED,
    completedStatus: EVENT_STATUS_COMPLETED,
  });
}

function sortArchivedResultsForDisplay() {
  return sortArchivedResultsRecordsForDisplay(Object.values(getArchivedResultsSnapshot()));
}

async function persistArchivedResultsDirectory() {
  saveArchivedResultsCache();
  if (!db) return;
  lastLocalPush = Date.now();
  try {
    await firestoreWriteService.publishArchive({
      events: getArchivedResultsSnapshot(),
      syncStamp: lastLocalPush,
    });
  } catch (error) {
    console.error("Results archive sync failed:", error);
    throw error;
  }
}

function readRoleSessionMap() {
  const raw = sessionStorage.getItem(EVENT_ROLE_SESSION_KEY) || localStorage.getItem(EVENT_ROLE_PERSIST_KEY);
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    return {};
  }
}

function writeRoleSessionMap(nextMap) {
  sessionStorage.setItem(EVENT_ROLE_SESSION_KEY, JSON.stringify(nextMap));
  localStorage.setItem(EVENT_ROLE_PERSIST_KEY, JSON.stringify(nextMap));
}

function readRoleUnlockMap() {
  const raw = localStorage.getItem(EVENT_ROLE_UNLOCK_KEY);
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    return {};
  }
}

function writeRoleUnlockMap(nextMap) {
  localStorage.setItem(EVENT_ROLE_UNLOCK_KEY, JSON.stringify(nextMap));
}

function isEventAdminBrowserUnlocked() {
  return localStorage.getItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY) === "true"
    || sessionStorage.getItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY) === "true";
}

function setEventAdminBrowserUnlocked(unlocked) {
  if (unlocked) {
    localStorage.setItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY, "true");
    sessionStorage.setItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY, "true");
  } else {
    localStorage.removeItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY);
    sessionStorage.removeItem(EVENT_ADMIN_BROWSER_UNLOCK_KEY);
  }
}

function isForcedEventAdminHost() {
  return forcedHostContext?.kind === "role" && forcedHostContext.role === "admin";
}

function isDirectEventAdminRouteRequested() {
  try {
    const route = parseRouteFromLocation();
    return route?.kind === "role" && route.role === "admin";
  } catch (error) {
    return false;
  }
}

function shouldGrantEventAdminBrowserAccess() {
  return isForcedEventAdminHost() || isDirectEventAdminRouteRequested();
}

function grantForcedEventAdminHostAccess(eventId = activeEventId) {
  if (!eventId) return false;
  if (TEST_MODE_ENABLED && isDirectEventAdminRouteRequested()) {
    setEventAdminBrowserUnlocked(true);
    setRoleUnlockedForEvent(eventId, "admin", true);
    saveRoleForEvent(eventId, "admin");
    return true;
  }
  if (!shouldGrantEventAdminBrowserAccess()) return false;
  if (!isRoleUnlockedForEvent(eventId, "admin")) {
    if (!isEventAdminBrowserUnlocked()) return false;
    setRoleUnlockedForEvent(eventId, "admin", true);
  }
  saveRoleForEvent(eventId, "admin");
  return true;
}

function isBrowserPersistentEventAdminRole(role) {
  return role === "admin" || role === "eventAdmin";
}

function hasAnyStoredEventAdminUnlock() {
  const unlockMap = readRoleUnlockMap();
  return Object.values(unlockMap).some((entry) => {
    return Boolean(entry && typeof entry === "object" && (entry.admin || entry.eventAdmin));
  });
}

function hydrateEventAdminBrowserUnlockFromExistingSessions() {
  if (isEventAdminBrowserUnlocked()) return;
  const sessionMap = readRoleSessionMap();
  const hasStoredAdminRole = Object.values(sessionMap).some((role) => isBrowserPersistentEventAdminRole(role));
  if (hasStoredAdminRole || hasAnyStoredEventAdminUnlock()) {
    setEventAdminBrowserUnlocked(true);
  }
}

function saveBracketPagePreference(eventId, page) {
  if (!eventId || !page) return;
  try {
    const raw = localStorage.getItem(`rc-drift-bracket-page-v${EVENT_STORAGE_VERSION}`);
    const parsed = raw ? JSON.parse(raw) : {};
    const nextMap = parsed && typeof parsed === "object" ? parsed : {};
    nextMap[eventId] = page;
    localStorage.setItem(`rc-drift-bracket-page-v${EVENT_STORAGE_VERSION}`, JSON.stringify(nextMap));
  } catch (error) {
    console.warn("Bracket page preference save failed:", error);
  }
}

function getSavedRoleForEvent(eventId) {
  if (!eventId) return "spectator";
  const role = readRoleSessionMap()[eventId];
  return typeof role === "string" ? role : "spectator";
}

function saveRoleForEvent(eventId, role) {
  if (!eventId) return;
  const sessionMap = readRoleSessionMap();
  if (!role || role === "spectator") {
    delete sessionMap[eventId];
  } else {
    sessionMap[eventId] = role;
  }
  writeRoleSessionMap(sessionMap);
}

function isRoleUnlockedForEvent(eventId, role) {
  if (!eventId || !role || role === "spectator") return false;
  const unlockMap = readRoleUnlockMap();
  return Boolean(unlockMap?.[eventId]?.[role]);
}

function canApplyRoleForEvent(eventId, role, eventMeta = activeEventMeta) {
  if (!role || role === "spectator") return true;
  if (STANDALONE_DEMO_MODE) return true;
  if (!isRoleAvailableForEvent(role, eventMeta)) return false;
  if (role?.startsWith("j") && isJudgeAccessLocked(eventMeta)) return false;
  if (isBrowserPersistentEventAdminRole(role) && isEventAdminBrowserUnlocked()) return true;
  return isRoleUnlockedForEvent(eventId, role);
}

function setRoleUnlockedForEvent(eventId, role, unlocked) {
  if (!eventId || !role || role === "spectator") return;
  const unlockMap = readRoleUnlockMap();
  const eventUnlocks = { ...(unlockMap[eventId] || {}) };
  if (unlocked) {
    eventUnlocks[role] = true;
    unlockMap[eventId] = eventUnlocks;
  } else {
    delete eventUnlocks[role];
    if (Object.keys(eventUnlocks).length) {
      unlockMap[eventId] = eventUnlocks;
    } else {
      delete unlockMap[eventId];
    }
  }
  writeRoleUnlockMap(unlockMap);
}

function getJudgeDeviceId() {
  try {
    let existing = localStorage.getItem(JUDGE_ROLE_DEVICE_ID_KEY);
    if (existing) return existing;
    existing = generateId();
    localStorage.setItem(JUDGE_ROLE_DEVICE_ID_KEY, existing);
    return existing;
  } catch (error) {
    console.warn("Failed to access judge device token.", error);
    return "judge-device-unavailable";
  }
}

function getJudgeRoleClaims(eventMeta = activeEventMeta) {
  return getSanitizedJudgeRoleClaims(eventMeta);
}

function getClaimedJudgeRoleForDevice(deviceId = getJudgeDeviceId(), eventMeta = activeEventMeta) {
  const claims = getJudgeRoleClaims(eventMeta);
  return getActiveJudgeRoles(eventMeta).find((role) => claims[role]?.deviceId === deviceId) || null;
}

function isJudgeRoleClaimedByAnotherDevice(role, eventMeta = activeEventMeta, deviceId = getJudgeDeviceId()) {
  const claim = getJudgeRoleClaims(eventMeta)[role];
  return Boolean(claim?.deviceId && claim.deviceId !== deviceId);
}

function buildJudgeRoleClaimLabel(role, eventMeta = activeEventMeta) {
  if (!usesCategoryJudging(eventMeta)) {
    return getRoleDisplayName(role, eventMeta);
  }
  return `${getJudgeCategoryConfig(role, eventMeta).label} Judge`;
}

function shouldUseJudgeRoleClaims(eventMeta = activeEventMeta) {
  return usesCategoryJudging(eventMeta) && getActiveJudgeRoles(eventMeta).length > 1;
}

function renderJudgeRoleClaimSelector(eventMeta = activeEventMeta, selectedRole = null) {
  if (!shouldUseJudgeRoleClaims(eventMeta)) return "";
  const claimedRole = selectedRole || getClaimedJudgeRoleForDevice(getJudgeDeviceId(), eventMeta) || "";
  const selectedLabel = claimedRole ? buildJudgeRoleClaimLabel(claimedRole, eventMeta) : "";
  const options = [
    `<option value="" ${claimedRole ? "" : "selected"}>Select Your Judge Role</option>`,
    ...getActiveJudgeRoles(eventMeta).filter((role) => isRoleAllowedForHost(role)).map((role) => {
      const claimedByOther = isJudgeRoleClaimedByAnotherDevice(role, eventMeta);
      const optionLabel = `${buildJudgeRoleClaimLabel(role, eventMeta)}${claimedByOther ? " (In Use)" : ""}`;
      return `<option value="${role}" ${claimedRole === role ? "selected" : ""} ${claimedByOther ? "disabled" : ""}>${escapeHtml(optionLabel)}</option>`;
    }),
  ];

  return `
    <div class="judge-role-picker">
      <label class="modal-field">
        <span>Judge Assignment</span>
        <select data-action="select-judge-role" aria-label="Choose judge assignment">
          ${options.join("")}
        </select>
      </label>
      <div class="helper-text">${claimedRole
        ? `This phone is currently assigned to ${escapeHtml(selectedLabel)}. Open roles stay selectable here, and any role already taken on another judge phone will stay greyed out.`
        : "Choose Line, Angle, or Style before scoring starts. Any role already claimed on another judge phone will be greyed out here to prevent duplicate judging assignments."}</div>
      <div class="judge-role-picker-status ${claimedRole ? "is-active" : ""}">${claimedRole ? `Assigned: ${escapeHtml(selectedLabel)}` : "Assignment Required"}</div>
    </div>
  `;
}

function renderJudgeRoleClaimGateCard(message) {
  return `
    <article class="mobile-driver-card">
      <div class="empty-state">${message}</div>
    </article>
  `;
}

async function syncJudgeRoleClaimSelection(role, options = {}) {
  if (!activeEventId || !activeEventMeta || !shouldUseJudgeRoleClaims(activeEventMeta)) {
    return { success: true, claimedRole: role || null };
  }

  const deviceId = getJudgeDeviceId();
  const releaseOnly = options.releaseOnly === true || !role || role === "spectator";
  const targetRole = releaseOnly ? null : (getActiveJudgeRoles(activeEventMeta).includes(role) ? role : null);
  if (!releaseOnly && !targetRole) {
    return { success: false, claimedRole: null };
  }

  const applyLocalClaimUpdate = async () => {
    const nextClaims = normalizeJudgeRoleClaims(activeEventMeta?.judgeRoleClaims);
    const nowIso = new Date().toISOString();
    getActiveJudgeRoles(activeEventMeta).forEach((judgeRole) => {
      if (nextClaims[judgeRole]?.deviceId === deviceId) {
        nextClaims[judgeRole] = null;
      }
    });
    if (targetRole) {
      nextClaims[targetRole] = {
        deviceId,
        claimedAt: nextClaims[targetRole]?.claimedAt || nowIso,
        lastSeenAt: nowIso,
      };
    }
    setActiveEventMetaState({
      ...activeEventMeta,
      judgeRoleClaims: nextClaims,
      updatedAt: nowIso,
    }, { syncQualifying: false });
    eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
    await publishStateImmediately();
    return {
      success: true,
      claimedRole: targetRole,
      remoteMeta: cloneEventMeta(activeEventMeta),
    };
  };

  if (!db) {
    return applyLocalClaimUpdate();
  }

  clearTimeout(syncTimeout);
  lastLocalPush = Date.now();
  let transactionResult = null;

  try {
    await runTransaction(db, async (transaction) => {
      const eventRef = getEventDocRef(activeEventId);
      const eventSnap = await transaction.get(eventRef);
      const remotePayload = eventSnap.exists() ? eventSnap.data() : {};
      const remoteMeta = extractEventMeta(remotePayload, activeEventId) || cloneEventMeta(eventDirectory[activeEventId] || activeEventMeta);
      const remoteClaims = getSanitizedJudgeRoleClaims(remoteMeta);
      const existingRole = getActiveJudgeRoles(remoteMeta).find((judgeRole) => remoteClaims[judgeRole]?.deviceId === deviceId) || null;

      if (targetRole && remoteClaims[targetRole]?.deviceId && remoteClaims[targetRole].deviceId !== deviceId) {
        transactionResult = {
          success: false,
          claimedRole: existingRole,
          blockedRole: targetRole,
          remoteMeta: cloneEventMeta({
            ...remoteMeta,
            judgeRoleClaims: remoteClaims,
          }),
        };
        return;
      }

      const nextClaims = normalizeJudgeRoleClaims(remoteClaims);
      getActiveJudgeRoles(remoteMeta).forEach((judgeRole) => {
        if (nextClaims[judgeRole]?.deviceId === deviceId) {
          nextClaims[judgeRole] = null;
        }
      });

      const nowIso = new Date().toISOString();
      if (targetRole) {
        nextClaims[targetRole] = {
          deviceId,
          claimedAt: existingRole === targetRole
            ? (remoteClaims[targetRole]?.claimedAt || nowIso)
            : nowIso,
          lastSeenAt: nowIso,
        };
      }

      const updatedMeta = {
        ...remoteMeta,
        judgeRoleClaims: nextClaims,
        updatedAt: nowIso,
        syncStamp: lastLocalPush,
      };

      transaction.set(eventRef, {
        ...remotePayload,
        ...updatedMeta,
        syncStamp: lastLocalPush,
      }, { merge: true });

      if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
        transaction.set(getDirectoryDocRef(), {
          events: getPersistableDirectorySnapshot({
            [activeEventId]: cloneEventMeta({
              ...(eventDirectory[activeEventId] || activeEventMeta || updatedMeta),
              ...updatedMeta,
            }),
          }),
          activeEventId,
          deletedEventIds: getDeletedEventIdsSnapshot(),
          syncStamp: lastLocalPush,
        }, { merge: true });
      }

      transactionResult = {
        success: true,
        claimedRole: targetRole,
        remoteMeta: cloneEventMeta(updatedMeta),
      };
    });

    if (transactionResult?.remoteMeta) {
      setActiveEventMetaState(transactionResult.remoteMeta, { syncQualifying: false });
      eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
      saveDirectoryCache();
      saveEventStateCache();
    }

    if (transactionResult?.success === false && transactionResult.blockedRole) {
      window.alert(`${buildJudgeRoleClaimLabel(transactionResult.blockedRole, transactionResult.remoteMeta || activeEventMeta)} is already assigned on another judge phone.`);
    }

    return transactionResult || { success: true, claimedRole: targetRole };
  } catch (error) {
    console.error("Judge role claim sync failed:", error);
    return { success: false, claimedRole: null };
  }
}

async function releaseJudgeRoleClaim(role = null, options = {}) {
  if (!shouldUseJudgeRoleClaims(activeEventMeta)) return { success: true, claimedRole: null };
  const claimedRole = role || getClaimedJudgeRoleForDevice();
  if (!claimedRole) return { success: true, claimedRole: null };
  return syncJudgeRoleClaimSelection(claimedRole, { ...options, releaseOnly: true });
}

async function refreshJudgeRoleClaimHeartbeat() {
  if (!activeEventId || !activeEventMeta || !shouldUseJudgeRoleClaims(activeEventMeta)) return false;
  const claimedRole = getClaimedJudgeRoleForDevice();
  if (!claimedRole || !currentRole?.startsWith("j")) return false;
  const result = await syncJudgeRoleClaimSelection(claimedRole);
  return Boolean(result?.success);
}

function syncJudgeRoleClaimHeartbeat() {
  const shouldHeartbeat = Boolean(
    activeEventId
    && activeEventMeta
    && currentRole?.startsWith("j")
    && shouldUseJudgeRoleClaims(activeEventMeta)
    && getClaimedJudgeRoleForDevice()
  );

  if (!shouldHeartbeat) {
    if (judgeRoleClaimHeartbeatTimer) {
      clearInterval(judgeRoleClaimHeartbeatTimer);
      judgeRoleClaimHeartbeatTimer = null;
    }
    return;
  }

  if (!judgeRoleClaimHeartbeatTimer) {
    judgeRoleClaimHeartbeatTimer = setInterval(() => {
      refreshJudgeRoleClaimHeartbeat().catch((error) => {
        console.error("Judge role claim heartbeat failed:", error);
      });
    }, JUDGE_ROLE_CLAIM_HEARTBEAT_MS);
  }
}

async function initLocalState() {
  isWebsiteAdmin = localStorage.getItem(WEBSITE_ADMIN_STORAGE_KEY) === "true"
    || sessionStorage.getItem(WEBSITE_ADMIN_STORAGE_KEY) === "true";
  try {
    deletedEventIds = new Set(normalizeDeletedEventIds(JSON.parse(localStorage.getItem(DELETED_EVENT_IDS_STORAGE_KEY) || "[]")));
  } catch (error) {
    deletedEventIds = new Set();
  }
  const storedDirectory = localStorage.getItem(EVENT_DIRECTORY_STORAGE_KEY);
  if (storedDirectory) {
    try { eventDirectory = JSON.parse(storedDirectory) || {}; } catch (e) {}
  }
  const storedArchivedResults = localStorage.getItem(ARCHIVED_RESULTS_STORAGE_KEY);
  if (storedArchivedResults) {
    try { archivedResultsDirectory = getArchivedResultsSnapshot(JSON.parse(storedArchivedResults) || {}); } catch (e) {}
  }

  eventDirectory = getSafeDirectorySnapshot(eventDirectory);

  if (!Object.keys(eventDirectory).length) {
    eventDirectory[DEFAULT_EVENT_ID] = await createLegacySeedEventRecord();
  }

  lastKnownRemoteActiveEventSelection = readCachedActiveEventSelection();
  const storedActiveEventId = localStorage.getItem(ACTIVE_EVENT_STORAGE_KEY) || Object.keys(eventDirectory)[0];
  const initialEventResolution = resolvePlatformCurrentEvent({
    storedActiveEventId,
    currentEventId: storedActiveEventId,
    referenceDate: new Date(),
  });
  setLocalEventPreviewModeState(Boolean(initialEventResolution?.isExplicitRoute));
  setActiveEventIdState(initialEventResolution?.eventId || storedActiveEventId);
  if (!eventDirectory[activeEventId]) {
    setActiveEventIdState(Object.keys(eventDirectory)[0]);
  }

  const cachedState = readEventStateCache(activeEventId) || {};
  applyActiveEventState({
    id: activeEventId,
    meta: cloneEventMeta(eventDirectory[activeEventId]),
    drivers: Array.isArray(cachedState.drivers) && cachedState.drivers.length ? sanitizeLoadedDrivers(cachedState.drivers) : createDriverSet(),
    bracket: cachedState.bracket ? upgradeStoredTournamentState(cachedState.bracket) : null,
    twinComp: normalizeTwinCompState(cachedState.twinComp),
    qualifyingFlow: cachedState.qualifyingFlow || createEmptyQualifyingFlow(),
    formatMode: cachedState.formatMode || FORMAT_CLASSIC,
    lowerCount: cachedState.lowerCount || "0",
  });
  const initLifecycle = reconcileActiveEventLifecycle(buildEventResults());
  const forcedEventAdminUnlocked = grantForcedEventAdminHostAccess(activeEventId);
  currentRole = forcedEventAdminUnlocked ? "admin" : getSavedRoleForEvent(activeEventId);
  const roleLockedForEvent = currentRole?.startsWith("j") && isJudgeAccessLocked(activeEventMeta);
  if (!isRoleAvailableForEvent(currentRole, activeEventMeta) || roleLockedForEvent || (currentRole !== "spectator" && !isRoleUnlockedForEvent(activeEventId, currentRole))) {
    currentRole = "spectator";
  }
  const forcedRole = getForcedRoleForHost();
  if (
    forcedRole === "admin"
    && isRoleUnlockedForEvent(activeEventId, "admin")
    && isRoleAvailableForEvent(forcedRole, activeEventMeta)
  ) {
    currentRole = forcedRole;
  }
  if (forcedRole?.startsWith("j") && isRoleUnlockedForEvent(activeEventId, forcedRole) && isRoleAvailableForEvent(forcedRole, activeEventMeta) && !isJudgeAccessLocked(activeEventMeta)) {
    currentRole = forcedRole;
  }
  document.body.dataset.role = currentRole;
  if (initLifecycle.archivedResultsChanged) saveArchivedResultsCache();
  saveDirectoryCache();
  saveEventStateCache();
}

function applyRemoteEventState(data) {
  if (!data) return;
  const nextSyncStamp = Number(data.syncStamp || 0);
  if (nextSyncStamp && nextSyncStamp < lastRemoteEventSyncStamp) {
    return;
  }
  const localJudgeDrafts = captureJudgeDraftScores(currentRole);
  const nextDrivers = Array.isArray(data.drivers) && data.drivers.length ? sanitizeLoadedDrivers(data.drivers) : createDriverSet();
  applyActiveEventState({
    id: activeEventId,
    drivers: restoreJudgeDraftScores(nextDrivers, currentRole, localJudgeDrafts),
    bracket: data.bracket ? upgradeStoredTournamentState(data.bracket) : null,
    twinComp: normalizeTwinCompState(data.twinComp),
    qualifyingFlow: data.qualifyingFlow || createEmptyQualifyingFlow(),
    formatMode: data.formatMode || FORMAT_CLASSIC,
    lowerCount: data.lowerCount || "0",
    meta: extractEventMeta(data, activeEventId),
  });
  const remoteLifecycle = reconcileActiveEventLifecycle(buildEventResults());
  lastRemoteEventSyncStamp = nextSyncStamp;
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  syncTech1ShellFromActiveEventMeta({ publish: tech1StaffCanManageSpecialEvent() });
  if (remoteLifecycle.archivedResultsChanged) saveArchivedResultsCache();
  saveDirectoryCache();
  saveEventStateCache();
  renderRoleAdminPanel();
}

function isJudgeEditingScoreInput() {
  if (!currentRole?.startsWith("j")) return false;
  if (judgeSubmissionInFlight) return false;
  const activeEl = document.activeElement;
  return Boolean(activeEl && activeEl.classList?.contains("score-input"));
}

function renderAfterRemoteSync() {
  renderEventDirectory();
  renderRoleAdminPanel();
  renderWebsiteAdminAccessState();
  renderWebsiteAdminSyncDiagnostics();
  renderLandingView();
  renderTech1DriftView();
  renderStreamerExperience();
  syncNativeBroadcastOverlays();
  renderRaceControlDashboard();
  ensureForcedHostRoleAccess();
  if (enforceWebsiteAdminHostRoute()) {
    return;
  }
  syncForcedJudgeRoleFromUnlockedState();
  if (currentRole.startsWith("j") && isJudgeAccessLocked()) {
    setDeferredInteractiveRenderPendingState(false);
    applyRoleChange("spectator");
    switchView("qualifying");
    return;
  }
  const judgeShouldUseBracketView = currentRole.startsWith("j")
    && shouldUseJudgeBracketView(currentRole, qualifyingFlow, appDrivers, tournamentState, activeEventMeta);
  if (judgeShouldUseBracketView && getActiveViewName() !== "bracket") {
    setDeferredInteractiveRenderPendingState(false);
    if (document.activeElement?.classList?.contains("score-input") && typeof document.activeElement.blur === "function") {
      document.activeElement.blur();
    }
    switchView("bracket");
    return;
  }
  if (isJudgeEditingScoreInput()) {
    setDeferredInteractiveRenderPendingState(true);
    return;
  }
  setDeferredInteractiveRenderPendingState(false);
  syncJudgeRoleClaimHeartbeat();
  syncCompetitionAutoAdvanceTimer();
  if (syncJudgeCompetitionView()) {
    return;
  }
  renderDriversTable();
  renderCommandCenter();
  if (document.getElementById('view-bracket').classList.contains('is-active')) {
    renderBracket();
  }
}

function getViewPreferenceStorageKey() {
  return `rc-drift-view-preference-v${EVENT_STORAGE_VERSION}`;
}

function getSavedViewForEventRole(eventId, role) {
  if (!eventId || !role) return null;
  try {
    const raw = localStorage.getItem(getViewPreferenceStorageKey());
    const parsed = raw ? JSON.parse(raw) : {};
    const eventViews = parsed && typeof parsed === "object" ? parsed[eventId] : null;
    const savedView = eventViews && typeof eventViews === "object" ? eventViews[role] : null;
    return ROUTABLE_VIEWS.has(savedView) ? savedView : null;
  } catch (error) {
    console.warn("View preference read failed:", error);
    return null;
  }
}

function saveViewForEventRole(eventId, role, viewName) {
  if (!eventId || !role || !ROUTABLE_VIEWS.has(viewName)) return;
  try {
    const raw = localStorage.getItem(getViewPreferenceStorageKey());
    const parsed = raw ? JSON.parse(raw) : {};
    const nextMap = parsed && typeof parsed === "object" ? parsed : {};
    const eventViews = nextMap[eventId] && typeof nextMap[eventId] === "object" ? nextMap[eventId] : {};
    eventViews[role] = viewName;
    nextMap[eventId] = eventViews;
    localStorage.setItem(getViewPreferenceStorageKey(), JSON.stringify(nextMap));
  } catch (error) {
    console.warn("View preference save failed:", error);
  }
}

function canPublishSharedDirectoryMetadata() {
  return Boolean(isWebsiteAdmin || TEST_MODE_ENABLED);
}

function buildPublicEventShell(eventMeta = activeEventMeta, options = {}) {
  const source = normalizeEventCompetitionModeState(eventMeta) || {};
  const status = getEventStatus(source);
  const qualifyingPhase = options.qualifyingPhase || getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const registrationClosed = getSelfRegistrationCloseReason(source, qualifyingFlow, appDrivers);
  return buildPublicEventShellPayload({
    eventMeta: source,
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    status,
    judgeCount: normalizeJudgeCountForMode(source.judgeCount, source.judgingMode),
    judgingMode: normalizeJudgingMode(source.judgingMode),
    qualifyingPhase,
    registrationClosed,
    hasValidVenue: hasValidVenueConfig(source),
    bracketLive: Boolean(tournamentState?.mainBracket?.rounds?.length),
    streamActive: Boolean(nativeStreamLatestState?.active),
  });
}

function buildPrivateEventConfig(eventMeta = activeEventMeta) {
  const source = normalizeEventCompetitionModeState(eventMeta) || {};
  return buildPrivateEventConfigPayload({
    eventMeta: source,
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    judgeCount: normalizeJudgeCountForMode(source.judgeCount, source.judgingMode),
    judgingMode: normalizeJudgingMode(source.judgingMode),
    competitionMode: normalizeCompetitionMode(source.competitionMode),
    roleNames: buildDefaultRoleNames(source.roleNames || {}),
    roleAccess: source.roleAccess || {},
    venueConfig: createDefaultVenueConfig(source.venueConfig || {}),
    venueProfiles: normalizeVenueProfileList(source.venueProfiles),
    judgeRoleClaims: getSanitizedJudgeRoleClaims(source),
    latestApprovalToast: source.latestApprovalToast || null,
  });
}

function buildScopedRegistrationDoc(entry, eventId = activeEventId) {
  return buildScopedRegistrationPayload(entry, {
    eventId,
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    normalizePendingRegistrationList,
    ownerUid: auth?.currentUser?.uid || null,
  });
}

function buildPublicRegistrationIndexDoc(entry, eventId = activeEventId) {
  return buildPublicRegistrationIndexPayload(entry, {
    eventId,
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    normalizePendingRegistrationList,
  });
}

function buildScopedDriverDoc(driver, eventId = activeEventId) {
  return buildScopedDriverPayload(driver, {
    eventId,
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    cloneDriver,
  });
}

function getQualifyingRunId(driverId, runKey = "run1") {
  return `${String(driverId || "driver").replace(/[^\w-]/g, "_")}_${String(runKey || "run1").replace(/[^\w-]/g, "_")}`;
}

function getJudgeSubmissionId(driverId, runKey, judgeSlot) {
  return `${getQualifyingRunId(driverId, runKey)}_${String(judgeSlot || "judge").replace(/[^\w-]/g, "_")}`;
}

function getBattleScopedId(entry = null, cycle = 1) {
  const snapshot = entry || getCompetitionJudgeControl()?.entry || getCompetitionFlowEntriesForState()?.currentEntry || {};
  const key = buildCompetitionJudgeEntryKey(snapshot) || `${snapshot.bracketKey || "main"}_${snapshot.roundIndex || 0}_${snapshot.matchIndex || 0}`;
  return `${String(key).replace(/[^\w-]/g, "_")}_c${Number(cycle || 1)}`;
}

function buildPublicAggregates() {
  const rankedDrivers = rankDrivers(appDrivers);
  const results = buildEventResults();
  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  return buildPublicAggregatesPayload({
    activeEventId,
    defaultEventId: DEFAULT_EVENT_ID,
    activeEventMeta,
    rankedDrivers,
    results,
    qualifyingPhase,
    currentDriverId: qualifyingFlow?.currentDriverId || null,
    bracketLive: Boolean(tournamentState?.mainBracket?.rounds?.length),
    tournamentState,
  });
}

async function publishScopedEventShell(eventId = activeEventId, eventMeta = activeEventMeta) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId || !eventMeta) return;
  await firestoreWriteService.publishEventShell(eventId, buildPublicEventShell(eventMeta), buildPrivateEventConfig(eventMeta));
}

async function publishScopedRegistrations(eventId = activeEventId, registrations = getPendingRegistrations()) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId) return;
  const writes = normalizePendingRegistrationList(registrations)
    .map((entry) => buildScopedRegistrationDoc(entry, eventId))
    .filter(Boolean)
    .flatMap((entry) => {
      const publicIndex = buildPublicRegistrationIndexDoc(entry, eventId);
      return [firestoreWriteService.publishRegistration(eventId, entry, publicIndex)];
    });
  await Promise.all(writes);
}

async function publishScopedRegistrationAdminPatch(entries = [], patch = {}, eventId = activeEventId) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId || TEST_MODE_ENABLED || STANDALONE_DEMO_MODE) return;
  const writes = normalizePendingRegistrationList(entries)
    .filter((entry) => entry?.id)
    .flatMap((entry) => {
      const merged = { ...entry, ...patch };
      const publicIndex = buildPublicRegistrationIndexDoc(merged, eventId);
      return [firestoreWriteService.publishRegistrationPatch(eventId, entry.id, {
          eventId,
          id: entry.id,
          schemaVersion: 2,
          ...patch,
          updatedAt: new Date().toISOString(),
        }, publicIndex)];
    });
  await Promise.all(writes);
}

async function publishScopedDrivers(eventId = activeEventId, drivers = appDrivers) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId) return;
  const writes = getRegisteredDrivers(drivers)
    .map((driver) => buildScopedDriverDoc(driver, eventId))
    .filter(Boolean)
    .map((driver) => firestoreWriteService.publishDriver(eventId, driver));
  await Promise.all(writes);
}

async function publishScopedBracketAndAggregates(eventId = activeEventId) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId) return;
  const aggregates = buildPublicAggregates();
  await firestoreWriteService.publishBracket(eventId, {
      eventId,
      schemaVersion: 2,
      state: tournamentState ? JSON.parse(JSON.stringify(tournamentState)) : null,
      formatMode: bracketModeSelect?.value || activeEventState.formatMode || FORMAT_CLASSIC,
      lowerCount: String(activeEventState.lowerCount || lowerCountInput?.value || "0"),
      published: true,
      updatedAt: new Date().toISOString(),
    }, Object.entries(aggregates));
}

async function publishScopedActiveEventState(eventId = activeEventId) {
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !auth?.currentUser || !eventId || !activeEventMeta) return;
  if (STANDALONE_DEMO_MODE || TEST_MODE_ENABLED) return;
  try {
    await Promise.all([
      publishScopedEventShell(eventId, activeEventMeta),
      publishScopedRegistrations(eventId, getPendingRegistrations()),
      publishScopedDrivers(eventId, appDrivers),
      publishScopedBracketAndAggregates(eventId),
    ]);
  } catch (error) {
    console.error("Scoped event sync failed:", error);
  }
}

async function publishScopedJudgeSubmission({ eventId = activeEventId, driverId, runKey, judgeSlot, score, submittedScore }) {
  if (!db || !auth?.currentUser || !eventId || !driverId || !runKey || !judgeSlot) return false;
  const numericScore = Number(submittedScore ?? score);
  if (!Number.isFinite(numericScore)) return false;
  const runId = getQualifyingRunId(driverId, runKey);
  const submissionId = getJudgeSubmissionId(driverId, runKey, judgeSlot);
  const nowIso = new Date().toISOString();
  await firestoreWriteService.publishQualifyingRunAndJudgeSubmission(eventId, runId, {
      eventId,
      runId,
      driverId,
      runKey,
      schemaVersion: 2,
      status: "scoring",
      updatedAt: nowIso,
    }, submissionId, {
      eventId,
      runId,
      driverId,
      runKey,
      judgeSlot,
      score: numericScore,
      submittedScore: numericScore,
      schemaVersion: 2,
      submittedAt: nowIso,
      updatedAt: nowIso,
    });
  return true;
}

async function publishScopedBattleVote({ eventId = activeEventId, battleId, judgeSlot, side, scorecard = null, cycle = 1 }) {
  if (!db || !auth?.currentUser || !eventId || !battleId || !judgeSlot) return false;
  const nowIso = new Date().toISOString();
  const voteId = `${String(battleId).replace(/[^\w-]/g, "_")}_${String(judgeSlot).replace(/[^\w-]/g, "_")}`;
  await firestoreWriteService.publishBattleVote(eventId, voteId, {
    eventId,
    battleId,
    judgeSlot,
    side: ["left", "right", "omt"].includes(side) ? side : null,
    scorecard,
    cycle: Number(cycle || 1),
    schemaVersion: 2,
    submittedAt: nowIso,
    updatedAt: nowIso,
  });
  return true;
}

function normalizeIceServerEntries(value) {
  const entries = Array.isArray(value) ? value : [];
  return entries
    .map((entry) => {
      if (!entry) return null;
      if (typeof entry === "string") {
        return { urls: [entry] };
      }
      if (!isPlainObject(entry)) return null;
      const urls = Array.isArray(entry.urls)
        ? entry.urls.map((url) => String(url || "").trim()).filter(Boolean)
        : [String(entry.urls || "").trim()].filter(Boolean);
      if (!urls.length) return null;
      const normalized = { urls };
      if (entry.username) normalized.username = String(entry.username);
      if (entry.credential) normalized.credential = String(entry.credential);
      return normalized;
    })
    .filter(Boolean);
}

function getNativeRtcConfiguration() {
  const configuredIceServers = normalizeIceServerEntries(CLIENT_STREAMING.iceServers);
  return {
    iceServers: configuredIceServers.length ? configuredIceServers : [...NATIVE_STREAM_DEFAULT_ICE_SERVERS],
    iceCandidatePoolSize: 4,
    bundlePolicy: "max-bundle",
  };
}

function getThemeAwareLogoSource(primaryLogo = CLIENT_BRANDING.logoPrimary || "./assets/prodigy-rc-logo-transparent.png", invertedLogo = CLIENT_BRANDING.logoInverted || primaryLogo) {
  return document.body?.dataset.theme === "dark" ? invertedLogo : primaryLogo;
}

function loadActiveEventStateFromCache() {
  if (!activeEventId || !eventDirectory[activeEventId]) return;
  const cachedState = readEventStateCache(activeEventId) || {};
  applyActiveEventState({
    id: activeEventId,
    meta: cloneEventMeta(eventDirectory[activeEventId]),
    drivers: Array.isArray(cachedState.drivers) && cachedState.drivers.length ? sanitizeLoadedDrivers(cachedState.drivers) : createDriverSet(),
    bracket: cachedState.bracket ? upgradeStoredTournamentState(cachedState.bracket) : null,
    twinComp: normalizeTwinCompState(cachedState.twinComp),
    qualifyingFlow: cachedState.qualifyingFlow || createEmptyQualifyingFlow(),
    formatMode: cachedState.formatMode || FORMAT_CLASSIC,
    lowerCount: cachedState.lowerCount || "0",
  });
  const cachedLifecycle = reconcileActiveEventLifecycle(buildEventResults());
  if (cachedLifecycle.archivedResultsChanged) saveArchivedResultsCache();
}

function buildDirectorySyncPayload(nextOverrides = {}) {
  return {
    events: getPersistableDirectorySnapshot(nextOverrides),
    activeEventId,
    deletedEventIds: getDeletedEventIdsSnapshot(),
    syncStamp: lastLocalPush,
  };
}

function publishActiveEventSelection() {
  saveDirectoryCache();
  saveEventStateCache();
  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db || !activeEventId) return;
  if (!canPublishSharedDirectoryMetadata()) return;
  if (!auth?.currentUser) {
    pendingCloudBootstrapSync = true;
    return;
  }
  lastLocalPush = Date.now();
  saveDirectoryCache();
  const directoryPayload = buildDirectorySyncPayload({
    [activeEventId]: eventDirectory[activeEventId] || activeEventMeta,
  });
  const activeEventPayload = {
    activeEventId,
    eventMeta: cloneEventMeta(directoryPayload.events[activeEventId] || activeEventMeta),
    syncStamp: lastLocalPush,
  };
  lastKnownRemoteActiveEventSelection = normalizeActiveEventSelectionSnapshot(activeEventPayload);
  saveCachedActiveEventSelection(activeEventPayload);
  firestoreWriteService.publishActiveEventSelection(activeEventPayload, directoryPayload).catch((error) => {
    console.error("Active event sync failed:", error);
  });
}

function resolveRoleForActiveEventSwitch(nextActiveEventId, preferredRole = currentRole) {
  const nextMeta = eventDirectory[nextActiveEventId];
  if (!nextMeta) return "spectator";
  const nextJudgeAccessLocked = isJudgeAccessLocked(nextMeta);
  const preferredRoleBlocked = preferredRole?.startsWith("j") ? nextJudgeAccessLocked : false;
  if (
    preferredRole
    && preferredRole !== "spectator"
    && isRoleAvailableForEvent(preferredRole, nextMeta)
    && !preferredRoleBlocked
    && isBrowserPersistentEventAdminRole(preferredRole)
    && isEventAdminBrowserUnlocked()
  ) {
    setRoleUnlockedForEvent(nextActiveEventId, preferredRole, true);
    return preferredRole;
  }
  if (preferredRole && preferredRole !== "spectator" && isRoleAvailableForEvent(preferredRole, nextMeta) && !preferredRoleBlocked && isRoleUnlockedForEvent(nextActiveEventId, preferredRole)) {
    return preferredRole;
  }
  const savedRole = getSavedRoleForEvent(nextActiveEventId);
  const savedRoleBlocked = savedRole?.startsWith("j") ? nextJudgeAccessLocked : false;
  if (savedRole && savedRole !== "spectator" && isRoleAvailableForEvent(savedRole, nextMeta) && !savedRoleBlocked && isRoleUnlockedForEvent(nextActiveEventId, savedRole)) {
    return savedRole;
  }
  return "spectator";
}

function adoptActiveEvent(nextActiveEventId, preferredRole = currentRole) {
  if (!nextActiveEventId || !eventDirectory[nextActiveEventId]) return false;
  const activeEventChanged = nextActiveEventId !== activeEventId;
  const requestedRoute = parseRouteFromLocation();
  const resolvedRole = resolveRoleForActiveEventSwitch(nextActiveEventId, preferredRole);
  if (requestedRoute?.kind === "role") {
    setPendingRouteViewState(normalizeRouteViewForRole(resolvedRole, requestedRoute.view));
  }
  setActiveEventIdState(nextActiveEventId);
  loadActiveEventStateFromCache();
  applyRoleChange(resolvedRole);
  if (requestedRoute?.kind === "website-admin") {
    switchView("website-admin");
  } else if (requestedRoute?.kind === "role") {
    switchView(normalizeRouteViewForRole(currentRole, requestedRoute.view));
  }
  saveDirectoryCache();
  if (activeEventChanged) {
    setJudgeLaneIndexState(0);
    const preservedView = getActiveViewName() === "website-admin" || requestedRoute?.kind === "website-admin"
      ? "website-admin"
      : requestedRoute?.kind === "role"
        ? normalizeRouteViewForRole(currentRole, requestedRoute.view)
        : normalizeRouteViewForRole(currentRole, getActiveViewName());
    switchView(preservedView || getDefaultViewForRole(currentRole));
    subscribeToActiveEvent();
  }
  return activeEventChanged;
}

function applyDirectorySnapshotData(data) {
  if (LOCAL_EVENT_DATA_MODE) return false;
  if (!data) return false;
  const nextSyncStamp = Number(data.syncStamp || 0);
  if (nextSyncStamp && nextSyncStamp < lastLocalPush) {
    return false;
  }
  if (nextSyncStamp && nextSyncStamp < lastRemoteDirectorySyncStamp) {
    return false;
  }
  hasLoadedRemoteDirectory = true;
  deletedEventIds = new Set(normalizeDeletedEventIds(data.deletedEventIds || []));
  lastRemoteDirectorySyncStamp = nextSyncStamp;
  lastRemoteDirectoryEvents = mergeDirectoryMaps(data.events || {});
  eventDirectory = getRecoveredDirectorySnapshot(data.events || {});
  if (data.activeEventId && eventDirectory[data.activeEventId]) {
    saveCachedActiveEventSelection({
      activeEventId: data.activeEventId,
      eventMeta: data.events?.[data.activeEventId] || eventDirectory[data.activeEventId],
      syncStamp: nextSyncStamp,
    });
  }
  const keepLocalSelection = shouldKeepCurrentRouteEventSelectionLocal();
  const resolvedEvent = resolvePlatformCurrentEvent({
    directoryActiveEventId: data.activeEventId,
    directoryEventMeta: data.events?.[data.activeEventId] || eventDirectory[data.activeEventId],
    directorySyncStamp: nextSyncStamp,
  });
  if (resolvedEvent?.eventId && resolvedEvent.eventId !== activeEventId && (!keepLocalSelection || resolvedEvent.isExplicitRoute)) {
    adoptActiveEvent(resolvedEvent.eventId, currentRole);
  } else if (!activeEventId || !eventDirectory[activeEventId]) {
    if (lastRemoteActiveEventSyncStamp && activeEventId && activeEventMeta?.id === activeEventId) {
      eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
      saveDirectoryCache();
      renderAfterRemoteSync();
      return false;
    }
    const fallbackId = resolvedEvent?.eventId || Object.keys(eventDirectory)[0] || null;
    if (fallbackId) {
      adoptActiveEvent(fallbackId, currentRole);
    }
  } else {
    if (resolvedEvent?.shouldFollowShared && !keepLocalSelection && localEventPreviewMode) {
      setLocalEventPreviewModeState(false);
    }
    setActiveEventMetaState(cloneEventMeta(eventDirectory[activeEventId]));
  }
  ensureForcedHostRoleAccess();
  syncRequestedRouteEventSelection({ route: parseRouteFromLocation() });
  saveDirectoryCache();
  renderAfterRemoteSync();
  return false;
}

function applyActiveEventSelectionData(data) {
  if (LOCAL_EVENT_DATA_MODE) return false;
  const normalizedSelection = normalizeActiveEventSelectionSnapshot(data);
  if (!normalizedSelection?.activeEventId) return false;
  const nextActiveEventId = normalizedSelection.activeEventId;
  const nextSyncStamp = Number(data.syncStamp || 0);
  if (nextSyncStamp && nextSyncStamp < lastLocalPush) {
    return false;
  }
  if (nextSyncStamp && nextSyncStamp < lastRemoteActiveEventSyncStamp) {
    return false;
  }
  lastRemoteActiveEventSyncStamp = nextSyncStamp;
  lastKnownRemoteActiveEventSelection = normalizedSelection;
  saveCachedActiveEventSelection(normalizedSelection);
  if (normalizedSelection.eventMeta) {
    eventDirectory[nextActiveEventId] = cloneEventMeta(normalizedSelection.eventMeta);
  }
  const keepLocalSelection = shouldKeepCurrentRouteEventSelectionLocal();
  if (keepLocalSelection && activeEventId && eventDirectory[activeEventId] && nextActiveEventId !== activeEventId) {
    renderAfterRemoteSync();
    return false;
  }
  const activeEventChanged = adoptActiveEvent(nextActiveEventId, currentRole);
  if (!keepLocalSelection && localEventPreviewMode) {
    setLocalEventPreviewModeState(false);
  }
  ensureForcedHostRoleAccess();
  syncRequestedRouteEventSelection({ route: parseRouteFromLocation() });
  renderAfterRemoteSync();
  return activeEventChanged;
}

function applyArchivedResultsSnapshotData(data) {
  if (LOCAL_EVENT_DATA_MODE) return false;
  const nextSyncStamp = Number(data?.syncStamp || 0);
  if (nextSyncStamp && nextSyncStamp < lastRemoteArchivedResultsSyncStamp) {
    return false;
  }
  lastRemoteArchivedResultsSyncStamp = nextSyncStamp;
  archivedResultsDirectory = getArchivedResultsSnapshot(data?.events || {});
  saveArchivedResultsCache();
  renderAfterRemoteSync();
  return false;
}

function stopScopedEventSubscriptions() {
  scopedEventSubscriptions.clearAll();
  scopedRegistrationsUnsubscribe = null;
  scopedDriversUnsubscribe = null;
  scopedJudgeSubmissionsUnsubscribe = null;
  scopedBattleVotesUnsubscribe = null;
  scopedBracketUnsubscribe = null;
  scopedAggregatesUnsubscribe = null;
}

function applyScopedRegistrationDocs(docs = []) {
  if (!docs.length || !activeEventMeta) return;
  const remoteEntries = buildPendingRegistrationsFromPublicIndexDocs(docs, {
    normalizePendingRegistrationList,
  });
  const localById = new Map(getPendingRegistrations().map((entry) => [entry.id, entry]));
  remoteEntries.forEach((entry) => {
    localById.set(entry.id, {
      ...(localById.get(entry.id) || {}),
      ...entry,
    });
  });
  setActiveEventMetaState({
    ...activeEventMeta,
    pendingRegistrations: Array.from(localById.values()),
  }, { syncQualifying: false });
}

function applyScopedDriverDocs(docs = []) {
  if (!docs.length) return;
  const remoteDrivers = docs
    .map((entry) => entry.data)
    .filter((driver) => driver?.id)
    .map((driver) => sanitizeLoadedDrivers([driver])[0])
    .filter(Boolean);
  if (!remoteDrivers.length) return;
  const localById = new Map(appDrivers.map((driver) => [driver.id, driver]));
  remoteDrivers.forEach((driver) => {
    localById.set(driver.id, {
      ...(localById.get(driver.id) || createEmptyDriver()),
      ...driver,
    });
  });
  setActiveDriversState(resequenceDrivers(Array.from(localById.values()), true));
}

function applyScopedJudgeSubmissionDocs(docs = []) {
  if (!docs.length) return;
  const result = applyScopedJudgeSubmissionDocsToDrivers(appDrivers, docs, {
    getRunKey,
  });
  if (result.changed) {
    setActiveDriversState(resequenceDrivers(result.drivers, true));
  }
}

function applyScopedBracketDoc(data = null) {
  if (!data?.state) return;
  setTournamentStateState(upgradeStoredTournamentState(data.state), { syncQualifying: false });
}

function subscribeToScopedEventModel(eventId = activeEventId) {
  if (!db || !auth?.currentUser || !eventId || TEST_MODE_ENABLED) return;
  stopScopedEventSubscriptions();
  if (LOCAL_EVENT_DATA_MODE) {
    scopedJudgeSubmissionsUnsubscribe = scopedEventSubscriptions.replace("judgeSubmissions", eventReadService.subscribeJudgeSubmissions(eventId, (docs) => {
      applyScopedJudgeSubmissionDocs(docs);
      renderAfterRemoteSync();
    }, (error) => console.error("Scoped judge submissions listener failed:", error)));
    return;
  }
  scopedRegistrationsUnsubscribe = scopedEventSubscriptions.replace("registrations", eventReadService.subscribePublicRegistrationIndex(eventId, (docs) => {
    applyScopedRegistrationDocs(docs);
    renderAfterRemoteSync();
  }, (error) => console.error("Scoped registration index listener failed:", error)));
  scopedDriversUnsubscribe = scopedEventSubscriptions.replace("drivers", eventReadService.subscribeDrivers(eventId, (docs) => {
    applyScopedDriverDocs(docs);
    renderAfterRemoteSync();
  }, (error) => console.error("Scoped drivers listener failed:", error)));
  scopedJudgeSubmissionsUnsubscribe = scopedEventSubscriptions.replace("judgeSubmissions", eventReadService.subscribeJudgeSubmissions(eventId, (docs) => {
    applyScopedJudgeSubmissionDocs(docs);
    renderAfterRemoteSync();
  }, (error) => console.error("Scoped judge submissions listener failed:", error)));
  scopedBracketUnsubscribe = scopedEventSubscriptions.replace("bracket", eventReadService.subscribeBracket(eventId, (result) => {
    if (result.exists) {
      applyScopedBracketDoc(result.data);
      renderAfterRemoteSync();
    }
  }, (error) => console.error("Scoped bracket listener failed:", error)));
  scopedAggregatesUnsubscribe = scopedEventSubscriptions.replace("aggregates", eventReadService.subscribePublicAggregates(eventId, () => {
    renderAfterRemoteSync();
  }, (error) => console.error("Scoped aggregates listener failed:", error)));
}

function subscribeToActiveEvent() {
  if (!db || !auth?.currentUser || !activeEventId) return;
  if (eventDocUnsubscribe) eventDocUnsubscribe();
  eventDocUnsubscribe = null;
  if (LOCAL_EVENT_DATA_MODE) {
    subscribeToScopedEventModel(activeEventId);
    return;
  }
  subscribeToNativeLiveStream();
  subscribeToScopedEventModel(activeEventId);

  const subscribedEventId = activeEventId;
  eventDocUnsubscribe = eventReadService.subscribeEvent(activeEventId, (result) => {
    if (!result.exists) return;
    if (subscribedEventId !== activeEventId) return;
    applyRemoteEventState(result.data);
    renderAfterRemoteSync();
  }, (error) => {
    const statusEl = document.getElementById('syncStatus');
    statusEl.textContent = "Sync Error";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    console.error(error);
  });
  eventReadService.readEvent(activeEventId).then((result) => {
    if (!result.exists) return;
    if (subscribedEventId !== activeEventId) return;
    applyRemoteEventState(result.data);
    renderAfterRemoteSync();
  }).catch((error) => {
    console.error("Event refresh failed:", error);
  });
}

function publishState() {
  if (!activeEventId || !activeEventMeta) return;
  syncQualifyingFlowState();
  syncActiveEventStateFromControls();

  const updatedAt = new Date().toISOString();
  setActiveEventMetaState({
    ...activeEventMeta,
    updatedAt,
  });
  const lifecycle = reconcileActiveEventLifecycle(buildEventResults());

  saveDirectoryCache();
  saveEventStateCache();
  if (lifecycle.archivedResultsChanged) saveArchivedResultsCache();

  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db) return;
  if (!auth?.currentUser) {
    pendingCloudBootstrapSync = true;
    return;
  }
  lastLocalPush = Date.now();
  activeEventMeta.syncStamp = lastLocalPush;
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  saveDirectoryCache();

  const persistableState = getPersistableActiveEventState();
  const publishEventId = activeEventId;
  const publishEventMeta = cloneEventMeta(activeEventMeta);
  const publishDrivers = JSON.parse(JSON.stringify(persistableState.drivers));
  const publishBracket = persistableState.bracket ? JSON.parse(JSON.stringify(persistableState.bracket)) : null;
  const publishTwinComp = persistableState.twinComp ? JSON.parse(JSON.stringify(persistableState.twinComp)) : null;
  const publishQualifyingFlow = JSON.parse(JSON.stringify(persistableState.qualifyingFlow));
  const publishFormatMode = persistableState.formatMode;
  const publishLowerCount = persistableState.lowerCount;
  const directoryPayload = buildDirectorySyncPayload({
    [publishEventId]: publishEventMeta,
  });
  const publishSyncStamp = lastLocalPush;

  clearTimeout(syncTimeout);
  syncTimeout = setTimeout(async () => {
    try {
      const syncTasks = [
        setDoc(getEventDocRef(publishEventId), (!TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE && Number(publishEventMeta.schemaVersion || 1) >= 2)
          ? buildPublicEventShell({ ...publishEventMeta, syncStamp: publishSyncStamp })
          : {
            ...publishEventMeta,
            drivers: publishDrivers,
            bracket: publishBracket,
            twinComp: publishTwinComp,
            qualifyingFlow: publishQualifyingFlow,
            formatMode: publishFormatMode,
            lowerCount: publishLowerCount,
            syncStamp: publishSyncStamp,
          }),
      ];
      if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
        syncTasks.push(setDoc(getDirectoryDocRef(), {
          ...directoryPayload,
          activeEventId: publishEventId,
          syncStamp: publishSyncStamp,
        }));
        if (lifecycle.archivedResultsChanged) {
          syncTasks.push(setDoc(getArchivedResultsDocRef(), {
            events: getArchivedResultsSnapshot(),
            syncStamp: publishSyncStamp,
          }));
        }
      }
    await Promise.all(syncTasks);
    await publishScopedActiveEventState(publishEventId);
  } catch (e) {
    console.error("Cloud sync failed:", e);
    handleCloudPermissionError(e, "eventAdmin", "event sync");
  }
  }, 800);
}

async function publishStateImmediately() {
  if (!activeEventId || !activeEventMeta) return;
  syncQualifyingFlowState();
  syncActiveEventStateFromControls();

  clearTimeout(syncTimeout);

  const updatedAt = new Date().toISOString();
  setActiveEventMetaState({
    ...activeEventMeta,
    updatedAt,
  });
  const lifecycle = reconcileActiveEventLifecycle(buildEventResults());

  saveDirectoryCache();
  saveEventStateCache();
  if (lifecycle.archivedResultsChanged) saveArchivedResultsCache();

  if (LOCAL_EVENT_DATA_MODE) return true;
  if (!db) return;
  if (!auth?.currentUser) {
    pendingCloudBootstrapSync = true;
    return;
  }
  lastLocalPush = Date.now();
  activeEventMeta.syncStamp = lastLocalPush;
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  saveDirectoryCache();
  const persistableState = getPersistableActiveEventState();
  const directoryPayload = buildDirectorySyncPayload({
    [activeEventId]: activeEventMeta,
  });

  try {
    const syncTasks = [
      setDoc(getEventDocRef(activeEventId), (!TEST_MODE_ENABLED && !STANDALONE_DEMO_MODE && Number(activeEventMeta.schemaVersion || 1) >= 2)
        ? buildPublicEventShell({ ...activeEventMeta, syncStamp: lastLocalPush })
        : {
          ...activeEventMeta,
          drivers: persistableState.drivers,
          bracket: persistableState.bracket,
          twinComp: persistableState.twinComp,
          qualifyingFlow: persistableState.qualifyingFlow,
          formatMode: persistableState.formatMode,
          lowerCount: persistableState.lowerCount,
          syncStamp: lastLocalPush,
        }),
    ];
    if (!STANDALONE_DEMO_MODE && canPublishSharedDirectoryMetadata()) {
      lastKnownRemoteActiveEventSelection = normalizeActiveEventSelectionSnapshot({
        activeEventId,
        eventMeta: cloneEventMeta(directoryPayload.events[activeEventId] || activeEventMeta),
        syncStamp: lastLocalPush,
      });
      saveCachedActiveEventSelection(lastKnownRemoteActiveEventSelection);
      syncTasks.push(
        setDoc(getDirectoryDocRef(), directoryPayload),
        setDoc(getActiveEventSelectionDocRef(), {
          activeEventId,
          eventMeta: cloneEventMeta(directoryPayload.events[activeEventId] || activeEventMeta),
          syncStamp: lastLocalPush,
        }, { merge: true }),
      );
      if (lifecycle.archivedResultsChanged) {
        syncTasks.push(setDoc(getArchivedResultsDocRef(), {
          events: getArchivedResultsSnapshot(),
          syncStamp: lastLocalPush,
        }));
      }
    }
    await Promise.all(syncTasks);
    await publishScopedActiveEventState(activeEventId);
    return true;
  } catch (e) {
    console.error("Immediate cloud sync failed:", e);
    handleCloudPermissionError(e, "eventAdmin", "event sync");
    return false;
  }
}

async function publishPublicRegistrationState() {
  if (!activeEventId || !activeEventMeta) return;
  const updatedAt = new Date().toISOString();
  lastLocalPush = Date.now();
  setActiveEventMetaState({
    ...activeEventMeta,
    updatedAt,
    syncStamp: lastLocalPush,
  }, { syncQualifying: false });
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  saveDirectoryCache();
  saveEventStateCache();

  if (LOCAL_EVENT_DATA_MODE) return;
  if (!db) return;
  if (!auth?.currentUser) {
    pendingCloudBootstrapSync = true;
    return;
  }
  try {
    if (TEST_MODE_ENABLED || STANDALONE_DEMO_MODE) {
      await setDoc(getEventDocRef(activeEventId), {
        pendingRegistrations: normalizePendingRegistrationList(activeEventMeta.pendingRegistrations),
        updatedAt,
        syncStamp: lastLocalPush,
      }, { merge: true });
      return;
    }
    await publishScopedRegistrations(activeEventId, activeEventMeta.pendingRegistrations);
    await setDoc(getEventDocRef(activeEventId), buildPublicEventShell(activeEventMeta), { merge: true });
  } catch (error) {
    console.error("Public registration sync failed:", error);
    handleCloudPermissionError(error, "driver", "registration");
  }
}

async function bootstrapStandaloneDemoSession() {
  if (!STANDALONE_DEMO_MODE || !db || !activeEventId) return;
  const statusEl = document.getElementById('syncStatus');
  if (statusEl) {
    statusEl.textContent = "Demo Window";
    statusEl.classList.remove("online", "connecting");
  }
  subscribeToActiveEvent();
  try {
    const eventSnap = await eventReadService.readEvent(activeEventId);
    if (!eventSnap.exists) {
      await publishStateImmediately();
      return;
    }
    applyRemoteEventState(eventSnap.data);
    renderAfterRemoteSync();
  } catch (error) {
    console.error("Standalone demo bootstrap failed:", error);
  }
}

function setupCloudSync(user) {
  if (!db || !user) return;
  const statusEl = document.getElementById('syncStatus');
  if (STANDALONE_DEMO_MODE) {
    statusEl.textContent = "Demo Window";
    statusEl.classList.remove("online", "connecting");
    bootstrapStandaloneDemoSession();
    return;
  }
  syncNetworkStatusIndicator();
  refreshCloudClaims(false).then(() => {
    renderAfterRemoteSync();
  }).catch((error) => {
    console.error("Initial cloud claim refresh failed:", error);
  });

  if (directoryDocUnsubscribe) directoryDocUnsubscribe();
  directoryDocUnsubscribe = eventReadService.subscribeDirectory((result) => {
    if (!result.exists) return;
    applyDirectorySnapshotData(result.data);
  }, (error) => {
    statusEl.textContent = "Sync Error";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    console.error(error);
  });

  eventReadService.readDirectory().then((result) => {
    if (!result.exists) return;
    applyDirectorySnapshotData(result.data);
  }).catch((error) => {
    console.error("Directory refresh failed:", error);
  });

  if (activeEventSelectionUnsubscribe) activeEventSelectionUnsubscribe();
  activeEventSelectionUnsubscribe = eventReadService.subscribeActiveEventSelection((result) => {
    if (!result.exists) return;
    applyActiveEventSelectionData(result.data);
  }, (error) => {
    statusEl.textContent = "Sync Error";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    console.error(error);
  });

  eventReadService.readActiveEventSelection().then((result) => {
    if (!result.exists) return;
    applyActiveEventSelectionData(result.data);
  }).catch((error) => {
    console.error("Active event refresh failed:", error);
  });

  if (archivedResultsDocUnsubscribe) archivedResultsDocUnsubscribe();
  archivedResultsDocUnsubscribe = eventReadService.subscribeResultsArchive((result) => {
    if (!result.exists) return;
    applyArchivedResultsSnapshotData(result.data);
  }, (error) => {
    statusEl.textContent = "Sync Error";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    console.error(error);
  });

  eventReadService.readResultsArchive().then((result) => {
    if (!result.exists) return;
    applyArchivedResultsSnapshotData(result.data);
  }).catch((error) => {
    console.error("Results archive refresh failed:", error);
  });

  setupTech1SpecialEventSync();
  subscribeToActiveEvent();
  if (pendingCloudBootstrapSync && activeEventId && activeEventMeta) {
    pendingCloudBootstrapSync = false;
    window.setTimeout(() => {
      publishStateImmediately().catch((error) => {
        console.error("Deferred cloud bootstrap sync failed:", error);
      });
    }, 0);
  }
}

function cleanupTech1SpecialEventSync() {
  tech1SpecialEventUnsubscribes.forEach((unsubscribe) => {
    try {
      unsubscribe?.();
    } catch (error) {
      console.warn("Tech 1 subscription cleanup failed", error);
    }
  });
  tech1SpecialEventUnsubscribes = [];
}

function updateTech1SpecialEventState(patch = {}) {
  tech1SpecialEventState = {
    ...tech1SpecialEventState,
    ...patch,
  };
  saveTech1LocalState(tech1SpecialEventState);
  if (getActiveViewName() === "tech1") {
    renderTech1DriftView();
  }
  if (getActiveViewName() === "registration") {
    renderTech1EventControlWorkflow();
  }
  if (getActiveViewName() === "bracket") {
    renderBracket();
  }
}

function syncTech1ShellFromActiveEventMeta(options = {}) {
  const { publish = false } = options || {};
  if (!isTech1AnniversaryMode(activeEventMeta)) return false;
  const judgeCount = normalizeJudgeCountForMode(activeEventMeta?.judgeCount, activeEventMeta?.judgingMode);
  const judgingMode = normalizeJudgingMode(activeEventMeta?.judgingMode);
  const currentEvent = tech1SpecialEventState.event || buildTech1AnniversaryShell();
  const needsUpdate = Number(currentEvent.judgeCount || 0) !== judgeCount
    || normalizeJudgingMode(currentEvent.judgingMode) !== judgingMode;
  if (!needsUpdate) return false;
  const updatedEvent = buildTech1AnniversaryShell({
    ...currentEvent,
    judgeCount,
    judgingMode,
    updatedAt: new Date().toISOString(),
  });
  updateTech1SpecialEventState({ event: updatedEvent });
  if (publish && tech1StaffCanManageSpecialEvent() && !shouldUseTech1LocalStore() && db && auth?.currentUser) {
    firestoreWriteService.publishSpecialEventShell(getActiveTech1SpecialEventId(), updatedEvent)
      .catch((error) => {
        if (!handleTech1PermissionError(error, "sync Tech 1 judge count")) {
          console.error("Tech 1 judge count sync failed:", error);
        }
      });
  }
  return true;
}

function setupTech1SpecialEventSync() {
  cleanupTech1SpecialEventSync();
  if (!isTech1AnniversaryMode(activeEventMeta)) return;
  updateTech1SpecialEventState({
    event: buildTech1AnniversaryShell({
      ...(tech1SpecialEventState.event || {}),
      updatedAt: new Date().toISOString(),
    }),
    publicIndex: [],
    privateRegistrations: [],
    raffleTransactions: [],
    bracket: null,
    battleResults: [],
    syncError: "",
  });
  if (shouldUseTech1LocalStore()) {
    updateTech1SpecialEventState(loadTech1LocalState());
    return;
  }
  if (!db || !auth?.currentUser || STANDALONE_DEMO_MODE) return;
  const eventId = getActiveTech1SpecialEventId();
  const onReadError = (error) => {
    if (isPermissionDeniedError(error)) {
      updateTech1SpecialEventState({ syncError: "Some staff-only Tech 1 data requires event admin access." });
      return;
    }
    console.error("Tech 1 special event sync failed:", error);
    updateTech1SpecialEventState({ syncError: "Tech 1 event sync is temporarily unavailable." });
  };

  tech1SpecialEventUnsubscribes.push(
    firestoreReadService.subscribeDoc(getSpecialEventDocRef(eventId), (result) => {
      updateTech1SpecialEventState({ event: result.exists ? result.data : null, syncError: "" });
      syncTech1ShellFromActiveEventMeta({ publish: tech1StaffCanManageSpecialEvent() });
    }, onReadError),
    firestoreReadService.subscribeCollection(getSpecialEventPublicRegistrationIndexCollectionRef(eventId), (docs) => {
      updateTech1SpecialEventState({
        publicIndex: docs.map((entry) => ({ id: entry.id, ...entry.data })),
        syncError: "",
      });
    }, onReadError),
    firestoreReadService.subscribeDoc(getSpecialEventBracketDocRef(eventId, "main"), (result) => {
      updateTech1SpecialEventState({ bracket: result.exists ? result.data : null, syncError: "" });
    }, onReadError),
    firestoreReadService.subscribeCollection(getSpecialEventBattleResultsCollectionRef(eventId), (docs) => {
      updateTech1SpecialEventState({
        battleResults: docs.map((entry) => ({ id: entry.id, ...entry.data })),
        syncError: "",
      });
    }, onReadError),
  );

  if (tech1StaffCanManageSpecialEvent()) {
    tech1SpecialEventUnsubscribes.push(
      firestoreReadService.subscribeCollection(getSpecialEventRegistrationsCollectionRef(eventId), (docs) => {
        updateTech1SpecialEventState({
          privateRegistrations: docs.map((entry) => ({ id: entry.id, ...entry.data })),
          syncError: "",
        });
      }, onReadError),
      firestoreReadService.subscribeCollection(getSpecialEventRaffleTransactionsCollectionRef(eventId), (docs) => {
        updateTech1SpecialEventState({
          raffleTransactions: docs.map((entry) => ({ id: entry.id, ...entry.data })),
          syncError: "",
        });
      }, onReadError),
    );
  } else {
    updateTech1SpecialEventState({ privateRegistrations: [], raffleTransactions: [] });
  }
}

// Initialize Database if available
if (firebaseConfig && !QA_OFFLINE_MODE) {
  const firebaseRuntime = initializeProdigyFirebase(firebaseConfig, {
    useEmulators: USE_FIREBASE_EMULATORS,
    emulatorHost: FIREBASE_EMULATOR_HOST,
    authEmulatorPort: FIREBASE_AUTH_EMULATOR_PORT,
    firestoreEmulatorPort: FIREBASE_FIRESTORE_EMULATOR_PORT,
  });
  auth = firebaseRuntime.auth;
  db = firebaseRuntime.db;

  const initAuth = async () => {
    if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
      await signInWithCustomToken(auth, __initial_auth_token);
    } else {
      await signInAnonymously(auth);
    }
  };

  initAuth().then(() => {
    onAuthStateChanged(auth, (user) => {
      if (user) {
        renderWebsiteAdminAccessDiagnostics();
        setupCloudSync(user);
        if (nativeStreamActive && activeEventId && nativeStreamSessionId && !nativeStreamViewerUnsubscribe) {
          listenForNativeStreamViewers().catch((error) => console.error("Native viewer listener bootstrap failed:", error));
        }
      }
    });
  }).catch((error) => {
    const statusEl = document.getElementById("syncStatus");
    if (statusEl) {
      statusEl.textContent = "Sync Sign-In Error";
      statusEl.classList.remove("online", "connecting");
      statusEl.classList.add("offline-protected");
    }
    console.error("Cloud auth bootstrap failed:", error);
  });
}

async function ensureCloudAuthReady(timeoutMs = 12000) {
  if (!auth) return false;
  if (auth.currentUser) return true;
  if (typeof auth.authStateReady === "function") {
    await Promise.race([
      auth.authStateReady().catch(() => {}),
      new Promise((resolve) => window.setTimeout(resolve, timeoutMs)),
    ]);
  }
  if (auth.currentUser) return true;
  try {
    await signInAnonymously(auth);
  } catch (error) {
    console.error("Anonymous auth refresh failed:", error);
  }
  return Boolean(auth.currentUser);
}

window.addEventListener("online", async () => {
  syncNetworkStatusIndicator();
  if (db && auth?.currentUser) {
    setupCloudSync(auth.currentUser);
    await publishStateImmediately();
  }
});

window.addEventListener("offline", () => {
  syncNetworkStatusIndicator();
});

