function getConfiguredWindowBaseUrl() {
  if (typeof window !== "undefined" && window.location.href) return window.location.href;
  return "https://example.com/";
}

function shouldKeepStandaloneDemoOnCurrentOrigin() {
  if (typeof window === "undefined") return false;
  if (STANDALONE_DEMO_MODE) return true;
  const protocol = String(window.location.protocol || "").toLowerCase();
  if (protocol === "file:") return true;
  const host = String(window.location.hostname || "").toLowerCase();
  return host === "localhost" || host === "127.0.0.1" || host.endsWith(".local");
}

function buildStandaloneDemoBaseUrl() {
  const targetUrl = new URL(getConfiguredWindowBaseUrl());
  if (!shouldKeepStandaloneDemoOnCurrentOrigin() && PUBLIC_ROLE_HOSTNAMES.spectator) {
    targetUrl.protocol = "https:";
    targetUrl.hostname = PUBLIC_ROLE_HOSTNAMES.spectator;
    targetUrl.port = "";
  }
  targetUrl.pathname = "/";
  targetUrl.hash = "";
  targetUrl.search = "";
  return targetUrl;
}

function getConfiguredSiteLabel() {
  const preferredHost = PUBLIC_ROLE_HOSTNAMES.spectator
    || sanitizeHostValue(CLIENT_ROUTING.websiteAdminHost)
    || (typeof window !== "undefined" ? window.location.host : "");
  return preferredHost || "this site";
}

function buildLandingHeroTitleHtml(titleValue) {
  const heroTitle = String(titleValue || "").trim() || "Live Drift Event Hub";
  return `<span class="landing-brand-wordmark" aria-label="${escapeAttributeValue(heroTitle)}">${escapeHtml(heroTitle)}</span>`;
}

function normalizeEventBannerSource(value) {
  const normalized = typeof value === "string" ? value.trim() : "";
  return normalized ? normalized : null;
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Unable to read image file."));
    reader.readAsDataURL(file);
  });
}

function loadImageElement(source) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Unable to load image."));
    image.src = source;
  });
}

async function buildUpcomingEventBannerDataUrl(file) {
  if (!file || !String(file.type || "").startsWith("image/")) {
    throw new Error("Choose an image file for the event banner.");
  }

  const sourceDataUrl = await readFileAsDataUrl(file);
  const image = await loadImageElement(sourceDataUrl);
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error("This browser could not prepare the event banner image.");
  }

  const maxWidth = 1600;
  const maxHeight = 620;
  const scale = Math.min(
    1,
    maxWidth / Math.max(1, image.naturalWidth || image.width || maxWidth),
    maxHeight / Math.max(1, image.naturalHeight || image.height || maxHeight),
  );

  let targetWidth = Math.max(1, Math.round((image.naturalWidth || image.width || maxWidth) * scale));
  let targetHeight = Math.max(1, Math.round((image.naturalHeight || image.height || maxHeight) * scale));
  let quality = 0.84;
  let output = "";

  while (true) {
    canvas.width = targetWidth;
    canvas.height = targetHeight;
    context.clearRect(0, 0, targetWidth, targetHeight);
    context.drawImage(image, 0, 0, targetWidth, targetHeight);
    output = canvas.toDataURL("image/jpeg", quality);

    if (output.length <= 260000 || (quality <= 0.52 && targetWidth <= 960)) {
      break;
    }

    quality = Math.max(0.52, quality - 0.08);
    if (output.length > 260000 && targetWidth > 960) {
      targetWidth = Math.max(960, Math.round(targetWidth * 0.9));
      targetHeight = Math.max(320, Math.round(targetHeight * 0.9));
    }
  }

  return output;
}

