function syncClientFontImports() {
  const head = document.head || document.getElementsByTagName("head")[0];
  if (!head) return;

  const requestedImports = Array.isArray(CLIENT_TYPOGRAPHY.fontImports)
    ? CLIENT_TYPOGRAPHY.fontImports
      .map((href) => String(href || "").trim())
      .filter(Boolean)
    : [];

  const existingNodes = Array.from(head.querySelectorAll('link[data-client-font-import="true"]'));
  const existingHrefMap = new Map(existingNodes.map((node) => [node.getAttribute("href"), node]));

  existingNodes.forEach((node) => {
    if (!requestedImports.includes(node.getAttribute("href"))) {
      node.remove();
    }
  });

  requestedImports.forEach((href) => {
    if (existingHrefMap.has(href)) return;
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = href;
    link.dataset.clientFontImport = "true";
    head.appendChild(link);
  });
}

function inferFontFormat(relativePath) {
  const normalizedPath = String(relativePath || "").trim().toLowerCase();
  if (normalizedPath.endsWith(".woff2")) return "woff2";
  if (normalizedPath.endsWith(".woff")) return "woff";
  if (normalizedPath.endsWith(".ttf")) return "truetype";
  if (normalizedPath.endsWith(".otf")) return "opentype";
  return "";
}

function escapeCssString(value) {
  return String(value || "")
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"');
}

function syncClientCustomFontFaces() {
  const head = document.head || document.getElementsByTagName("head")[0];
  if (!head) return;

  const customFonts = ["display", "body"]
    .map((key) => CLIENT_TYPOGRAPHY?.customFonts?.[key])
    .filter((entry) => isPlainObject(entry) && entry.family && entry.relativePath);

  const existingStyle = head.querySelector('style[data-client-font-face="true"]');
  if (!customFonts.length) {
    existingStyle?.remove();
    return;
  }

  const rules = customFonts.map((entry) => {
    const family = escapeCssString(entry.family);
    const resolvedPath = escapeCssString(new URL(entry.relativePath, window.location.href).href);
    const format = escapeCssString(entry.format || inferFontFormat(entry.relativePath) || "opentype");
    return `@font-face {
  font-family: "${family}";
  src: url("${resolvedPath}") format("${format}");
  font-display: swap;
  font-weight: 100 900;
  font-style: normal;
}`;
  }).join("\n\n");

  const styleNode = existingStyle || document.createElement("style");
  styleNode.dataset.clientFontFace = "true";
  styleNode.textContent = rules;
  if (!existingStyle) {
    head.appendChild(styleNode);
  }
}

