function clearLocalDeviceCaches() {
  const eventStateKeyPattern = new RegExp(`^rc-drift-event-state-(.+)-v${EVENT_STORAGE_VERSION}$`);
  const keysToRemove = [
    WEBSITE_ADMIN_STORAGE_KEY,
    EVENT_DIRECTORY_STORAGE_KEY,
    ACTIVE_EVENT_STORAGE_KEY,
    ACTIVE_EVENT_SELECTION_CACHE_KEY,
    ARCHIVED_RESULTS_STORAGE_KEY,
    DELETED_EVENT_IDS_STORAGE_KEY,
    EVENT_ROLE_SESSION_KEY,
    EVENT_ROLE_PERSIST_KEY,
    EVENT_ROLE_UNLOCK_KEY,
    EVENT_ADMIN_BROWSER_UNLOCK_KEY,
    JUDGE_ROLE_DEVICE_ID_KEY,
    "rc-drift-drivers-v7",
    "rc-drift-drivers-v6",
    "rc-drift-bracket-state-v7",
    "rc-drift-bracket-state-v6",
  ];
  keysToRemove.forEach((key) => {
    localStorage.removeItem(key);
    sessionStorage.removeItem(key);
  });
  try {
    for (let index = localStorage.length - 1; index >= 0; index -= 1) {
      const storageKey = localStorage.key(index);
      if (storageKey && eventStateKeyPattern.test(storageKey)) {
        localStorage.removeItem(storageKey);
      }
    }
  } catch (error) {
    console.warn("Device cache reset scan failed:", error);
  }
}

function syncModalFullscreenHost(modalEl) {
  if (!modalEl) return;
  const fullscreenHost = document.fullscreenElement;
  if (fullscreenHost && !fullscreenHost.contains(modalEl)) {
    fullscreenHost.appendChild(modalEl);
  } else if (!fullscreenHost && modalEl.parentElement !== document.body) {
    document.body.appendChild(modalEl);
  }
}

function openModal(modalEl, focusEl = null) {
  if (!modalEl) return;
  syncModalFullscreenHost(modalEl);
  modalEl.classList.remove("hidden");
  modalEl.style.display = "flex";
  modalEl.setAttribute("aria-hidden", "false");
  modalEl.scrollTop = 0;
  const modalContent = modalEl.querySelector(".modal-content");
  if (modalContent) modalContent.scrollTop = 0;
  if (focusEl) {
    setTimeout(() => {
      if (typeof focusEl.focus === "function") {
        try {
          focusEl.focus({ preventScroll: true });
        } catch (_) {
          focusEl.focus();
        }
      }
    }, 0);
  }
}

function closeModal(modalEl) {
  if (!modalEl) return;
  modalEl.classList.add("hidden");
  modalEl.style.removeProperty("display");
  modalEl.setAttribute("aria-hidden", "true");
}

function cleanupPdfPreview() {
  if (pdfPreviewFrame) pdfPreviewFrame.src = "about:blank";
  if (pdfPreviewDownloadLink) pdfPreviewDownloadLink.removeAttribute("href");
  if (pdfPreviewOpenLink) pdfPreviewOpenLink.removeAttribute("href");
  if (pdfPreviewUrl) {
    URL.revokeObjectURL(pdfPreviewUrl);
    pdfPreviewUrl = "";
  }
}

function showPdfPreview(blob, fileName, message = "") {
  if (!blob || !pdfPreviewModal) return false;
  cleanupPdfPreview();
  pdfPreviewUrl = URL.createObjectURL(blob);
  if (pdfPreviewFrame) pdfPreviewFrame.src = pdfPreviewUrl;
  if (pdfPreviewDownloadLink) {
    pdfPreviewDownloadLink.href = pdfPreviewUrl;
    pdfPreviewDownloadLink.download = fileName;
  }
  if (pdfPreviewOpenLink) pdfPreviewOpenLink.href = pdfPreviewUrl;
  if (pdfPreviewCopy) {
    pdfPreviewCopy.textContent = message || "Your browser can open the generated PDF here even if it does not auto-download it.";
  }
  openModal(pdfPreviewModal);
  return true;
}

function hidePdfPreview() {
  closeModal(pdfPreviewModal);
  setTimeout(cleanupPdfPreview, 120);
}

function prefersPdfPreviewModal() {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  const platform = navigator.platform || "";
  const touchMac = platform === "MacIntel" && navigator.maxTouchPoints > 1;
  return /iPhone|iPad|iPod/i.test(ua) || touchMac;
}

function startDirectBlobDownload(blob, fileName) {
  try {
    const downloadUrl = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = downloadUrl;
    anchor.download = fileName;
    anchor.rel = "noopener";
    anchor.style.display = "none";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(downloadUrl), 4000);
    return true;
  } catch (error) {
    console.warn("Direct PDF download attempt failed", error);
    return false;
  }
}

function showWebsiteAdminModal() {
  websiteAdminModalTitle.textContent = "Website Admin";
  websiteAdminModalCopy.textContent = "Enter the website admin password once. This browser will stay unlocked until you sign out.";
  if (websiteAdminEmailInput) {
    websiteAdminEmailInput.value = "";
    websiteAdminEmailInput.classList.add("hidden");
    websiteAdminEmailInput.setAttribute("aria-hidden", "true");
  }
  websiteAdminPasswordInput.value = "";
  websiteAdminError.style.display = "none";
  openModal(websiteAdminModal, websiteAdminPasswordInput);
}

function hideWebsiteAdminModal(options = {}) {
  const { syncRoute = true } = options || {};
  closeModal(websiteAdminModal);
  if (websiteAdminEmailInput) websiteAdminEmailInput.value = "";
  websiteAdminPasswordInput.value = "";
  websiteAdminError.style.display = "none";
  if (syncRoute) {
    syncRouteWithState();
  }
}

function openWebsiteAdminAccess() {
  if (forcedHostContext && forcedHostContext.kind !== "website-admin") return;
  switchView("website-admin");
  if (isWebsiteAdmin) {
    renderWebsiteAdminAccessState();
  } else {
    showWebsiteAdminModal();
  }
}

function enforceWebsiteAdminHostRoute() {
  if (forcedHostContext?.kind !== "website-admin") return false;
  if (getActiveViewName() !== "website-admin") {
    switchView("website-admin");
  }
  renderWebsiteAdminAccessState();
  syncRouteWithState();
  return true;
}

function maybeOpenWebsiteAdminFromLocation() {
  if (typeof window === "undefined") return;
  const hash = String(window.location.hash || "").toLowerCase();
  const search = new URLSearchParams(window.location.search || "");
  if (hash === "#website-admin" || hash === "#/website-admin" || search.get("admin") === "1") {
    setTimeout(() => openWebsiteAdminAccess(), 0);
  }
}

function detectForcedHostContext() {
  if (typeof window === "undefined") return null;
  if (STANDALONE_DEMO_MODE) return null;
  const search = new URLSearchParams(window.location.search || "");
  const rawHash = String(window.location.hash || "").trim().toLowerCase();
  const cleanedHash = rawHash.replace(/^#\/?/, "");
  const segments = cleanedHash.split("/").filter(Boolean);
  const explicitStreamerRoute = search.get("streamer") === "1"
    || (shouldKeepStandaloneDemoOnCurrentOrigin() && ["dashboard", "library", "demo", "scene", "overlay"].includes(segments[0] || ""));
  if (explicitStreamerRoute) {
    return { kind: "streamer", view: "streamer-dashboard", slug: "streamer" };
  }
  const host = String(window.location.hostname || "").toLowerCase();
  return HOST_ROUTE_CONTEXTS[host] || null;
}

function syncForcedHostContext() {
  setForcedHostContextState(detectForcedHostContext());
  document.body.dataset.hostRoute = forcedHostContext?.slug || "shared";
  if (globalRoleSelect) {
    globalRoleSelect.disabled = Boolean(forcedHostContext && (forcedHostContext.kind === "role" || forcedHostContext.kind === "streamer"));
  }
  renderWebsiteAdminAccessState();
  syncStandaloneDemoSandboxUi();
}

function isRoleAllowedForHost(role) {
  if (!forcedHostContext) return true;
  if (forcedHostContext.kind === "website-admin") {
    return role === "spectator";
  }
  if (forcedHostContext.kind === "streamer") {
    return role === "spectator" || role === "admin";
  }
  if (forcedHostContext.kind === "role") {
    return role === forcedHostContext.role || role === "spectator";
  }
  return true;
}

function getForcedRoleForHost() {
  return forcedHostContext?.kind === "role" ? forcedHostContext.role : null;
}

function normalizeStreamerScene(sceneKey) {
  const normalized = String(sceneKey || "").trim().toLowerCase();
  return STREAMER_SCENE_META[normalized] ? normalized : "qualifying";
}

function normalizeStreamerVariant(variant) {
  return String(variant || "").trim().toLowerCase() === "overlay" ? "overlay" : "scene";
}

function normalizeStreamerViewName(viewName) {
  const normalized = String(viewName || "").trim().toLowerCase();
  if (normalized === "library" || normalized === "streamer-library") return "streamer-library";
  if (normalized === "demo" || normalized === "streamer-demo") return "streamer-demo";
  if (normalized === "scene" || normalized === "overlay" || normalized === "streamer-scene") return "streamer-scene";
  return "streamer-dashboard";
}

function normalizeStreamerRoute(route = {}) {
  const view = normalizeStreamerViewName(route.view);
  const variant = normalizeStreamerVariant(route.variant || (view === "streamer-scene" && route.view === "overlay" ? "overlay" : "scene"));
  return {
    kind: "streamer",
    view,
    scene: normalizeStreamerScene(route.scene),
    variant,
    demo: route.demo === true,
  };
}

function setStreamerRouteState(nextRoute = {}) {
  streamerRouteState = normalizeStreamerRoute({
    ...streamerRouteState,
    ...nextRoute,
  });
  return streamerRouteState;
}

function buildStreamerRouteHash(route = streamerRouteState) {
  const normalized = normalizeStreamerRoute(route);
  if (normalized.view === "streamer-library") return "#/library";
  if (normalized.view === "streamer-demo") return "#/demo";
  if (normalized.view === "streamer-scene") {
    const demoSuffix = normalized.demo ? "/demo" : "";
    return `#/${normalized.variant}/${normalized.scene}${demoSuffix}`;
  }
  return "#/dashboard";
}

function buildStreamerRouteUrl(route = streamerRouteState, options = {}) {
  if (typeof window === "undefined") return "";
  const targetUrl = new URL(getConfiguredWindowBaseUrl());
  const streamerHost = PUBLIC_ROLE_HOSTNAMES.streamer;
  if (streamerHost && options.useCurrentHost !== true) {
    targetUrl.protocol = "https:";
    targetUrl.hostname = streamerHost;
    targetUrl.port = "";
  }
  targetUrl.pathname = "/";
  targetUrl.search = options.useCurrentHost === true && targetUrl.hostname !== streamerHost
    ? "?streamer=1"
    : "";
  targetUrl.hash = buildStreamerRouteHash(route);
  return targetUrl.toString();
}

function getActiveViewName() {
  const views = ["registration", "home", "privacy", "live", "self-register", "self-register-display", "qualifying", "results", "website-admin", "bracket", "streamer-dashboard", "streamer-library", "streamer-demo", "streamer-scene"];
  return views.find((viewName) => document.getElementById(`view-${viewName}`)?.classList.contains("is-active")) || "qualifying";
}

function syncViewAccessibility(activeViewName) {
  const views = ["registration", "home", "privacy", "live", "self-register", "self-register-display", "qualifying", "results", "website-admin", "bracket", "streamer-dashboard", "streamer-library", "streamer-demo", "streamer-scene"];
  document.body.dataset.activeView = activeViewName;
  views.forEach((candidateView) => {
    const viewEl = document.getElementById(`view-${candidateView}`);
    if (!viewEl) return;
    const isActive = candidateView === activeViewName;
    viewEl.classList.toggle("is-active", isActive);
    viewEl.toggleAttribute("hidden", !isActive);
    viewEl.setAttribute("aria-hidden", isActive ? "false" : "true");
    if (isActive) {
      viewEl.removeAttribute("inert");
    } else {
      viewEl.setAttribute("inert", "");
    }
  });
}

function getViewDisplayLabel(viewName = getActiveViewName()) {
  return ({
    registration: "Registration",
    home: "Home",
    privacy: "Privacy",
    live: "LIVE",
    "self-register": "Driver Check-In",
    "self-register-display": "QR Display",
    qualifying: currentRole?.startsWith("j") ? "Judge Input" : "Qualifying",
    results: "Results",
    "website-admin": "Website Admin",
    bracket: "Competition",
    "streamer-dashboard": "Streamer Dashboard",
    "streamer-library": "Package Library",
    "streamer-demo": "Demo Mode",
    "streamer-scene": "Native Scene",
  })[viewName] || "Event Control";
}

function getPhaseTransitionCopy(viewName = "") {
  return ({
    registration: "Registration Desk Ready",
    qualifying: "Qualifying Board Live",
    bracket: "Competition Stage Armed",
    results: "Results Showcase Ready",
    "website-admin": "Control Room Active",
  })[viewName] || "Event Control Ready";
}

function getPhaseTransitionLogoSource() {
  const isDarkTheme = document.body?.getAttribute("data-theme") === "dark";
  if (isTech1AnniversaryMode(activeEventMeta)) {
    return isDarkTheme
      ? (TECH1DRIFT_ANNIVERSARY_CONFIG.branding?.logoDark || TECH1DRIFT_ANNIVERSARY_CONFIG.branding?.logo || "./assets/tech1drift-vector-transparent.svg")
      : (TECH1DRIFT_ANNIVERSARY_CONFIG.branding?.logoLight || TECH1DRIFT_ANNIVERSARY_CONFIG.branding?.logo || "./assets/tech1drift-vector-transparent-black.svg");
  }
  return "./assets/prodigy-rc-logo-transparent.png";
}

function ensurePhaseTransitionOverlay() {
  let overlay = document.getElementById("phaseTransitionOverlay");
  if (overlay) return overlay;
  overlay = document.createElement("div");
  overlay.id = "phaseTransitionOverlay";
  overlay.className = "phase-transition-overlay";
  overlay.setAttribute("aria-hidden", "true");
  overlay.innerHTML = `
    <section class="phase-transition-panel" role="status" aria-live="polite">
      <img class="phase-transition-logo" src="${escapeAttributeValue(getPhaseTransitionLogoSource())}" alt="Event brand logo" />
      <p class="phase-transition-kicker">Event Phase Transition</p>
      <h2 class="phase-transition-title">Preparing Next Stage</h2>
      <p class="phase-transition-copy">Stand by...</p>
    </section>
  `;
  document.body.appendChild(overlay);
  return overlay;
}

function shouldPlayPhaseTransitionMoment(fromView = "", toView = "") {
  if (currentRole !== "admin") return false;
  if (fromView === toView) return false;
  const supportedViews = new Set(["registration", "qualifying", "bracket", "results", "website-admin"]);
  return supportedViews.has(fromView) && supportedViews.has(toView);
}

function playPhaseTransitionMoment(fromView = "", toView = "") {
  if (!shouldPlayPhaseTransitionMoment(fromView, toView)) return;
  const overlay = ensurePhaseTransitionOverlay();
  const logo = overlay.querySelector(".phase-transition-logo");
  const title = overlay.querySelector(".phase-transition-title");
  const copy = overlay.querySelector(".phase-transition-copy");
  const logoSrc = getPhaseTransitionLogoSource();
  if (logo && logoSrc && logo.getAttribute("src") !== logoSrc) {
    logo.setAttribute("src", logoSrc);
  }
  if (title) title.textContent = `${getViewDisplayLabel(fromView)} -> ${getViewDisplayLabel(toView)}`;
  if (copy) copy.textContent = getPhaseTransitionCopy(toView);

  if (phaseTransitionHideTimeout) {
    clearTimeout(phaseTransitionHideTimeout);
    phaseTransitionHideTimeout = null;
  }
  if (phaseTransitionResetTimeout) {
    clearTimeout(phaseTransitionResetTimeout);
    phaseTransitionResetTimeout = null;
  }

  overlay.classList.remove("is-leave", "is-enter");
  overlay.classList.add("is-active");
  void overlay.offsetHeight;
  overlay.classList.add("is-enter");

  phaseTransitionHideTimeout = setTimeout(() => {
    overlay.classList.remove("is-enter");
    overlay.classList.add("is-leave");
  }, 920);
  phaseTransitionResetTimeout = setTimeout(() => {
    overlay.classList.remove("is-active", "is-leave");
  }, 1240);
}

function shouldKeepWebsiteAdminSelectionLocal() {
  return Boolean(isWebsiteAdmin && getActiveViewName() === "website-admin" && localEventPreviewMode);
}

function shouldUseJudgeBracketView(role = currentRole, flow = qualifyingFlow, drivers = appDrivers, state = tournamentState, eventMeta = activeEventMeta) {
  if (!role?.startsWith("j")) return false;
  if (isJudgeAccessLocked(eventMeta)) return false;
  if (isTwinTripleMode(eventMeta)) return false;
  if (!state?.mainBracket?.rounds?.length) return false;
  if (isTeamTandemMode(eventMeta)) return true;
  if (getQualifyingFlowPhase(flow, drivers) === "complete") return true;
  const currentCompetitionEntry = getCompetitionFlowEntriesForState(state).currentEntry;
  return Boolean(currentCompetitionEntry?.match?.left && currentCompetitionEntry?.match?.right);
}

function syncJudgeCompetitionView() {
  if (!currentRole?.startsWith("j")) return false;
  const preferredView = getDefaultViewForRole(currentRole);
  if (getActiveViewName() === preferredView) return false;
  if (preferredView === "bracket" && document.activeElement?.classList?.contains("score-input") && typeof document.activeElement.blur === "function") {
    document.activeElement.blur();
  }
  switchView(preferredView);
  return true;
}

function getDefaultViewForRole(role) {
  if (role === "admin") return "registration";
  if (role?.startsWith("j")) {
    if (isTech1AnniversaryMode(activeEventMeta)) return "bracket";
    if (isTeamCompetitionMode()) return "bracket";
    return shouldUseJudgeBracketView(role) ? "bracket" : "qualifying";
  }
  return "home";
}

function normalizeRouteViewForRole(role, requestedView = null) {
  const fallbackView = getDefaultViewForRole(role);
  const viewName = ROUTABLE_VIEWS.has(requestedView) ? requestedView : fallbackView;
  if (isTech1AnniversaryMode(activeEventMeta) && viewName === "qualifying") {
    return getTech1NoQualifyingFallbackView(role);
  }
  if (role?.startsWith("j")) return fallbackView;
  if (requestedView === "queue" || requestedView === "simulation") return fallbackView;
  if (isTeamCompetitionMode() && viewName === "qualifying") {
    if (role === "admin") return isTeamTandemMode() ? (tournamentState?.mainBracket?.rounds?.length ? "bracket" : "registration") : "bracket";
    if (role === "spectator" && isTeamTandemMode()) return tournamentState?.mainBracket?.rounds?.length ? "bracket" : "home";
  }
  if (role !== "admin" && viewName === "registration") return fallbackView;
  if (role !== "spectator" && viewName === "home") return fallbackView;
  if (role !== "spectator" && viewName === "privacy") return fallbackView;
  if (role !== "spectator" && viewName === "live") return fallbackView;
  if (role !== "spectator" && viewName === "self-register") return fallbackView;
  if (role !== "admin" && viewName === "self-register-display") return fallbackView;
  return viewName;
}

function normalizeEventRouteViewSegment(segment) {
  return normalizeEventRouteViewSegmentForRoute(segment);
}

function getCanonicalEventHost() {
  return PUBLIC_ROLE_HOSTNAMES.spectator
    || (typeof window !== "undefined" ? sanitizeHostValue(window.location.host || window.location.hostname) : "");
}

function buildEventRoutePath(eventId = activeEventId, role = currentRole, viewName = null) {
  return buildEventRoutePathForRoute({
    eventId: eventId || activeEventId || DEFAULT_EVENT_ID,
    role,
    viewName,
    defaultEventId: DEFAULT_EVENT_ID,
    getDefaultViewForRole,
    normalizeRouteViewForRole,
  });
}

function buildEventRouteUrl(role = currentRole, viewName = null, eventId = activeEventId, options = {}) {
  if (typeof window === "undefined") return "";
  const targetUrl = new URL(getConfiguredWindowBaseUrl());
  const canonicalHost = getCanonicalEventHost();
  if (canonicalHost && options.useCurrentHost !== true) {
    targetUrl.protocol = "https:";
    targetUrl.host = canonicalHost;
  }
  targetUrl.pathname = buildEventRoutePath(eventId, role, viewName);
  targetUrl.hash = "";
  targetUrl.search = "";
  if (TEST_MODE_ENABLED) {
    targetUrl.searchParams.set("testMode", "1");
  }
  return targetUrl.toString();
}

function buildRoleRouteHash(role = currentRole, viewName = getActiveViewName()) {
  const roleSlug = ROLE_ROUTE_SLUGS[role] || ROLE_ROUTE_SLUGS.spectator;
  const resolvedView = normalizeRouteViewForRole(role, viewName);
  const defaultView = getDefaultViewForRole(role);
  if (resolvedView === defaultView) {
    return `#/${roleSlug}`;
  }
  return `#/${roleSlug}/${resolvedView}`;
}

function buildRoleRouteUrl(role, viewName = null) {
  if (typeof window === "undefined") return "";
  const routeKey = role === "website-admin" ? "website-admin" : role;
  if (role !== "website-admin") {
    return buildEventRouteUrl(role, viewName || getDefaultViewForRole(role), activeEventId);
  }
  const publicHost = PUBLIC_ROLE_HOSTNAMES[routeKey];
  if (publicHost) {
    const targetUrl = new URL(getConfiguredWindowBaseUrl());
    targetUrl.protocol = "https:";
    targetUrl.hostname = publicHost;
    targetUrl.port = "";
    targetUrl.pathname = "/";
    targetUrl.hash = "";
    targetUrl.search = "";
    if (TEST_MODE_ENABLED) {
      targetUrl.searchParams.set("testMode", "1");
    }
    const resolvedView = normalizeRouteViewForRole(role, viewName || getDefaultViewForRole(role));
    if (!forcedHostContext && routeKey !== "website-admin" && resolvedView && resolvedView !== getDefaultViewForRole(role)) {
      targetUrl.hash = buildRoleRouteHash(role, resolvedView);
    }
    return targetUrl.toString();
  }
  const baseUrl = String(window.location.href || "").split("#")[0];
  return `${baseUrl}${buildRoleRouteHash(role, viewName || getDefaultViewForRole(role))}`;
}

function getCleanPublicPathForView(viewName = getActiveViewName()) {
  return getCleanPublicPathForRoute(viewName);
}

function hasInternalSearchState(searchParams = getCurrentPageSearchParams()) {
  return [
    "admin",
    "streamer",
    "testMode",
    "seedTest",
    "testScenario",
    "demoRole",
    "demoScenario",
    "demoSession",
    "demoView",
    "demoWindow",
    "debug",
    "qaOffline",
  ].some((key) => searchParams.has(key));
}

function shouldUseCleanPublicRoute(viewName = getActiveViewName(), currentRequestedRoute = parseRouteFromLocation()) {
  if (!["home", "live", "self-register", "qualifying", "bracket", "results", "privacy"].includes(viewName)) return false;
  if (currentRole !== "spectator") return false;
  if (STREAMER_VIEWS.has(viewName) || STANDALONE_DEMO_MODE || TEST_MODE_ENABLED) return false;
  if (currentRequestedRoute?.routeStyle === "event-path") return false;
  if (hasInternalSearchState()) return false;
  if (getVenueQrCheckInRequest()?.qrMode) return false;
  return !forcedHostContext || forcedHostContext.kind === "role" || forcedHostContext.kind === "website-admin";
}

function syncRouteWithState(options = {}) {
  if (typeof window === "undefined" || routeHandlingInProgress) return;
  const currentRequestedRoute = parseRouteFromLocation();
  if (
    pendingRole
    && currentRequestedRoute?.kind === "role"
    && currentRequestedRoute.role === pendingRole
    && !isRoleUnlockedForEvent(activeEventId, pendingRole)
  ) {
    return;
  }
  const { replace = false } = options || {};
  const activeView = getActiveViewName();
  if (shouldUseCleanPublicRoute(activeView, currentRequestedRoute)) {
    const nextUrl = getCleanPublicPathForView(activeView);
    if (`${window.location.pathname}${window.location.search}${window.location.hash}` === nextUrl) return;
    if (replace) {
      history.replaceState(null, "", nextUrl);
    } else {
      history.pushState(null, "", nextUrl);
    }
    syncSeoMetadata(activeView);
    return;
  }
  const nextHash = (forcedHostContext?.kind === "streamer" || STREAMER_VIEWS.has(getActiveViewName()))
    ? buildStreamerRouteHash(streamerRouteState)
    : getActiveViewName() === "website-admin" || forcedHostContext?.kind === "website-admin"
      ? "#/website-admin"
      : buildRoleRouteHash(forcedHostContext?.kind === "role" ? forcedHostContext.role : currentRole, getActiveViewName());
  const shouldUseEventPath = currentRequestedRoute?.routeStyle === "event-path"
    || Boolean(currentRequestedRoute?.eventId)
    || (!forcedHostContext && activeEventId && currentRole !== "website-admin");
  if (!nextHash) return;
  if (!shouldUseEventPath && window.location.hash === nextHash) return;
  const nextUrl = shouldUseEventPath && currentRole !== "website-admin" && !STREAMER_VIEWS.has(getActiveViewName())
    ? buildEventRoutePath(activeEventId, forcedHostContext?.kind === "role" ? forcedHostContext.role : currentRole, getActiveViewName()) + (window.location.search || "")
    : `${window.location.pathname}${window.location.search}${nextHash}`;
  if (`${window.location.pathname}${window.location.search}${window.location.hash}` === nextUrl) return;
  if (replace) {
    history.replaceState(null, "", nextUrl);
  } else {
    history.pushState(null, "", nextUrl);
  }
}

function parsePublicRouteFromPathname(pathname = typeof window !== "undefined" ? window.location.pathname : "") {
  const segments = String(pathname || "")
    .split("/")
    .map((segment) => segment.trim().toLowerCase())
    .filter(Boolean);
  if (!segments.length) return null;
  const first = segments[0];
  if (first === "live") return { kind: "role", role: "spectator", view: "live", routeStyle: "public-path" };
  if (first === "register" || first === "check-in" || first === "checkin") return { kind: "role", role: "spectator", view: "self-register", routeStyle: "public-path" };
  if (first === "qualifying" || first === "standings") return { kind: "role", role: "spectator", view: "qualifying", routeStyle: "public-path" };
  if (first === "competition" || first === "bracket") return { kind: "role", role: "spectator", view: "bracket", routeStyle: "public-path" };
  if (first === "results") return { kind: "role", role: "spectator", view: "results", routeStyle: "public-path" };
  if (first === "privacy") return { kind: "role", role: "spectator", view: "privacy", routeStyle: "public-path" };
  if (first === "admin" || first === "event-admin") return { kind: "role", role: "admin", view: normalizeEventRouteViewSegment(segments[1]) || "registration", routeStyle: "internal-path" };
  if (first === "judge") {
    const judgeNumber = Number.parseInt(segments[1] || "1", 10);
    const role = judgeNumber >= 1 && judgeNumber <= 3 ? `j${judgeNumber}` : "j1";
    return { kind: "role", role, view: normalizeEventRouteViewSegment(segments[2]) || "qualifying", routeStyle: "internal-path" };
  }
  if (first === "staff" || first === "login" || first === "debug" || first === "diagnostics") return { kind: "website-admin", routeStyle: "internal-path" };
  if (first === "stream-studio" || first === "streamer") return normalizeStreamerRoute({ view: normalizeStreamerViewName(segments[1] || "streamer-dashboard") });
  if (first === "demo" || first === "sandbox") return normalizeStreamerRoute({ view: "streamer-demo", demo: true });
  return null;
}

function parseEventRouteFromPathname(pathname = typeof window !== "undefined" ? window.location.pathname : "") {
  const segments = String(pathname || "")
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean);
  if (segments[0]?.toLowerCase() !== "events" || !segments[1]) return null;
  const eventId = decodeURIComponent(segments[1]);
  const section = String(segments[2] || "spectator").toLowerCase();
  if (section === "judge") {
    const judgeNumber = Number.parseInt(segments[3] || "0", 10);
    const role = judgeNumber >= 1 && judgeNumber <= 3 ? `j${judgeNumber}` : null;
    if (!role) {
      return { kind: "role", role: "spectator", view: "home", eventId, routeStyle: "event-path" };
    }
    const requestedView = normalizeEventRouteViewSegment(segments[4]);
    return {
      kind: "role",
      role,
      view: requestedView,
      eventId,
      routeStyle: "event-path",
    };
  }
  if (section === "admin" || section === "event-admin") {
    return {
      kind: "role",
      role: "admin",
      view: normalizeEventRouteViewSegment(segments[3]) || "registration",
      eventId,
      routeStyle: "event-path",
    };
  }
  if (section === "spectator") {
    return {
      kind: "role",
      role: "spectator",
      view: normalizeEventRouteViewSegment(segments[3]) || "home",
      eventId,
      routeStyle: "event-path",
    };
  }
  const directView = normalizeEventRouteViewSegment(section);
  if (directView) {
    return {
      kind: "role",
      role: directView === "registration" || directView === "self-register-display" ? "admin" : "spectator",
      view: directView,
      eventId,
      routeStyle: "event-path",
    };
  }
  return { kind: "role", role: "spectator", view: "home", eventId, routeStyle: "event-path" };
}

function parseRouteFromLocation() {
  if (typeof window === "undefined") return null;
  const eventPathRoute = parseEventRouteFromPathname(window.location.pathname || "");
  if (eventPathRoute?.kind === "role") return eventPathRoute;
  const publicPathRoute = parsePublicRouteFromPathname(window.location.pathname || "");
  if (publicPathRoute) return publicPathRoute;
  const rawHash = String(window.location.hash || "").trim().toLowerCase();
  const search = new URLSearchParams(window.location.search || "");
  const cleanedHash = rawHash.replace(/^#\/?/, "");
  const segments = cleanedHash.split("/").filter(Boolean);
  const hasStreamerSegments = ["dashboard", "library", "demo", "scene", "overlay"].includes(segments[0] || "");
  if (forcedHostContext?.kind === "streamer" || search.get("streamer") === "1" || (shouldKeepStandaloneDemoOnCurrentOrigin() && hasStreamerSegments)) {
    if (!segments.length) {
      return normalizeStreamerRoute({
        view: forcedHostContext.view || "streamer-dashboard",
        scene: streamerFeaturedScene,
        variant: "scene",
      });
    }
    if (segments[0] === "library") {
      return normalizeStreamerRoute({ view: "streamer-library" });
    }
    if (segments[0] === "demo") {
      return normalizeStreamerRoute({ view: "streamer-demo" });
    }
    if (segments[0] === "scene" || segments[0] === "overlay") {
      return normalizeStreamerRoute({
        view: "streamer-scene",
        variant: segments[0],
        scene: segments[1],
        demo: segments[2] === "demo",
      });
    }
    return normalizeStreamerRoute({ view: "streamer-dashboard" });
  }
  if (!rawHash && search.get("admin") === "1") {
    return { kind: "website-admin" };
  }
  if (!segments.length) return eventPathRoute || null;
  if (segments[0] === "website-admin") {
    return { kind: "website-admin" };
  }

  const routeRole = ROLE_ROUTE_LOOKUP[segments[0]];
  if (!routeRole) return null;
  return {
    kind: "role",
    role: routeRole,
    view: segments[1] || null,
  };
}

function getProductionOrigin() {
  const host = PUBLIC_ROLE_HOSTNAMES.spectator || "prodigyrccomp.com";
  return `https://${host}`;
}

function setMetaContent(selector, content, createName = "") {
  if (typeof document === "undefined") return null;
  const propertyMatch = String(selector || "").match(/meta\[property="([^"]+)"\]/);
  const nameMatch = String(selector || "").match(/meta\[name="([^"]+)"\]/);
  const nameOrProperty = createName || (propertyMatch ? `property:${propertyMatch[1]}` : nameMatch?.[1] || "");
  return setMetaContentForDocument(document, nameOrProperty, content);
}

function setCanonicalHref(href) {
  if (typeof document === "undefined") return null;
  return setCanonicalHrefForDocument(document, href);
}

function isInternalRouteForSeo(route = parseRouteFromLocation(), viewName = getActiveViewName()) {
  const search = getCurrentPageSearchParams();
  return isInternalRouteForSeoRoute({
    route,
    viewName,
    standaloneDemoMode: STANDALONE_DEMO_MODE,
    testModeEnabled: TEST_MODE_ENABLED,
    hasInternalSearchState: hasInternalSearchState(search),
  });
}

function getSeoDescriptor(viewName = getActiveViewName()) {
  return getSeoDescriptorForRoute({ viewName });
}

function buildSeoCanonicalUrl(viewName = getActiveViewName(), route = parseRouteFromLocation()) {
  return buildSeoCanonicalUrlForRoute({
    route,
    viewName,
    productionOrigin: getProductionOrigin(),
    buildEventRoutePath,
    getCleanPublicPathForView,
  });
}

function syncSeoMetadata(viewName = getActiveViewName()) {
  if (typeof document === "undefined") return;
  const route = parseRouteFromLocation();
  syncSeoMetadataForRoute({
    doc: document,
    route,
    viewName,
    standaloneDemoMode: STANDALONE_DEMO_MODE,
    testModeEnabled: TEST_MODE_ENABLED,
    hasInternalSearchState: hasInternalSearchState(getCurrentPageSearchParams()),
    productionOrigin: getProductionOrigin(),
    buildEventRoutePath,
    getCleanPublicPathForView,
  });
}

function copyTextToClipboard(text) {
  if (!text) return Promise.resolve(false);
  if (navigator.clipboard?.writeText) {
    return navigator.clipboard.writeText(text).then(() => true).catch(() => false);
  }
  const helper = document.createElement("textarea");
  helper.value = text;
  helper.setAttribute("readonly", "");
  helper.style.position = "fixed";
  helper.style.opacity = "0";
  document.body.appendChild(helper);
  helper.select();
  const copied = document.execCommand("copy");
  helper.remove();
  return Promise.resolve(Boolean(copied));
}

async function copyRoleRoute(role) {
  const routeUrl = buildRoleRouteUrl(role);
  const copied = await copyTextToClipboard(routeUrl);
  if (!copied) {
    window.prompt("Copy this direct role link:", routeUrl);
    return;
  }
  window.alert(`${getRoleDisplayName(role)} link copied.`);
}

function buildSelfRegisterUrl() {
  if (typeof window === "undefined") return "";
  const targetUrl = new URL(buildEventRouteUrl("spectator", "self-register", activeEventId));
  targetUrl.search = "";
  if (TEST_MODE_ENABLED) {
    targetUrl.searchParams.set("testMode", "1");
  }
  return targetUrl.toString();
}

function buildPublicEventUrl(viewName = "home") {
  return buildRoleRouteUrl("spectator", viewName || "home");
}

function getCurrentPageSearchParams() {
  if (typeof window === "undefined") return new URLSearchParams();
  return new URLSearchParams(window.location.search || "");
}

function getVenueQrCheckInRequest() {
  const route = parseRouteFromLocation();
  const search = getCurrentPageSearchParams();
  const eventId = (route?.eventId || search.get("eventId") || "").trim();
  const checkInMode = (search.get("checkIn") || "").trim().toLowerCase();
  const qrToken = (search.get("qrToken") || "").trim();
  const roleRouteMatches = route?.kind === "role" && route.role === "spectator" && (route.view || getDefaultViewForRole("spectator")) === "self-register";
  return {
    active: Boolean(roleRouteMatches && eventId),
    eventId,
    checkInMode,
    qrToken,
    qrMode: Boolean(roleRouteMatches && eventId && checkInMode === "qr"),
  };
}

function createVenueQrToken() {
  return `${generateId()}-${Math.random().toString(36).slice(2, 10)}`;
}

function issueVenueQrConfig(config = getVenueConfig(), options = {}) {
  const nextToken = options.forceRotate || !config?.qrToken
    ? createVenueQrToken()
    : config.qrToken;
  const issuedAt = options.forceRotate || !config?.qrTokenIssuedAt
    ? new Date().toISOString()
    : config.qrTokenIssuedAt;
  return createDefaultVenueConfig({
    ...(config || {}),
    qrToken: nextToken,
    qrTokenIssuedAt: issuedAt,
    qrTokenExpiresAt: options.expiresAt ?? config?.qrTokenExpiresAt ?? null,
  });
}

function buildEventScopedSelfRegisterUrl(eventMeta = activeEventMeta, options = {}) {
  if (typeof window === "undefined") return "";
  const targetUrl = new URL(buildEventRouteUrl("spectator", "self-register", eventMeta?.id || activeEventId));
  targetUrl.hash = "";
  targetUrl.search = "";
  if (TEST_MODE_ENABLED) {
    targetUrl.searchParams.set("testMode", "1");
  }
  if (options.qrCheckIn) {
    targetUrl.searchParams.set("checkIn", "qr");
    const venueConfig = createDefaultVenueConfig(eventMeta?.venueConfig || {});
    if (venueConfig.qrToken) {
      targetUrl.searchParams.set("qrToken", venueConfig.qrToken);
    }
  }
  return targetUrl.toString();
}

function buildVenueQrCheckInUrl(eventMeta = activeEventMeta) {
  return buildEventScopedSelfRegisterUrl(eventMeta, { qrCheckIn: true });
}

function buildSelfRegisterQrUrl() {
  const selfRegisterUrl = buildVenueQrCheckInUrl();
  if (!selfRegisterUrl) return "";
  return `https://api.qrserver.com/v1/create-qr-code/?size=320x320&data=${encodeURIComponent(selfRegisterUrl)}`;
}

