function normalizeStandaloneDemoRole(role) {
  return ["spectator", "admin", "j1", "j2", "j3"].includes(role) ? role : "spectator";
}

function normalizeStandaloneDemoView(viewName, role = "spectator") {
  const normalizedRole = normalizeStandaloneDemoRole(role);
  const resolvedView = viewName === "qualifying" ? "qualifying" : "bracket";
  if (normalizedRole.startsWith("j")) return "qualifying";
  return resolvedView;
}

function normalizeStandaloneDemoScenario(scenario, role = "spectator", viewName = "bracket") {
  if (scenario === "live") return "live";
  if (scenario === "judging" && normalizeStandaloneDemoRole(role).startsWith("j")) return "judging";
  if (scenario === "overview") return "overview";
  return normalizeStandaloneDemoView(viewName, role) === "qualifying" ? "judging" : "bracket";
}

function createStandaloneDemoSessionId() {
  return `live-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function getStandaloneDemoEventId(sessionId = STANDALONE_DEMO_SESSION_PARAM) {
  return `standalone-demo-${sessionId || "window"}`;
}

function getLiveDemoLaunchOptions(overrides = {}) {
  return {
    role: "spectator",
    view: "qualifying",
    scenario: "live",
    sessionId: overrides.sessionId || STANDALONE_DEMO_SESSION_PARAM || createStandaloneDemoSessionId(),
  };
}

function buildStandaloneDemoUrl(options = {}) {
  if (typeof window === "undefined") return "";
  const demoRole = normalizeStandaloneDemoRole(options.role || STANDALONE_DEMO_ROLE_PARAM || "spectator");
  const demoView = normalizeStandaloneDemoView(options.view || STANDALONE_DEMO_VIEW_PARAM || "qualifying", demoRole);
  const demoScenario = normalizeStandaloneDemoScenario(options.scenario || STANDALONE_DEMO_SCENARIO_PARAM || null, demoRole, demoView);
  const demoSessionId = options.sessionId || STANDALONE_DEMO_SESSION_PARAM || createStandaloneDemoSessionId();
  const targetUrl = buildStandaloneDemoBaseUrl();
  targetUrl.searchParams.set("demoWindow", "1");
  targetUrl.searchParams.set("demoSession", demoSessionId);
  targetUrl.searchParams.set("demoRole", demoRole);
  targetUrl.searchParams.set("demoView", demoView);
  targetUrl.searchParams.set("demoScenario", demoScenario);
  targetUrl.hash = buildRoleRouteHash(demoRole, demoView);
  return targetUrl.toString();
}

