function buildTestSampleDrivers(populateScores = false) {
  return TEST_SAMPLE_DRIVER_ENTRIES.map(([name, teamName, chassis, run1, run2], index) => {
    const driver = createEmptyDriver(index + 1);
    driver.name = name;
    driver.teamName = teamName;
    driver.chassis = chassis;
    driver.runFlags = { run1: null, run2: null, runoff: null };
    JUDGE_ROLE_ORDER.forEach((role, roleIndex) => {
        const run1Score = populateScores ? clampJudgeScoreValue(run1 - (roleIndex * 0.1), role) : null;
        const run2Score = populateScores ? clampJudgeScoreValue(run2 - (roleIndex * 0.1), role) : null;
      driver.scores[role] = {
        run1: run1Score,
        run2: run2Score,
        runoff: null,
        submitted: { run1: run1Score, run2: run2Score, runoff: null },
        deductionHistory: { run1: [], run2: [], runoff: [] },
      };
    });
    return driver;
  });
}

function createStandaloneDemoDrivers() {
  return buildTestSampleDrivers(true).slice(0, 16);
}

function buildStandaloneJudgeDemoDrivers(activeRole = "j1") {
  const demoRole = normalizeStandaloneDemoRole(activeRole);
  return TEST_SAMPLE_DRIVER_ENTRIES.slice(0, 23).map(([name, teamName, chassis], index) => {
    const driver = createEmptyDriver(index + 1);
    driver.name = name;
    driver.teamName = teamName;
    driver.chassis = chassis;
    driver.runFlags = { run1: null, run2: null, runoff: null };
    JUDGE_ROLE_ORDER.forEach((role) => {
      const isInteractiveRole = role === demoRole;
      driver.scores[role] = {
        run1: null,
        run2: null,
        runoff: null,
        submitted: {
          run1: null,
          run2: null,
          runoff: null,
        },
        deductionHistory: { run1: [], run2: [], runoff: [] },
      };
      if (!isInteractiveRole) {
        driver.scores[role].run1 = null;
        driver.scores[role].run2 = null;
      }
    });
    return driver;
  });
}

function createStandaloneDemoSnapshot(options = {}) {
  const initialRole = normalizeStandaloneDemoRole(options.role || STANDALONE_DEMO_ROLE_PARAM || "spectator");
  const initialView = normalizeStandaloneDemoView(options.view || STANDALONE_DEMO_VIEW_PARAM || "qualifying", initialRole);
  const scenario = normalizeStandaloneDemoScenario(options.scenario || STANDALONE_DEMO_SCENARIO_PARAM || null, initialRole, initialView);
  const createdAt = new Date().toISOString();
  const sessionId = options.sessionId || STANDALONE_DEMO_SESSION_PARAM || createStandaloneDemoSessionId();
  const bracketDrivers = createStandaloneDemoDrivers();
  const bracketRankedDrivers = rankDrivers(bracketDrivers);
  const demoTournament = createTournamentState(bracketRankedDrivers, FORMAT_CLASSIC, 0);
  const liveQualifyingBoard = scenario === "live";
  const demoDrivers = (scenario === "judging" && initialRole.startsWith("j")) || liveQualifyingBoard
    ? buildStandaloneJudgeDemoDrivers(initialRole)
    : bracketDrivers;
  const rankedDrivers = rankDrivers(demoDrivers);
  const liveQualifying = scenario === "judging" && initialRole.startsWith("j");
  const judgeCount = liveQualifyingBoard || liveQualifying ? 1 : 3;

  return {
    meta: {
      id: getStandaloneDemoEventId(sessionId),
      name: liveQualifyingBoard
        ? `${CLIENT_PLATFORM.productName || "Prodigy Event Control"} Live Demo`
        : liveQualifying
          ? `${CLIENT_PLATFORM.productName || "Prodigy Event Control"} Judge Sandbox`
          : `${CLIENT_PLATFORM.productName || "Prodigy Event Control"} Bracket Sandbox`,
      date: new Date().toISOString().slice(0, 10),
      status: "active",
      judgeCount,
      createdAt,
      updatedAt: createdAt,
      syncStamp: Date.now(),
      roleNames: buildDefaultRoleNames(),
      venueConfig: createDefaultVenueConfig({
        enabled: true,
        label: CLIENT_BRANDING.demoVenueLabel || CLIENT_BRANDING.venueName || "Prodigy Demo Arena",
        latitude: 33,
        longitude: -117,
        radiusMeters: 150,
      }),
      venueProfiles: [],
      pendingRegistrations: [],
      upcomingEventBanner: null,
      latestApprovalToast: null,
      judgeRoleClaims: createEmptyJudgeRoleClaims(),
      roleAccess: {},
      results: {
        ...buildEmptyEventResults(),
        qualifiedCount: rankedDrivers.length,
        totalDrivers: rankedDrivers.length,
        planDescription: liveQualifyingBoard
          ? "Dedicated live demo window. Keep this board open, scan the QR on a phone, submit scores there, then switch to bracket mode to advance demo battles."
          : liveQualifying
          ? "Fresh live judging demo. Start at 100, use deductions, and submit each run to watch the qualifying lane update live."
          : (demoTournament?.plan?.description || "Interactive demo bracket ready."),
      },
    },
    drivers: demoDrivers,
    qualifyingFlow: liveQualifying || liveQualifyingBoard
      ? {
          currentDriverId: demoDrivers[0]?.id || null,
          readyRoles: {},
          started: true,
          completed: false,
        }
      : {
          currentDriverId: null,
          readyRoles: {},
          started: true,
          completed: true,
        },
    tournament: demoTournament,
    initialRole,
    initialView,
    scenario,
  };
}

function syncStandaloneDemoSandboxUi() {
  if (!demoSandboxBar || !demoSandboxStatus) return;
  demoSandboxBar.classList.toggle("hidden", !STANDALONE_DEMO_MODE);
  document.body.dataset.demoWindow = STANDALONE_DEMO_MODE ? "true" : "false";
  if (demoQualifyingQrPanel && !STANDALONE_DEMO_MODE) {
    demoQualifyingQrPanel.hidden = true;
  }
  if (!STANDALONE_DEMO_MODE) return;

  const activeView = getActiveViewName();
  const isJudgeDemo = currentRole?.startsWith("j") && activeView === "qualifying";
  const isLiveDemoBoard = currentRole === "spectator" && activeView === "qualifying";
  demoSandboxStatus.textContent = isJudgeDemo
    ? `${getRoleDisplayName(currentRole)} phone demo is live. Submit Run 1 and Run 2 here while the main demo window stays on the live spectator board.`
    : isLiveDemoBoard
      ? "This standalone live demo window is the spectator board. Scan the QR on a phone to submit scores here live, or switch to the bracket demo when you're ready."
      : "Interactive bracket sandbox is live. Click any sample winner card or battle flow card to advance the bracket.";
  if (demoJudgeRoleSelect && currentRole?.startsWith("j")) {
    demoJudgeRoleSelect.value = currentRole;
  }
  syncDemoQualifyingQrPanel();
  if (demoQualifyingQrPanel) {
    demoQualifyingQrPanel.hidden = !(currentRole === "spectator" && activeView === "qualifying");
  }

  demoSandboxBar.querySelectorAll("[data-demo-launch]").forEach((button) => {
    const buttonRole = normalizeStandaloneDemoRole(button.dataset.demoRole || "spectator");
    const buttonView = normalizeStandaloneDemoView(button.dataset.demoView || "bracket", buttonRole);
    button.classList.toggle("is-active", buttonRole === currentRole && buttonView === activeView);
  });
}

function isTestDebugEnabled() {
  try {
    return localStorage.getItem(TEST_MODE_DEBUG_STORAGE_KEY) === "1";
  } catch (error) {
    return false;
  }
}

function setTestDebugEnabled(enabled) {
  try {
    if (enabled) localStorage.setItem(TEST_MODE_DEBUG_STORAGE_KEY, "1");
    else localStorage.removeItem(TEST_MODE_DEBUG_STORAGE_KEY);
  } catch (error) {}
}

function buildExitTestModeUrl() {
  const targetUrl = new URL(window.location.href);
  targetUrl.searchParams.set("testMode", "0");
  targetUrl.searchParams.delete("seedTest");
  targetUrl.searchParams.delete("testScenario");
  return targetUrl.toString();
}

function exitTestMode() {
  try {
    localStorage.removeItem(TEST_MODE_STORAGE_KEY);
    localStorage.removeItem(TEST_MODE_PENDING_SCENARIO_KEY);
    localStorage.removeItem(TEST_MODE_DEBUG_STORAGE_KEY);
  } catch (error) {}
  window.location.href = buildExitTestModeUrl();
}

function buildTestDebugSnapshot() {
  const currentDriver = getCurrentQualifyingDriver();
  const twinRound = getTwinCompCurrentRound();
  return {
    mode: TEST_MODE_ENABLED ? "TEST" : "PRODUCTION",
    dataScope: TEST_MODE_ENABLED ? "testData" : "data",
    activeEventId,
    activeView: getActiveViewName(),
    role: currentRole,
    eventName: activeEventMeta?.name || null,
    competitionMode: activeEventMeta?.competitionMode || null,
    currentDriverOrTeam: currentDriver ? { id: currentDriver.id, name: currentDriver.name, teamName: currentDriver.teamName } : null,
    qualifyingFlow,
    bracketLive: Boolean(tournamentState?.mainBracket?.rounds?.length),
    twinComp: twinCompState ? {
      status: twinCompState.status,
      roundNumber: twinCompState.roundNumber,
      currentRoundId: twinCompState.currentRoundId,
      activeTeams: getTwinCompActiveTeams().length,
      currentRound: twinRound ? {
        number: twinRound.number,
        status: twinRound.status,
        scoredTeams: twinRound.teamIds?.filter((teamId) => getTwinCompTeamRoundScore(teamId, twinRound)).length || 0,
        totalTeams: twinRound.teamIds?.length || 0,
      } : null,
    } : null,
    judges: getActiveJudgeRoles(activeEventMeta).map((role) => ({
      role,
      ready: Boolean(qualifyingFlow?.readyRoles?.[role]),
      currentSubmitted: currentDriver ? {
        run1: currentDriver.scores?.[role]?.submitted?.run1 ?? null,
        run2: currentDriver.scores?.[role]?.submitted?.run2 ?? null,
      } : null,
    })),
    directoryEvents: Object.keys(eventDirectory || {}),
  };
}

function syncTestModeUi() {
  document.body.dataset.testMode = TEST_MODE_ENABLED ? "true" : "false";
  if (topbarLifecyclePill && TEST_MODE_ENABLED) {
    topbarLifecyclePill.textContent = "TEST MODE";
    topbarLifecyclePill.className = "topbar-inline-pill archived";
  }
  if (!testModePanel) return;
  const canShowControls = currentRole === "admin" || isWebsiteAdmin || TEST_MODE_ENABLED;
  testModePanel.classList.toggle("hidden", !canShowControls);
  if (testModePanelTitle) testModePanelTitle.textContent = TEST_MODE_ENABLED ? "TEST MODE" : "Demo Environment";
  if (testModePanelStatus) {
    testModePanelStatus.textContent = TEST_MODE_ENABLED
      ? "Isolated Firebase testData namespace. Demo resets and judge submissions cannot write to production event data."
      : "Click Start Demo Event to enter isolated test mode and seed a fully populated QA event.";
  }
  if (startDemoEventBtn) startDemoEventBtn.textContent = TEST_MODE_ENABLED ? "Start Demo Event" : "Enter Test Mode + Start Demo";
  if (resetDemoDataBtn) resetDemoDataBtn.disabled = !TEST_MODE_ENABLED;
  if (exitTestModeBtn) exitTestModeBtn.hidden = !TEST_MODE_ENABLED;
  if (testDebugToggleBtn) testDebugToggleBtn.classList.toggle("is-active", isTestDebugEnabled());
  if (testDebugPanel) {
    const showDebug = TEST_MODE_ENABLED && isTestDebugEnabled();
    testDebugPanel.classList.toggle("hidden", !showDebug);
    if (showDebug) {
      testDebugPanel.textContent = JSON.stringify(buildTestDebugSnapshot(), null, 2);
    }
  }
}

function activateStandaloneDemoWindow(options = {}) {
  const demoSnapshot = createStandaloneDemoSnapshot(options);
  eventDirectory = { [demoSnapshot.meta.id]: cloneEventMeta(demoSnapshot.meta) };
  applyActiveEventState({
    id: demoSnapshot.meta.id,
    meta: cloneEventMeta(demoSnapshot.meta),
    drivers: sanitizeLoadedDrivers(demoSnapshot.drivers),
    qualifyingFlow: demoSnapshot.qualifyingFlow,
    bracket: demoSnapshot.tournament,
    formatMode: FORMAT_CLASSIC,
    lowerCount: "0",
  });
  currentRole = demoSnapshot.initialRole;
  applyUiState({
    localEventPreviewMode: true,
    pendingRouteView: demoSnapshot.initialView,
    activeCompetitionBracketPage: tournamentState?.lowerBracket ? "lower" : "main",
  });
  document.body.dataset.role = currentRole;
  if (globalRoleSelect) {
    globalRoleSelect.value = currentRole;
  }
  if (typeof window !== "undefined" && STANDALONE_DEMO_MODE) {
    history.replaceState(null, "", buildStandaloneDemoUrl({
      role: demoSnapshot.initialRole,
      view: demoSnapshot.initialView,
      scenario: demoSnapshot.scenario,
      sessionId: options.sessionId || STANDALONE_DEMO_SESSION_PARAM || null,
    }));
  }
  syncStandaloneDemoSandboxUi();
  if (db && auth?.currentUser) {
    bootstrapStandaloneDemoSession();
  }
}

function runStandaloneDemoMode(options = {}) {
  activateStandaloneDemoWindow(options);
  applyRoleChange(currentRole);
  syncStandaloneDemoSandboxUi();
}

function openStandaloneDemoWindow(options = {}) {
  const targetUrl = buildStandaloneDemoUrl(options);
  if (!targetUrl) return null;
  return window.open(targetUrl, CLIENT_PLATFORM.demoWindowName || "prodigy-live-demo-window", "width=1680,height=960");
}

function launchStandaloneDemo(options = {}) {
  const demoWindow = openStandaloneDemoWindow(options);
  if (demoWindow) return demoWindow;
  window.alert(`Please allow pop-ups for ${getConfiguredSiteLabel()} so Live Demo can open in a separate window.`);
  return null;
}

function applyResolvedRoute(route) {
  setRouteHandlingInProgressState(true);
  try {
    if (route.kind === "streamer") {
      setStreamerRouteState(route);
      if (currentRole !== "spectator") {
        currentRole = "spectator";
        document.body.dataset.role = currentRole;
        if (globalRoleSelect) globalRoleSelect.value = currentRole;
      }
      if (getActiveViewName() !== streamerRouteState.view) {
        switchView(streamerRouteState.view);
      }
      return;
    }
    if (route.kind === "website-admin") {
      openWebsiteAdminAccess();
      return;
    }

    hideWebsiteAdminModal({ syncRoute: false });
    const normalizedView = normalizeRouteViewForRole(route.role, route.view);
    setPendingRouteViewState(normalizedView);
    if (route.role === "spectator") {
      applyRoleChange("spectator");
      if (normalizedView && getActiveViewName() !== normalizedView) {
        switchView(normalizedView);
      }
      return;
    }

    requestRoleAccess(route.role);
  } finally {
    setRouteHandlingInProgressState(false);
  }
}

function applyRouteFromLocation() {
  if (forcedHostContext) {
    setRouteHandlingInProgressState(true);
    try {
      const forcedRoute = parseRouteFromLocation();
      syncRequestedRouteEventSelection({ route: forcedRoute });
      if (forcedHostContext.kind === "streamer") {
        const streamerRoute = forcedRoute;
        setStreamerRouteState(streamerRoute?.kind === "streamer"
          ? streamerRoute
          : normalizeStreamerRoute({ view: forcedHostContext.view || "streamer-dashboard" }));
        if (currentRole !== "spectator") {
          currentRole = "spectator";
          document.body.dataset.role = currentRole;
          if (globalRoleSelect) globalRoleSelect.value = currentRole;
        }
        switchView(streamerRouteState.view);
        return;
      }
      if (forcedHostContext.kind === "website-admin") {
        openWebsiteAdminAccess();
        return;
      }
      const parsedRoute = forcedRoute;
      const requestedForcedView = parsedRoute?.kind === "role" && parsedRoute.role === forcedHostContext.role
        ? parsedRoute.view
        : forcedHostContext.view;
      setPendingRouteViewState(normalizeRouteViewForRole(forcedHostContext.role, requestedForcedView));
      if (forcedHostContext.role === "admin" && grantForcedEventAdminHostAccess(activeEventId)) {
        applyRoleChange("admin");
        return;
      }
      if (currentRole === forcedHostContext.role) {
        applyRoleChange(forcedHostContext.role);
        return;
      }
      requestRoleAccess(forcedHostContext.role);
      return;
    } finally {
      setRouteHandlingInProgressState(false);
    }
  }

  const route = parseRouteFromLocation();
  syncRequestedRouteEventSelection({ route });
  if (!route) {
    const resolvedEvent = resolvePlatformCurrentEvent({ currentEventId: activeEventId });
    if (resolvedEvent?.shouldFollowShared && localEventPreviewMode && !shouldKeepCurrentRouteEventSelectionLocal()) {
      if (resolvedEvent.eventId && resolvedEvent.eventId !== activeEventId) {
        adoptActiveEvent(resolvedEvent.eventId, currentRole);
      }
      setLocalEventPreviewModeState(false);
    }
    const defaultView = getDefaultViewForRole(currentRole);
    if (getActiveViewName() !== defaultView) {
      switchView(defaultView);
      return;
    }
    syncRouteWithState({ replace: true });
    return;
  }

  if (route.kind === "role" && route.role === "spectator" && (route.view || getDefaultViewForRole("spectator")) === "self-register") {
    syncRequestedSelfRegisterEventSelection({ view: "self-register" });
  }

  if (route.kind === "role" && route.role === "admin" && grantForcedEventAdminHostAccess(activeEventId)) {
    setPendingRouteViewState(normalizeRouteViewForRole("admin", route.view));
    applyRoleChange("admin");
    return;
  }

  applyResolvedRoute(route);
}

function ensureForcedHostRoleAccess() {
  if (!forcedHostContext || forcedHostContext.kind !== "role" || !activeEventMeta || !activeEventId) return;
  const forcedRole = forcedHostContext.role;
  if (!isRoleAvailableForEvent(forcedRole, activeEventMeta) || isJudgeAccessLocked(activeEventMeta)) return;
  if (currentRole === forcedRole) return;
  if (forcedRole === "admin" && grantForcedEventAdminHostAccess(activeEventId)) {
    applyRoleChange("admin");
    return;
  }
  if (isRoleUnlockedForEvent(activeEventId, forcedRole)) {
    applyRoleChange(forcedRole);
    return;
  }
  setPendingRouteViewState(normalizeRouteViewForRole(forcedRole, forcedHostContext.view));
  const modalOpen = !document.getElementById("passwordModal")?.classList.contains("hidden");
  if (!modalOpen) {
    showPasswordModal(forcedRole);
  }
}

function syncForcedJudgeRoleFromUnlockedState() {
  if (!forcedHostContext || forcedHostContext.kind !== "role" || !activeEventMeta || !activeEventId) return false;
  const forcedRole = forcedHostContext.role;
  if (!forcedRole?.startsWith("j")) return false;
  if (!isRoleUnlockedForEvent(activeEventId, forcedRole)) return false;
  if (!isRoleAvailableForEvent(forcedRole, activeEventMeta) || isJudgeAccessLocked(activeEventMeta)) return false;
  if (currentRole === forcedRole) return false;
  currentRole = forcedRole;
  saveRoleForEvent(activeEventId, currentRole);
  document.body.dataset.role = currentRole;
  if (globalRoleSelect) {
    globalRoleSelect.value = currentRole;
  }
  if (searchInput) searchInput.value = "";
  setJudgeLaneIndexState(0);
  syncThemeState();
  const judgeHeroTitle = document.getElementById("judgeHeroTitle");
  if (judgeHeroTitle) {
    judgeHeroTitle.textContent = `${shouldUseJudgeRoleClaims(activeEventMeta) ? buildJudgeRoleClaimLabel(currentRole, activeEventMeta) : getRoleDisplayName(currentRole)} Input`;
  }
  const thRun1 = document.getElementById("thRun1");
  const thRun2 = document.getElementById("thRun2");
  if (thRun1) thRun1.textContent = getAverageColumnLabel(1, currentRole, activeEventMeta);
  if (thRun2) thRun2.textContent = getAverageColumnLabel(2, currentRole, activeEventMeta);
  return true;
}

function resetWebsiteAdminTapSequence() {
  websiteAdminTapCount = 0;
  if (websiteAdminTapResetTimer) {
    clearTimeout(websiteAdminTapResetTimer);
    websiteAdminTapResetTimer = null;
  }
}

function registerWebsiteAdminHiddenTap() {
  websiteAdminTapCount += 1;
  if (websiteAdminTapResetTimer) {
    clearTimeout(websiteAdminTapResetTimer);
  }
  websiteAdminTapResetTimer = setTimeout(() => {
    resetWebsiteAdminTapSequence();
  }, 1800);
  if (websiteAdminTapCount >= 5) {
    resetWebsiteAdminTapSequence();
    openWebsiteAdminAccess();
  }
}

function formatClaimedAt(value) {
  if (!value) return "Invite not claimed yet";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return "Claimed";
  return `Claimed ${new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(parsed)}`;
}

function isSampleEventEnabled(eventMeta = activeEventMeta) {
  const eventName = String(eventMeta?.name || "");
  return /test/i.test(eventName);
}

function getTopQualifierTieInfo(rankedDrivers) {
  if (!rankedDrivers.length || rankedDrivers[0].bestScore === null) return null;
  const topBestScore = rankedDrivers[0].bestScore;
  const tiedDrivers = rankedDrivers.filter((driver) => driver.bestScore === topBestScore);
  if (tiedDrivers.length < 2) return null;
  return {
    tiedDrivers,
    requiresRunoff: false,
  };
}

function setRunFlag(driverId, runKey, reason) {
  const driver = appDrivers.find((entry) => entry.id === driverId);
  if (!driver) return;
  if (currentRole.startsWith("j")) {
    driver.scores[currentRole][runKey] = 0;
    renderDriversTable();
    return;
  }
  driver.runFlags[runKey] = reason;
  if (reason) {
    driver.scores.j1[runKey] = 0;
    driver.scores.j2[runKey] = 0;
    driver.scores.j3[runKey] = 0;
  }
  publishState();
  renderDriversTable();
}

function syncCompetitionModeNavigation() {
  const teamTandemMode = isTeamTandemMode(activeEventMeta);
  const twinTripleMode = isTwinTripleMode(activeEventMeta);
  const tech1Mode = isTech1AnniversaryMode(activeEventMeta);
  const teamCompetitionMode = isTeamCompetitionMode(activeEventMeta);
  const bracketPublished = Boolean(tournamentState?.mainBracket?.rounds?.length);
  const websiteAdminActive = Boolean(isWebsiteAdmin || forcedHostContext?.kind === "website-admin" || getActiveViewName() === "website-admin");
  const hideQualifyingForAdmin = (teamCompetitionMode || tech1Mode) && (currentRole === "admin" || websiteAdminActive);
  const hideQualifyingTab = tech1Mode || hideQualifyingForAdmin;
  const qualifyingTab = document.querySelector('.mode-tab[data-target="qualifying"]');
  if (qualifyingTab) {
    qualifyingTab.hidden = hideQualifyingTab;
  }
  if (registrationToQualifyingBtn) {
    registrationToQualifyingBtn.hidden = false;
    registrationToQualifyingBtn.classList.toggle("tech1-bracket-hero-button", tech1Mode);
    registrationToQualifyingBtn.textContent = tech1Mode
      ? "Open Tech 1 Bracket"
      : teamTandemMode
      ? (bracketPublished ? "Open Competition" : "Launch Team Bracket")
      : twinTripleMode
        ? "Open Twin Comp"
      : "Go To Qualifying";
    registrationToQualifyingBtn.title = tech1Mode ? "No qualifying - random bracket from drivers marked Competing." : "";
  }
  if (registrationRandomTwinCompBtn) {
    const activeTeams = twinTripleMode ? getTwinCompActiveTeams().length || getRegisteredDrivers(appDrivers).length : 0;
    const currentTwinRound = getTwinCompCurrentRound();
    const canShowRandomTwinButton = twinTripleMode && (currentRole === "admin" || isWebsiteAdmin);
    registrationRandomTwinCompBtn.hidden = !canShowRandomTwinButton;
    registrationRandomTwinCompBtn.classList.toggle("hidden", !canShowRandomTwinButton);
    registrationRandomTwinCompBtn.textContent = currentTwinRound?.status === "live"
      ? "Open Randomized Twin Round"
      : "Randomize + Start Twin Comp";
    registrationRandomTwinCompBtn.disabled = !adminCanEdit() || (!currentTwinRound && activeTeams <= 1);
    registrationRandomTwinCompBtn.title = activeTeams <= 1
      ? "Register at least 2 active teams before starting a randomized Twin Comp round."
      : "";
  }
  if (bracketModeSelect) {
    const showBracketFormatSelector = !tech1Mode && !teamTandemMode && !twinTripleMode;
    const bracketModeField = bracketModeSelect.closest(".search-field");
    if (bracketModeField) {
      bracketModeField.hidden = !showBracketFormatSelector;
      bracketModeField.classList.toggle("hidden", !showBracketFormatSelector);
      bracketModeField.setAttribute("aria-hidden", showBracketFormatSelector ? "false" : "true");
    }
    const bracketModeToolbar = bracketModeSelect.closest(".hero-meta-inline");
    if (bracketModeToolbar) {
      const hasVisibleControl = Array.from(bracketModeToolbar.children).some((child) => {
        return !child.hidden && !child.classList.contains("hidden");
      });
      bracketModeToolbar.hidden = !hasVisibleControl;
      bracketModeToolbar.classList.toggle("hidden", !hasVisibleControl);
    }
  }
  if (commandCenterQualifyingBtn) {
    commandCenterQualifyingBtn.hidden = hideQualifyingForAdmin;
  }
  if (startQualifyingBtn) {
    startQualifyingBtn.hidden = hideQualifyingForAdmin;
  }
  if (randomizeQualifyingBtn) {
    randomizeQualifyingBtn.hidden = hideQualifyingForAdmin;
  }
  renderTech1EventControlWorkflow();
}

function updateEventChrome() {
  heroEventName.textContent = activeEventMeta?.name || "Main Event";
  heroEventDate.textContent = formatEventDate(activeEventMeta?.date);
  heroJudgeSystem.textContent = getJudgeSystemLabel(activeEventMeta);
  document.getElementById("qualifyingBoardCopy").textContent = getQualifyingBoardCopy(activeEventMeta);
  document.getElementById("judgeBoardCopy").textContent = getJudgeBoardCopy(currentRole, activeEventMeta);
  if (qualifyingPanelTitle) {
    qualifyingPanelTitle.textContent = currentRole.startsWith("j") ? "Judges Panel" : "Driver Scores";
  }
  document.getElementById("thRun1").textContent = getAverageColumnLabel(1, currentRole, activeEventMeta);
  document.getElementById("thRun2").textContent = getAverageColumnLabel(2, currentRole, activeEventMeta);
  const bestHeader = document.getElementById("thBestAvg");
  if (bestHeader) bestHeader.textContent = getBestRunColumnLabel(activeEventMeta);
  syncCompetitionModeNavigation();
  const eventStatus = getEventStatus(activeEventMeta);
  const eventLifecycleLabel = eventStatus === EVENT_STATUS_ARCHIVED
    ? "Archived"
    : eventStatus === EVENT_STATUS_COMPLETED
      ? "Completed"
      : "Active";
  const eventLifecycleTone = eventStatus === EVENT_STATUS_ARCHIVED ? "archived" : "active";
  currentEventStatus.textContent = eventLifecycleLabel;
  currentEventStatus.className = `status-pill ${eventLifecycleTone}`;
  if (topbarEventName) topbarEventName.textContent = activeEventMeta?.name || "Main Event";
  if (topbarEventMeta) {
    const activeView = getActiveViewName();
    topbarEventName.textContent = currentRole === "spectator" && activeView === "home"
      ? "Prodigy RC Comp"
      : activeEventMeta?.name || "Main Event";
    topbarEventMeta.textContent = currentRole === "spectator" && activeView === "home"
      ? "Registration, judging, brackets, results, and Stream Studio"
      : `${getRoleDisplayName(currentRole)} | ${getViewDisplayLabel(activeView)} | ${formatEventDate(activeEventMeta?.date)}`;
  }
  if (topbarLifecyclePill) {
    topbarLifecyclePill.textContent = eventLifecycleLabel;
    topbarLifecyclePill.className = `topbar-inline-pill ${eventLifecycleTone}`;
  }
  if (topbarRolePill) {
    topbarRolePill.textContent = getRoleDisplayName(currentRole);
    topbarRolePill.className = "topbar-inline-pill role";
  }
  const runtimeProductTitle = CLIENT_PLATFORM.browserTitle || CLIENT_PLATFORM.productName || "Prodigy Event Control";
  if (isStreamerHostRoute()) {
    const streamerContext = getStreamerSceneContext(streamerRouteState);
    const sceneLabel = STREAMER_SCENE_META[streamerRouteState.scene]?.label || "Streamer Control";
    document.title = streamerRouteState.view === "streamer-scene"
      ? `${streamerContext.eventName} | ${sceneLabel} | Prodigy Streamer`
      : `${streamerContext.eventName} | Prodigy Streamer`;
  } else {
    document.title = activeEventMeta?.name ? `${activeEventMeta.name} | ${runtimeProductTitle}` : runtimeProductTitle;
  }
  syncSeoMetadata(getActiveViewName());
  if (startQualifyingBtn) {
    const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
    startQualifyingBtn.textContent = qualifyingPhase === "complete" ? "Restart Qualifying" : "Start Qualifying";
    startQualifyingBtn.disabled = !adminCanEdit() || !getQualifyingDriverQueue().length;
  }
  if (randomizeQualifyingBtn) {
    const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
    const canRandomize = adminCanEdit()
      && !isTeamTandemMode(activeEventMeta)
      && qualifyingPhase === "waiting"
      && getQualifyingDriverQueue().length >= 2;
    randomizeQualifyingBtn.disabled = !canRandomize;
    randomizeQualifyingBtn.title = canRandomize
      ? "Shuffle the qualifying order before the first run starts."
      : "Qualifying order can only be randomized before qualifying starts and requires at least 2 drivers.";
  }
  if (loadSampleBtn) {
    const canLoadSample = adminCanEdit() && isSampleEventEnabled(activeEventMeta);
    loadSampleBtn.classList.toggle("hidden", !canLoadSample);
    loadSampleBtn.disabled = !canLoadSample;
    loadSampleBtn.textContent = "Load Test Sample";
    loadSampleBtn.title = "Only available on events with TEST in the name.";
  }
  Array.from(globalRoleSelect.options).forEach((option) => {
    option.textContent = getRoleDisplayName(option.value);
    option.hidden = !isRoleAvailableForEvent(option.value, activeEventMeta);
    option.disabled = !isRoleAvailableForEvent(option.value, activeEventMeta);
  });
  if (currentRole.startsWith("j") && isJudgeAccessLocked()) {
    applyRoleChange("spectator");
    switchView("qualifying");
    return;
  }
  if (!isRoleAvailableForEvent(currentRole, activeEventMeta)) {
    currentRole = "spectator";
    document.body.dataset.role = currentRole;
    saveRoleForEvent(activeEventId, currentRole);
  }
  globalRoleSelect.value = currentRole;
  if (registrationHeroEventName) registrationHeroEventName.textContent = activeEventMeta?.name || "Main Event";
  if (registrationHeroEventDate) registrationHeroEventDate.textContent = formatEventDate(activeEventMeta?.date);
  if (registrationAddDriverBtn) registrationAddDriverBtn.classList.toggle("hidden", !registrationCanEdit());
  if (registrationAddDriverSecondaryBtn) registrationAddDriverSecondaryBtn.classList.toggle("hidden", !registrationCanEdit());
  if (websiteAdminNewEventBtn) websiteAdminNewEventBtn.disabled = !websiteAdminCanUseProductionWrites();
  if (editCurrentEventBtn) editCurrentEventBtn.disabled = !websiteAdminCanUseProductionWrites() || !activeEventMeta;
  if (restoreRound3PdfBtn) {
    restoreRound3PdfBtn.disabled = !websiteAdminCanUseProductionWrites() || !isRound3PdfRecoveryEvent(activeEventMeta);
  }
  if (websiteAdminSignOutBtn) websiteAdminSignOutBtn.disabled = !isWebsiteAdmin;
  if (websiteAdminClearCacheBtn) websiteAdminClearCacheBtn.disabled = !websiteAdminCanUseProductionWrites();
  renderWebsiteAdminAccessState();
  renderWebsiteAdminSyncDiagnostics();
  renderStreamerExperience();
  syncVenueConfigForm();
  syncSelfRegisterForm();
  syncSelfRegisterQrPanel();
  syncRegistrationAdminAlerts();
  syncApprovalToast();
  syncBroadcastTicker();
  syncSelfRegisterProfileCard();
  renderCommandCenter();
  syncTestModeUi();
  syncNetworkStatusIndicator();
  syncBrandLogoAssetsForTheme();
}

function getRenderableEventsMap() {
  const merged = { ...(eventDirectory || {}) };
  if (activeEventId && activeEventMeta) {
    const liveResults = buildEventResults();
    merged[activeEventId] = cloneEventMeta({
      ...(merged[activeEventId] || {}),
      ...activeEventMeta,
      results: liveResults,
    });
  }
  return merged;
}

function getEventDateSortValue(eventMeta) {
  const rawValue = typeof eventMeta?.date === "string" ? eventMeta.date.trim() : "";
  return /^\d{4}-\d{2}-\d{2}$/.test(rawValue) ? rawValue : "";
}

function getLocalCalendarDateKey(referenceDate = new Date()) {
  const value = referenceDate instanceof Date ? referenceDate : new Date(referenceDate);
  if (Number.isNaN(value.getTime())) {
    return new Date().toISOString().slice(0, 10);
  }
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getScheduledActiveEventCandidate(referenceDate = new Date()) {
  const todayKey = getLocalCalendarDateKey(referenceDate);
  const visibleEvents = Object.values(getRenderableEventsMap())
    .filter((eventMeta) => getEventStatus(eventMeta) !== EVENT_STATUS_ARCHIVED);
  if (!visibleEvents.length) return null;

  const datedEvents = visibleEvents
    .filter((eventMeta) => Boolean(getEventDateSortValue(eventMeta)))
    .sort((left, right) => {
      const rightDate = getEventDateSortValue(right);
      const leftDate = getEventDateSortValue(left);
      if (rightDate !== leftDate) return rightDate.localeCompare(leftDate);
      return (right.updatedAt || "").localeCompare(left.updatedAt || "");
    });

  const dueEvent = datedEvents.find((eventMeta) => getEventDateSortValue(eventMeta) <= todayKey);
  if (dueEvent) return dueEvent;

  const upcomingEvent = [...datedEvents].sort((left, right) => {
    const leftDate = getEventDateSortValue(left);
    const rightDate = getEventDateSortValue(right);
    if (leftDate !== rightDate) return leftDate.localeCompare(rightDate);
    return (right.updatedAt || "").localeCompare(left.updatedAt || "");
  })[0] || null;
  if (upcomingEvent) return upcomingEvent;

  return sortEventsForDisplay().find((eventMeta) => getEventStatus(eventMeta) !== EVENT_STATUS_ARCHIVED)
    || sortEventsForDisplay()[0]
    || null;
}

function resolveScheduledActiveEventId(currentEventId = activeEventId, referenceDate = new Date()) {
  const candidateEvent = getScheduledActiveEventCandidate(referenceDate);
  if (!candidateEvent?.id || !eventDirectory[candidateEvent.id]) return null;
  if (!currentEventId || !eventDirectory[currentEventId]) return candidateEvent.id;
  if (candidateEvent.id === currentEventId) return null;

  const todayKey = getLocalCalendarDateKey(referenceDate);
  const currentEvent = eventDirectory[currentEventId];
  const currentDate = getEventDateSortValue(currentEvent);
  const candidateDate = getEventDateSortValue(candidateEvent);
  if (getEventStatus(currentEvent) === EVENT_STATUS_ARCHIVED) return candidateEvent.id;
  if (!currentDate) return candidateEvent.id;
  if (!candidateDate) return null;

  const currentIsFuture = currentDate > todayKey;
  const candidateIsDue = candidateDate <= todayKey;
  if (currentIsFuture && candidateIsDue) return candidateEvent.id;
  if (candidateIsDue && candidateDate > currentDate) return candidateEvent.id;
  return null;
}

function syncScheduledActiveEventSelection(options = {}) {
  if (shouldKeepCurrentRouteEventSelectionLocal() && !options.allowDuringPreview) return false;
  if (shouldKeepWebsiteAdminSelectionLocal() && !options.allowDuringWebsiteAdmin) return false;
  if ((isWebsiteAdmin || currentRole === "admin") && !options.allowDuringAdmin) return false;
  const sharedLiveSelection = getAuthoritativeLiveEventSelection();
  if (sharedLiveSelection?.activeEventId && !options.allowDuringSharedSelection) return false;
  const referenceDate = options.referenceDate instanceof Date ? options.referenceDate : new Date();
  const nextEventId = resolveScheduledActiveEventId(options.currentEventId || activeEventId, referenceDate);
  if (!nextEventId) return false;
  openEventById(nextEventId, null, options.publishSelection === true);
  if (options.renderAfterSwitch !== false) {
    renderAfterRemoteSync();
  }
  return true;
}

function startAutoEventSwitchWatcher() {
  lastAutoEventSwitchDateKey = getLocalCalendarDateKey();
  if (autoEventSwitchTimer) return;
  autoEventSwitchTimer = window.setInterval(() => {
    const todayKey = getLocalCalendarDateKey();
    if (todayKey === lastAutoEventSwitchDateKey) return;
    lastAutoEventSwitchDateKey = todayKey;
    syncScheduledActiveEventSelection({
      publishSelection: Boolean(isWebsiteAdmin && !localEventPreviewMode),
    });
  }, AUTO_EVENT_SWITCH_CHECK_MS);
}

function sortEventsForDisplay() {
  return Object.values(getRenderableEventsMap()).sort((left, right) => {
    if ((getEventStatus(left) === EVENT_STATUS_ARCHIVED) !== (getEventStatus(right) === EVENT_STATUS_ARCHIVED)) {
      return getEventStatus(left) === EVENT_STATUS_ARCHIVED ? 1 : -1;
    }
    const rightDate = right.date || "";
    const leftDate = left.date || "";
    if (rightDate !== leftDate) return rightDate.localeCompare(leftDate);
    return (right.updatedAt || "").localeCompare(left.updatedAt || "");
  });
}

function getRegisteredDrivers(drivers = appDrivers) {
  return normalizeDriverList(drivers).filter((driver) => {
    const hasName = Boolean(driver.name?.trim());
    return hasName;
  });
}

function getPendingRegistrations(eventMeta = activeEventMeta) {
  return normalizePendingRegistrationList(eventMeta?.pendingRegistrations);
}

function normalizeDriverName(value) {
  return String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
}

function formatDriverDisplayName(driver, fallback = "Unnamed Driver") {
  const name = String(driver?.name || "").trim() || fallback;
  const driverNumber = String(driver?.driverNumber || "").trim();
  return driverNumber ? `${name} #${driverNumber}` : name;
}

function getPendingRegistrationGroupId(entry) {
  return String(entry?.teamRegistrationId || entry?.id || "");
}

function getPendingRegistrationGroupEntries(entryId, eventMeta = activeEventMeta) {
  const pendingEntries = getPendingRegistrations(eventMeta);
  const seedEntry = pendingEntries.find((entry) => entry.id === entryId);
  if (!seedEntry) return [];
  const groupId = getPendingRegistrationGroupId(seedEntry);
  return pendingEntries
    .filter((entry) => getPendingRegistrationGroupId(entry) === groupId)
    .sort((left, right) => (left.teamMemberOrder || 0) - (right.teamMemberOrder || 0));
}

function getPendingRegistrationGroupLeader(entries) {
  return [...(Array.isArray(entries) ? entries : [])]
    .sort((left, right) => (left.teamMemberOrder || 0) - (right.teamMemberOrder || 0))[0] || null;
}

function getPendingRegistrationGroupByDeviceToken(deviceToken = getSelfRegisterDeviceId(), eventMeta = activeEventMeta) {
  if (!deviceToken) return [];
  const deviceEntries = findPendingRegistrationByDeviceToken(deviceToken, eventMeta);
  if (!deviceEntries.length) return [];
  const groupIds = [...new Set(deviceEntries.map((entry) => getPendingRegistrationGroupId(entry)).filter(Boolean))];
  if (groupIds.length !== 1) return [];
  return getPendingRegistrationGroupEntries(deviceEntries[0].id, eventMeta);
}

function getDraftSubmissionKey(draft, eventMeta = activeEventMeta) {
  if (isTeamTandemMode(eventMeta)) {
    const teamName = (draft?.teamName || "").trim();
    const memberNames = getNamedDraftDriverMembers(draft).map((member) => member.name).join("|");
    return teamName ? `${teamName}|${memberNames}` : memberNames;
  }
  return (draft?.name || "").trim();
}

function getDraftMemberInputs(prefix) {
  if (prefix === "self") {
    return [
      { nameInput: selfRegisterName, chassisInput: selfRegisterChassis },
      { nameInput: selfRegisterName2, chassisInput: selfRegisterChassis2 },
      { nameInput: selfRegisterName3, chassisInput: selfRegisterChassis3 },
    ];
  }
  return [
    { nameInput: registrationDraftName, chassisInput: registrationDraftChassis },
    { nameInput: registrationDraftName2, chassisInput: registrationDraftChassis2 },
    { nameInput: registrationDraftName3, chassisInput: registrationDraftChassis3 },
  ];
}

function validateTeamTandemDraft(draft, options = {}) {
  const normalizedDraft = normalizeRegistrationDraftState(draft);
  const teamName = normalizedDraft.teamName.trim();
  const slots = getDraftDriverMembers(normalizedDraft);
  const namedMembers = slots.filter((slot) => Boolean(slot.name));
  const inputSlots = getDraftMemberInputs(options.prefix === "self" ? "self" : "registration");
  const teamInput = options.prefix === "self" ? selfRegisterTeam : registrationDraftTeam;

  if (!teamName) {
    window.alert("Team tandem registration requires a team name.");
    teamInput?.focus();
    return null;
  }

  const chassisWithoutName = slots.find((slot) => slot.chassis && !slot.name);
  if (chassisWithoutName) {
    window.alert(`Driver ${chassisWithoutName.order} needs a name before adding a chassis.`);
    inputSlots[chassisWithoutName.order - 1]?.nameInput?.focus();
    return null;
  }

  const numberWithoutName = slots.find((slot) => slot.driverNumber && !slot.name);
  if (numberWithoutName) {
    window.alert(`Driver ${numberWithoutName.order} needs a name before adding a driver number.`);
    inputSlots[numberWithoutName.order - 1]?.nameInput?.focus();
    return null;
  }

  if (namedMembers.length < TEAM_TANDEM_MIN_DRIVERS) {
    window.alert(`Team tandem registration requires ${TEAM_TANDEM_MIN_DRIVERS} to ${TEAM_TANDEM_MAX_DRIVERS} drivers.`);
    inputSlots[1]?.nameInput?.focus();
    return null;
  }

  const normalizedNames = new Set();
  for (const member of namedMembers) {
    const normalizedName = normalizeDriverName(member.name);
    if (normalizedNames.has(normalizedName)) {
      window.alert(`${member.name} is listed twice in the same team registration.`);
      inputSlots[member.order - 1]?.nameInput?.focus();
      return null;
    }
    normalizedNames.add(normalizedName);
  }

  return { teamName, members: namedMembers };
}

function findDuplicateDriverEntry(name, options = {}) {
  const normalizedName = normalizeDriverName(name);
  if (!normalizedName) return null;
  const excludePendingId = options.excludePendingId || null;
  const excludeDriverId = options.excludeDriverId || null;
  const excludePendingIds = new Set(Array.isArray(options.excludePendingIds) ? options.excludePendingIds : []);
  const excludeDriverIds = new Set(Array.isArray(options.excludeDriverIds) ? options.excludeDriverIds : []);
  const liveDriver = getRegisteredDrivers(options.drivers || appDrivers)
    .find((driver) =>
      driver.id !== excludeDriverId
      && !excludeDriverIds.has(driver.id)
      && normalizeDriverName(driver.name) === normalizedName
    );
  if (liveDriver) {
    return { type: "roster", entry: liveDriver };
  }
  const pendingEntry = getPendingRegistrations(options.eventMeta || activeEventMeta)
    .find((entry) =>
      entry.id !== excludePendingId
      && !excludePendingIds.has(entry.id)
      && normalizeDriverName(entry.name) === normalizedName
    );
  if (pendingEntry) {
    return { type: "pending", entry: pendingEntry };
  }
  return null;
}

function normalizeActiveEventSelectionSnapshot(snapshot, fallbackEventId = "") {
  if (!snapshot || typeof snapshot !== "object") return null;
  const resolvedEventId = String(snapshot.activeEventId || fallbackEventId || "").trim();
  if (!resolvedEventId) return null;
  const resolvedMeta = snapshot.eventMeta
    ? extractEventMeta(snapshot.eventMeta, resolvedEventId)
    : eventDirectory[resolvedEventId]
      ? cloneEventMeta(eventDirectory[resolvedEventId])
      : null;
  return {
    activeEventId: resolvedEventId,
    eventMeta: resolvedMeta ? cloneEventMeta(resolvedMeta) : null,
    syncStamp: Math.max(0, Number(snapshot.syncStamp || 0)),
  };
}

function readCachedActiveEventSelection() {
  try {
    const cached = localStorage.getItem(ACTIVE_EVENT_SELECTION_CACHE_KEY);
    if (!cached) return null;
    return normalizeActiveEventSelectionSnapshot(JSON.parse(cached));
  } catch (error) {
    console.warn("Failed to read active event selection cache.", error);
    return null;
  }
}

function saveCachedActiveEventSelection(snapshot) {
  if (STANDALONE_DEMO_MODE) return null;
  const normalizedSnapshot = normalizeActiveEventSelectionSnapshot(snapshot);
  if (!normalizedSnapshot) {
    localStorage.removeItem(ACTIVE_EVENT_SELECTION_CACHE_KEY);
    return null;
  }
  const existingSnapshot = readCachedActiveEventSelection();
  if (existingSnapshot && existingSnapshot.syncStamp > normalizedSnapshot.syncStamp) {
    return existingSnapshot;
  }
  localStorage.setItem(ACTIVE_EVENT_SELECTION_CACHE_KEY, JSON.stringify(normalizedSnapshot));
  return normalizedSnapshot;
}

function getRequestedRouteEventSelection(searchParams = getCurrentPageSearchParams(), route = parseRouteFromLocation()) {
  const eventId = String(route?.eventId || searchParams?.get("eventId") || "").trim();
  return {
    active: Boolean(eventId),
    eventId,
    valid: Boolean(eventId && eventDirectory[eventId]),
  };
}

function shouldKeepCurrentRouteEventSelectionLocal(searchParams = getCurrentPageSearchParams()) {
  return Boolean(shouldKeepWebsiteAdminSelectionLocal() || getRequestedRouteEventSelection(searchParams).valid);
}

function getAuthoritativeLiveEventSelection(options = {}) {
  const liveSelection = normalizeActiveEventSelectionSnapshot(options.activeSelection || lastKnownRemoteActiveEventSelection);
  if (liveSelection?.activeEventId && eventDirectory[liveSelection.activeEventId]) {
    return { ...liveSelection, source: "cloud-active-selection" };
  }

  const cachedSelection = readCachedActiveEventSelection();
  if (cachedSelection?.activeEventId && eventDirectory[cachedSelection.activeEventId]) {
    return { ...cachedSelection, source: "cached-active-selection" };
  }

  const directoryActiveEventId = String(options.directoryActiveEventId || "").trim();
  if (directoryActiveEventId && eventDirectory[directoryActiveEventId]) {
    return {
      activeEventId: directoryActiveEventId,
      eventMeta: cloneEventMeta(options.directoryEventMeta || eventDirectory[directoryActiveEventId]),
      syncStamp: Math.max(0, Number(options.directorySyncStamp || 0)),
      source: "directory-active-selection",
    };
  }

  return null;
}

function resolvePlatformCurrentEvent(options = {}) {
  const requestedRouteEvent = getRequestedRouteEventSelection(options.searchParams, options.route || parseRouteFromLocation());
  if (requestedRouteEvent.valid) {
    return {
      eventId: requestedRouteEvent.eventId,
      source: "explicit-route",
      isExplicitRoute: true,
      shouldFollowShared: false,
    };
  }

  const liveSelection = getAuthoritativeLiveEventSelection(options);
  if (liveSelection?.activeEventId) {
    return {
      eventId: liveSelection.activeEventId,
      source: liveSelection.source,
      isExplicitRoute: false,
      shouldFollowShared: true,
      syncStamp: liveSelection.syncStamp,
    };
  }

  const storedActiveEventId = String(options.storedActiveEventId || localStorage.getItem(ACTIVE_EVENT_STORAGE_KEY) || "").trim();
  const scheduledActiveEventId = resolveScheduledActiveEventId(options.currentEventId || storedActiveEventId || activeEventId, options.referenceDate || new Date());
  const fallbackEventId = [
    scheduledActiveEventId,
    storedActiveEventId,
    Object.keys(eventDirectory)[0],
  ].find((eventId) => eventId && eventDirectory[eventId]) || null;

  return {
    eventId: fallbackEventId,
    source: scheduledActiveEventId ? "scheduled-fallback" : storedActiveEventId ? "local-cache" : "directory-fallback",
    isExplicitRoute: false,
    shouldFollowShared: false,
  };
}

function getRecoveredCachedEventDirectory() {
  const recovered = {};
  const keyPattern = new RegExp(`^rc-drift-event-state-(.+)-v${EVENT_STORAGE_VERSION}$`);
  try {
    for (let index = 0; index < localStorage.length; index += 1) {
      const storageKey = localStorage.key(index);
      if (!storageKey) continue;
      const match = storageKey.match(keyPattern);
      if (!match) continue;
      const eventId = match[1];
      const cachedState = readEventStateCache(eventId);
      const cachedMeta = cachedState?.meta;
      if (!cachedMeta) continue;
      recovered[eventId] = extractEventMeta(cachedMeta, eventId);
    }
  } catch (error) {
    console.warn("Event cache recovery scan failed:", error);
  }
  return recovered;
}

function mergeDirectoryMaps(...maps) {
  return maps.reduce((accumulator, entry) => {
    if (!entry || typeof entry !== "object") return accumulator;
    Object.entries(entry).forEach(([eventId, meta]) => {
      if (!eventId || !meta) return;
      if (isDeletedEventId(eventId)) return;
      accumulator[eventId] = extractEventMeta(meta, eventId);
    });
    return accumulator;
  }, {});
}

function getRecoveredDirectorySnapshot(nextOverrides = {}) {
  return mergeDirectoryMaps(
    getRecoveredCachedEventDirectory(),
    lastRemoteDirectoryEvents,
    eventDirectory,
    nextOverrides,
  );
}

function getPersistableDirectorySnapshot(nextOverrides = {}) {
  return mergeDirectoryMaps(eventDirectory, nextOverrides);
}

function getSafeDirectorySnapshot(nextOverrides = {}) {
  return hasLoadedRemoteDirectory
    ? getPersistableDirectorySnapshot(nextOverrides)
    : getRecoveredDirectorySnapshot(nextOverrides);
}

function getSelfRegistrationCloseReason(eventMeta = activeEventMeta, flow = qualifyingFlow, drivers = appDrivers) {
  const venueConfig = getVenueConfig(eventMeta);
  if (getQualifyingFlowPhase(flow, drivers) === "live") return "qualifying-live";
  if (getQualifyingFlowPhase(flow, drivers) === "complete") return "qualifying-complete";
  if (venueConfig.closeAt) {
    const closeAtMs = new Date(venueConfig.closeAt).getTime();
    if (Number.isFinite(closeAtMs) && Date.now() >= closeAtMs) return "scheduled-close";
  }
  return null;
}

function isSelfRegistrationClosedByQualifying(eventMeta = activeEventMeta, flow = qualifyingFlow, drivers = appDrivers) {
  return Boolean(getSelfRegistrationCloseReason(eventMeta, flow, drivers));
}

function loadSavedSelfRegisterProfile() {
  try {
    const raw = localStorage.getItem(SELF_REGISTER_PROFILE_STORAGE_KEY);
    if (!raw) return createEmptyRegistrationDraft();
    return normalizeRegistrationDraftState(JSON.parse(raw));
  } catch (error) {
    console.warn("Failed to load saved self-registration profile.", error);
    return createEmptyRegistrationDraft();
  }
}

function normalizeSavedSelfRegisterProfiles(entries) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => {
      const normalized = entry && typeof entry === "object" ? entry : {};
      return {
        id: normalized.id || generateId(),
        label: typeof normalized.label === "string" ? normalized.label : "",
        name: typeof normalized.name === "string" ? normalized.name : "",
        teamName: typeof normalized.teamName === "string" ? normalized.teamName : "",
        chassis: typeof normalized.chassis === "string" ? normalized.chassis : "",
        teammate2Name: typeof normalized.teammate2Name === "string" ? normalized.teammate2Name : "",
        teammate2Chassis: typeof normalized.teammate2Chassis === "string" ? normalized.teammate2Chassis : "",
        teammate3Name: typeof normalized.teammate3Name === "string" ? normalized.teammate3Name : "",
        teammate3Chassis: typeof normalized.teammate3Chassis === "string" ? normalized.teammate3Chassis : "",
        lastUsedAt: normalized.lastUsedAt || null,
      };
    })
    .filter((entry) => Boolean(entry.name.trim()))
    .sort((left, right) => String(right.lastUsedAt || "").localeCompare(String(left.lastUsedAt || "")));
}

function loadSavedSelfRegisterProfiles() {
  try {
    const raw = localStorage.getItem(SELF_REGISTER_PROFILES_STORAGE_KEY);
    if (!raw) return [];
    return normalizeSavedSelfRegisterProfiles(JSON.parse(raw));
  } catch (error) {
    console.warn("Failed to load saved self-registration profiles.", error);
    return [];
  }
}

function persistSavedSelfRegisterProfiles(profiles) {
  try {
    localStorage.setItem(SELF_REGISTER_PROFILES_STORAGE_KEY, JSON.stringify(normalizeSavedSelfRegisterProfiles(profiles)));
  } catch (error) {
    console.warn("Failed to save self-registration profiles.", error);
  }
}

function persistSelfRegisterProfile() {
  try {
    localStorage.setItem(SELF_REGISTER_PROFILE_STORAGE_KEY, JSON.stringify(normalizeRegistrationDraftState(selfRegistrationDraft)));
  } catch (error) {
    console.warn("Failed to save self-registration profile.", error);
  }
}

function clearSavedSelfRegisterProfile() {
  try {
    localStorage.removeItem(SELF_REGISTER_PROFILE_STORAGE_KEY);
  } catch (error) {
    console.warn("Failed to clear saved self-registration profile.", error);
  }
}

function getSelfRegisterDeviceId() {
  try {
    let existing = localStorage.getItem(SELF_REGISTER_DEVICE_ID_KEY);
    if (existing) return existing;
    existing = generateId();
    localStorage.setItem(SELF_REGISTER_DEVICE_ID_KEY, existing);
    return existing;
  } catch (error) {
    console.warn("Failed to access self-registration device token.", error);
    return "device-unavailable";
  }
}

function readLastSelfRegisterSubmitMeta() {
  try {
    const raw = localStorage.getItem(SELF_REGISTER_LAST_SUBMIT_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch (error) {
    console.warn("Failed to read last self-registration submit state.", error);
    return null;
  }
}

function writeLastSelfRegisterSubmitMeta(meta) {
  try {
    localStorage.setItem(SELF_REGISTER_LAST_SUBMIT_KEY, JSON.stringify(meta || {}));
  } catch (error) {
    console.warn("Failed to save last self-registration submit state.", error);
  }
}

function findPendingRegistrationByDeviceToken(deviceToken = getSelfRegisterDeviceId(), eventMeta = activeEventMeta) {
  if (!deviceToken) return [];
  return getPendingRegistrations(eventMeta).filter((entry) => entry.deviceToken && entry.deviceToken === deviceToken);
}

function getPendingEntryGroupForCheckIn(draft = selfRegistrationDraft, deviceToken = getSelfRegisterDeviceId(), eventMeta = activeEventMeta) {
  const pendingEntries = getPendingRegistrations(eventMeta);
  const memberNames = getNamedDraftDriverMembers(draft).map((member) => normalizeDriverName(member.name)).filter(Boolean);
  if (memberNames.length) {
    const namedMatch = pendingEntries.find((entry) =>
      memberNames.includes(normalizeDriverName(entry.name))
      && (!deviceToken || !entry.deviceToken || entry.deviceToken === deviceToken)
    );
    if (namedMatch) return getPendingRegistrationGroupEntries(namedMatch.id, eventMeta);
  }
  return getPendingRegistrationGroupByDeviceToken(deviceToken, eventMeta);
}

function getPendingEntryForCheckIn(name = (selfRegistrationDraft.name || "").trim(), deviceToken = getSelfRegisterDeviceId(), eventMeta = activeEventMeta) {
  const groupEntries = getPendingEntryGroupForCheckIn(
    normalizeRegistrationDraftState({
      ...selfRegistrationDraft,
      name,
    }),
    deviceToken,
    eventMeta,
  );
  return getPendingRegistrationGroupLeader(groupEntries);
}

function getPendingRegistrationGroupLeaders(eventMeta = activeEventMeta) {
  const pendingEntries = getPendingRegistrations(eventMeta);
  const groupLeaders = [];
  const seenGroupIds = new Set();
  pendingEntries.forEach((entry) => {
    const groupId = getPendingRegistrationGroupId(entry);
    if (!groupId || seenGroupIds.has(groupId)) return;
    seenGroupIds.add(groupId);
    const groupEntries = getPendingRegistrationGroupEntries(entry.id, eventMeta);
    const leader = getPendingRegistrationGroupLeader(groupEntries);
    if (leader) {
      groupLeaders.push(leader);
    }
  });
  return groupLeaders;
}

function getPendingGroupLabel(entry, eventMeta = activeEventMeta) {
  const entryGroup = getPendingRegistrationGroupEntries(entry?.id, eventMeta);
  const leader = getPendingRegistrationGroupLeader(entryGroup) || entry;
  const isTeamEntry = entryGroup.length > 1;
  if (isTeamEntry) {
    return `${leader?.teamName || leader?.name || "Team"} | ${entryGroup.length} drivers`;
  }
  return leader?.teamName?.trim()
    ? `${leader.name || "Driver"} | ${leader.teamName.trim()}`
    : (leader?.name || "Driver");
}

function findPendingRegistrationGroupLeaderById(entryId, eventMeta = activeEventMeta) {
  if (!entryId) return null;
  return getPendingRegistrationGroupLeader(getPendingRegistrationGroupEntries(entryId, eventMeta));
}

function populateSelfRegistrationDraftFromPendingGroup(entryId, eventMeta = activeEventMeta) {
  const entries = getPendingRegistrationGroupEntries(entryId, eventMeta);
  const leader = getPendingRegistrationGroupLeader(entries);
  if (!leader) return false;
  const orderedEntries = [...entries].sort((left, right) => (left.teamMemberOrder || 0) - (right.teamMemberOrder || 0));
  const nextDraft = createEmptyRegistrationDraft();
  if (orderedEntries[0]) {
    nextDraft.name = orderedEntries[0].name || "";
    nextDraft.driverNumber = orderedEntries[0].driverNumber || "";
    nextDraft.teamName = orderedEntries[0].teamName || "";
    nextDraft.chassis = orderedEntries[0].chassis || "";
  }
  if (orderedEntries[1]) {
    nextDraft.teammate2Name = orderedEntries[1].name || "";
    nextDraft.teammate2Number = orderedEntries[1].driverNumber || "";
    nextDraft.teammate2Chassis = orderedEntries[1].chassis || "";
  }
  if (orderedEntries[2]) {
    nextDraft.teammate3Name = orderedEntries[2].name || "";
    nextDraft.teammate3Number = orderedEntries[2].driverNumber || "";
    nextDraft.teammate3Chassis = orderedEntries[2].chassis || "";
  }
  selfRegistrationDraft = normalizeRegistrationDraftState(nextDraft);
  persistSelfRegisterProfile();
  return true;
}

function isPendingRegistrationRejected(entry) {
  return Boolean(entry?.rejectedAt);
}

function isPendingRegistrationNeedsReview(entry) {
  return Boolean(entry?.needsReviewAt);
}

function needsPendingRegistrationApproval(entry) {
  return Boolean(entry?.checkedInAt && entry?.approvalRequired !== false && !entry?.paidAt && !isPendingRegistrationRejected(entry) && !isPendingRegistrationNeedsReview(entry));
}

function getVenueQrCheckInValidation(eventMeta = activeEventMeta, request = getVenueQrCheckInRequest()) {
  if (!request?.qrMode) {
    return { valid: false, code: "not-qr", copy: "" };
  }
  if (!request.eventId || !eventMeta?.id || request.eventId !== eventMeta.id) {
    return { valid: false, code: "invalid-event", copy: "This QR code does not match a valid active event." };
  }
  const venueConfig = createDefaultVenueConfig(eventMeta?.venueConfig || {});
  if (!venueConfig.qrCheckInEnabled) {
    return { valid: false, code: "disabled", copy: "Venue QR check-in is disabled for this event right now." };
  }
  if (!venueConfig.qrToken || request.qrToken !== venueConfig.qrToken) {
    return { valid: false, code: "invalid-token", copy: "This venue QR code is invalid. Ask event staff for the latest check-in screen." };
  }
  if (venueConfig.qrTokenExpiresAt && new Date(venueConfig.qrTokenExpiresAt).getTime() <= Date.now()) {
    return { valid: false, code: "expired", copy: "This venue QR code has expired. Ask event staff for a fresh check-in QR." };
  }
  const closeReason = getSelfRegistrationCloseReason(eventMeta);
  if (closeReason) {
    return {
      valid: false,
      code: closeReason === "scheduled-close" ? "closed" : "qualifying-live",
      copy: closeReason === "scheduled-close"
        ? "Venue check-in is closed because the scheduled registration cutoff has passed."
        : "Venue check-in is closed because qualifying is already live for this event.",
    };
  }
  return { valid: true, code: "ok", copy: venueConfig.qrApprovalMode ? "Scan complete. Confirm your preregistered entry so staff can approve you quickly." : "Scan complete. Confirm your preregistered entry to mark yourself arrived." };
}

function getRequestedRouteTargetView(route = parseRouteFromLocation(), fallbackView = null) {
  if (fallbackView) return fallbackView;
  if (route?.kind === "streamer") return normalizeStreamerRoute(route).view;
  if (route?.kind === "role") return normalizeRouteViewForRole(route.role, route.view);
  return getActiveViewName();
}

function syncRequestedRouteEventSelection(options = {}) {
  const route = options.route || parseRouteFromLocation();
  const request = getRequestedRouteEventSelection(options.searchParams, route);
  if (!request.active || !request.valid) return false;
  const targetView = getRequestedRouteTargetView(route, options.view || null);
  if (activeEventId === request.eventId) {
    if (!localEventPreviewMode) {
      setLocalEventPreviewModeState(true);
    }
    if (targetView && getActiveViewName() !== targetView) {
      switchView(targetView);
    }
    return false;
  }
  openEventById(request.eventId, targetView, false);
  return true;
}

function syncRequestedSelfRegisterEventSelection(options = {}) {
  const request = getVenueQrCheckInRequest();
  if (!request?.eventId) return false;
  const targetView = options.view || "self-register";
  const routeSynced = syncRequestedRouteEventSelection({
    ...options,
    view: targetView,
  });
  if (!eventDirectory[request.eventId]) return false;
  applyRoleChange("spectator");
  switchView(targetView);
  return routeSynced;
}

function buildSelfRegisterProfileLabel(profile) {
  const name = (profile?.name || "").trim() || "Unnamed Driver";
  const team = (profile?.teamName || "").trim();
  const memberCount = getNamedDraftDriverMembers(profile).length;
  if (team && memberCount > 1) return `${team} | ${memberCount} drivers`;
  return team ? `${name} | ${team}` : name;
}

function syncSavedSelfRegisterProfilesUi(selectedId = "") {
  if (!selfRegisterSavedProfileSelect) return;
  const profiles = loadSavedSelfRegisterProfiles();
  if (!profiles.length) {
    selfRegisterSavedProfileSelect.innerHTML = `<option value="">No saved profiles yet</option>`;
    selfRegisterSavedProfileSelect.value = "";
    return;
  }
  selfRegisterSavedProfileSelect.innerHTML = [
    `<option value="">${isTeamTandemMode() ? "Choose a saved team" : "Choose a saved driver"}</option>`,
    ...profiles.map((profile) => `<option value="${escapeHtml(profile.id)}">${escapeHtml(buildSelfRegisterProfileLabel(profile))}</option>`)
  ].join("");
  selfRegisterSavedProfileSelect.value = profiles.some((profile) => profile.id === selectedId) ? selectedId : "";
}

function saveCurrentSelfRegisterProfile() {
  const name = (selfRegistrationDraft.name || "").trim();
  if (!name) {
    if (selfRegisterName) selfRegisterName.focus();
    return false;
  }
  const now = new Date().toISOString();
  const profiles = loadSavedSelfRegisterProfiles();
  const matchingProfile = profiles.find((profile) =>
    profile.name.trim().toLowerCase() === name.toLowerCase()
    && (profile.teamName || "").trim().toLowerCase() === (selfRegistrationDraft.teamName || "").trim().toLowerCase()
  );
  const nextProfile = {
    id: matchingProfile?.id || generateId(),
    label: "",
    name,
    driverNumber: (selfRegistrationDraft.driverNumber || "").trim(),
    teamName: (selfRegistrationDraft.teamName || "").trim(),
    chassis: (selfRegistrationDraft.chassis || "").trim(),
    teammate2Name: (selfRegistrationDraft.teammate2Name || "").trim(),
    teammate2Number: (selfRegistrationDraft.teammate2Number || "").trim(),
    teammate2Chassis: (selfRegistrationDraft.teammate2Chassis || "").trim(),
    teammate3Name: (selfRegistrationDraft.teammate3Name || "").trim(),
    teammate3Number: (selfRegistrationDraft.teammate3Number || "").trim(),
    teammate3Chassis: (selfRegistrationDraft.teammate3Chassis || "").trim(),
    lastUsedAt: now,
  };
  const nextProfiles = [
    nextProfile,
    ...profiles.filter((profile) => profile.id !== nextProfile.id),
  ].slice(0, 20);
  persistSavedSelfRegisterProfiles(nextProfiles);
  syncSavedSelfRegisterProfilesUi(nextProfile.id);
  return true;
}

function applySavedSelfRegisterProfile(profileId) {
  const profile = loadSavedSelfRegisterProfiles().find((entry) => entry.id === profileId);
  if (!profile) return false;
  selfRegistrationDraft = normalizeRegistrationDraftState(profile);
  persistSelfRegisterProfile();
  syncSavedSelfRegisterProfilesUi(profile.id);
  syncSelfRegisterForm();
  return true;
}

function deleteSavedSelfRegisterProfile(profileId) {
  if (!profileId) return false;
  const profiles = loadSavedSelfRegisterProfiles();
  if (!profiles.some((profile) => profile.id === profileId)) return false;
  persistSavedSelfRegisterProfiles(profiles.filter((profile) => profile.id !== profileId));
  syncSavedSelfRegisterProfilesUi("");
  return true;
}

function collectVenueConfigFromForm() {
  const enabled = venueEnabledSelect?.value === "true";
  const qrCheckInEnabled = venueQrEnabledSelect?.value !== "false";
  const qrApprovalMode = venueQrApprovalSelect?.value !== "false";
  const latitude = venueLatitudeInput?.value === "" ? null : Number.parseFloat(venueLatitudeInput.value);
  const longitude = venueLongitudeInput?.value === "" ? null : Number.parseFloat(venueLongitudeInput.value);
  const radiusMeters = venueRadiusInput?.value === "" ? 150 : Number.parseFloat(venueRadiusInput.value);
  const closeAt = venueCloseAtInput?.value ? new Date(venueCloseAtInput.value).toISOString() : null;
  return createDefaultVenueConfig({
    enabled,
    qrCheckInEnabled,
    qrApprovalMode,
    label: (venueLabelInput?.value || "").trim(),
    latitude: Number.isFinite(latitude) ? latitude : null,
    longitude: Number.isFinite(longitude) ? longitude : null,
    radiusMeters: Number.isFinite(radiusMeters) && radiusMeters > 0 ? Math.round(radiusMeters) : 150,
    closeAt: closeAt && !Number.isNaN(new Date(closeAt).getTime()) ? closeAt : null,
  });
}

function applyVenueConfigToForm(venueConfig) {
  const nextConfig = createDefaultVenueConfig(venueConfig || {});
  if (venueEnabledSelect) venueEnabledSelect.value = nextConfig.enabled ? "true" : "false";
  if (venueQrEnabledSelect) venueQrEnabledSelect.value = nextConfig.qrCheckInEnabled ? "true" : "false";
  if (venueQrApprovalSelect) venueQrApprovalSelect.value = nextConfig.qrApprovalMode ? "true" : "false";
  if (venueLabelInput) venueLabelInput.value = nextConfig.label || "";
  if (venueLatitudeInput) venueLatitudeInput.value = nextConfig.latitude ?? "";
  if (venueLongitudeInput) venueLongitudeInput.value = nextConfig.longitude ?? "";
  if (venueRadiusInput) venueRadiusInput.value = nextConfig.radiusMeters ?? 150;
  if (venueCloseAtInput) {
    venueCloseAtInput.value = nextConfig.closeAt
      ? new Date(nextConfig.closeAt).toISOString().slice(0, 16)
      : "";
  }
}

function setVenueLocationLookupState(tone = "info", message = "") {
  venueLocationLookupTone = tone || "info";
  venueLocationLookupMessage = message || "Capture the current device position at the venue to set the geofence center, or open the manual backup fields if GPS permission is unavailable.";
  if (!venueCurrentLocationStatus) return;
  venueCurrentLocationStatus.dataset.tone = venueLocationLookupTone;
  venueCurrentLocationStatus.innerHTML = `
    <strong>${escapeHtml(venueLocationLookupTone === "success" ? "Location Captured" : venueLocationLookupTone === "error" ? "Location Needed" : "Recommended")}</strong>
    <div>${escapeHtml(venueLocationLookupMessage)}</div>
  `;
}

function syncVenueLocationActionUi(canEditVenue = websiteAdminCanEditVenueSettings()) {
  if (useCurrentVenueLocationBtn) {
    useCurrentVenueLocationBtn.disabled = !canEditVenue || venueLocationLookupInFlight;
    useCurrentVenueLocationBtn.textContent = venueLocationLookupInFlight ? "Locating..." : "Use Current Location";
  }
  if (venueCurrentLocationStatus && !venueCurrentLocationStatus.innerHTML.trim()) {
    setVenueLocationLookupState(venueLocationLookupTone, venueLocationLookupMessage);
  }
}

function syncVenueProfilesUi(selectedId = venueProfileSelect?.value || "") {
  if (!venueProfileSelect) return;
  const profiles = getVenueProfiles();
  if (!profiles.length) {
    venueProfileSelect.innerHTML = `<option value="">No saved venue profiles</option>`;
    venueProfileSelect.value = "";
    return;
  }
  venueProfileSelect.innerHTML = [
    `<option value="">Choose a saved profile</option>`,
    ...profiles.map((profile) => `<option value="${escapeHtml(profile.id)}">${escapeHtml(profile.name)}</option>`),
  ].join("");
  venueProfileSelect.value = profiles.some((profile) => profile.id === selectedId) ? selectedId : "";
}

function clearVenueProfileSelection() {
  if (venueProfileSelect) venueProfileSelect.value = "";
  if (venueProfileNameInput) venueProfileNameInput.value = "";
}

function loadVenueProfileIntoForm(profileId, options = {}) {
  const profile = getVenueProfileById(profileId);
  if (!profile) return false;
  applyVenueConfigToForm(buildVenueProfileConfig(profile));
  syncVenueProfilesUi(profile.id);
  if (venueProfileNameInput) {
    venueProfileNameInput.value = profile.name || "";
  }
  if (options.syncState) {
    syncVenueConfigForm();
  }
  return true;
}

function saveVenueProfileDraft() {
  if (!websiteAdminCanManageVenueProfiles()) return false;
  const currentProfiles = getVenueProfiles();
  const selectedId = venueProfileSelect?.value || "";
  const trimmedName = (venueProfileNameInput?.value || "").trim();
  const nextName = trimmedName || (venueLabelInput?.value || "").trim() || `${activeEventMeta?.name || "Event"} Venue`;
  const baseConfig = collectVenueConfigFromForm();
  const now = new Date().toISOString();
  const existingProfile = currentProfiles.find((profile) => profile.id === selectedId) || null;
  const nextProfile = normalizeVenueProfile({
    ...(existingProfile || {}),
    ...baseConfig,
    id: existingProfile?.id || generateId(),
    name: nextName,
    createdAt: existingProfile?.createdAt || now,
    updatedAt: now,
  });
  setActiveEventMetaState({
    ...activeEventMeta,
    venueProfiles: normalizeVenueProfileList([
      nextProfile,
      ...currentProfiles.filter((profile) => profile.id !== nextProfile.id),
    ]),
  }, { syncQualifying: false });
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  publishState();
  syncVenueProfilesUi(nextProfile.id);
  if (venueProfileNameInput) venueProfileNameInput.value = nextProfile.name;
  return true;
}

function deleteSelectedVenueProfile() {
  if (!websiteAdminCanManageVenueProfiles()) return false;
  const selectedId = venueProfileSelect?.value || "";
  if (!selectedId) return false;
  const currentProfiles = getVenueProfiles();
  const targetProfile = currentProfiles.find((profile) => profile.id === selectedId);
  if (!targetProfile) return false;
  const confirmed = window.confirm(`Delete the venue profile "${targetProfile.name}"?`);
  if (!confirmed) return false;
  setActiveEventMetaState({
    ...activeEventMeta,
    venueProfiles: normalizeVenueProfileList(currentProfiles.filter((profile) => profile.id !== selectedId)),
  }, { syncQualifying: false });
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  publishState();
  syncVenueProfilesUi("");
  if ((venueProfileNameInput?.value || "").trim() === (targetProfile.name || "").trim()) {
    venueProfileNameInput.value = "";
  }
  return true;
}

function syncRegistrationDraftForm() {
  const canEditRegistration = registrationCanEdit();
  const teamMode = isTeamTandemMode();
  const twinMode = isTwinTripleMode();
  if (registrationDraftNameLabel) registrationDraftNameLabel.textContent = teamMode ? "Driver 1" : "Driver Name";
  if (registrationDraftNumberLabel) registrationDraftNumberLabel.textContent = teamMode ? "Driver 1 Number" : "Driver Number";
  if (registrationDraftTeamLabel) registrationDraftTeamLabel.textContent = "Team Name";
  if (registrationDraftChassisLabel) registrationDraftChassisLabel.textContent = teamMode ? "Driver 1 Chassis" : "Chassis";
  if (registrationDraftName) registrationDraftName.value = registrationDraft.name || "";
  if (registrationDraftNumber) registrationDraftNumber.value = registrationDraft.driverNumber || "";
  if (registrationDraftTeam) registrationDraftTeam.value = registrationDraft.teamName || "";
  if (registrationDraftChassis) registrationDraftChassis.value = registrationDraft.chassis || "";
  if (registrationDraftName) registrationDraftName.placeholder = teamMode ? "First driver name" : "Driver name";
  if (registrationDraftNumber) registrationDraftNumber.placeholder = teamMode ? "First driver number" : "Driver number";
  if (registrationDraftTeam) registrationDraftTeam.placeholder = "Team name";
  if (registrationDraftChassis) registrationDraftChassis.placeholder = teamMode ? "First driver chassis" : "Chassis";
  if (registrationDraftName2) registrationDraftName2.value = registrationDraft.teammate2Name || "";
  if (registrationDraftNumber2) registrationDraftNumber2.value = registrationDraft.teammate2Number || "";
  if (registrationDraftChassis2) registrationDraftChassis2.value = registrationDraft.teammate2Chassis || "";
  if (registrationDraftName3) registrationDraftName3.value = registrationDraft.teammate3Name || "";
  if (registrationDraftNumber3) registrationDraftNumber3.value = registrationDraft.teammate3Number || "";
  if (registrationDraftChassis3) registrationDraftChassis3.value = registrationDraft.teammate3Chassis || "";
  if (registrationDraftName) registrationDraftName.disabled = !canEditRegistration;
  if (registrationDraftNumber) registrationDraftNumber.disabled = !canEditRegistration;
  if (registrationDraftTeam) registrationDraftTeam.disabled = !canEditRegistration;
  if (registrationDraftChassis) registrationDraftChassis.disabled = !canEditRegistration;
  if (registrationDraftName2) registrationDraftName2.disabled = !canEditRegistration;
  if (registrationDraftNumber2) registrationDraftNumber2.disabled = !canEditRegistration;
  if (registrationDraftChassis2) registrationDraftChassis2.disabled = !canEditRegistration;
  if (registrationDraftName3) registrationDraftName3.disabled = !canEditRegistration;
  if (registrationDraftNumber3) registrationDraftNumber3.disabled = !canEditRegistration;
  if (registrationDraftChassis3) registrationDraftChassis3.disabled = !canEditRegistration;
  if (registrationTeamFields) registrationTeamFields.hidden = !teamMode;
  if (registrationSoloFields) registrationSoloFields.hidden = false;
  if (registrationAddDriverBtn) registrationAddDriverBtn.disabled = !canEditRegistration;
  if (registrationAddDriverBtn) registrationAddDriverBtn.textContent = teamMode ? "Add Team" : "Add Driver";
  if (registrationAddDriverSecondaryBtn) registrationAddDriverSecondaryBtn.disabled = !canEditRegistration;
  if (registrationAddDriverSecondaryBtn) registrationAddDriverSecondaryBtn.textContent = teamMode ? "Submit Team" : "Submit Driver";
  if (registrationEntryIntro) {
    registrationEntryIntro.textContent = teamMode
      ? "Team tandem mode registers one team at a time. Team name is required, Driver 1 and Driver 2 are required, and Driver 3 is optional."
      : twinMode
        ? "Twin Comp registers one driver at a time. Drivers with the same team name are grouped into one scoring team, up to 3 drivers."
      : "Submit one driver at a time. After each submit, a fresh form appears automatically for the next registration number.";
  }
  if (registrationModeNote) {
    registrationModeNote.textContent = teamMode
      ? "Use the first driver fields for Driver 1, then add Driver 2 and an optional Driver 3 below. All submitted drivers stay linked to the same team."
      : twinMode
        ? "Team name is required for Twin Comp. Matching team names appear in the same team box and score together."
      : "Team names are optional for solo driver events.";
  }
  if (registrationDraftRegLabel) {
    registrationDraftRegLabel.textContent = teamMode
      ? `Next team starts at registration #: #${getNextSignUpPosition(appDrivers)}`
      : `Next registration number: #${getNextSignUpPosition(appDrivers)}`;
  }
}

function getTeamNameGroupCount(teamName, options = {}) {
  const normalizedTeamName = normalizeDriverName(teamName || "");
  if (!normalizedTeamName) return 0;
  const excludeDriverIds = new Set(options.excludeDriverIds || []);
  return getRegisteredDrivers(appDrivers).filter((driver) => (
    !excludeDriverIds.has(driver.id)
    && normalizeDriverName(driver.teamName || "") === normalizedTeamName
  )).length;
}

function canAddToTeamNameGroup(teamName, addedCount = 1, options = {}) {
  const existingCount = getTeamNameGroupCount(teamName, options);
  return existingCount + Math.max(0, Number(addedCount) || 0) <= TEAM_TANDEM_MAX_DRIVERS;
}

function syncVenueConfigForm(options = {}) {
  const preserveDraft = Boolean(options.preserveDraft);
  const canEditVenue = websiteAdminCanEditVenueSettings();
  const canManageProfiles = websiteAdminCanManageVenueProfiles();
  const selectedProfileId = preserveDraft && canManageProfiles ? (venueProfileSelect?.value || "") : "";
  const venueConfig = createDefaultVenueConfig(preserveDraft ? collectVenueConfigFromForm() : getVenueConfig());
  const isClosedByQualifying = isSelfRegistrationClosedByQualifying();
  if (!preserveDraft) {
    applyVenueConfigToForm(venueConfig);
  }
  if (createEventVenueProfileBar) {
    createEventVenueProfileBar.classList.toggle("hidden", createEventModalMode !== "edit");
  }
  if (venueEnabledSelect) venueEnabledSelect.disabled = !canEditVenue;
  if (venueQrEnabledSelect) venueQrEnabledSelect.disabled = !canEditVenue;
  if (venueQrApprovalSelect) venueQrApprovalSelect.disabled = !canEditVenue || !venueConfig.qrCheckInEnabled;
  if (venueLocationPasteInput) venueLocationPasteInput.disabled = !canEditVenue;
  if (applyVenueLocationPasteBtn) applyVenueLocationPasteBtn.disabled = !canEditVenue;
  syncVenueLocationActionUi(canEditVenue);
  if (!venueLocationLookupInFlight) {
    if (Number.isFinite(Number(venueConfig.latitude)) && Number.isFinite(Number(venueConfig.longitude)) && venueLocationLookupTone !== "error") {
      setVenueLocationLookupState("success", `Geofence center ready at ${formatCoordinateValue(venueConfig.latitude)}, ${formatCoordinateValue(venueConfig.longitude)}. Use Current Location to recapture on-site, or open the backup coordinates to adjust manually.`);
    } else if (!Number.isFinite(Number(venueConfig.latitude)) || !Number.isFinite(Number(venueConfig.longitude))) {
      setVenueLocationLookupState(venueLocationLookupTone === "error" ? "error" : "info", venueLocationLookupTone === "error"
        ? venueLocationLookupMessage
        : "Capture the current device position at the venue to set the geofence center, or open the manual backup fields if GPS permission is unavailable.");
    }
  }
  if (venueLabelInput) venueLabelInput.disabled = !canEditVenue;
  if (venueLatitudeInput) venueLatitudeInput.disabled = !canEditVenue;
  if (venueLongitudeInput) venueLongitudeInput.disabled = !canEditVenue;
  if (venueRadiusInput) venueRadiusInput.disabled = !canEditVenue;
  if (venueCloseAtInput) venueCloseAtInput.disabled = !canEditVenue;
  syncVenueProfilesUi(selectedProfileId);
  if (venueProfileNameInput) {
    const selectedProfile = getVenueProfileById(venueProfileSelect?.value || "");
    venueProfileNameInput.value = selectedProfile?.name || "";
    venueProfileNameInput.disabled = !canManageProfiles;
  }
  if (venueProfileSelect) venueProfileSelect.disabled = !canManageProfiles;
  if (newVenueProfileBtn) newVenueProfileBtn.disabled = !canManageProfiles;
  if (saveVenueProfileBtn) saveVenueProfileBtn.disabled = !canManageProfiles;
  if (deleteVenueProfileBtn) {
    deleteVenueProfileBtn.disabled = !canManageProfiles || !(venueProfileSelect?.value || "");
  }
  if (saveVenueConfigBtn) saveVenueConfigBtn.disabled = !canEditVenue;
  if (venueConfigStatus) {
    const venueStatusMeta = {
      ...(activeEventMeta || {}),
      name: (eventNameInput?.value || activeEventMeta?.name || "").trim(),
      venueConfig,
    };
    const closeReason = getSelfRegistrationCloseReason(venueStatusMeta);
    const qrStatus = venueConfig.qrCheckInEnabled
      ? venueConfig.qrApprovalMode ? "QR arrival approval is ON." : "QR arrival approval is OFF."
      : "QR check-in is disabled.";
    venueConfigStatus.textContent = closeReason
      ? closeReason === "scheduled-close"
        ? `Self-registration is closed because the scheduled close time has passed${venueConfig.closeAt ? ` (${new Date(venueConfig.closeAt).toLocaleString()})` : ""}. ${qrStatus}`
        : `Self-registration is automatically closed because qualifying has already started. ${qrStatus}`
      : hasValidVenueConfig(venueStatusMeta)
      ? `Enabled for ${venueConfig.label || (eventNameInput?.value || "").trim() || activeEventMeta?.name || "this venue"} within ${Math.round(Number(venueConfig.radiusMeters) || 0)} meters${venueConfig.closeAt ? ` until ${new Date(venueConfig.closeAt).toLocaleString()}` : ""}. ${qrStatus}`
      : `Public self-registration is disabled for this event. ${qrStatus}`;
  }
}

function syncSelfRegisterForm() {
  const venueIsValid = hasValidVenueConfig();
  const closeReason = getSelfRegistrationCloseReason();
  const isClosedByQualifying = Boolean(closeReason);
  const teamMode = isTeamTandemMode();
  const qrRequest = getVenueQrCheckInRequest();
  const qrMode = qrRequest.qrMode;
  const qrValidation = qrMode ? getVenueQrCheckInValidation() : { valid: false, code: "not-qr", copy: "" };
  const qrSearchValue = (selfRegisterQrSearchInput?.value || "").trim().toLowerCase();
  const qrCandidates = qrMode
    ? getPendingRegistrationGroupLeaders().filter((entry) => {
      if (!qrSearchValue) return true;
      const label = getPendingGroupLabel(entry).toLowerCase();
      return label.includes(qrSearchValue) || (entry.name || "").toLowerCase().includes(qrSearchValue) || (entry.teamName || "").toLowerCase().includes(qrSearchValue);
    })
    : [];
  const selectedQrLeader = qrMode ? findPendingRegistrationGroupLeaderById(selfRegisterQrPendingSelect?.value || "") : null;
  if (selfRegisterNameLabel) selfRegisterNameLabel.textContent = teamMode ? "Driver 1" : "Driver Name";
  if (selfRegisterTeamLabel) selfRegisterTeamLabel.textContent = "Team Name";
  if (selfRegisterChassisLabel) selfRegisterChassisLabel.textContent = teamMode ? "Driver 1 Chassis" : "Chassis";
  const draftSlots = getDraftDriverMembers(selfRegistrationDraft);
  const namedDraftMembers = draftSlots.filter((member) => Boolean(member.name));
  const hasDraftName = teamMode
    ? Boolean((selfRegistrationDraft.teamName || "").trim()) && namedDraftMembers.length >= TEAM_TANDEM_MIN_DRIVERS && !draftSlots.some((member) => member.chassis && !member.name)
    : Boolean((selfRegistrationDraft.name || "").trim());
  const canSubmit = venueIsValid && !isEventReadOnly() && !isClosedByQualifying && hasDraftName;
  const effectiveCopy = qrMode
    ? (qrValidation.valid
      ? selfRegistrationState.copy || qrValidation.copy
      : qrValidation.copy)
    : venueIsValid
      ? selfRegistrationState.copy
      : "Pre-registration is disabled until event admin saves a valid venue location and radius.";
  const effectiveStatus = qrMode
    ? (qrValidation.valid ? selfRegistrationState.status : "error")
    : (!venueIsValid || isClosedByQualifying ? "error" : selfRegistrationState.status);
  const pendingCheckInGroup = selectedQrLeader && qrMode
    ? getPendingRegistrationGroupEntries(selectedQrLeader.id)
    : getPendingEntryGroupForCheckIn();
  const pendingCheckInEntry = getPendingRegistrationGroupLeader(pendingCheckInGroup);
  const qrLocateReady = qrMode && qrValidation.valid && Boolean(pendingCheckInEntry);
  if (selfRegisterNumberLabel) selfRegisterNumberLabel.textContent = teamMode ? "Driver 1 Number" : "Driver Number";
  if (selfRegisterName) selfRegisterName.value = selfRegistrationDraft.name || "";
  if (selfRegisterNumber) selfRegisterNumber.value = selfRegistrationDraft.driverNumber || "";
  if (selfRegisterTeam) selfRegisterTeam.value = selfRegistrationDraft.teamName || "";
  if (selfRegisterChassis) selfRegisterChassis.value = selfRegistrationDraft.chassis || "";
  if (selfRegisterName) selfRegisterName.placeholder = teamMode ? "First driver name" : "Driver name";
  if (selfRegisterNumber) selfRegisterNumber.placeholder = teamMode ? "First driver number" : "Driver number";
  if (selfRegisterTeam) selfRegisterTeam.placeholder = "Team name";
  if (selfRegisterChassis) selfRegisterChassis.placeholder = teamMode ? "First driver chassis" : "Chassis";
  if (selfRegisterName2) selfRegisterName2.value = selfRegistrationDraft.teammate2Name || "";
  if (selfRegisterNumber2) selfRegisterNumber2.value = selfRegistrationDraft.teammate2Number || "";
  if (selfRegisterChassis2) selfRegisterChassis2.value = selfRegistrationDraft.teammate2Chassis || "";
  if (selfRegisterName3) selfRegisterName3.value = selfRegistrationDraft.teammate3Name || "";
  if (selfRegisterNumber3) selfRegisterNumber3.value = selfRegistrationDraft.teammate3Number || "";
  if (selfRegisterChassis3) selfRegisterChassis3.value = selfRegistrationDraft.teammate3Chassis || "";
  if (selfRegisterName) selfRegisterName.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterNumber) selfRegisterNumber.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterTeam) selfRegisterTeam.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterChassis) selfRegisterChassis.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterName2) selfRegisterName2.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterNumber2) selfRegisterNumber2.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterChassis2) selfRegisterChassis2.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterName3) selfRegisterName3.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterNumber3) selfRegisterNumber3.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterChassis3) selfRegisterChassis3.disabled = !venueIsValid || isEventReadOnly() || isClosedByQualifying;
  if (selfRegisterTeamFields) selfRegisterTeamFields.hidden = !teamMode;
  if (selfRegisterSoloFields) selfRegisterSoloFields.hidden = false;
  if (selfRegisterSubmitBtn) {
    selfRegisterSubmitBtn.disabled = !canSubmit;
    selfRegisterSubmitBtn.textContent = pendingCheckInEntry
      ? teamMode ? "Update Team Pre-Registration" : "Update Pre-Registration"
      : teamMode ? "Pre-Register Team" : "Pre-Register";
  }
  if (selfRegisterQrArrivalPanel) {
    selfRegisterQrArrivalPanel.hidden = !qrMode;
    selfRegisterQrArrivalPanel.classList.remove("is-ready", "is-locked", "is-error");
    selfRegisterQrArrivalPanel.classList.add(
      !qrValidation.valid
        ? "is-error"
        : pendingCheckInEntry?.checkedInAt
          ? "is-ready"
          : pendingCheckInEntry
            ? "is-ready"
            : "is-locked"
    );
  }
  if (selfRegisterQrArrivalTitle) {
    selfRegisterQrArrivalTitle.textContent = !qrMode
      ? "Venue QR Check-In"
      : !qrValidation.valid
        ? "Venue QR Check-In Unavailable"
        : pendingCheckInEntry?.checkedInAt
          ? "Already Checked In"
          : pendingCheckInEntry
            ? "Venue QR Check-In Ready"
            : "Find Your Pre-Registration";
  }
  if (selfRegisterQrArrivalCopy) {
    selfRegisterQrArrivalCopy.textContent = !qrMode
      ? "Select your preregistered name or use saved details to confirm arrival."
      : !qrValidation.valid
        ? qrValidation.copy
        : pendingCheckInEntry?.checkedInAt
          ? `${pendingCheckInEntry.teamName || pendingCheckInEntry.name} already arrived for ${activeEventMeta?.name || "this event"}.`
          : pendingCheckInEntry
            ? `${pendingCheckInEntry.teamName || pendingCheckInEntry.name} is ready for QR arrival confirmation.`
            : "Select your preregistered name or use saved details to match your arrival.";
  }
  if (selfRegisterQrLookupPanel) {
    selfRegisterQrLookupPanel.hidden = !qrMode;
  }
  if (selfRegisterQrPendingSelect) {
    const currentValue = selectedQrLeader?.id || pendingCheckInEntry?.id || "";
    const optionsMarkup = [
      `<option value="">Choose your preregistered entry</option>`,
      ...qrCandidates.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(getPendingGroupLabel(entry))}</option>`),
    ];
    selfRegisterQrPendingSelect.innerHTML = optionsMarkup.join("");
    selfRegisterQrPendingSelect.value = qrCandidates.some((entry) => entry.id === currentValue) ? currentValue : "";
    selfRegisterQrPendingSelect.disabled = !qrMode || !qrValidation.valid;
  }
  if (selfRegisterQrSearchInput) {
    selfRegisterQrSearchInput.disabled = !qrMode || !qrValidation.valid;
  }
  if (selfRegisterQrLookupNote) {
    selfRegisterQrLookupNote.textContent = !qrMode
      ? "Choose your preregistered name or use saved details to confirm arrival faster."
      : !qrValidation.valid
        ? qrValidation.copy
        : qrCandidates.length
          ? `Matching preregistrations: ${qrCandidates.length}. Select your entry to confirm arrival.`
          : "No preregistered entry matches your current name yet. Search by name or use saved details.";
  }
  if (selfRegisterLocateBtn) {
    selfRegisterLocateBtn.disabled = qrMode
      ? !qrLocateReady || isEventReadOnly()
      : !venueIsValid || isEventReadOnly() || isClosedByQualifying;
    selfRegisterLocateBtn.textContent = qrMode
      ? pendingCheckInEntry?.checkedInAt
        ? "Already Checked In"
        : teamMode ? "Confirm Team QR Arrival" : "Confirm QR Arrival"
      : pendingCheckInEntry?.checkedInAt
        ? "Venue Check-In Verified"
        : teamMode ? "Verify Team Venue Check-In" : "Verify Venue Check-In";
  }
  if (selfRegisterStatus) {
    selfRegisterStatus.classList.remove("is-ready", "is-locked", "is-error");
    selfRegisterStatus.classList.add(
      effectiveStatus === "ready"
        ? "is-ready"
        : effectiveStatus === "error"
          ? "is-error"
        : "is-locked"
    );
  }
  if (selfRegisterStatusTitle) {
    selfRegisterStatusTitle.textContent = isClosedByQualifying
      ? closeReason === "scheduled-close"
        ? "Registration is closed."
        : "Registration is closed."
      : qrMode && !qrValidation.valid
        ? "Venue QR Check-In Unavailable"
      : !venueIsValid
        ? "Self-registration is disabled by event staff."
      : effectiveStatus === "ready"
        ? pendingCheckInEntry?.checkedInAt
          ? "You are preregistered."
          : qrMode
            ? "Venue check-in is open."
            : "Venue check-in is open."
        : effectiveStatus === "error"
          ? "Check-In Required"
          : "Pre-registration is open.";
  }
  if (selfRegisterStatusCopy) selfRegisterStatusCopy.textContent = isClosedByQualifying
    ? closeReason === "scheduled-close"
      ? `Registration is closed. The scheduled cutoff has passed${getVenueConfig().closeAt ? ` (${new Date(getVenueConfig().closeAt).toLocaleString()})` : ""}.`
      : "Registration is closed because qualifying has already started for this event."
    : !venueIsValid && !qrMode
      ? "Self-registration is disabled by event staff."
      : effectiveStatus === "ready" && pendingCheckInEntry?.checkedInAt
        ? "You are preregistered. Complete venue check-in when you arrive."
        : effectiveStatus === "ready"
          ? "Venue check-in is open."
          : qrMode
            ? effectiveCopy
            : "Pre-registration is open. Venue check-in opens on event day.";
  if (selfRegisterFormNote) {
    selfRegisterFormNote.textContent = qrMode
      ? !qrValidation.valid
        ? qrValidation.copy
        : pendingCheckInEntry?.checkedInAt
          ? teamMode
            ? "QR arrival already confirmed. Event admin can approve this team after payment."
            : "QR arrival already confirmed. Event admin can approve this driver after payment."
          : pendingCheckInEntry
            ? teamMode
              ? "Use Confirm Team QR Arrival to mark this preregistered team on site."
              : "Use Confirm QR Arrival to mark this preregistered driver on site."
            : "Search your preregistered name, choose the right entry, then confirm arrival."
      : !venueIsValid
      ? "Self-registration is disabled until event admin saves a valid venue location and radius."
      : selfRegistrationState.unlocked
      ? pendingCheckInEntry?.checkedInAt
        ? teamMode
          ? "Venue check-in confirmed. Event admin can now approve this team after payment."
          : "Venue check-in confirmed. Event admin can now approve this driver after payment."
        : teamMode
          ? "Venue check-in confirmed. Submit now to pre-register this team with on-site verification."
          : "Venue check-in confirmed. Submit now to pre-register with on-site verification."
      : isClosedByQualifying
        ? closeReason === "scheduled-close"
          ? "Pre-registration is closed because the scheduled close time has passed."
          : "Pre-registration is closed once qualifying is live."
        : teamMode
          ? "Team tandem mode requires a team name plus 2-3 drivers. Verify venue check-in when the team arrives."
          : "Pre-register from anywhere, then tap Verify Venue Check-In when you arrive.";
  }
  if (selfRegisterVenueMeta) {
    const venueConfig = getVenueConfig();
    const pendingCount = getPendingRegistrations().length;
    selfRegisterVenueMeta.textContent = isClosedByQualifying
      ? closeReason === "scheduled-close"
        ? `Pre-registration is closed because the scheduled close time passed. Live roster: ${getRegisteredDrivers(appDrivers).length} drivers | Pending payment: ${pendingCount}`
        : `Pre-registration is closed because qualifying is already ${getQualifyingFlowPhase(qualifyingFlow, appDrivers) === "complete" ? "complete" : "live"}. Live roster: ${getRegisteredDrivers(appDrivers).length} drivers | Pending payment: ${pendingCount}`
      : qrMode
        ? qrValidation.valid
          ? `${activeEventMeta?.name || "Current event"} | Venue QR mode | Pending pre-registrations: ${pendingCount} | Approval mode: ${venueConfig.qrApprovalMode ? "On" : "Off"}`
          : qrValidation.copy
      : hasValidVenueConfig()
      ? `${venueConfig.label || activeEventMeta?.name || "Current venue"} | Radius ${Math.round(Number(venueConfig.radiusMeters) || 0)} m | Live roster: ${getRegisteredDrivers(appDrivers).length} drivers | Pending pre-registrations: ${pendingCount}`
      : "Self-registration is disabled by event staff.";
  }
  if (selfRegisterDriverCount) {
    const count = getRegisteredDrivers(appDrivers).length;
    selfRegisterDriverCount.textContent = count
      ? `${count} Driver${count === 1 ? "" : "s"}`
      : "Driver list will appear when registration opens.";
  }
  if (selfRegisterSavedProfileNote) {
    const hasSavedProfile = Boolean(
      (selfRegistrationDraft.name || "").trim()
      || (selfRegistrationDraft.teamName || "").trim()
      || (selfRegistrationDraft.chassis || "").trim()
      || (selfRegistrationDraft.teammate2Name || "").trim()
      || (selfRegistrationDraft.teammate2Chassis || "").trim()
      || (selfRegistrationDraft.teammate3Name || "").trim()
      || (selfRegistrationDraft.teammate3Chassis || "").trim()
    );
    const savedProfiles = loadSavedSelfRegisterProfiles();
    selfRegisterSavedProfileNote.textContent = hasSavedProfile
      ? teamMode
        ? `This device is remembering the current team details. Saved profiles available: ${savedProfiles.length}.`
        : `This device is remembering the current driver details. Saved profiles available: ${savedProfiles.length}.`
      : teamMode
        ? `This device can remember team details for faster tandem check-in next time. Saved profiles: ${savedProfiles.length}.`
        : `This device can remember driver details for faster check-in next time. Saved profiles: ${savedProfiles.length}.`;
  }
  if (selfRegisterModeNote) {
    selfRegisterModeNote.textContent = qrMode
      ? teamMode
        ? "Venue QR check-in works best with a saved team profile or by selecting the preregistered team below."
        : "Venue QR check-in works best with your saved profile or by selecting your preregistered name below."
      : teamMode
        ? "Use the first driver fields for Driver 1, then add Driver 2 and an optional Driver 3. Team name is required."
        : "Solo events accept one driver per pre-registration.";
  }
  syncSavedSelfRegisterProfilesUi(selfRegisterSavedProfileSelect?.value || "");
  syncSelfRegisterProfileCard();
}

function syncSelfRegisterQrPanel() {
  const selfRegisterUrl = buildVenueQrCheckInUrl();
  const qrUrl = buildSelfRegisterQrUrl();
  const closeReason = getSelfRegistrationCloseReason();
  const venueConfig = getVenueConfig();
  const checkInCounts = getVenueCheckInCounts(activeEventMeta);
  if (selfRegisterPublicLink) {
    selfRegisterPublicLink.href = selfRegisterUrl || "#";
    selfRegisterPublicLink.textContent = selfRegisterUrl || "Venue QR check-in link unavailable.";
  }
  if (selfRegisterQrImage) {
    if (qrUrl && venueConfig.qrCheckInEnabled) {
      selfRegisterQrImage.src = qrUrl;
      selfRegisterQrImage.hidden = false;
    } else {
      selfRegisterQrImage.removeAttribute("src");
      selfRegisterQrImage.hidden = true;
    }
  }
  if (selfRegisterQrLabel) {
    selfRegisterQrLabel.textContent = !venueConfig.qrCheckInEnabled
      ? "Venue QR check-in is disabled for this event."
      : selfRegisterUrl
        ? `Scan to open venue QR check-in for ${activeEventMeta?.name || "the current event"}.`
        : "Venue QR check-in will appear here.";
  }
  if (selfRegisterDisplayQrImage) {
    if (qrUrl && venueConfig.qrCheckInEnabled) {
      selfRegisterDisplayQrImage.src = qrUrl;
      selfRegisterDisplayQrImage.hidden = false;
    } else {
      selfRegisterDisplayQrImage.removeAttribute("src");
      selfRegisterDisplayQrImage.hidden = true;
    }
  }
  if (selfRegisterDisplayTitle) {
    selfRegisterDisplayTitle.textContent = activeEventMeta?.name
      ? `${activeEventMeta.name} Check-In`
      : "Scan To Register";
  }
  if (selfRegisterDisplayCopy) {
    selfRegisterDisplayCopy.textContent = closeReason
      ? closeReason === "scheduled-close"
        ? "Venue QR check-in is closed because the scheduled close time has passed."
        : "Venue QR check-in is now closed because qualifying is in progress."
      : !venueConfig.qrCheckInEnabled
        ? "Venue QR check-in is disabled for this event right now."
      : activeEventMeta?.date
        ? `Scan with your phone camera to open check-in for ${activeEventMeta.name} on ${formatEventDate(activeEventMeta.date)}.`
        : "Use your phone camera to open the venue QR check-in page for this event.";
  }
  if (selfRegisterDisplayLink) {
    selfRegisterDisplayLink.href = selfRegisterUrl || "#";
    selfRegisterDisplayLink.textContent = selfRegisterUrl || "Venue QR check-in link unavailable.";
  }
  if (selfRegisterQrAdminStatus) {
    selfRegisterQrAdminStatus.textContent = !venueConfig.qrCheckInEnabled
      ? "Venue QR check-in is disabled for this event."
      : closeReason
        ? closeReason === "scheduled-close"
          ? "Venue QR check-in is closed because the scheduled close time has passed."
          : "Venue QR check-in is closed because qualifying is live."
        : `Venue QR check-in is live for ${activeEventMeta?.name || "this event"}. Approval mode is ${venueConfig.qrApprovalMode ? "on" : "off"}.`;
  }
  if (selfRegisterQrArrivalSummary) {
    selfRegisterQrArrivalSummary.innerHTML = `
      ${renderStatusChips([
        { label: `${checkInCounts.preregistered} Pre-Registered`, tone: checkInCounts.preregistered ? "warning" : "muted" },
        { label: `${checkInCounts.arrived} Arrived`, tone: checkInCounts.arrived ? "ready" : "muted" },
        { label: `${checkInCounts.needsReview} Needs Review`, tone: checkInCounts.needsReview ? "warning" : "ready" },
        { label: `${checkInCounts.rejected} Rejected`, tone: checkInCounts.rejected ? "error" : "muted" },
      ])}
      <div>${venueConfig.qrCheckInEnabled ? "Scan feedback is live. Arrived drivers are safe to approve after payment." : "QR check-in is disabled for this event."}</div>
    `;
  }
}

function syncRegistrationAdminAlerts() {
  if (!registrationAdminAlerts) return;
  const pendingEntries = getPendingRegistrations();
  const unpaidCount = pendingEntries.filter((entry) => !entry.paidAt).length;
  const paidAwaitingCount = pendingEntries.filter((entry) => Boolean(entry.paidAt)).length;
  const queueCount = getQualifyingDriverQueue().length;
  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const alerts = [
    {
      tone: unpaidCount ? "is-warning" : "is-muted",
      label: "Pending Payment",
      value: unpaidCount,
    },
    {
      tone: paidAwaitingCount ? "is-warning" : "is-muted",
      label: "Paid Awaiting Approval",
      value: paidAwaitingCount,
    },
    {
      tone: qualifyingPhase === "waiting" && queueCount > 0 ? "is-success" : "is-muted",
      label: "Qualifying Ready",
      value: qualifyingPhase === "waiting" && queueCount > 0 ? "Yes" : "No",
    },
    {
      tone: isSelfRegistrationClosedByQualifying() ? "is-warning" : hasValidVenueConfig() ? "is-success" : "is-muted",
      label: "Self-Register",
      value: isSelfRegistrationClosedByQualifying() ? "Closed" : hasValidVenueConfig() ? "Open" : "Off",
    },
  ];
  const closeAt = getVenueConfig().closeAt;
  if (closeAt && !isSelfRegistrationClosedByQualifying()) {
    alerts.push({
      tone: "is-muted",
      label: "Closes",
      value: new Date(closeAt).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }),
    });
  }
  registrationAdminAlerts.innerHTML = alerts.map((alert) => `
    <div class="admin-alert-pill ${alert.tone}">
      <span>${escapeHtml(alert.label)}</span>
      <strong>${escapeHtml(String(alert.value))}</strong>
    </div>
  `).join("");
}

function syncApprovalToast() {
  if (!approvalToast) return;
  if (approvalToastDismissTimer) {
    clearTimeout(approvalToastDismissTimer);
    approvalToastDismissTimer = null;
  }
  approvalToast.classList.add("hidden");
}

function buildBroadcastTickerItems() {
  const items = [];
  const eventName = activeEventMeta?.name || "Main Event";
  items.push(`Event <strong>${escapeHtml(eventName)}</strong>`);

  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const currentDriver = getCurrentQualifyingDriver();
  if (isTwinTripleMode(activeEventMeta)) {
    const state = getTwinCompState();
    const round = getTwinCompCurrentRound(state);
    if (state.winnerName) {
      items.push(`Twin Comp Winner <strong>${escapeHtml(state.winnerName)}</strong>`);
    } else if (currentDriver) {
      items.push(`Twin Comp Round ${round?.number || state.roundNumber || 1} <strong>${escapeHtml(currentDriver.teamName || currentDriver.name || "Current Team")}</strong>`);
    }
    if (state.latestScore?.teamName) {
      items.push(`Latest Score <strong>${escapeHtml(state.latestScore.teamName)} ${formatScore(Number(state.latestScore.score))}</strong>`);
    }
    items.push(`Active Teams <strong>${getTwinCompActiveTeams(state).length}</strong>`);
    return items.filter(Boolean);
  }
  if (qualifyingPhase === "live" && currentDriver) {
    const queue = getQualifyingDriverQueue();
    const currentIndex = queue.findIndex((driver) => driver.id === currentDriver.id);
    const nextDriver = currentIndex > -1 ? queue[currentIndex + 1] || null : null;
    items.push(`Now Qualifying <strong>${escapeHtml(formatDriverDisplayName(currentDriver))}</strong>`);
    items.push(`Best Live Score <strong>${escapeHtml(formatScore(getBestScore(getLiveRunAverage(currentDriver, 1), getLiveRunAverage(currentDriver, 2))))}</strong>`);
    if (nextDriver?.name) {
      items.push(`On Deck <strong>${escapeHtml(nextDriver.name)}</strong>`);
    }
  } else if (qualifyingPhase === "waiting") {
    items.push(`Qualifying <strong>Ready To Start</strong>`);
  } else if (qualifyingPhase === "complete") {
    items.push(`Qualifying <strong>Complete</strong>`);
  }

  const rankedDrivers = rankDrivers(appDrivers);
  if (rankedDrivers[0]?.name) {
    items.push(`Top Seed <strong>#${rankedDrivers[0].seed} ${escapeHtml(rankedDrivers[0].name)}</strong>`);
  }

  const pendingCount = getPendingRegistrations().length;
  if (pendingCount) {
    items.push(`Pending Check-Ins <strong>${pendingCount}</strong>`);
  }

  if (tournamentState?.mainBracket?.rounds?.length) {
    const bracketEntries = getMainBattleFlowEntries(
      tournamentState.mainBracket.rounds,
      tournamentState.mainBracket.thirdPlaceMatch,
    );
    const nextBattle = bracketEntries[0];
    if (nextBattle?.match?.left?.name && nextBattle?.match?.right?.name) {
      items.push(`Now Battling <strong>${escapeHtml(nextBattle.match.left.name)} vs ${escapeHtml(nextBattle.match.right.name)}</strong>`);
    } else {
      items.push(`Competition <strong>Bracket Live</strong>`);
    }
  }

  const results = activeEventMeta?.results || {};
  if (results.championName) {
    items.push(`Champion <strong>#${results.championSeed || "-"} ${escapeHtml(results.championName)}</strong>`);
  }

  return items.filter(Boolean);
}

function isOfflineMode() {
  return typeof navigator !== "undefined" && navigator.onLine === false;
}

function getCompetitionPlanForCurrentState(rankedDrivers = rankDrivers(appDrivers)) {
  const requestedMainSize = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;
  return getCompetitionPlan(rankedDrivers.length, bracketModeSelect.value, requestedMainSize);
}

function getDuplicateDriverNames() {
  const counts = new Map();
  [...getRegisteredDrivers(appDrivers), ...getPendingRegistrations()].forEach((entry) => {
    const normalized = normalizeDriverName(entry?.name || "");
    if (!normalized) return;
    counts.set(normalized, (counts.get(normalized) || 0) + 1);
  });
  return [...counts.entries()]
    .filter(([, count]) => count > 1)
    .map(([name]) => name.replace(/\b\w/g, (char) => char.toUpperCase()));
}

function getBracketValidationState(rankedDrivers = rankDrivers(appDrivers)) {
  if (isTwinTripleMode()) {
    syncTwinCompTeamsFromRoster();
    const teams = getRegisteredDrivers(appDrivers);
    const eliminationLabel = getTwinCompEliminationLabel();
    const eliminationLimit = getTwinCompEliminationLimit();
    const issues = [];
    const warnings = [];
    if (teams.length < 2) {
      issues.push(`Twin Comp ${eliminationLabel.toLowerCase()} needs at least 2 teams so the bottom half can receive points in opening rounds.`);
    }
    const state = getTwinCompState();
    const round = getTwinCompCurrentRound(state);
    if (round?.tieReviewRequired) {
      warnings.push("Tie at the lowest-three cutoff needs admin review before points are applied.");
    }
    return {
      plan: {
        qualifiedCount: teams.length,
        description: `Twin Comp ${getTwinCompEliminationAdjective()}. Every active team runs each round; the bottom half of finalized scores receive one elimination point. Teams are eliminated at ${eliminationLimit} points.`,
      },
      phase: state.status,
      issues,
      warnings,
      buildReady: issues.length === 0,
      rankedDrivers: teams,
    };
  }
  if (isTeamTandemMode()) {
    const teamEntries = getTeamTandemRosterEntries(appDrivers);
    const issues = [];
    const warnings = [];
    const invalidTeams = teamEntries.filter((entry) => entry.memberCount < TEAM_TANDEM_MIN_DRIVERS || entry.memberCount > TEAM_TANDEM_MAX_DRIVERS);

    if (teamEntries.length < 2) {
      issues.push("At least 2 registered teams are required before the Team Tandem bracket can launch.");
    }
    if (invalidTeams.length) {
      issues.push(`Every Team Tandem team must have ${TEAM_TANDEM_MIN_DRIVERS}-${TEAM_TANDEM_MAX_DRIVERS} drivers. Fix ${invalidTeams[0].teamName} first.`);
    }

    const buildReady = issues.length === 0;
    return {
      plan: getTeamTandemCompetitionPlan(teamEntries.length),
      phase: tournamentState?.mainBracket?.rounds?.length ? "complete" : "waiting",
      issues,
      warnings,
      buildReady,
      rankedDrivers: buildTeamTandemOrderedParticipants(appDrivers),
    };
  }

  const plan = getCompetitionPlanForCurrentState(rankedDrivers);
  const phase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const issues = [];
  const warnings = [];
  const tieInfo = getTopQualifierTieInfo(rankedDrivers);
  const selectedMainSize = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;

  if (rankedDrivers.length < 2) {
    issues.push("At least 2 scored drivers are required before any bracket can be built.");
  }

  if (tieInfo?.requiresRunoff) {
    issues.push("Top qualifier runoff scores are still required before bracket launch.");
  }

  if (isSdcFormat(bracketModeSelect.value)) {
    const validSizes = getValidSdcMainBracketSizes(rankedDrivers.length);
    if (selectedMainSize && !validSizes.includes(selectedMainSize)) {
      issues.push(`SDC Top ${selectedMainSize} needs ${selectedMainSize} scored drivers. Right now ${rankedDrivers.length} are scored.`);
    }
  }

  if (phase === "waiting") {
    warnings.push("Qualifying has not started yet.");
  } else if (phase === "live") {
    warnings.push("Qualifying is still live. The bracket will auto-build once the final driver is complete.");
  }

  const duplicateNames = getDuplicateDriverNames();
  if (duplicateNames.length) {
    warnings.push(`Duplicate driver names detected: ${duplicateNames.join(", ")}.`);
  }

  if (isTeamTandemMode()) {
    const registeredDrivers = getRegisteredDrivers(appDrivers);
    const missingTeamDrivers = registeredDrivers.filter((driver) => !(driver.teamName || "").trim());
    if (missingTeamDrivers.length) {
      warnings.push(`Team tandem mode still has drivers without team names: ${missingTeamDrivers.slice(0, 3).map((driver) => driver.name || "Unnamed").join(", ")}${missingTeamDrivers.length > 3 ? "..." : ""}.`);
    }

    const teamCounts = new Map();
    registeredDrivers.forEach((driver) => {
      const teamName = (driver.teamName || "").trim();
      if (!teamName) return;
      teamCounts.set(teamName, (teamCounts.get(teamName) || 0) + 1);
    });
    const invalidTeams = [...teamCounts.entries()].filter(([, count]) => count < TEAM_TANDEM_MIN_DRIVERS || count > TEAM_TANDEM_MAX_DRIVERS);
    if (invalidTeams.length) {
      warnings.push(`Team tandem teams should have ${TEAM_TANDEM_MIN_DRIVERS}-${TEAM_TANDEM_MAX_DRIVERS} drivers: ${invalidTeams.slice(0, 3).map(([teamName, count]) => `${teamName} (${count})`).join(", ")}${invalidTeams.length > 3 ? "..." : ""}.`);
    }
  }

  const paidAwaitingCount = getPendingRegistrations().filter((entry) => Boolean(entry.paidAt)).length;
  if (paidAwaitingCount) {
    warnings.push(`${paidAwaitingCount} paid self-registration${paidAwaitingCount === 1 ? " is" : "s are"} still waiting for roster approval.`);
  }

  const buildReady = phase === "complete" && issues.length === 0;
  return { plan, phase, issues, warnings, buildReady, rankedDrivers };
}

function getEventLifecycleMeta() {
  const results = activeEventMeta?.results || {};
  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  const eventStatus = getEventStatus(activeEventMeta);
  if (eventStatus === EVENT_STATUS_ARCHIVED) {
    return { label: "Archived", tone: "archived", detail: "Past event locked" };
  }
  if (eventStatus === EVENT_STATUS_COMPLETED) {
    return { label: "Event Final", tone: "active", detail: results.championName ? `Champion #${results.championSeed || "-"} ${results.championName}` : "Results locked" };
  }
  if (isTwinTripleMode(activeEventMeta)) {
    const state = getTwinCompState();
    const round = getTwinCompCurrentRound(state);
    if (state.status === "complete") {
      return { label: "Ready to Finalize", tone: "active", detail: state.winnerName ? `Winner ${state.winnerName}` : "Winner declared" };
    }
    if (round && ["live", "scored", "review"].includes(round.status)) {
      const currentTeam = getCurrentQualifyingDriver();
      return { label: "Twin Comp Live", tone: "active", detail: currentTeam?.name || currentTeam?.teamName ? `Round ${round.number}: ${currentTeam.teamName || currentTeam.name}` : `Round ${round.number}` };
    }
    return { label: "Twin Comp Setup", tone: "active", detail: "Waiting to start the next round" };
  }
  if (isBracketReadyToFinalize()) {
    return {
      label: "Ready to Finalize",
      tone: "active",
      detail: results.championName
        ? `Admin review: #${results.championSeed || "-"} ${results.championName} is currently on top`
        : "Admin review before locking results",
    };
  }
  if (tournamentState?.mainBracket?.rounds?.length) {
    const battleEntries = activeCompetitionBracketPage === "lower" && tournamentState?.lowerBracket?.rounds?.length
      ? getLowerBattleFlowEntries(tournamentState.lowerBracket.rounds)
      : getMainBattleFlowEntries(tournamentState.mainBracket.rounds, tournamentState.mainBracket.thirdPlaceMatch);
    return {
      label: "Competition Live",
      tone: "active",
      detail: battleEntries[0]?.match?.left?.name && battleEntries[0]?.match?.right?.name
        ? `${battleEntries[0].match.left.name} vs ${battleEntries[0].match.right.name}`
        : "Bracket published",
    };
  }
  if (qualifyingPhase === "live") {
    const currentDriver = getCurrentQualifyingDriver();
    return {
      label: "Qualifying Live",
      tone: "active",
      detail: currentDriver?.name ? `Now qualifying ${currentDriver.name}` : "Judges scoring live",
    };
  }
  if (qualifyingPhase === "complete") {
    return { label: "Qualifying Complete", tone: "active", detail: "Waiting for bracket publish" };
  }
  return { label: "Registration Live", tone: "active", detail: "Roster open" };
}

function buildDriverStatusContext() {
  const rankedDrivers = rankDrivers(appDrivers);
  const plan = getCompetitionPlanForCurrentState(rankedDrivers);
  const rankingLookup = new Map(rankedDrivers.map((driver, index) => [driver.id, { ...driver, index }]));
  const queue = getQualifyingDriverQueue();
  const currentDriver = getCurrentQualifyingDriver();
  const currentIndex = currentDriver ? queue.findIndex((entry) => entry.id === currentDriver.id) : -1;
  const nextDriver = currentIndex > -1 ? queue[currentIndex + 1] || null : null;
  const tournamentDriverIds = new Set((tournamentState?.qualifiedDrivers || []).map((driver) => driver.id));
  const results = activeEventMeta?.results || {};
  return {
    rankedDrivers,
    plan,
    rankingLookup,
    queue,
    currentDriverId: currentDriver?.id || null,
    nextDriverId: nextDriver?.id || null,
    qualifyingPhase: getQualifyingFlowPhase(qualifyingFlow, appDrivers),
    tournamentDriverIds,
    results,
  };
}

function getDriverStatusBadges(driver, context = buildDriverStatusContext()) {
  const statuses = [];
  const rankedInfo = context.rankingLookup.get(driver.id) || null;
  const queueIndex = context.queue.findIndex((entry) => entry.id === driver.id);

  if (context.results.championName === driver.name && context.results.championSeed === rankedInfo?.seed) {
    statuses.push({ label: "Champion", tone: "champion" });
  } else if (context.results.runnerUpName === driver.name && context.results.runnerUpSeed === rankedInfo?.seed) {
    statuses.push({ label: "Runner Up", tone: "ready" });
  } else if (context.results.thirdPlaceName === driver.name && context.results.thirdPlaceSeed === rankedInfo?.seed) {
    statuses.push({ label: "Podium", tone: "ready" });
  }

  if (isTwinTripleMode(activeEventMeta)) {
    const team = getTwinCompState().teams.find((entry) => entry.id === driver.id);
    if (team) {
      statuses.push({ label: team.active ? `${team.eliminationPoints}/${getTwinCompEliminationLimit()} Elim` : `Eliminated R${team.roundEliminated || "-"}`, tone: team.active ? "ready" : "muted" });
    }
  }

  if (context.currentDriverId === driver.id && context.qualifyingPhase === "live") {
    statuses.push({ label: "Now Qualifying", tone: "live" });
  } else if (context.nextDriverId === driver.id && context.qualifyingPhase === "live") {
    statuses.push({ label: "On Deck", tone: "ready" });
  } else if (queueIndex > -1 && context.qualifyingPhase === "live" && context.currentDriverId) {
    statuses.push({ label: `Queue ${queueIndex + 1}`, tone: "muted" });
  }

  if (rankedInfo && rankedInfo.index < context.plan.qualifiedCount && context.qualifyingPhase === "complete") {
    statuses.push({ label: `Qualified #${rankedInfo.seed}`, tone: "ready" });
  } else if (context.tournamentDriverIds.has(driver.id)) {
    statuses.push({ label: "Bracket Live", tone: "ready" });
  }

  if (driver.selfRegisteredAt && driver.approvedToRosterAt) {
    statuses.push({ label: "Checked In", tone: "muted" });
  } else if (!statuses.length && context.qualifyingPhase === "waiting") {
    statuses.push({ label: "Registered", tone: "muted" });
  }

  if (!statuses.length) {
    statuses.push({ label: "In Event", tone: "muted" });
  }

  return statuses.slice(0, 3);
}

function renderStatusChips(statuses = []) {
  if (!statuses.length) return "";
  return `<div class="driver-status-row">${statuses.map((status) => `<span class="driver-status-chip ${status.tone || "muted"}">${escapeHtml(status.label)}</span>`).join("")}</div>`;
}

function renderDriverStatusChips(driver, context = buildDriverStatusContext()) {
  return renderStatusChips(getDriverStatusBadges(driver, context));
}

function renderPendingStatusChips(entry) {
  const statuses = [];
  if (isPendingRegistrationRejected(entry)) {
    statuses.push({ label: "Rejected", tone: "error" });
  } else if (isPendingRegistrationNeedsReview(entry)) {
    statuses.push({ label: "Duplicate / Needs Review", tone: "warning" });
  } else if (entry.checkedInAt) {
    statuses.push({ label: "Arrived", tone: "ready" });
    statuses.push({ label: needsPendingRegistrationApproval(entry) ? "Pending Approval" : "Checked In", tone: needsPendingRegistrationApproval(entry) ? "warning" : "ready" });
  } else {
    statuses.push({ label: "Pre-Registered", tone: "muted" });
    statuses.push({ label: "Venue Check-In Needed", tone: "warning" });
  }
  if (entry.paidAt) {
    statuses.push({ label: "Paid", tone: "ready" });
  } else {
    statuses.push({ label: "Pending Payment", tone: "warning" });
  }
  return renderStatusChips(statuses);
}

function getVenueCheckInCounts(eventMeta = activeEventMeta) {
  const pendingEntries = getPendingRegistrations(eventMeta);
  return {
    preregistered: pendingEntries.filter((entry) => !entry.checkedInAt && !isPendingRegistrationRejected(entry) && !isPendingRegistrationNeedsReview(entry)).length,
    arrived: pendingEntries.filter((entry) => Boolean(entry.arrivedAt || entry.checkedInAt) && !isPendingRegistrationRejected(entry)).length,
    needsReview: pendingEntries.filter((entry) => isPendingRegistrationNeedsReview(entry)).length,
    rejected: pendingEntries.filter((entry) => isPendingRegistrationRejected(entry)).length,
  };
}

function renderJudgeProgressChips(eventMeta = activeEventMeta, options = {}) {
  const activeRoles = getActiveJudgeRoles(eventMeta);
  if (!activeRoles.length) {
    return renderStatusChips([{ label: "No Active Judges", tone: "warning" }]);
  }
  const mode = options.mode || "qualifying";
  const control = mode === "competition" ? getCompetitionJudgeControl() : null;
  const resolution = control ? getCompetitionDecisionResolution(control, eventMeta) : null;
  return renderStatusChips(activeRoles.map((role) => {
    let ready = Boolean(qualifyingFlow?.readyRoles?.[role]);
    let label = getRoleDisplayName(role);
    if (mode === "competition" && resolution) {
      if (resolution.mode === "scorecard") {
        const currentSide = resolution.currentSide || "done";
        ready = currentSide === "done"
          ? true
          : hasCompetitionScoreValue(control?.scorecards?.[role]?.[currentSide]);
        label = `${label} ${currentSide === "right" ? "Team 2" : currentSide === "left" ? "Team 1" : "Done"}`;
      } else {
        ready = ["left", "right", "omt"].includes(control?.votes?.[role]);
        label = `${label} ${ready ? "Voted" : "Open"}`;
      }
    } else {
      label = `${label} ${ready ? "Ready" : "Waiting"}`;
    }
    return { label, tone: ready ? "ready" : "warning" };
  }));
}

function renderCommandCenter() {
  const hasLegacyCommandCenter = Boolean(eventCommandCenter && commandCenterGrid && commandCenterValidation);
  const adminSurfaces = adminCommandCenterSurfaces || [];
  if (!hasLegacyCommandCenter && !adminSurfaces.length) return;
  if (!activeEventMeta) {
    if (commandCenterGrid) commandCenterGrid.innerHTML = "";
    if (commandCenterValidation) commandCenterValidation.innerHTML = "";
    adminSurfaces.forEach((surface) => { surface.innerHTML = ""; });
    return;
  }
  const lifecycle = getEventLifecycleMeta();
  const validation = getBracketValidationState();
  const rankedDrivers = validation.rankedDrivers;
  const registeredDrivers = getRegisteredDrivers(appDrivers);
  const teamTandemMode = isTeamTandemMode(activeEventMeta);
  const twinTripleMode = isTwinTripleMode(activeEventMeta);
  const teamEntries = teamTandemMode ? getTeamTandemRosterEntries(appDrivers) : [];
  const twinState = twinTripleMode ? getTwinCompState() : null;
  const twinRound = twinTripleMode ? getTwinCompCurrentRound(twinState) : null;
  const currentDriver = getCurrentQualifyingDriver();
  const queue = getQualifyingDriverQueue();
  const currentIndex = currentDriver ? queue.findIndex((entry) => entry.id === currentDriver.id) : -1;
  const nextDriver = currentIndex > -1 ? queue[currentIndex + 1] || null : null;
  const competitionFlow = getCompetitionFlowEntriesForState(tournamentState);
  const currentBattle = competitionFlow.currentEntry || null;
  const nextBattle = competitionFlow.nextEntry || null;
  const activeJudgeRoles = getActiveJudgeRoles(activeEventMeta);
  const judgesReady = activeJudgeRoles.filter((role) => qualifyingFlow?.readyRoles?.[role]).length;
  const results = activeEventMeta?.results || {};
  const bracketPublished = Boolean(tournamentState?.mainBracket?.rounds?.length);
  const twinLive = twinTripleMode && twinState?.status !== "setup";
  const venueConfig = getVenueConfig();
  const checkInCounts = getVenueCheckInCounts(activeEventMeta);
  const healthItems = [
    { label: isOfflineMode() ? "Offline" : "Sync Online", tone: isOfflineMode() ? "warning" : "ready" },
    { label: activeJudgeRoles.length ? `${judgesReady}/${activeJudgeRoles.length} Judges` : "No Judges", tone: !activeJudgeRoles.length ? "warning" : judgesReady === activeJudgeRoles.length ? "ready" : "warning" },
    { label: venueConfig.qrCheckInEnabled ? "QR Live" : "QR Off", tone: venueConfig.qrCheckInEnabled ? "ready" : "muted" },
    { label: `${checkInCounts.needsReview} Review`, tone: checkInCounts.needsReview ? "warning" : "ready" },
    { label: validation.issues.length ? `${validation.issues.length} Setup Issue${validation.issues.length === 1 ? "" : "s"}` : "Setup Clear", tone: validation.issues.length ? "error" : "ready" },
  ];
  const setupChecklistItems = [
    { label: activeEventMeta?.name ? "Event Named" : "Name Event", tone: activeEventMeta?.name ? "ready" : "warning" },
    { label: activeJudgeRoles.length ? `${activeJudgeRoles.length} Judges` : "Add Judges", tone: activeJudgeRoles.length ? "ready" : "warning" },
    { label: venueConfig.qrCheckInEnabled ? "QR Ready" : "QR Optional", tone: venueConfig.qrCheckInEnabled ? "ready" : "muted" },
    { label: teamTandemMode ? (teamEntries.length >= 2 ? "Teams Ready" : "Need Teams") : twinTripleMode ? (getRegisteredDrivers(appDrivers).length >= 2 ? "Teams Ready" : "Need Teams") : (registeredDrivers.length >= 2 ? "Drivers Ready" : "Need Drivers"), tone: (teamTandemMode ? teamEntries.length >= 2 : getRegisteredDrivers(appDrivers).length >= 2) ? "ready" : "warning" },
    { label: bracketPublished || twinLive ? "Competition Live" : validation.buildReady ? "Build Ready" : "Setup Pending", tone: bracketPublished || twinLive || validation.buildReady ? "ready" : "warning" },
  ];
  const judgeClaims = getJudgeRoleClaims(activeEventMeta);
  const claimedJudgeCount = activeJudgeRoles.filter((role) => judgeClaims?.[role]?.status === "claimed").length;
  const judgeControl = getCompetitionJudgeControl();
  const decisionResolution = judgeControl ? getCompetitionDecisionResolution(judgeControl, activeEventMeta) : null;
  const submittedDecisionCount = activeJudgeRoles.filter((role) => {
    if (!decisionResolution) return false;
    if (decisionResolution.mode === "scorecard") {
      const side = decisionResolution.currentSide || "done";
      return side === "done" || hasCompetitionScoreValue(judgeControl?.scorecards?.[role]?.[side]);
    }
    return ["left", "right", "omt"].includes(judgeControl?.votes?.[role]);
  }).length;
  const currentBattleTitle = currentBattle
    ? buildPublicEventBattleTitle(currentBattle)
    : currentDriver?.name || "Waiting";
  const nextBattleTitle = nextBattle
    ? buildPublicEventBattleTitle(nextBattle)
    : nextDriver?.name || "No battle queued";
  const syncTone = isOfflineMode() ? "warning" : "ready";
  const syncLabel = isOfflineMode() ? "Offline Mode" : "Live Sync";
  const competitionModeLabel = twinTripleMode
    ? getTwinCompEliminationLabel()
    : isTech1AnniversaryMode() ? "Tech 1 Drift Anniversary"
    : teamTandemMode ? "Team Tandem" : "Solo Drivers";
  let recommendedAction = {
    label: "Review Event Setup",
    detail: "Confirm roster, judges, check-in, and format before the first run.",
    action: "registration",
    actionLabel: "Open Setup",
  };
  if (validation.issues.length) {
    recommendedAction = {
      label: "Fix Setup Issue",
      detail: validation.issues[0],
      action: "registration",
      actionLabel: "Review Setup",
    };
  } else if (checkInCounts.needsReview) {
    recommendedAction = {
      label: "Review Check-Ins",
      detail: `${checkInCounts.needsReview} check-in entr${checkInCounts.needsReview === 1 ? "y needs" : "ies need"} admin review.`,
      action: "registration",
      actionLabel: "Open Check-In",
    };
  } else if (bracketPublished && judgeControl?.status === "admin_decision") {
    recommendedAction = {
      label: "Contest Decision Pending",
      detail: "Resolve the contest call before advancing the event.",
      action: "bracket",
      actionLabel: "Open Bracket",
    };
  } else if (bracketPublished && currentBattle) {
    recommendedAction = {
      label: "Monitor Current Battle",
      detail: `${currentBattleTitle || "Current battle"} is live. Watch judge submissions and contest timer.`,
      action: "bracket",
      actionLabel: "Control Battle",
    };
  } else if (twinTripleMode && twinState?.status === "complete") {
    recommendedAction = {
      label: "Complete Event",
      detail: "Twin Comp winner is locked. Save this event to results when presentation is complete.",
      action: "finalize",
      actionLabel: "Mark Complete",
    };
  } else if (!bracketPublished && validation.buildReady) {
    recommendedAction = {
      label: teamTandemMode ? "Launch Team Bracket" : "Build Bracket",
      detail: validation.plan?.description || "Qualifying and roster are ready for competition.",
      action: "bracket",
      actionLabel: teamTandemMode ? "Launch Bracket" : "Build Bracket",
    };
  } else if (getQualifyingFlowPhase(qualifyingFlow, appDrivers) === "live") {
    recommendedAction = {
      label: "Continue Qualifying",
      detail: currentDriver?.name ? `${currentDriver.name} is up now. ${nextDriver?.name ? `${nextDriver.name} is on deck.` : "No on-deck driver yet."}` : "Judges are scoring the qualifying order.",
      action: "qualifying",
      actionLabel: "Open Qualifying",
    };
  }

  if (commandCenterPhase) {
    commandCenterPhase.textContent = lifecycle.label;
    commandCenterPhase.className = `status-pill ${lifecycle.tone}`;
  }

  if (commandCenterGrid) {
  commandCenterGrid.innerHTML = `
    <article class="command-center-card">
      <span>Current Phase</span>
      <strong>${escapeHtml(lifecycle.label)}</strong>
      <small>${escapeHtml(lifecycle.detail)}</small>
    </article>
    <article class="command-center-card">
      <span>Roster</span>
      <strong>${teamTandemMode ? `${teamEntries.length} Teams` : twinTripleMode ? `${getRegisteredDrivers(appDrivers).length} Teams` : `${getRegisteredDrivers(appDrivers).length} Drivers`}</strong>
      <small>${teamTandemMode ? `${getRegisteredDrivers(appDrivers).length} total registered drivers are grouped into team entries.` : twinTripleMode ? `${getTwinCompActiveTeams(twinState).length} active, ${twinState.teams.filter((team) => !team.active).length} eliminated.` : `${getPendingRegistrations().length} pending check-ins waiting at the desk.`}</small>
    </article>
    <article class="command-center-card">
      <span>${teamTandemMode ? "Current Battle" : twinTripleMode ? "Current Team" : "Current Driver"}</span>
      <strong>${escapeHtml(teamTandemMode ? (currentBattle?.match?.left?.name && currentBattle?.match?.right?.name ? `${currentBattle.match.left.name} vs ${currentBattle.match.right.name}` : "Waiting") : twinTripleMode ? (currentDriver?.teamName || currentDriver?.name || "Waiting") : (currentDriver?.name || "Waiting"))}</strong>
      <small>${teamTandemMode ? (bracketPublished ? "Judges score line, angle, and proximity for the live team battle." : "Launch the randomized team bracket straight from registration.") : twinTripleMode ? (twinRound ? `Round ${twinRound.number}: ${twinRound.teamIds.filter((teamId) => getTwinCompTeamRoundScore(teamId, twinRound)).length}/${twinRound.teamIds.length} scores locked.` : `Start the first ${getTwinCompEliminationAdjective()} round from Competition.`) : (nextDriver?.name ? `On deck: ${nextDriver.name}` : "No next driver locked yet.")}</small>
    </article>
    <article class="command-center-card">
      <span>Judges Ready</span>
      <strong>${judgesReady}/${activeJudgeRoles.length || 0}</strong>
      ${renderJudgeProgressChips(activeEventMeta, { mode: bracketPublished ? "competition" : "qualifying" })}
      <small>${activeJudgeRoles.length ? (teamTandemMode ? "Team Tandem judges lock in one category each: Line, Angle, and Proximity." : "Ready states clear automatically when the driver advances.") : "No active judges on this event."}</small>
    </article>
    <article class="command-center-card">
      <span>Bracket Automation</span>
      <strong>${twinTripleMode ? (twinState.status === "complete" ? "Winner Declared" : twinLive ? "Twin Comp Live" : validation.buildReady ? "Ready To Start" : "Waiting") : bracketPublished ? "Published" : validation.buildReady ? (teamTandemMode ? "Ready To Launch" : "Ready To Auto-Build") : "Waiting"}</strong>
      <small>${twinTripleMode ? `${getTwinCompEliminationLabel()} is separate from the bracket. Use Competition to run rounds and standings.` : bracketPublished ? (tournamentState?.plan?.description || "Bracket is live.") : validation.plan?.description || (teamTandemMode ? "Waiting for teams." : "Waiting for qualifying scores.")}</small>
    </article>
    <article class="command-center-card">
      <span>Post-Event Summary</span>
      <strong>${escapeHtml(results.championName ? `#${results.championSeed || "-"} ${results.championName}` : "Open")}</strong>
      <small>${escapeHtml(twinTripleMode ? "Winner saves automatically when only one active team remains." : teamTandemMode ? "Champion, runner-up, and podium teams save automatically when finals are complete." : (results.topQualifierName ? `Top qualifier #${results.topQualifierSeed || "-"} ${results.topQualifierName} | Avg field ${formatScore(results.averageBestScore)}` : "Champion, top qualifier, and average field score will save here automatically."))}</small>
    </article>
    <article class="command-center-card">
      <span>Event Health</span>
      <strong>${validation.issues.length || checkInCounts.needsReview || isOfflineMode() ? "Needs Attention" : "Ready"}</strong>
      ${renderStatusChips(healthItems)}
      <small>${venueConfig.qrCheckInEnabled ? `${checkInCounts.preregistered} pre-registered, ${checkInCounts.arrived} arrived, ${checkInCounts.needsReview} need review.` : "QR check-in is currently off for this event."}</small>
    </article>
    <article class="command-center-card">
      <span>Setup Checklist</span>
      <strong>${setupChecklistItems.every((item) => item.tone === "ready" || item.tone === "muted") ? "Ready To Run" : "Review Setup"}</strong>
      ${renderStatusChips(setupChecklistItems)}
      <small>Fast event-day scan for staff: event identity, judges, check-in, roster, and competition readiness.</small>
    </article>
  `;
  }

  const noteMarkup = [
    ...validation.issues.map((item) => `<div class="command-center-note issue">${escapeHtml(item)}</div>`),
    ...validation.warnings.map((item) => `<div class="command-center-note warning">${escapeHtml(item)}</div>`),
  ];
  if (commandCenterValidation) {
  commandCenterValidation.innerHTML = noteMarkup.length
    ? noteMarkup.join("")
    : `<div class="command-center-note">Command center is clear. ${teamTandemMode ? (teamEntries.length ? `${teamEntries.length} team${teamEntries.length === 1 ? "" : "s"} are ready for the randomized bracket.` : "Register teams to begin.") : twinTripleMode ? (getRegisteredDrivers(appDrivers).length ? `${getRegisteredDrivers(appDrivers).length} team${getRegisteredDrivers(appDrivers).length === 1 ? "" : "s"} ready for ${getTwinCompEliminationAdjective()}.` : "Add teams to begin.") : (rankedDrivers.length ? `${rankedDrivers.length} scored driver${rankedDrivers.length === 1 ? "" : "s"} are tracked for this event.` : "Add drivers or scores to begin.")}</div>`;
  }

  const controlCenterMarkup = `
    <div class="admin-control-center-shell">
      <header class="admin-control-center-header">
        <div>
          <p class="section-kicker">Event Control Center</p>
          <h2>${escapeHtml(activeEventMeta.name || "Live Event")}</h2>
          <small>${escapeHtml(competitionModeLabel)} | ${escapeHtml(lifecycle.label)} | ${escapeHtml(lifecycle.detail)}</small>
        </div>
        <div class="admin-control-center-status">
          ${renderStatusChips([
            { label: syncLabel, tone: syncTone },
            { label: `${claimedJudgeCount}/${activeJudgeRoles.length || 0} Connected`, tone: activeJudgeRoles.length && claimedJudgeCount === activeJudgeRoles.length ? "ready" : "warning" },
            { label: `${submittedDecisionCount}/${activeJudgeRoles.length || 0} Submitted`, tone: bracketPublished && activeJudgeRoles.length && submittedDecisionCount === activeJudgeRoles.length ? "ready" : bracketPublished ? "warning" : "muted" },
            { label: venueConfig.qrCheckInEnabled ? "QR Check-In On" : "QR Check-In Off", tone: venueConfig.qrCheckInEnabled ? "ready" : "muted" },
          ])}
        </div>
      </header>
      <div class="admin-control-center-focus">
        <article class="admin-control-focus-card is-primary">
          <span>Recommended Next Action</span>
          <strong>${escapeHtml(recommendedAction.label)}</strong>
          <small>${escapeHtml(recommendedAction.detail)}</small>
          <button class="micro-button button-accent" type="button" data-admin-command-action="${escapeAttributeValue(recommendedAction.action)}">${escapeHtml(recommendedAction.actionLabel)}</button>
        </article>
        <article class="admin-control-focus-card">
          <span>Current Battle</span>
          <strong>${escapeHtml(currentBattleTitle || "Waiting")}</strong>
          <small>${escapeHtml(currentBattle?.meta || currentBattle?.label || currentDriver?.teamName || "No active battle is locked yet.")}</small>
        </article>
        <article class="admin-control-focus-card">
          <span>Up Next</span>
          <strong>${escapeHtml(nextBattleTitle || "No battle queued")}</strong>
          <small>${escapeHtml(nextBattle?.meta || nextBattle?.label || nextDriver?.teamName || "Queue updates when qualifying or bracket advances.")}</small>
        </article>
        <article class="admin-control-focus-card">
          <span>Check-In Desk</span>
          <strong>${checkInCounts.arrived}/${Math.max(checkInCounts.preregistered + checkInCounts.arrived + checkInCounts.needsReview, registeredDrivers.length)}</strong>
          <small>${checkInCounts.needsReview ? `${checkInCounts.needsReview} need review before roster approval.` : "No check-in issues flagged."}</small>
        </article>
      </div>
      <div class="admin-control-center-grid">
        <article class="command-center-card">
          <span>Judges</span>
          <strong>${claimedJudgeCount}/${activeJudgeRoles.length || 0} Connected</strong>
          ${renderJudgeProgressChips(activeEventMeta, { mode: bracketPublished ? "competition" : "qualifying" })}
          <small>${bracketPublished ? "Decision submission status reflects the current battle control." : "Qualifying ready states clear as the run advances."}</small>
        </article>
        <article class="command-center-card">
          <span>Live Sync</span>
          <strong>${escapeHtml(syncLabel)}</strong>
          ${renderStatusChips(healthItems)}
          <small>${escapeHtml(isOfflineMode() ? "This device is using protected local mode. Reconnect before event-critical changes." : "Firebase/live event sync appears available from this device.")}</small>
        </article>
        <article class="command-center-card">
          <span>Setup Safety</span>
          <strong>${setupChecklistItems.every((item) => item.tone === "ready" || item.tone === "muted") ? "Ready" : "Review"}</strong>
          ${renderStatusChips(setupChecklistItems)}
          <small>Controls stay visible, while risky actions still require existing confirmations.</small>
        </article>
        <article class="command-center-card">
          <span>Quick Actions</span>
          <div class="admin-control-quick-actions">
            <button class="micro-button" type="button" data-admin-command-action="registration">Registration</button>
            <button class="micro-button" type="button" data-admin-command-action="qualifying">Qualifying</button>
            <button class="micro-button" type="button" data-admin-command-action="bracket">Bracket</button>
            <button class="micro-button" type="button" data-admin-command-action="website-admin">Website Admin</button>
          </div>
          <small>Jump to the live control surface without digging through navigation.</small>
        </article>
      </div>
      <div class="admin-control-center-validation">
        ${noteMarkup.length ? noteMarkup.join("") : `<div class="command-center-note">Control center clear. Keep judging devices connected and continue the live event flow.</div>`}
      </div>
    </div>
  `;

  adminSurfaces.forEach((surface) => {
    surface.innerHTML = controlCenterMarkup;
  });

  if (commandCenterQualifyingBtn) commandCenterQualifyingBtn.disabled = currentRole !== "admin";
  if (commandCenterBracketBtn) {
    commandCenterBracketBtn.textContent = twinTripleMode ? "Open Twin Comp" : bracketPublished ? "Open Competition" : (teamTandemMode ? "Launch Team Bracket" : "Build Competition");
    commandCenterBracketBtn.disabled = currentRole !== "admin" || (!bracketPublished && validation.issues.length > 0);
  }
  if (commandCenterFinalizeBtn) {
    const hasBracket = Boolean(tournamentState?.mainBracket?.rounds?.length);
    const eventStatus = getEventStatus(activeEventMeta);
    const bracketReadyToFinalize = isBracketReadyToFinalize();
    const twinReadyToFinalize = twinTripleMode && twinState?.status === "complete";
    commandCenterFinalizeBtn.textContent = eventStatus === EVENT_STATUS_COMPLETED
      ? "Event Completed"
      : twinReadyToFinalize || bracketReadyToFinalize
        ? "Mark Event Complete"
        : twinTripleMode ? "Finish Twin Comp To Complete Event" : "Finish Bracket To Complete Event";
    commandCenterFinalizeBtn.disabled = currentRole !== "admin"
      || (!hasBracket && !twinTripleMode)
      || eventStatus !== EVENT_STATUS_ACTIVE
      || !(bracketReadyToFinalize || twinReadyToFinalize);
  }
}

async function finalizeCurrentEventResults(options = {}) {
  const {
    confirmCompletion = true,
    silent = false,
    switchToResults = true,
  } = options;
  if (currentRole !== "admin") return;
  if (!activeEventId || !activeEventMeta) {
    if (!silent) window.alert("Open an event before finalizing results.");
    return false;
  }
  if (isTwinTripleMode(activeEventMeta)) {
    const state = getTwinCompState();
    if (state.status !== "complete" || !state.winnerName) {
      if (!silent) window.alert("Finish Twin Comp until one team remains before marking the event complete.");
      return false;
    }
  } else if (!tournamentState?.mainBracket?.rounds?.length) {
    if (!silent) window.alert("Build the competition bracket before finalizing results.");
    return false;
  }
  if (!isTwinTripleMode(activeEventMeta) && !isBracketReadyToFinalize()) {
    if (!silent) window.alert("Finish every battle in the published bracket before marking the event complete.");
    return false;
  }
  if (getEventStatus(activeEventMeta) !== EVENT_STATUS_ACTIVE) {
    if (!silent) window.alert("This event is already locked.");
    return getEventStatus(activeEventMeta) === EVENT_STATUS_COMPLETED;
  }

  if (confirmCompletion) {
    const confirmed = window.confirm(isTwinTripleMode(activeEventMeta)
      ? `Mark this Twin Comp complete and lock the current ${getTwinCompEliminationAdjective()} results?`
      : "Mark this event complete and lock the current bracket and qualifying results?");
    if (!confirmed) return false;
  }

  setActiveEventMetaState({
    ...activeEventMeta,
    status: EVENT_STATUS_COMPLETED,
    results: {
      ...buildEventResults(),
      completedAt: activeEventMeta?.results?.completedAt || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    },
  }, { syncQualifying: false });
  eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
  const archivedRecord = buildArchivedResultsRecord(activeEventMeta, activeEventMeta.results);
  if (archivedRecord) {
    archivedResultsDirectory[activeEventId] = archivedRecord;
  }
  saveDirectoryCache();
  saveEventStateCache();
  saveArchivedResultsCache();
  await publishStateImmediately();
  try {
    await persistArchivedResultsDirectory();
  } catch (error) {
    if (!silent) window.alert("The event was finalized locally, but the past-events archive could not sync to the cloud yet. Keep this page open and retry once your connection is stable.");
    return false;
  }
  renderEventDirectory();
  renderRoleAdminPanel();
  renderDriversTable();
  if (document.getElementById('view-bracket').classList.contains('is-active')) {
    renderBracket();
  }
  if (switchToResults) switchView("results");
  if (!silent) window.alert("Current event results were finalized and saved to the Results tab.");
  return true;
}

