function renderLandingView() {
  if (!landingUpcomingEvent || !landingLiveSnapshot || !landingFeaturedDrivers || !landingLatestPodium || !landingWhyFeatures || !landingQuickLinks) return;

  const registeredDriversForPublicHome = getRegisteredDrivers(appDrivers);
  const archivedResultsForPublicHome = sortArchivedResultsForDisplay();
  const currentEventResultsForPublicHome = activeEventMeta
    ? {
        ...(activeEventMeta.results || buildEmptyEventResults()),
        ...buildEventResults(),
      }
    : buildEmptyEventResults();
  const lifecycleForPublicHome = getEventLifecycleMeta();
  const latestArchiveForPublicHome = archivedResultsForPublicHome[0] || null;
  const activePublicEvent = activeEventMeta && getEventStatus(activeEventMeta) === EVENT_STATUS_ACTIVE ? activeEventMeta : null;
  const currentPublicDriver = getCurrentQualifyingDriver();
  const publicCompetitionFlow = getCompetitionFlowEntriesForState(tournamentState);
  const currentPublicBattle = publicCompetitionFlow.currentEntry || null;
  const publicCloseReason = getSelfRegistrationCloseReason();
  const publicRegistrationStatus = !activePublicEvent
    ? "No active event"
    : publicCloseReason
      ? "Registration is closed."
      : hasValidVenueConfig()
        ? "Pre-registration is open. Venue check-in opens on event day."
        : "Self-registration is disabled by event staff.";
  const publicLiveStatus = currentPublicBattle?.match?.left && currentPublicBattle?.match?.right
    ? "Bracket battle live"
    : currentPublicDriver?.name
      ? "Qualifying live"
      : nativeStreamLatestState?.active
        ? "Stream live"
        : lifecycleForPublicHome.label || "Waiting";
  const hasPublicResults = Boolean(currentEventResultsForPublicHome.championName || latestArchiveForPublicHome);
  const hasPublicBracket = Boolean(tournamentState?.mainBracket?.rounds?.length || tournamentState?.lowerBracket?.rounds?.length);
  const publicEventDate = activePublicEvent?.date ? formatEventDate(activePublicEvent.date) : "Date coming soon";
  const currentBattleTitle = currentPublicBattle?.match?.left?.name && currentPublicBattle?.match?.right?.name
    ? `${currentPublicBattle.match.left.name} vs ${currentPublicBattle.match.right.name}`
    : "";
  const latestArchiveDate = latestArchiveForPublicHome
    ? formatEventDate(latestArchiveForPublicHome.results?.completedAt?.slice?.(0, 10) || latestArchiveForPublicHome.date)
    : "";
  const homeView = renderPublicHomeView({
    activePublicEvent,
    lifecycleDetail: lifecycleForPublicHome.detail,
    publicEventDate,
    publicRegistrationStatus,
    publicLiveStatus,
    hasPublicResults,
    currentBattleTitle,
    currentDriverName: currentPublicDriver?.name || "",
    hasPublicBracket,
    registeredDriverCount: registeredDriversForPublicHome.length,
    latestArchive: latestArchiveForPublicHome,
    formattedArchiveDate: latestArchiveDate,
  });

  if (landingHeroEyebrow) landingHeroEyebrow.textContent = homeView.copy.eyebrow;
  if (landingHeroTitle) landingHeroTitle.textContent = homeView.copy.title;
  if (landingHeroCopy) {
    landingHeroCopy.textContent = homeView.copy.heroCopy;
  }
  if (landingWhySectionCopy) {
    landingWhySectionCopy.textContent = homeView.copy.whyCopy;
  }

  landingUpcomingEvent.innerHTML = homeView.upcomingEventHtml;
  landingWhyFeatures.innerHTML = homeView.featuresHtml;
  landingLiveSnapshot.innerHTML = homeView.liveSnapshotHtml;
  landingFeaturedDrivers.innerHTML = homeView.featuredDriversHtml;
  landingLatestPodium.innerHTML = homeView.latestPodiumHtml;
  landingQuickLinks.innerHTML = homeView.quickLinksHtml;

}

