function getTestModeUrl(scenario = "qualifying") {
  const targetUrl = new URL(window.location.href);
  targetUrl.searchParams.set("testMode", "1");
  targetUrl.searchParams.set("seedTest", normalizeTestScenario(scenario));
  targetUrl.hash = buildRoleRouteHash("admin", "registration");
  try {
    localStorage.setItem(TEST_MODE_STORAGE_KEY, "1");
    localStorage.setItem(TEST_MODE_PENDING_SCENARIO_KEY, normalizeTestScenario(scenario));
  } catch (error) {}
  return targetUrl.toString();
}

function buildDemoTeamDrivers(count = 8) {
  return buildTestSampleDrivers(false).slice(0, count).map((driver, index) => {
    const memberCount = index % 3 === 0 ? 3 : 2;
    const sourceOffset = index * 3;
    const memberNames = Array.from({ length: memberCount }, (_, memberIndex) => {
      const source = TEST_SAMPLE_DRIVER_ENTRIES[(sourceOffset + memberIndex) % TEST_SAMPLE_DRIVER_ENTRIES.length];
      return source?.[0] || `Demo Driver ${index + 1}-${memberIndex + 1}`;
    });
    const teamName = TEST_SAMPLE_DRIVER_ENTRIES[index]?.[1] || `Demo Team ${index + 1}`;
    driver.name = teamName;
    driver.teamName = memberNames.join(", ");
    driver.chassis = `${memberCount} driver twin team`;
    driver.memberCount = memberCount;
    driver.teamMemberCount = memberCount;
    driver.tandemMembers = memberNames;
    driver.tandemType = "team";
    driver.tandemBonusPoints = memberCount >= TEAM_TANDEM_MAX_DRIVERS ? TEAM_TANDEM_THREE_DRIVER_BONUS : 0;
    return driver;
  });
}

