function buildDemoBracketState(drivers) {
  const state = createTournamentState(rankDrivers(drivers), FORMAT_CLASSIC, 0);
  const firstRound = state?.mainBracket?.rounds?.[0]?.matches || [];
  firstRound.slice(0, 2).forEach((match, index) => {
    const side = index % 2 === 0 ? "left" : "right";
    if (match?.[side]) {
      match.winner = cloneDriver(match[side]);
      match.winnerMode = "manual";
    }
  });
  normalizeBracketState(state);
  resetCompetitionJudgeControlToCurrentEntry(state);
  return state;
}

function buildDemoTwinCompState(drivers) {
  const teams = drivers.map((driver, index) => normalizeTwinCompTeam({
    id: driver.id,
    seed: index + 1,
    name: driver.teamName || driver.name || `Team ${index + 1}`,
    eliminationPoints: index < 2 ? 1 : 0,
    active: true,
    roundScores: index < 4 ? [{ round: 1, run1: 82 + index, run2: 84 + index, score: 84 + index, scoredAt: new Date().toISOString() }] : [],
  }, index));
  const round = {
    id: `demo-twin-round-${Date.now()}`,
    number: 2,
    status: "live",
    teamIds: teams.map((team) => team.id),
    currentTeamId: teams[0]?.id || null,
    scores: {},
    pointAssignments: [],
    tieReviewRequired: false,
    finalizedAt: null,
  };
  return {
    ...createEmptyTwinCompState(),
    status: "live",
    roundNumber: 2,
    currentRoundId: round.id,
    teams,
    rounds: [
      {
        id: "demo-twin-round-1",
        number: 1,
        status: "finalized",
        teamIds: teams.map((team) => team.id),
        currentTeamId: null,
        scores: Object.fromEntries(teams.slice(0, 4).map((team, index) => [team.id, { teamId: team.id, run1: 82 + index, run2: 84 + index, score: 84 + index, scoredAt: new Date().toISOString() }])),
        pointAssignments: teams.slice(0, 3).map((team) => team.id),
        tieReviewRequired: false,
        finalizedAt: new Date().toISOString(),
      },
      round,
    ],
  };
}

async function buildTestDemoScenario(scenario = "qualifying") {
  const normalizedScenario = normalizeTestScenario(scenario);
  const now = Date.now();
  const completedDrivers = buildTestSampleDrivers(true).slice(0, 8);
  const completedMeta = await buildDemoEventMeta({
    id: "demo-completed-reference",
    name: "DEMO Completed Reference Event",
    status: EVENT_STATUS_COMPLETED,
    results: buildDemoCompletedResults(completedDrivers),
  });

  if (normalizedScenario === "bracket") {
    const drivers = buildTestSampleDrivers(true).slice(0, 16);
    const bracket = buildDemoBracketState(drivers);
    const meta = await buildDemoEventMeta({
      id: `demo-bracket-${now}`,
      name: "DEMO Bracket Battle Test",
      results: {
        ...buildEmptyEventResults(),
        qualifiedCount: drivers.length,
        totalDrivers: drivers.length,
        planDescription: "Demo bracket with qualifying complete, a few battles advanced, and the next battle ready for judge/admin QA.",
      },
    });
    return {
      activeEventId: meta.id,
      directory: { [meta.id]: meta, [completedMeta.id]: completedMeta },
      archived: { [completedMeta.id]: buildArchivedResultsRecord(completedMeta, completedMeta.results) },
      state: {
        id: meta.id,
        meta,
        drivers,
        bracket,
        twinComp: null,
        qualifyingFlow: { currentDriverId: null, readyRoles: {}, started: true, completed: true },
        formatMode: FORMAT_CLASSIC,
        lowerCount: "0",
      },
      view: "bracket",
    };
  }

  if (normalizedScenario === "twin" || normalizedScenario === "twin-double") {
    const twinDoubleDemo = normalizedScenario === "twin-double";
    const drivers = buildDemoTeamDrivers(8);
    const twinComp = buildDemoTwinCompState(drivers);
    const meta = await buildDemoEventMeta({
      id: `${twinDoubleDemo ? "demo-twin-double" : "demo-twin"}-${now}`,
      name: twinDoubleDemo ? "DEMO Twin Comp Double Elimination" : "DEMO Twin Comp Triple Elimination",
      competitionMode: twinDoubleDemo ? COMPETITION_MODE_TWIN_DOUBLE : COMPETITION_MODE_TWIN_TRIPLE,
      judgeCount: 3,
      results: {
        ...buildEmptyEventResults(),
        qualifiedCount: drivers.length,
        totalDrivers: drivers.length,
        planDescription: `Demo Twin Comp ${twinDoubleDemo ? "double" : "triple"}-elimination event with Round 2 live and sample elimination points already applied.`,
      },
    });
    return {
      activeEventId: meta.id,
      directory: { [meta.id]: meta, [completedMeta.id]: completedMeta },
      archived: { [completedMeta.id]: buildArchivedResultsRecord(completedMeta, completedMeta.results) },
      state: {
        id: meta.id,
        meta,
        drivers,
        bracket: null,
        twinComp,
        qualifyingFlow: { currentDriverId: twinComp.rounds[1]?.currentTeamId || drivers[0]?.id || null, readyRoles: {}, started: true, completed: false },
        formatMode: FORMAT_CLASSIC,
        lowerCount: "0",
      },
      view: "bracket",
    };
  }

  const drivers = buildTestSampleDrivers(false).slice(0, 16);
  const waitingQualifying = normalizedScenario === "qualifying-waiting";
  const meta = await buildDemoEventMeta({
    id: `demo-qualifying-${now}`,
    name: waitingQualifying ? "DEMO Qualifying Order Test" : "DEMO Qualifying Judge Test",
    judgeCount: 3,
    results: {
      ...buildEmptyEventResults(),
      qualifiedCount: 0,
      totalDrivers: drivers.length,
      planDescription: "Demo qualifying event with 16 drivers and judge phones ready to submit Run 1 and Run 2.",
    },
  });
  return {
    activeEventId: meta.id,
    directory: { [meta.id]: meta, [completedMeta.id]: completedMeta },
    archived: { [completedMeta.id]: buildArchivedResultsRecord(completedMeta, completedMeta.results) },
    state: {
      id: meta.id,
      meta,
      drivers,
      bracket: null,
      twinComp: null,
      qualifyingFlow: waitingQualifying
        ? { currentDriverId: null, readyRoles: {}, started: false, completed: false }
        : { currentDriverId: drivers[0]?.id || null, readyRoles: {}, started: true, completed: false },
      formatMode: FORMAT_CLASSIC,
      lowerCount: "0",
    },
    view: "qualifying",
  };
}

async function seedTestDemoScenario(scenario = "qualifying") {
  const normalizedScenario = normalizeTestScenario(scenario);
  if (!TEST_MODE_ENABLED) {
    window.location.href = getTestModeUrl(normalizedScenario);
    return false;
  }
  const demo = await buildTestDemoScenario(normalizedScenario);
  activeEventId = demo.activeEventId;
  eventDirectory = demo.directory;
  archivedResultsDirectory = demo.archived;
  setDeletedEventId(demo.activeEventId, false);
  applyActiveEventState(demo.state, { syncQualifying: false });
  currentRole = "admin";
  setRoleUnlockedForEvent(activeEventId, "admin", true);
  saveDirectoryCache();
  saveArchivedResultsCache();
  saveEventStateCache();
  await publishStateImmediately();
  syncScheduledActiveEventSelection({ publishSelection: true });
  applyRoleChange("admin");
  switchView(demo.view);
  renderEventDirectory();
  renderRoleAdminPanel();
  renderDriversTable();
  syncTestModeUi();
  return true;
}

async function maybeRunPendingTestScenario() {
  if (!TEST_MODE_ENABLED || STANDALONE_DEMO_MODE) return false;
  let pendingScenario = null;
  try {
    pendingScenario = PAGE_SEARCH_PARAMS.get("seedTest") || localStorage.getItem(TEST_MODE_PENDING_SCENARIO_KEY);
    localStorage.removeItem(TEST_MODE_PENDING_SCENARIO_KEY);
  } catch (error) {}
  if (!pendingScenario) return false;
  await seedTestDemoScenario(pendingScenario);
  return true;
}

function renderPublicEventCameraPreview({
  lifecycle,
  results,
  registeredDrivers,
  rankedDrivers,
  currentDriver,
  currentBest,
  nextDriver,
  activeBattle,
  activeBattleTitle,
  queuedBattleTitle,
  battleStats,
}) {
  const feedLabel = activeBattleTitle
    ? "Trackside Battle Cam"
    : currentDriver?.name
      ? "Trackside Qualifying Cam"
      : results.championName
        ? "Victory Lap Cam"
        : "Trackside Live Cam";
  const feedTitle = activeBattleTitle
    || currentDriver?.name
    || (results.championName ? `${results.championName} Victory Lane` : lifecycle.label || "Awaiting Live Action");
  const feedCopy = activeBattleTitle
    ? `${activeBattle?.title || "Competition battle"} is on course with the next matchup already staged for the venue screen.`
    : currentDriver?.name
      ? `${currentDriver.name} is on track now with live scoring overlays framed right over the camera feed.`
      : results.championName
        ? `The podium is locked, so the stream can swing wide for interviews, replay loops, and the final winner shot.`
        : `This concept block shows how a fixed track camera could sit beside the live event data without crowding the queue page.`;
  const laneLeft = buildPublicEventSeedLabel(activeBattle?.match?.left);
  const laneRight = buildPublicEventSeedLabel(activeBattle?.match?.right);
  const topSeedLabel = results.topQualifierName
    ? `#${results.topQualifierSeed || "-"} ${results.topQualifierName}`
    : rankedDrivers[0]
      ? `#${rankedDrivers[0].seed} ${rankedDrivers[0].name}`
      : "Waiting";
  const queueLabel = nextDriver?.name || queuedBattleTitle || "Queue loading";
  const cameraSource = escapeAttributeValue(CLIENT_BRANDING.backgroundImage || "./assets/track-background.png");
  const venueLabel = activeEventMeta?.name || CLIENT_BRANDING.venueName || "Prodigy RC Drift Arena";

  return `
    <aside class="public-event-camera-panel">
      <div class="public-event-camera-head">
        <div>
          <p class="broadcast-kicker">Spectator Concept</p>
          <h3 class="public-event-stage-title">Live Camera Window</h3>
        </div>
        <strong>Feed A</strong>
      </div>
      <p class="public-event-camera-copy">${escapeHtml(feedCopy)}</p>
      <div class="public-event-camera-shell">
        <div
          class="public-event-camera-feed"
          style="background-image:
            linear-gradient(180deg, rgba(4, 8, 10, 0.10), rgba(4, 8, 10, 0.38)),
            linear-gradient(135deg, rgba(255,255,255,0.10), rgba(255,255,255,0) 34%),
            url('${cameraSource}');"
        >
          <div class="public-event-camera-feed-top">
            <span class="public-event-camera-badge live">Live Track Cam</span>
            <span class="public-event-camera-badge">${escapeHtml(formatPublicEventCameraTimestamp())} PT</span>
          </div>
          <div class="public-event-camera-title-block">
            <p class="public-event-camera-kicker">${escapeHtml(venueLabel)}</p>
            <h4 class="public-event-camera-title">${escapeHtml(feedTitle)}</h4>
            <p class="public-event-camera-subtitle">${escapeHtml(activeBattleTitle
              ? `${laneLeft} lead lane vs ${laneRight} chase lane`
              : currentDriver?.name
                ? `Best score ${formatScore(currentBest)} with ${nextDriver?.name || "the next driver"} staged immediately after`
                : results.championName
                  ? `Champion package and podium wrap-up ready for the spectator stream`
                  : `A clean camera-safe zone for sponsor bugs, battle labels, and live event overlays`)}</p>
          </div>
          <div class="public-event-camera-feed-bottom">
            <div class="public-event-camera-hud">
              <div class="public-event-camera-hud-item">
                <small>Now Live</small>
                <strong>${escapeHtml(activeBattleTitle || currentDriver?.name || lifecycle.label || "Waiting")}</strong>
              </div>
              <div class="public-event-camera-hud-item">
                <small>On Deck</small>
                <strong>${escapeHtml(queueLabel)}</strong>
              </div>
              <div class="public-event-camera-hud-item">
                <small>Top Seed</small>
                <strong>${escapeHtml(topSeedLabel)}</strong>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="public-event-camera-note">
        <p>The live feed can carry your camera angle, match title, seed callouts, and venue branding while the main panel keeps the structured event data readable.</p>
        <strong>${battleStats.totalBattles ? `${battleStats.completedBattles}/${battleStats.totalBattles} Battles` : `${registeredDrivers.length} Drivers`}</strong>
      </div>
    </aside>
  `;
}

function renderPublicEventQueueCard(entry, index) {
  if (!entry) return "";
  const battleTitle = buildPublicEventBattleTitle(entry);
  return `
    <article class="public-event-queue-card">
      <div class="public-event-queue-card-head">
        <span>Next ${index + 1}</span>
        <strong>${escapeHtml(entry.title || "Queued Battle")}</strong>
      </div>
      <h4 class="public-event-queue-card-title">${escapeHtml(battleTitle || "Waiting for battle")}</h4>
      <p class="public-event-queue-card-copy">${escapeHtml(entry.meta || "Waiting for bracket progress.")}</p>
      <div class="public-event-queue-card-pills">
        <div class="broadcast-match-pill tone-ready">
          <small>Lead</small>
          <strong>${escapeHtml(buildPublicEventSeedLabel(entry.match?.left))}</strong>
        </div>
        <div class="broadcast-match-pill tone-muted">
          <small>Chase</small>
          <strong>${escapeHtml(buildPublicEventSeedLabel(entry.match?.right))}</strong>
        </div>
      </div>
    </article>
  `;
}

function buildPublicEventBroadcastState({
  context,
  lifecycle,
  results,
  registerOpen,
  registeredDrivers,
  rankedDrivers,
  currentDriver,
  nextDriver,
  currentRun1,
  currentRun2,
  currentBest,
  lowerBattleEntries,
  mainBattleEntries,
  battleQueue,
  battleStats,
}) {
  const activeBattle = battleQueue[0] || null;
  const queuedBattleAfterCurrent = battleQueue[1] || null;
  const queuedBattles = activeBattle ? battleQueue.slice(1, 7) : battleQueue.slice(0, 6);
  const activeBattleTitle = buildPublicEventBattleTitle(activeBattle);
  const queuedBattleTitle = buildPublicEventBattleTitle(queuedBattleAfterCurrent);
  const mainRounds = tournamentState?.mainBracket?.rounds || [];
  const finalRoundIndex = mainRounds.length ? mainRounds.length - 1 : -1;
  const finalMatch = finalRoundIndex >= 0 ? mainRounds[finalRoundIndex]?.matches?.[0] || null : null;
  const thirdPlaceMatch = tournamentState?.mainBracket?.thirdPlaceMatch || null;
  const finalPending = mainBattleEntries.some((entry) => entry.bracketKey === "main" && entry.roundIndex === finalRoundIndex && entry.matchIndex === 0);
  const thirdPending = mainBattleEntries.some((entry) => entry.bracketKey === "third");
  const finalsReady = Boolean(mainRounds.length) && !lowerBattleEntries.length && (
    Boolean(results.championName)
    || finalPending
    || thirdPending
    || Boolean(finalMatch?.left && finalMatch?.right)
    || Boolean(thirdPlaceMatch?.left && thirdPlaceMatch?.right)
  );

  let announcerLabel = "Venue Announcer";
  let announcerHeadline = activeEventMeta?.name ? `${activeEventMeta.name} Live` : "Live Event";
  let announcerCopy = lifecycle.detail || "Live event updates will appear here as drivers and battles progress.";

  if (results.championName) {
    announcerLabel = "Final Call";
    announcerHeadline = `#${results.championSeed || "-"} ${results.championName}`;
    announcerCopy = results.runnerUpName
      ? `Champion locked. ${results.championName} closes out ${activeEventMeta.name} over ${results.runnerUpName}, and the full results package is now saved.`
      : `Champion locked for ${activeEventMeta.name}. Final standings, saved bracket results, and qualifying history are ready to view.`;
  } else if (finalsReady && finalPending && finalMatch?.left?.name && finalMatch?.right?.name) {
    announcerLabel = "Final Battle";
    announcerHeadline = `${finalMatch.left.name} vs ${finalMatch.right.name}`;
    announcerCopy = "Center stage is live. The championship battle is now the focus, and podium updates will lock automatically as winners are selected.";
  } else if (activeBattleTitle) {
    announcerLabel = activeBattle?.title || "Center Stage";
    announcerHeadline = activeBattleTitle;
    announcerCopy = `${activeBattle?.meta || "Bracket flow is live."} Spectators can follow this page for the live lane without checking the admin table.`;
  } else if (currentDriver?.name) {
    announcerLabel = "Now Qualifying";
    announcerHeadline = currentDriver.name;
    announcerCopy = `Reg #${formatDriverRegistrationNumber(currentDriver)} is on course right now. Run averages and best score update live as judges submit.`;
  } else if (context.qualifyingPhase === "complete") {
    announcerLabel = "Qualifying Locked";
    announcerHeadline = rankedDrivers[0]?.name ? `#${rankedDrivers[0].seed} ${rankedDrivers[0].name}` : "Bracket Ready";
    announcerCopy = `Qualifying is complete. ${context.plan.description || "The bracket can be published now."}`;
  } else if (registerOpen) {
    announcerLabel = "Registration Live";
    announcerHeadline = activeEventMeta?.name || "Driver Check-In Open";
    announcerCopy = "Drivers can still self-register, complete payment at the front desk, and join the roster before qualifying begins.";
  }

  const announcerPills = [
    { label: "Phase", value: lifecycle.label, tone: lifecycle.tone === "archived" ? "tone-muted" : "tone-live" },
    { label: "Now Live", value: activeBattleTitle || currentDriver?.name || lifecycle.detail || "Waiting", tone: activeBattleTitle || currentDriver?.name ? "tone-ready" : "tone-muted" },
    { label: "Battles", value: battleStats.totalBattles ? `${battleStats.completedBattles}/${battleStats.totalBattles} Complete` : "Bracket Pending", tone: battleStats.totalBattles ? "tone-ready" : "tone-muted" },
    { label: "Registration", value: registerOpen ? "Open" : "Closed", tone: registerOpen ? "tone-live" : "tone-muted" },
  ];

  const finalsPanelMarkup = finalsReady
    ? `
      <article class="public-event-finals-stage">
        <div class="public-event-stage-head">
          <div>
            <p class="broadcast-kicker">Finals Desk</p>
            <h3 class="public-event-stage-title">Center Stage Package</h3>
          </div>
          <strong>${results.championName ? "Results Locked" : finalPending ? "Championship Live" : "Finals Queue"}</strong>
        </div>
        <p class="public-event-stage-copy">${escapeHtml(results.championName
          ? "The championship and podium are locked in. This finals panel keeps the winner, runner-up, and podium race easy to read from across the room."
          : finalPending
            ? "The finals stage is active. Championship and podium battles are highlighted here so the venue screen can stay focused on the finish."
            : "Finalists are set and the venue screen is ready for the deciding battles.")}</p>
        <div class="public-event-finals-grid">
          ${renderPublicEventStageCard({
            label: results.championName ? "Champion" : "Championship Battle",
            title: results.championName
              ? `#${results.championSeed || "-"} ${results.championName}`
              : buildPublicEventBattleTitle(finalMatch) || "Waiting for finalists",
            copy: results.championName
              ? (results.runnerUpName
                ? `Runner-up: #${results.runnerUpSeed || "-"} ${results.runnerUpName}.`
                : "Final result saved for the event archive.")
              : finalMatch?.left?.name && finalMatch?.right?.name
                ? "Center stage is live for the title run."
                : "Winners from the last side of the bracket will feed in automatically.",
            pills: [
              { label: "Status", value: results.championName ? "Champion Crowned" : finalPending ? "Live Now" : "Loading", tone: results.championName ? "tone-live" : finalPending ? "tone-ready" : "tone-muted" },
              { label: "Left Lane", value: buildPublicEventSeedLabel(finalMatch?.left), tone: finalMatch?.left?.name ? "tone-ready" : "tone-muted" },
              { label: "Right Lane", value: buildPublicEventSeedLabel(finalMatch?.right), tone: finalMatch?.right?.name ? "tone-ready" : "tone-muted" },
            ],
            emphasisClass: "championship",
          })}
          ${renderPublicEventStageCard({
            label: thirdPlaceMatch?.left?.name && thirdPlaceMatch?.right?.name
              ? "3rd Place Battle"
              : results.thirdPlaceName
                ? "Podium Locked"
                : "Podium Snapshot",
            title: results.thirdPlaceName
              ? `#${results.thirdPlaceSeed || "-"} ${results.thirdPlaceName}`
              : buildPublicEventBattleTitle(thirdPlaceMatch) || (rankedDrivers[0] ? `#${rankedDrivers[0].seed} ${rankedDrivers[0].name}` : "Waiting for podium"),
            copy: results.thirdPlaceName
              ? "Podium result saved to the archive."
              : thirdPlaceMatch?.left?.name && thirdPlaceMatch?.right?.name
                ? "Semifinal losers battle here for the final podium spot."
                : rankedDrivers[0]
                  ? `Top qualifier is currently #${rankedDrivers[0].seed} ${rankedDrivers[0].name}.`
                  : "Podium and top qualifier details will appear here.",
            pills: [
              { label: "Top Qualifier", value: results.topQualifierName ? `#${results.topQualifierSeed || "-"} ${results.topQualifierName}` : rankedDrivers[0] ? `#${rankedDrivers[0].seed} ${rankedDrivers[0].name}` : "Open", tone: rankedDrivers[0] ? "tone-ready" : "tone-muted" },
              { label: "Average Best", value: results.averageBestScore !== null ? formatScore(results.averageBestScore) : "Waiting", tone: results.averageBestScore !== null ? "tone-ready" : "tone-muted" },
            ],
            emphasisClass: "podium",
          })}
        </div>
      </article>
    `
    : "";

  const tracksidePanelMarkup = !finalsReady
    ? `
      <article class="public-event-track-panel">
        <div class="public-event-stage-head">
          <div>
            <p class="broadcast-kicker">Trackside Control</p>
            <h3 class="public-event-stage-title">${activeBattleTitle ? "Competition Lane" : currentDriver?.name ? "Qualifying Lane" : "Event Status"}</h3>
          </div>
          <strong>${activeBattleTitle ? "Bracket Live" : currentDriver?.name ? "Judges Scoring" : lifecycle.label}</strong>
        </div>
        <p class="public-event-stage-copy">${escapeHtml(activeBattleTitle
          ? `${activeBattle?.title || "Live battle"} is on deck, with the next matchup already queued behind it.`
          : currentDriver?.name
            ? `${currentDriver.name} is on track now, and the next driver is already highlighted below for smooth staging.`
            : registerOpen
              ? "Registration and check-in are open. This page will switch into qualifying and bracket coverage automatically as the event advances."
              : "The event is staged and waiting for the next live action.")}</p>
        <div class="public-event-track-layout">
          ${renderPublicEventStageCard({
            label: activeBattleTitle ? "Up Now" : currentDriver?.name ? "On Course" : "Event Pulse",
            title: activeBattleTitle || currentDriver?.name || lifecycle.label,
            copy: activeBattleTitle
              ? `${activeBattle?.meta || "Competition battle in progress."}`
              : currentDriver?.name
                ? `Reg #${formatDriverRegistrationNumber(currentDriver)} | ${buildPublicEventBestScoreLabel(currentDriver, currentRun1, currentRun2)}`
                : lifecycle.detail || "Waiting for the next live phase.",
            pills: activeBattleTitle
              ? [
                  { label: "Battle", value: activeBattle?.title || "Live", tone: "tone-live" },
                  { label: "Lead", value: buildPublicEventSeedLabel(activeBattle?.match?.left), tone: activeBattle?.match?.left?.name ? "tone-ready" : "tone-muted" },
                  { label: "Chase", value: buildPublicEventSeedLabel(activeBattle?.match?.right), tone: activeBattle?.match?.right?.name ? "tone-ready" : "tone-muted" },
                ]
              : currentDriver?.name
                ? [
                    { label: "Run 1", value: formatScore(currentRun1), tone: currentRun1 !== null ? "tone-ready" : "tone-muted" },
                    { label: "Run 2", value: formatScore(currentRun2), tone: currentRun2 !== null ? "tone-ready" : "tone-muted" },
                    { label: "Best", value: formatScore(currentBest), tone: currentBest !== null ? "tone-live" : "tone-muted" },
                  ]
                : [
                    { label: "Roster", value: `${registeredDrivers.length}`, tone: registeredDrivers.length ? "tone-ready" : "tone-muted" },
                    { label: "Qualified", value: `${context.plan.qualifiedCount || 0}`, tone: context.plan.qualifiedCount ? "tone-ready" : "tone-muted" },
                    { label: "Status", value: registerOpen ? "Check-In Open" : "Waiting", tone: registerOpen ? "tone-live" : "tone-muted" },
                  ],
            emphasisClass: "championship",
          })}
          ${activeBattleTitle
            ? `
              <section class="public-event-queue-stack">
                <div class="public-event-queue-head">
                  <p>Competition Queue</p>
                  <strong>${queuedBattles.length ? `Next ${queuedBattles.length} Battles` : "Queue Waiting"}</strong>
                </div>
                <div class="public-event-queue-list">
                  ${queuedBattles.length
                    ? queuedBattles.map((entry, index) => renderPublicEventQueueCard(entry, index)).join("")
                    : `
                      <article class="public-event-queue-card">
                        <div class="public-event-queue-card-head">
                          <span>Queue</span>
                          <strong>Waiting</strong>
                        </div>
                        <h4 class="public-event-queue-card-title">No additional battles queued yet</h4>
                        <p class="public-event-queue-card-copy">As soon as the bracket advances, the next six battles will appear here automatically.</p>
                      </article>
                    `}
                </div>
              </section>
            `
            : renderPublicEventStageCard({
                label: nextDriver?.name ? "On Deck" : queuedBattleTitle ? "Next Battle" : "Top Qualifier",
                title: nextDriver?.name || queuedBattleTitle || (results.topQualifierName ? `#${results.topQualifierSeed || "-"} ${results.topQualifierName}` : rankedDrivers[0] ? `#${rankedDrivers[0].seed} ${rankedDrivers[0].name}` : "Open"),
                copy: nextDriver?.name
                  ? `Stage next. ${buildPublicEventBestScoreLabel(nextDriver)}${nextDriver.chassis ? ` | ${nextDriver.chassis}` : ""}`
                  : queuedBattleTitle
                    ? `${queuedBattleAfterCurrent?.title || "Queued battle"} | ${queuedBattleAfterCurrent?.meta || "Waiting for bracket progress."}`
                    : results.topQualifierScore !== null
                      ? `Top qualifying mark is ${formatScore(results.topQualifierScore)}.`
                      : rankedDrivers[0]
                        ? `Current top qualifier with best score ${formatScore(rankedDrivers[0].bestScore)}.`
                        : "The next lane assignment will appear here.",
                pills: nextDriver?.name
                  ? [
                      { label: "Reg", value: `#${formatDriverRegistrationNumber(nextDriver)}`, tone: "tone-ready" },
                      { label: "Team", value: nextDriver.teamName || "Independent", tone: "tone-muted" },
                    ]
                  : queuedBattleTitle
                    ? [
                        { label: "Queue", value: queuedBattleAfterCurrent?.title || "Next", tone: "tone-ready" },
                        { label: "Page", value: queuedBattleAfterCurrent?.bracketKey === "lower" ? "Lower" : "Main", tone: "tone-muted" },
                      ]
                    : [
                        { label: "Seed", value: results.topQualifierName ? `#${results.topQualifierSeed || "-"}` : rankedDrivers[0] ? `#${rankedDrivers[0].seed}` : "-", tone: rankedDrivers[0] ? "tone-ready" : "tone-muted" },
                        { label: "Entries", value: `${registeredDrivers.length}`, tone: registeredDrivers.length ? "tone-ready" : "tone-muted" },
                      ],
                emphasisClass: "podium",
              })}
        </div>
      </article>
    `
    : "";

  return {
    activeBattle,
    queuedBattleAfterCurrent,
    activeBattleTitle,
    queuedBattleTitle,
    finalsReady,
    announcerLabel,
    announcerHeadline,
    announcerCopy,
    announcerPills,
    broadcastPanelMarkup: finalsPanelMarkup || tracksidePanelMarkup,
  };
}

function renderQueueViewV2() {
  if (!publicEventLayout || !publicEventBroadcast || !publicEventRoster || !publicEventStandings || !publicEventSummary) return;
  if (!activeEventMeta) {
    publicEventLayout.classList.remove("is-finals");
    publicEventBroadcast.innerHTML = "";
    publicEventRoster.innerHTML = "";
    publicEventStandings.innerHTML = "";
    publicEventSummary.innerHTML = "";
    return;
  }

  const context = buildDriverStatusContext();
  const rankedDrivers = context.rankedDrivers;
  const registeredDrivers = getRegisteredDrivers(appDrivers);
  const currentDriver = appDrivers.find((driver) => driver.id === context.currentDriverId) || null;
  const nextDriver = appDrivers.find((driver) => driver.id === context.nextDriverId) || null;
  const currentRun1 = currentDriver ? getLiveRunAverage(currentDriver, 1) : null;
  const currentRun2 = currentDriver ? getLiveRunAverage(currentDriver, 2) : null;
  const currentBest = currentDriver ? getBestScore(currentRun1, currentRun2) : null;
  const lowerBattleEntries = tournamentState?.lowerBracket?.rounds?.length
    ? getLowerBattleFlowEntries(tournamentState.lowerBracket.rounds)
    : [];
  const mainBattleEntries = tournamentState?.mainBracket?.rounds?.length
    ? getMainBattleFlowEntries(tournamentState.mainBracket.rounds, tournamentState.mainBracket.thirdPlaceMatch)
    : [];
  const battleQueue = lowerBattleEntries.length ? [...lowerBattleEntries, ...mainBattleEntries] : mainBattleEntries;
  const lifecycle = getEventLifecycleMeta();
  const results = activeEventMeta?.results || {};
  const registerOpen = !getSelfRegistrationCloseReason() && hasValidVenueConfig();
  const battleStats = getTournamentBattleStats(tournamentState);
  const hasBracketPublished = Boolean(tournamentState?.mainBracket?.rounds?.length || tournamentState?.lowerBracket?.rounds?.length);
  const hasSavedResults = Boolean(results.championName || getEventStatus(activeEventMeta) === EVENT_STATUS_COMPLETED || getEventStatus(activeEventMeta) === EVENT_STATUS_ARCHIVED);
  const broadcastState = buildPublicEventBroadcastState({
    context,
    lifecycle,
    results,
    registerOpen,
    registeredDrivers,
    rankedDrivers,
    currentDriver,
    nextDriver,
    currentRun1,
    currentRun2,
    currentBest,
    lowerBattleEntries,
    mainBattleEntries,
    battleQueue,
    battleStats,
  });

  const queueQualifyingBtn = document.querySelector('[data-queue-jump="qualifying"]');
  const queueBracketBtn = document.querySelector('[data-queue-jump="bracket"]');
  const queueResultsBtn = document.querySelector('[data-queue-jump="results"]');
  if (queueQualifyingBtn) {
    queueQualifyingBtn.textContent = results.championName ? "View Qualifying" : "Open Qualifying";
  }
  if (queueBracketBtn) {
    queueBracketBtn.textContent = hasBracketPublished ? "Open Competition" : "Bracket Pending";
    queueBracketBtn.disabled = !hasBracketPublished;
  }
  if (queueResultsBtn) {
    queueResultsBtn.textContent = hasSavedResults ? "Past Results" : "Results Pending";
    queueResultsBtn.disabled = !hasSavedResults;
  }

  if (queueHeroTitle) {
    queueHeroTitle.textContent = activeEventMeta?.name ? `${activeEventMeta.name} Live Event` : "Live Event";
  }
  if (queueHeroCopy) {
    queueHeroCopy.textContent = broadcastState.announcerCopy;
  }
  if (queueHeroStats) {
    queueHeroStats.innerHTML = `
      <div class="hero-stat">
        <span class="hero-stat-label">Now Live</span>
        <strong>${escapeHtml(broadcastState.activeBattleTitle || currentDriver?.name || lifecycle.label)}</strong>
      </div>
      <div class="hero-stat">
        <span class="hero-stat-label">On Deck</span>
        <strong>${escapeHtml(nextDriver?.name || broadcastState.queuedBattleTitle || "Waiting")}</strong>
      </div>
      <div class="hero-stat">
        <span class="hero-stat-label">Top Seed</span>
        <strong>${results.topQualifierName ? `#${results.topQualifierSeed || "-"} ${escapeHtml(results.topQualifierName)}` : rankedDrivers[0] ? `#${rankedDrivers[0].seed} ${escapeHtml(rankedDrivers[0].name)}` : "Open"}</strong>
      </div>
      <div class="hero-stat hero-stat-emphasis">
        <span class="hero-stat-label">Venue Status</span>
        <strong>${results.championName ? "Final Results" : broadcastState.activeBattleTitle ? "Competition Live" : currentDriver?.name ? "Qualifying Live" : registerOpen ? "Check-In Open" : lifecycle.label}</strong>
      </div>
    `;
  }

  publicEventLayout.classList.toggle("is-finals", broadcastState.finalsReady);
  publicEventBroadcast.innerHTML = `
    <div class="public-event-broadcast-grid">
      ${broadcastState.broadcastPanelMarkup}
      ${renderPublicEventCameraPreview({
        lifecycle,
        results,
        registeredDrivers,
        rankedDrivers,
        currentDriver,
        currentBest,
        nextDriver,
        activeBattle: broadcastState.activeBattle,
        activeBattleTitle: broadcastState.activeBattleTitle,
        queuedBattleTitle: broadcastState.queuedBattleTitle,
        battleStats,
      })}
    </div>
  `;

  const rosterCards = sortPublicEventRoster(registeredDrivers, context).slice(0, 12);
  publicEventRoster.innerHTML = rosterCards.length
    ? rosterCards.map((driver) => {
        const badges = getDriverStatusBadges(driver, context);
        const rankedInfo = context.rankingLookup.get(driver.id) || null;
        const bestScore = rankedInfo?.bestScore ?? getBestScore(getRunAverage(driver, 1), getRunAverage(driver, 2));
        const leadLabel = badges[0]?.label || "Driver";
        return `
        <article class="public-event-card queue-roster-card">
          <span>${escapeHtml(leadLabel)}</span>
          <div class="queue-roster-meta">
            <strong>#${formatDriverRegistrationNumber(driver)} ${escapeHtml(formatDriverDisplayName(driver))}</strong>
            <div>${escapeHtml(driver.teamName || "Independent")}</div>
          </div>
          <div class="queue-roster-detail-grid">
            <div class="queue-roster-detail">
              <span>Best</span>
              <strong>${formatScore(bestScore)}</strong>
            </div>
            <div class="queue-roster-detail">
              <span>Chassis</span>
              <strong>${escapeHtml(driver.chassis || "Not listed")}</strong>
            </div>
          </div>
          ${renderDriverStatusChips(driver, context)}
        </article>
      `;
      }).join("")
    : renderNoDriversState();

  publicEventStandings.innerHTML = rankedDrivers.slice(0, 10).length
    ? rankedDrivers.slice(0, 10).map((driver, index) => `
        <div class="public-event-standing">
          <div class="public-event-standing-main">
            <span class="public-event-standing-rank">${driver.seed}.</span>
            ${getStandingsTrophyMarkup(index)}
            <div>
              <strong>${escapeHtml(formatDriverDisplayName(driver))}</strong>
            <span>${escapeHtml(driver.teamName || "Independent")}</span>
            </div>
          </div>
          <div class="public-event-standing-score">
            <small>Best</small>
            <strong>${formatScore(driver.bestScore)}</strong>
          </div>
        </div>
      `).join("")
    : renderNoStandingsState();

  publicEventSummary.innerHTML = `
    <article class="public-event-statline">
      <span>Roster</span>
      <strong>${registeredDrivers.length}</strong>
      <small>Live drivers checked into this event.</small>
    </article>
    <article class="public-event-statline">
      <span>Qualified</span>
      <strong>${context.plan.qualifiedCount || 0}</strong>
      <small>${escapeHtml(context.plan.description || "Waiting for scores.")}</small>
    </article>
    <article class="public-event-statline">
      <span>Top Qualifier</span>
      <strong>${results.topQualifierName ? `#${results.topQualifierSeed || "-"} ${escapeHtml(results.topQualifierName)}` : rankedDrivers[0] ? `#${rankedDrivers[0].seed} ${escapeHtml(rankedDrivers[0].name)}` : "Open"}</strong>
      <small>${results.topQualifierScore !== null ? `Best score ${formatScore(results.topQualifierScore)}` : rankedDrivers[0] ? `Best score ${formatScore(rankedDrivers[0].bestScore)}` : "Waiting for first score."}</small>
    </article>
    <article class="public-event-statline">
      <span>Post Event</span>
      <strong>${results.championName ? `#${results.championSeed || "-"} ${escapeHtml(results.championName)}` : battleStats.totalBattles ? `${battleStats.completedBattles}/${battleStats.totalBattles} Battles` : "In Progress"}</strong>
      <small>${results.averageBestScore !== null ? `Average best score ${formatScore(results.averageBestScore)}` : "Champion, podium, and summary save automatically when finals are complete."}</small>
    </article>
  `;
}

