function getStreamerDivisionLabel(eventMeta = activeEventMeta, state = tournamentState) {
  if (isTeamTandemMode(eventMeta)) return "Team Tandem";
  const preferredFormat = normalizePreferredFormat(state?.preferredFormat || bracketModeSelect?.value || FORMAT_CLASSIC);
  if (preferredFormat === FORMAT_SDC_TOP_8) return "SDC Top 8";
  if (preferredFormat === FORMAT_SDC_TOP_16) return "SDC Top 16";
  if (preferredFormat === FORMAT_SDC_TOP_32) return "SDC Top 32";
  if (preferredFormat === FORMAT_SDC) return "SDC Format";
  return "Open Class";
}

