function getStreamerPreferredScene() {
  if (tournamentState?.mainBracket?.rounds?.length) return "battle";
  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  if (qualifyingPhase === "live" || qualifyingPhase === "complete") return "qualifying";
  if (getEventStatus(activeEventMeta) === EVENT_STATUS_COMPLETED) return "results";
  return "starting-soon";
}

function isLocalNativeStreamerAuthorized() {
  return Boolean(isWebsiteAdmin || currentRole === "admin" || isRoleUnlockedForEvent(activeEventId, "admin"));
}

function isNativeStreamerAuthorized() {
  return isLocalNativeStreamerAuthorized() && roleCanUseProductionWrites("streamOperator");
}

function resolveNativeStreamLayoutKey(options = {}) {
  const eventMeta = options.eventMeta || activeEventMeta;
  const drivers = options.drivers || appDrivers;
  const state = options.tournamentState || tournamentState;
  const flow = options.qualifyingFlow || qualifyingFlow;
  const status = getEventStatus(eventMeta);
  const results = eventMeta?.results || {};
  if (!eventMeta) return "starting-soon";
  if (status === EVENT_STATUS_COMPLETED || status === EVENT_STATUS_ARCHIVED || results.championName) {
    return "results";
  }
  const competitionFlow = getCompetitionFlowEntriesForState(state);
  if (competitionFlow?.currentEntry?.match?.left && competitionFlow?.currentEntry?.match?.right) {
    return "battle";
  }
  if (state?.mainBracket?.rounds?.length || state?.lowerBracket?.rounds?.length) {
    return "bracket";
  }
  const qualifyingPhase = getQualifyingFlowPhase(flow, drivers);
  if (qualifyingPhase === "live") return "qualifying";
  if (qualifyingPhase === "complete") return "standings";
  return "starting-soon";
}

function getNativeStreamPhaseLabel(layoutKey = resolveNativeStreamLayoutKey()) {
  return ({
    "starting-soon": "Starting Soon",
    qualifying: "Qualifying Live",
    standings: "Standings",
    bracket: "Competition Bracket",
    battle: "Head-To-Head Battle",
    results: "Results",
    intermission: "Intermission",
    "event-complete": "Event Complete",
  })[layoutKey] || "Live";
}

function getNativeLiveViewerUrl() {
  if (typeof window === "undefined") return "";
  const targetUrl = new URL(getConfiguredWindowBaseUrl());
  const spectatorHost = PUBLIC_ROLE_HOSTNAMES.spectator;
  if (spectatorHost) {
    targetUrl.protocol = "https:";
    targetUrl.hostname = spectatorHost;
    targetUrl.port = "";
  }
  targetUrl.pathname = "/";
  targetUrl.search = "";
  targetUrl.hash = "#/spectator/live";
  return targetUrl.toString();
}

function getNativeBroadcastContext(layoutKey = resolveNativeStreamLayoutKey()) {
  const context = getStreamerSceneContext({
    ...streamerRouteState,
    scene: STREAMER_SCENE_META[layoutKey] ? layoutKey : "starting-soon",
    demo: streamerRouteState.demo,
  });
  return {
    ...context,
    sceneKey: layoutKey,
    layoutKey,
    phaseLabel: getNativeStreamPhaseLabel(layoutKey),
  };
}

function buildNativeBroadcastRows(entries = [], scoreKey = "bestScore") {
  const rows = entries.slice(0, 6);
  if (!rows.length) {
    return `<div class="native-broadcast-row"><span class="native-broadcast-rank">-</span><strong>Waiting for live data</strong><span>--</span></div>`;
  }
  return rows.map((entry, index) => `
    <div class="native-broadcast-row">
      <span class="native-broadcast-rank">#${escapeHtml(String(entry.seed || index + 1))}</span>
      <strong>${escapeHtml(entry.name || "Pending")}</strong>
      <span>${escapeHtml(scoreKey === "seed" ? `Seed ${entry.seed || index + 1}` : formatScore(entry[scoreKey]))}</span>
    </div>
  `).join("");
}

