function renderNativeBroadcastOverlay(target, layoutKey = resolveNativeStreamLayoutKey()) {
  if (!target) return;
  const stage = target.closest?.(".native-live-stage, .streamer-live-preview-shell, .native-broadcast-composite");
  if (stage) stage.dataset.layoutKey = layoutKey;
  target.innerHTML = renderNativeBroadcastLayoutMarkup(layoutKey, getNativeBroadcastContext(layoutKey));
}

function renderNativeStreamSummary(target, streamState = nativeStreamLatestState) {
  if (!target) return;
  const layoutKey = streamState?.layoutKey || resolveNativeStreamLayoutKey();
  const context = getNativeBroadcastContext(layoutKey);
  target.innerHTML = `
    <span class="streamer-status-kicker">${streamState?.active ? "On Air" : "Waiting"}</span>
    <strong>${escapeHtml(context.eventName || "Current Event")}</strong>
    <p>${escapeHtml(`${getNativeStreamPhaseLabel(layoutKey)} is selected from event state. ${context.lifecycle?.detail || ""}`.trim())}</p>
    <div class="streamer-chip-row" style="margin-top: 12px;">
      <span class="streamer-chip accent">${escapeHtml(getNativeStreamPhaseLabel(layoutKey))}</span>
      <span class="streamer-chip">${escapeHtml(context.divisionLabel)}</span>
      <span class="streamer-chip">${streamState?.active ? "Live Signal" : "Offline"}</span>
    </div>
  `;
}

function getNativeRemoteTrackCount(kind = "") {
  if (!nativeStreamRemoteStream) return 0;
  if (kind === "video") return nativeStreamRemoteStream.getVideoTracks().length;
  if (kind === "audio") return nativeStreamRemoteStream.getAudioTracks().length;
  return nativeStreamRemoteStream.getTracks().length;
}

function isNativeLiveStreamFresh(streamState = nativeStreamLatestState) {
  return Boolean(streamState?.active && (!streamState.heartbeatAt || Date.now() - Number(streamState.heartbeatAt || 0) < NATIVE_STREAM_STALE_MS));
}

function syncNativeLiveAudioButton() {
  if (!nativeLiveAudioBtn || !nativeLiveVideo) return;
  const hasFreshStream = isNativeLiveStreamFresh();
  const hasAudioTrack = getNativeRemoteTrackCount("audio") > 0;
  nativeLiveAudioBtn.hidden = !hasFreshStream || !hasAudioTrack;
  nativeLiveAudioBtn.textContent = nativeLiveVideo.muted ? "Enable Audio" : "Mute Audio";
  nativeLiveAudioBtn.classList.toggle("button-accent", !nativeLiveVideo.muted);
  nativeLiveAudioBtn.setAttribute("aria-pressed", nativeLiveVideo.muted ? "false" : "true");
}

async function playNativeLiveVideo(options = {}) {
  if (!nativeLiveVideo) return false;
  const withAudio = options.withAudio === true;
  nativeLiveVideo.muted = !withAudio;
  nativeLiveVideo.defaultMuted = nativeLiveVideo.muted;
  try {
    await nativeLiveVideo.play();
    nativeStreamViewerPlayBlocked = false;
    nativeStreamViewerLastError = "";
    if (getNativeRemoteTrackCount("video") > 0) {
      nativeStreamViewerMediaState = "live";
    }
    syncNativeLiveAudioButton();
    return true;
  } catch (error) {
    nativeStreamViewerPlayBlocked = true;
    nativeStreamViewerLastError = String(error?.message || error || "Playback failed.");
    if (withAudio) {
      nativeLiveVideo.muted = true;
      nativeLiveVideo.defaultMuted = true;
      try {
        await nativeLiveVideo.play();
        nativeStreamViewerPlayBlocked = false;
        nativeStreamViewerLastError = "";
      } catch (fallbackError) {
        nativeStreamViewerLastError = String(fallbackError?.message || fallbackError || nativeStreamViewerLastError);
      }
    }
    syncNativeLiveAudioButton();
    return !nativeStreamViewerPlayBlocked;
  }
}

function scheduleNativeViewerReconnect(reason = "") {
  clearTimeout(nativeStreamViewerRetryTimer);
  nativeStreamViewerRetryTimer = null;
  if (!nativeStreamLatestState?.active || nativeStreamActive) return;
  nativeStreamViewerRetryTimer = window.setTimeout(() => {
    if (!nativeStreamLatestState?.active || nativeStreamActive) return;
    startNativeViewerConnection(nativeStreamLatestState).catch((error) => console.error("Native viewer reconnect failed:", error));
  }, NATIVE_STREAM_VIEWER_RETRY_MS);
  if (reason) {
    console.warn("Scheduling native viewer reconnect:", reason);
  }
}

function renderNativeLiveView() {
  renderRaceControlDashboard();
  const streamState = nativeStreamLatestState;
  const isFresh = isNativeLiveStreamFresh(streamState);
  const layoutKey = streamState?.layoutKey || resolveNativeStreamLayoutKey();
  const remoteVideoTrackCount = getNativeRemoteTrackCount("video");
  const remoteAudioTrackCount = getNativeRemoteTrackCount("audio");
  const hasVisibleVideo = remoteVideoTrackCount > 0;
  const liveStageState = !isFresh
    ? "offline"
    : hasVisibleVideo
      ? "live"
      : (["failed", "error"].includes(nativeStreamViewerConnectionState) ? "error" : "connecting");
  if (nativeLiveStage) nativeLiveStage.dataset.streamState = liveStageState;
  if (nativeLiveStage) nativeLiveStage.dataset.layoutKey = layoutKey;
  if (nativeLiveOfflineTitle) {
    nativeLiveOfflineTitle.textContent = !isFresh
      ? "Stream Offline"
      : liveStageState === "error"
        ? "Live Signal Error"
        : "Connecting Live Camera";
  }
  if (nativeLiveOfflineCopy) {
    nativeLiveOfflineCopy.textContent = !isFresh
      ? "The live camera feed has not started yet. This page will connect automatically when Stream Studio goes live."
      : liveStageState === "error"
        ? "The stream session is live, but the spectator player needs to reconnect to the active camera feed."
        : "The stream session is live. Waiting for the spectator player to finish connecting to the active camera feed.";
  }
  if (nativeLiveStatus) {
    if (!isFresh) {
      nativeLiveStatus.textContent = "Stream Studio is offline. The LIVE tab will connect automatically when a streamer starts broadcasting.";
    } else if (hasVisibleVideo) {
      nativeLiveStatus.textContent = nativeLiveVideo?.muted && remoteAudioTrackCount
        ? `${getNativeStreamPhaseLabel(layoutKey)} live stream connected. Video is playing now, and audio starts muted so browser playback stays reliable.`
        : `${getNativeStreamPhaseLabel(layoutKey)} live stream connected. Layout follows event admin state automatically.`;
    } else if (["failed", "error"].includes(nativeStreamViewerConnectionState)) {
      nativeLiveStatus.textContent = `The live session is active, but spectator playback is reconnecting. ${nativeStreamViewerLastError || "Trying the current camera feed again."}`.trim();
    } else {
      nativeLiveStatus.textContent = `${getNativeStreamPhaseLabel(layoutKey)} is live. Connecting the spectator camera feed now.`;
    }
  }
  if (nativeLiveLayoutTitle) {
    nativeLiveLayoutTitle.textContent = getNativeStreamPhaseLabel(layoutKey);
  }
  renderNativeBroadcastOverlay(nativeLiveOverlay, layoutKey);
  renderNativeStreamSummary(nativeLiveEventSummary, streamState);
  if (nativeLiveVideo && nativeStreamRemoteStream && nativeLiveVideo.srcObject !== nativeStreamRemoteStream) {
    nativeLiveVideo.srcObject = nativeStreamRemoteStream;
    playNativeLiveVideo({ withAudio: false }).catch(() => {});
  }
  syncNativeLiveAudioButton();
}

function setNativeStreamStatus(message, tone = "idle") {
  if (streamerNativeStatus) {
    streamerNativeStatus.textContent = message;
    streamerNativeStatus.dataset.tone = tone;
  }
}

function syncNativeBroadcastOverlays() {
  const layoutKey = resolveNativeStreamLayoutKey();
  streamerFeaturedScene = normalizeStreamerScene(layoutKey === "bracket" ? "battle" : layoutKey);
  if (streamerLivePreviewShell) streamerLivePreviewShell.dataset.layoutKey = layoutKey;
  renderNativeBroadcastOverlay(streamerOverlayPreviewFrame, layoutKey);
  renderNativeLiveView();
  if (nativeStreamActive) {
    publishNativeStreamState({ active: true }).catch((error) => console.error("Native stream layout sync failed:", error));
  }
}

function buildStreamerDemoContext(sceneKey = "qualifying") {
  const sampleDrivers = buildTestSampleDrivers(true).slice(0, 12);
  const rankedDrivers = rankDrivers(sampleDrivers);
  const podium = rankedDrivers.slice(0, 3);
  const demoBattle = {
    title: sceneKey === "battle" ? "Top 16 Heat 4" : "Bracket Preview",
    roundLabel: "Main Bracket Round 1",
    left: rankedDrivers[0] || null,
    right: rankedDrivers[1] || null,
    status: sceneKey === "battle" ? "OMT Rerun Required" : "Coming Up",
    winner: sceneKey === "results" ? rankedDrivers[0] : null,
    omt: sceneKey === "battle",
  };
  return {
    demo: true,
    sceneKey,
    eventName: "Prodigy Broadcast Demo",
    venueName: CLIENT_BRANDING.demoVenueLabel || CLIENT_BRANDING.venueName || "Prodigy RC Drift Arena",
    venueLabel: "Broadcast Sandbox",
    dateLabel: formatEventDate(new Date().toISOString().slice(0, 10)),
    lifecycle: { label: "Demo Data", tone: "active", detail: "Safe setup mode for native stream rehearsals" },
    divisionLabel: "Open Class",
    currentDriver: rankedDrivers[2] || rankedDrivers[0] || null,
    nextDriver: rankedDrivers[3] || rankedDrivers[1] || null,
    standings: rankedDrivers.slice(0, 8),
    podium,
    results: {
      championName: podium[0]?.name || "Takumi Sato",
      championSeed: podium[0]?.seed || 1,
      runnerUpName: podium[1]?.name || "Mika Torres",
      runnerUpSeed: podium[1]?.seed || 2,
      thirdPlaceName: podium[2]?.name || "Jordan Lee",
      thirdPlaceSeed: podium[2]?.seed || 3,
      topQualifierName: podium[0]?.name || "Takumi Sato",
      topQualifierSeed: podium[0]?.seed || 1,
      topQualifierScore: podium[0]?.bestScore || 99.2,
      averageBestScore: 95.4,
    },
    battle: demoBattle,
    sponsorLabel: "Sponsor Region Available",
    footerLabel: "Prodigy RC Comp Broadcast Suite",
    tickerItems: [
      "Demo mode active",
      "Native browser stream previews",
      "Transparent overlays supported",
      "1920x1080 recommended",
    ],
  };
}

function getStreamerSceneContext(route = streamerRouteState) {
  const normalizedRoute = normalizeStreamerRoute(route);
  if (normalizedRoute.demo || !activeEventMeta) {
    return buildStreamerDemoContext(normalizedRoute.scene);
  }

  const rankedDrivers = rankDrivers(appDrivers);
  const queue = getQualifyingDriverQueue(appDrivers);
  const currentDriver = getCurrentQualifyingDriver();
  const currentIndex = currentDriver ? queue.findIndex((entry) => entry.id === currentDriver.id) : -1;
  const nextDriver = currentIndex > -1 ? queue[currentIndex + 1] || null : rankedDrivers[0] || null;
  const competitionFlow = getCompetitionFlowEntriesForState(tournamentState);
  const currentBattle = competitionFlow.currentEntry || null;
  const judgeControl = getCompetitionJudgeControl();
  const activeBattleKey = buildCompetitionJudgeEntryKey(currentBattle);
  const controlKey = buildCompetitionJudgeEntryKey(judgeControl.entry);
  const competitionResolution = activeBattleKey && controlKey && activeBattleKey === controlKey
    ? getCompetitionDecisionResolution(judgeControl, activeEventMeta)
    : null;
  const liveResults = activeEventMeta
    ? {
        ...(activeEventMeta.results || buildEmptyEventResults()),
        ...buildEventResults(),
      }
    : buildEmptyEventResults();
  const podium = [
    liveResults.championName ? { name: liveResults.championName, seed: liveResults.championSeed || 1 } : rankedDrivers[0] || null,
    liveResults.runnerUpName ? { name: liveResults.runnerUpName, seed: liveResults.runnerUpSeed || 2 } : rankedDrivers[1] || null,
    liveResults.thirdPlaceName ? { name: liveResults.thirdPlaceName, seed: liveResults.thirdPlaceSeed || 3 } : rankedDrivers[2] || null,
  ].filter(Boolean);

  const battleStatus = competitionResolution?.omtMajority
    ? "OMT Rerun Required"
    : judgeControl.status === "review_hold"
      ? "Review Hold"
      : judgeControl.status === "admin_decision"
        ? "Awaiting Admin Continue"
        : currentBattle?.match?.winner?.name
          ? `${currentBattle.match.winner.name} Advanced`
          : currentBattle?.match?.left?.name && currentBattle?.match?.right?.name
            ? "Battle Live"
            : "Bracket Pending";

  return {
    demo: false,
    sceneKey: normalizedRoute.scene,
    eventName: activeEventMeta?.name || "Prodigy RC Event",
    venueName: CLIENT_BRANDING.venueName || "Prodigy RC Drift Arena",
    venueLabel: getVenueConfig(activeEventMeta)?.label || CLIENT_BRANDING.venueName || "Prodigy RC Drift Arena",
    dateLabel: formatEventDate(activeEventMeta?.date),
    lifecycle: getEventLifecycleMeta(),
    divisionLabel: getStreamerDivisionLabel(activeEventMeta, tournamentState),
    currentDriver,
    nextDriver,
    standings: rankedDrivers.slice(0, 8),
    podium,
    results: liveResults,
    battle: {
      title: currentBattle?.title || "Current Battle",
      roundLabel: currentBattle?.meta || "Waiting for bracket publish",
      left: currentBattle?.match?.left || rankedDrivers[0] || null,
      right: currentBattle?.match?.right || rankedDrivers[1] || null,
      status: battleStatus,
      winner: currentBattle?.match?.winner || null,
      omt: Boolean(competitionResolution?.omtMajority || (judgeControl.reason === "omt" && judgeControl.status === "voting")),
      leftVotes: competitionResolution?.leftVotes ?? null,
      rightVotes: competitionResolution?.rightVotes ?? null,
      omtVotes: competitionResolution?.omtVotes ?? null,
    },
    sponsorLabel: "Sponsor / Partner Region",
    footerLabel: "streamer.prodigyrccomp.com",
    tickerItems: buildBroadcastTickerItems().length ? buildBroadcastTickerItems() : [
      `${liveResults.topQualifierName ? `Top qualifier ${liveResults.topQualifierName}` : "Waiting for first score"}`,
      `${currentBattle?.title || "Bracket not live yet"}`,
      `${getEventLifecycleMeta().detail || "Prodigy live event data"}`,
    ],
  };
}

function getStreamerPreviewUrl(sceneKey, variant = "scene", demo = false) {
  return buildStreamerRouteUrl({
    view: "streamer-scene",
    scene: sceneKey,
    variant,
    demo,
  }, {
    useCurrentHost: true,
  });
}

function setStreamerCameraStatus(message, tone = "idle") {
  if (!streamerCameraStatus) return;
  streamerCameraStatus.textContent = message;
  streamerCameraStatus.dataset.tone = tone;
}

function syncStreamerCameraPreviewUi() {
  const hasLiveStream = Boolean((streamerCameraPreviewStream || nativeStreamLocalStream) && streamerLiveCameraVideo?.srcObject);
  if (streamerLivePreviewShell) {
    streamerLivePreviewShell.dataset.cameraState = hasLiveStream ? "live" : (streamerCameraPreviewBusy ? "loading" : "idle");
  }
  if (streamerStartCameraPreviewBtn) {
    streamerStartCameraPreviewBtn.disabled = streamerCameraPreviewBusy || hasLiveStream || nativeStreamActive;
  }
  if (streamerStopCameraPreviewBtn) {
    streamerStopCameraPreviewBtn.disabled = streamerCameraPreviewBusy || !streamerCameraPreviewStream || nativeStreamActive;
  }
  renderNativeBroadcastOverlay(streamerOverlayPreviewFrame, resolveNativeStreamLayoutKey());
}

function stopStreamerCameraPreview(options = {}) {
  if (nativeStreamActive && options.force !== true) {
    syncStreamerCameraPreviewUi();
    return;
  }
  if (streamerCameraPreviewStream) {
    streamerCameraPreviewStream.getTracks().forEach((track) => track.stop());
  }
  streamerCameraPreviewStream = null;
  if (streamerLiveCameraVideo) {
    streamerLiveCameraVideo.pause?.();
    streamerLiveCameraVideo.srcObject = null;
  }
  streamerCameraPreviewBusy = false;
  if (options.preserveStatus !== true) {
    setStreamerCameraStatus(
      "Preview uses the selected camera and microphone locally before publishing to spectators.",
      "idle",
    );
  }
  syncStreamerCameraPreviewUi();
}

async function startStreamerCameraPreview() {
  if (!streamerLiveCameraVideo) return false;
  if (!navigator.mediaDevices?.getUserMedia) {
    setStreamerCameraStatus("This browser does not expose camera preview support.", "error");
    syncStreamerCameraPreviewUi();
    return false;
  }
  stopStreamerCameraPreview({ preserveStatus: true });
  streamerCameraPreviewBusy = true;
  setStreamerCameraStatus("Requesting camera permission for the local Stream Studio preview...", "idle");
  syncStreamerCameraPreviewUi();
  try {
    const constraints = getNativeMediaConstraints();
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: false,
      video: constraints.video,
    });
    streamerCameraPreviewStream = stream;
    streamerLiveCameraVideo.srcObject = stream;
    await streamerLiveCameraVideo.play().catch(() => {});
    await refreshNativeStreamDevices();
    streamerCameraPreviewBusy = false;
    setStreamerCameraStatus("Camera preview is running with the automatic Prodigy layout layered on top.", "live");
    syncStreamerCameraPreviewUi();
    return true;
  } catch (error) {
    streamerCameraPreviewBusy = false;
    const denied = /denied|permission/i.test(String(error?.message || error?.name || ""));
    setStreamerCameraStatus(
      denied
        ? "Camera access was denied. Allow camera permission to preview or stream from this browser."
        : "Camera preview could not start on this device. Check browser permissions and selected devices.",
      "error",
    );
    syncStreamerCameraPreviewUi();
    return false;
  }
}

async function refreshNativeStreamDevices() {
  if (!navigator.mediaDevices?.enumerateDevices) {
    if (streamerCameraSelect) streamerCameraSelect.innerHTML = `<option value="">Camera unavailable</option>`;
    if (streamerMicSelect) streamerMicSelect.innerHTML = `<option value="">Microphone unavailable</option>`;
    return;
  }
  try {
    const devices = await navigator.mediaDevices.enumerateDevices();
    const cameras = devices.filter((device) => device.kind === "videoinput");
    const microphones = devices.filter((device) => device.kind === "audioinput");
    if (streamerCameraSelect) {
      const previous = streamerCameraSelect.value;
      streamerCameraSelect.innerHTML = cameras.length
        ? cameras.map((device, index) => `<option value="${escapeAttributeValue(device.deviceId)}">${escapeHtml(device.label || `Camera ${index + 1}`)}</option>`).join("")
        : `<option value="">Default camera</option>`;
      if (previous && cameras.some((device) => device.deviceId === previous)) streamerCameraSelect.value = previous;
    }
    if (streamerMicSelect) {
      const previous = streamerMicSelect.value;
      streamerMicSelect.innerHTML = microphones.length
        ? microphones.map((device, index) => `<option value="${escapeAttributeValue(device.deviceId)}">${escapeHtml(device.label || `Microphone ${index + 1}`)}</option>`).join("")
        : `<option value="">Default microphone</option>`;
      if (previous && microphones.some((device) => device.deviceId === previous)) streamerMicSelect.value = previous;
    }
  } catch (error) {
    console.warn("Device enumeration failed:", error);
  }
}

function getNativeMediaConstraints() {
  const videoDeviceId = streamerCameraSelect?.value || "";
  const audioDeviceId = streamerMicSelect?.value || "";
  return {
    video: videoDeviceId
      ? { deviceId: { exact: videoDeviceId }, width: { ideal: 1280 }, height: { ideal: 720 } }
      : { facingMode: { ideal: "environment" }, width: { ideal: 1280 }, height: { ideal: 720 } },
    audio: audioDeviceId
      ? { deviceId: { exact: audioDeviceId }, echoCancellation: true, noiseSuppression: true }
      : { echoCancellation: true, noiseSuppression: true },
  };
}

function syncNativeStreamControlUi() {
  const localAuthorized = isLocalNativeStreamerAuthorized();
  const authorized = isNativeStreamerAuthorized();
  const syncReady = Boolean(db && auth?.currentUser);
  const claimBlocked = localAuthorized && syncReady && productionCloudClaimsRequired() && !roleCanUseProductionWrites("streamOperator");
  if (streamerStudioControls) {
    streamerStudioControls.classList.toggle("is-disabled", !authorized || !syncReady);
  }
  if (streamerStudioAuthPanel) {
    streamerStudioAuthPanel.innerHTML = claimBlocked
      ? `
        <span class="streamer-status-kicker">Access Needed</span>
        <strong>Your account is not authorized for this event role.</strong>
        <p>Ask the event owner to assign Stream Studio access, then refresh your session.</p>
        <div class="streamer-card-actions" style="margin-top: 12px;">
          <button class="micro-button button-accent" type="button" data-action="refresh-cloud-session">Refresh Session</button>
        </div>
      `
      : !localAuthorized
      ? `
        <span class="streamer-status-kicker">Protected</span>
        <strong>Unlock event admin access to manage the live stream.</strong>
        <p>Spectators can watch, but only authorized users can start, stop, or manage the broadcast.</p>
        <div class="streamer-card-actions" style="margin-top: 12px;">
          <button class="micro-button button-accent" type="button" data-action="streamer-unlock-admin">Unlock Stream Studio</button>
        </div>
      `
      : !syncReady
        ? `
          <span class="streamer-status-kicker">Syncing</span>
          <strong>Preparing secure live sync.</strong>
          <p>Cloud auth is still connecting. Start Live Stream will unlock as soon as Sync Online is ready.</p>
          <div class="streamer-card-actions" style="margin-top: 12px;">
            <button class="micro-button" type="button" data-action="refresh-cloud-session">Refresh Session</button>
          </div>
        `
        : `
          <span class="streamer-status-kicker">Authorized</span>
          <strong>Stream Studio is unlocked.</strong>
          <p>Start the stream when the camera is framed. Layout switching is automatic and follows event admin state.</p>
        `;
  }
  [streamerCameraSelect, streamerMicSelect, streamerStartNativeStreamBtn].forEach((control) => {
    if (control) control.disabled = !authorized || !syncReady || nativeStreamActive;
  });
  if (streamerStopNativeStreamBtn) streamerStopNativeStreamBtn.disabled = !authorized || !nativeStreamActive;
  if (streamerMuteNativeStreamBtn) {
    streamerMuteNativeStreamBtn.disabled = !authorized || !nativeStreamLocalStream;
    streamerMuteNativeStreamBtn.textContent = nativeStreamAudioMuted ? "Unmute Mic" : "Mute Mic";
    streamerMuteNativeStreamBtn.classList.toggle("button-accent", nativeStreamAudioMuted);
  }
  if (streamerCameraNativeStreamBtn) {
    streamerCameraNativeStreamBtn.disabled = !authorized || !nativeStreamLocalStream;
    streamerCameraNativeStreamBtn.textContent = nativeStreamCameraEnabled ? "Camera Off" : "Camera On";
    streamerCameraNativeStreamBtn.classList.toggle("button-accent", !nativeStreamCameraEnabled);
  }
}

function buildNativeStreamStatePayload(overrides = {}) {
  const layoutKey = resolveNativeStreamLayoutKey();
  return {
    active: Boolean(overrides.active ?? nativeStreamActive),
    eventId: activeEventId || "",
    sessionId: nativeStreamSessionId || "",
    layoutKey,
    phaseLabel: getNativeStreamPhaseLabel(layoutKey),
    eventName: activeEventMeta?.name || "Prodigy RC Comp",
    transportMode: "webrtc-p2p",
    audioMuted: nativeStreamAudioMuted,
    cameraEnabled: nativeStreamCameraEnabled,
    hasVideoTrack: Boolean(nativeStreamLocalStream?.getVideoTracks?.()?.some((track) => track.readyState === "live" && track.enabled)),
    hasAudioTrack: Boolean(nativeStreamLocalStream?.getAudioTracks?.()?.some((track) => track.readyState === "live" && track.enabled)),
    startedAt: overrides.startedAt || nativeStreamLatestState?.startedAt || Date.now(),
    heartbeatAt: Date.now(),
    updatedAt: Date.now(),
  };
}

async function publishNativeStreamState(overrides = {}) {
  if (!db || !activeEventId || !auth?.currentUser) return;
  const payload = buildNativeStreamStatePayload(overrides);
  nativeStreamLatestState = payload;
  try {
    await firestoreWriteService.publishStreamState(activeEventId, payload);
    renderNativeLiveView();
  } catch (error) {
    handleCloudPermissionError(error, "streamOperator", "stream state");
    throw error;
  }
}

function closeNativePeerConnection(viewerId) {
  const peerRecord = nativeStreamPeerConnections.get(viewerId);
  if (peerRecord?.pc) {
    try { peerRecord.pc.close(); } catch {}
  }
  nativeStreamPeerConnections.delete(viewerId);
}

async function handleNativeViewerRequest(viewerId, viewerData = {}) {
  if (!nativeStreamActive || !nativeStreamLocalStream || !nativeStreamSessionId || !viewerId) return;
  const viewerUpdatedAt = Number(viewerData.updatedAt || viewerData.createdAt || 0);
  if (viewerUpdatedAt && Date.now() - viewerUpdatedAt > NATIVE_STREAM_VIEWER_TTL_MS) return;
  let peerRecord = nativeStreamPeerConnections.get(viewerId);
  if (!peerRecord) {
    const pc = new RTCPeerConnection(getNativeRtcConfiguration());
    peerRecord = { pc, broadcasterIce: [], addedViewerIce: new Set(), remoteSet: false };
    nativeStreamPeerConnections.set(viewerId, peerRecord);
    nativeStreamLocalStream.getTracks().forEach((track) => pc.addTrack(track, nativeStreamLocalStream));
    pc.onconnectionstatechange = () => {
      if (["failed", "disconnected", "closed"].includes(pc.connectionState)) {
        closeNativePeerConnection(viewerId);
      }
    };
    pc.onicecandidate = async (event) => {
      if (!event.candidate) return;
      peerRecord.broadcasterIce.push(event.candidate.toJSON());
      await setDoc(getNativeLiveViewerDocRef(activeEventId, nativeStreamSessionId, viewerId), {
        broadcasterIce: peerRecord.broadcasterIce,
        updatedAt: Date.now(),
      }, { merge: true }).catch((error) => console.error("Broadcaster ICE sync failed:", error));
    };
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    await setDoc(getNativeLiveViewerDocRef(activeEventId, nativeStreamSessionId, viewerId), {
      status: "offer",
      offer: pc.localDescription.toJSON(),
      layoutKey: resolveNativeStreamLayoutKey(),
      updatedAt: Date.now(),
    }, { merge: true });
  }
  if (viewerData.answer && !peerRecord.remoteSet) {
    await peerRecord.pc.setRemoteDescription(new RTCSessionDescription(viewerData.answer)).catch((error) => {
      console.error("Native stream answer failed:", error);
    });
    peerRecord.remoteSet = true;
  }
  (viewerData.viewerIce || []).forEach((candidate) => {
    const key = JSON.stringify(candidate);
    if (peerRecord.addedViewerIce.has(key)) return;
    peerRecord.addedViewerIce.add(key);
    peerRecord.pc.addIceCandidate(new RTCIceCandidate(candidate)).catch(() => {});
  });
}

async function listenForNativeStreamViewers() {
  if (!db || !activeEventId || !nativeStreamSessionId) return false;
  const authReady = await ensureCloudAuthReady();
  if (!authReady) return false;
  if (nativeStreamViewerUnsubscribe) nativeStreamViewerUnsubscribe();
  nativeStreamViewerUnsubscribe = streamReadService.subscribeViewerRequests(activeEventId, nativeStreamSessionId, (_docs, snapshot) => {
    snapshot.docChanges().forEach((change) => {
      const viewerId = change.doc.id;
      if (change.type === "removed") {
        closeNativePeerConnection(viewerId);
        return;
      }
      handleNativeViewerRequest(viewerId, change.doc.data()).catch((error) => console.error("Viewer connection failed:", error));
    });
  }, (error) => {
    console.error("Native viewer listener failed:", error);
    nativeStreamViewerUnsubscribe = null;
    ensureCloudAuthReady().then((ready) => {
      if (ready && nativeStreamActive && activeEventId && nativeStreamSessionId) {
        listenForNativeStreamViewers().catch((listenerError) => console.error("Native viewer listener retry failed:", listenerError));
      }
    });
  });
  return true;
}

async function startNativeStream() {
  if (!isNativeStreamerAuthorized()) {
    setNativeStreamStatus("Unlock event admin access before starting the stream.", "error");
    syncNativeStreamControlUi();
    return false;
  }
  const authReady = await ensureCloudAuthReady();
  if (!db || !authReady) {
    setNativeStreamStatus("Cloud sync is still connecting. Wait for Sync Online before starting the live stream.", "error");
    syncNativeStreamControlUi();
    return false;
  }
  if (!navigator.mediaDevices?.getUserMedia || typeof RTCPeerConnection === "undefined") {
    setNativeStreamStatus("This browser does not support native camera streaming.", "error");
    return false;
  }
  try {
    stopStreamerCameraPreview({ preserveStatus: true });
    nativeStreamSessionId = `${Date.now()}-${generateId()}`;
    nativeStreamLocalStream = await navigator.mediaDevices.getUserMedia(getNativeMediaConstraints());
    nativeStreamActive = true;
    nativeStreamAudioMuted = false;
    nativeStreamCameraEnabled = true;
    if (streamerLiveCameraVideo) {
      streamerLiveCameraVideo.srcObject = nativeStreamLocalStream;
      await streamerLiveCameraVideo.play().catch(() => {});
    }
    await refreshNativeStreamDevices();
    await publishNativeStreamState({ active: true, startedAt: Date.now() });
    const viewerListenerReady = await listenForNativeStreamViewers();
    if (!viewerListenerReady) {
      throw new Error("Viewer signaling could not attach because cloud auth is not ready yet.");
    }
    clearInterval(nativeStreamHeartbeatTimer);
    nativeStreamHeartbeatTimer = window.setInterval(() => {
      publishNativeStreamState({ active: true }).catch((error) => console.error("Native stream heartbeat failed:", error));
    }, NATIVE_STREAM_HEARTBEAT_MS);
    setNativeStreamStatus("Native live stream is on air. Layout switching is following event admin state.", "live");
    setStreamerCameraStatus("Native stream is live. This preview matches the spectator LIVE layout.", "live");
    syncStreamerCameraPreviewUi();
    syncNativeStreamControlUi();
    return true;
  } catch (error) {
    const roleDenied = handleCloudPermissionError(error, "streamOperator", "stream start");
    const denied = /denied|permission/i.test(String(error?.message || error?.name || ""));
    await stopNativeStream(false);
    setNativeStreamStatus(roleDenied
      ? getRoleAuthorizationMessage("streamOperator")
      : denied
        ? "Camera or microphone permission was denied."
        : "Native stream could not start. Check selected devices and browser permissions.", "error");
    return false;
  }
}

async function stopNativeStream(publishOffline = true) {
  clearInterval(nativeStreamHeartbeatTimer);
  nativeStreamHeartbeatTimer = null;
  if (nativeStreamViewerUnsubscribe) nativeStreamViewerUnsubscribe();
  nativeStreamViewerUnsubscribe = null;
  nativeStreamPeerConnections.forEach((_, viewerId) => closeNativePeerConnection(viewerId));
  nativeStreamPeerConnections = new Map();
  if (nativeStreamLocalStream) {
    nativeStreamLocalStream.getTracks().forEach((track) => track.stop());
  }
  nativeStreamLocalStream = null;
  nativeStreamActive = false;
  if (streamerLiveCameraVideo) {
    streamerLiveCameraVideo.pause?.();
    streamerLiveCameraVideo.srcObject = null;
  }
  if (publishOffline && db && activeEventId && auth?.currentUser) {
    await firestoreWriteService.publishStreamState(activeEventId, {
      active: false,
      sessionId: nativeStreamSessionId || "",
      layoutKey: resolveNativeStreamLayoutKey(),
      heartbeatAt: Date.now(),
      updatedAt: Date.now(),
    }).catch((error) => console.error("Native stream stop sync failed:", error));
  }
  setNativeStreamStatus("Native stream is offline.", "idle");
  setStreamerCameraStatus("Preview uses the selected camera and microphone locally before publishing to spectators.", "idle");
  syncStreamerCameraPreviewUi();
  syncNativeStreamControlUi();
}

function toggleNativeStreamAudio() {
  if (!nativeStreamLocalStream) return;
  nativeStreamAudioMuted = !nativeStreamAudioMuted;
  nativeStreamLocalStream.getAudioTracks().forEach((track) => {
    track.enabled = !nativeStreamAudioMuted;
  });
  publishNativeStreamState({ active: nativeStreamActive }).catch(() => {});
  syncNativeStreamControlUi();
}

function toggleNativeStreamCamera() {
  if (!nativeStreamLocalStream) return;
  nativeStreamCameraEnabled = !nativeStreamCameraEnabled;
  nativeStreamLocalStream.getVideoTracks().forEach((track) => {
    track.enabled = nativeStreamCameraEnabled;
  });
  publishNativeStreamState({ active: nativeStreamActive }).catch(() => {});
  syncNativeStreamControlUi();
}

function closeNativeViewerConnection(options = {}) {
  clearTimeout(nativeStreamViewerRetryTimer);
  nativeStreamViewerRetryTimer = null;
  if (nativeStreamViewerDocUnsubscribe) nativeStreamViewerDocUnsubscribe();
  nativeStreamViewerDocUnsubscribe = null;
  if (nativeStreamViewerPeer) {
    try { nativeStreamViewerPeer.close(); } catch {}
  }
  if (options.deleteDoc !== false && db && activeEventId && nativeStreamRemoteSessionId && nativeStreamViewerId) {
    deleteDoc(getNativeLiveViewerDocRef(activeEventId, nativeStreamRemoteSessionId, nativeStreamViewerId)).catch(() => {});
  }
  nativeStreamViewerPeer = null;
  nativeStreamRemoteStream = null;
  nativeStreamRemoteSessionId = null;
  nativeStreamViewerConnectionState = options.state || "idle";
  nativeStreamViewerMediaState = options.state || "idle";
  nativeStreamViewerPlayBlocked = false;
  nativeStreamViewerLastError = options.errorMessage || "";
  if (nativeLiveVideo) {
    nativeLiveVideo.pause?.();
    nativeLiveVideo.muted = true;
    nativeLiveVideo.defaultMuted = true;
    nativeLiveVideo.srcObject = null;
  }
  syncNativeLiveAudioButton();
}

async function startNativeViewerConnection(streamState = nativeStreamLatestState) {
  if (!db || !activeEventId || !streamState?.active || !streamState.sessionId || typeof RTCPeerConnection === "undefined") return;
  const authReady = await ensureCloudAuthReady();
  if (!authReady || !auth?.currentUser) return;
  if (nativeStreamRemoteSessionId === streamState.sessionId && nativeStreamViewerPeer) return;
  closeNativeViewerConnection({ deleteDoc: true });
  nativeStreamRemoteSessionId = streamState.sessionId;
  nativeStreamViewerId = nativeStreamViewerId || `viewer-${Date.now()}-${generateId()}`;
  const viewerId = nativeStreamViewerId;
  const pc = new RTCPeerConnection(getNativeRtcConfiguration());
  const remoteStream = new MediaStream();
  const viewerIce = [];
  const addedBroadcasterIce = new Set();
  let remoteOfferSet = false;
  nativeStreamViewerPeer = pc;
  nativeStreamRemoteStream = remoteStream;
  nativeStreamViewerConnectionState = "connecting";
  nativeStreamViewerMediaState = "connecting";
  nativeStreamViewerPlayBlocked = false;
  nativeStreamViewerLastError = "";
  if (nativeLiveVideo) {
    nativeLiveVideo.muted = true;
    nativeLiveVideo.defaultMuted = true;
    nativeLiveVideo.srcObject = remoteStream;
    playNativeLiveVideo({ withAudio: false }).catch(() => {});
  }
  pc.ontrack = (event) => {
    const incomingTracks = event.streams?.[0]?.getTracks?.()?.length
      ? event.streams[0].getTracks()
      : [event.track].filter(Boolean);
    incomingTracks.forEach((track) => {
      if (!remoteStream.getTracks().some((existing) => existing.id === track.id)) {
        remoteStream.addTrack(track);
      }
    });
    nativeStreamViewerMediaState = getNativeRemoteTrackCount("video") > 0 ? "live" : "connecting";
    playNativeLiveVideo({ withAudio: false }).catch(() => {});
    renderNativeLiveView();
  };
  pc.onconnectionstatechange = () => {
    nativeStreamViewerConnectionState = pc.connectionState || "connecting";
    if (["failed", "disconnected"].includes(pc.connectionState)) {
      nativeStreamViewerMediaState = "error";
      nativeStreamViewerLastError = `Peer connection ${pc.connectionState}.`;
      renderNativeLiveView();
      closeNativeViewerConnection({ deleteDoc: true, state: "error", errorMessage: nativeStreamViewerLastError });
      scheduleNativeViewerReconnect(pc.connectionState);
      return;
    }
    if (pc.connectionState === "connected") {
      nativeStreamViewerMediaState = getNativeRemoteTrackCount("video") > 0 ? "live" : "connecting";
    }
    renderNativeLiveView();
  };
  pc.onicecandidate = async (event) => {
    if (!event.candidate) return;
    viewerIce.push(event.candidate.toJSON());
    await setDoc(getNativeLiveViewerDocRef(activeEventId, streamState.sessionId, viewerId), {
      viewerIce,
      updatedAt: Date.now(),
    }, { merge: true }).catch((error) => console.error("Viewer ICE sync failed:", error));
  };
  await setDoc(getNativeLiveViewerDocRef(activeEventId, streamState.sessionId, viewerId), {
    status: "requesting",
    eventId: activeEventId,
    sessionId: streamState.sessionId,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  }, { merge: true });
  nativeStreamViewerDocUnsubscribe = streamReadService.subscribeViewerDoc(activeEventId, streamState.sessionId, viewerId, async (result) => {
    if (!result.exists || nativeStreamRemoteSessionId !== streamState.sessionId) return;
    const data = result.data;
    if (data.offer && !remoteOfferSet) {
      await pc.setRemoteDescription(new RTCSessionDescription(data.offer)).catch((error) => console.error("Viewer offer failed:", error));
      remoteOfferSet = true;
      const answer = await pc.createAnswer();
      await pc.setLocalDescription(answer);
      await setDoc(getNativeLiveViewerDocRef(activeEventId, streamState.sessionId, viewerId), {
        status: "answer",
        answer: pc.localDescription.toJSON(),
        updatedAt: Date.now(),
      }, { merge: true });
    }
    (data.broadcasterIce || []).forEach((candidate) => {
      const key = JSON.stringify(candidate);
      if (addedBroadcasterIce.has(key)) return;
      addedBroadcasterIce.add(key);
      pc.addIceCandidate(new RTCIceCandidate(candidate)).catch(() => {});
    });
  }, (error) => {
    nativeStreamViewerConnectionState = "failed";
    nativeStreamViewerMediaState = "error";
    nativeStreamViewerLastError = String(error?.message || error || "Viewer signaling failed.");
    renderNativeLiveView();
    console.error("Viewer signaling failed:", error);
  });
  renderNativeLiveView();
}

function applyNativeLiveStreamData(data = null) {
  nativeStreamLatestState = data && typeof data === "object" ? { ...data } : null;
  const isFresh = isNativeLiveStreamFresh(nativeStreamLatestState);
  if (isFresh && !nativeStreamActive) {
    startNativeViewerConnection(nativeStreamLatestState).catch((error) => console.error("Native viewer connection failed:", error));
  } else if (!nativeStreamActive) {
    closeNativeViewerConnection({ deleteDoc: true });
  }
  renderNativeLiveView();
}

function subscribeToNativeLiveStream() {
  if (!db || !auth?.currentUser || !activeEventId) return;
  if (nativeStreamMetaUnsubscribe) nativeStreamMetaUnsubscribe();
  nativeStreamMetaUnsubscribe = streamReadService.subscribeStreamState(activeEventId, (result) => {
    applyNativeLiveStreamData(result.exists ? result.data : null);
  }, (error) => console.error("Native live stream listener failed:", error));
  streamReadService.readStreamState(activeEventId).then((result) => {
    applyNativeLiveStreamData(result.exists ? result.data : null);
  }).catch((error) => console.error("Native live stream refresh failed:", error));
}

function renderStreamerScenePreviewCard(sceneKey, context = getStreamerSceneContext()) {
  const meta = STREAMER_SCENE_META[sceneKey];
  const focusedContext = context.sceneKey === sceneKey ? context : getStreamerSceneContext({
    ...streamerRouteState,
    scene: sceneKey,
    demo: context.demo,
  });
  const supportingLine = sceneKey === "battle"
    ? `${focusedContext.battle.left?.name || "Lead"} vs ${focusedContext.battle.right?.name || "Chase"}`
    : sceneKey === "qualifying"
      ? `${focusedContext.currentDriver?.name || "Current driver pending"}`
      : sceneKey === "results" || sceneKey === "event-complete"
        ? `${focusedContext.results.championName || "Champion pending"}`
        : focusedContext.eventName;
  return `
    <div class="streamer-card-preview">
      <div class="streamer-chip-row">
        <span class="streamer-chip accent">${escapeHtml(meta.badge)}</span>
        <span class="streamer-chip ${meta.transparent ? "overlay" : ""}">${escapeHtml(meta.overlayType)}</span>
      </div>
      <strong>${escapeHtml(meta.label)}</strong>
      <small>${escapeHtml(supportingLine || meta.description)}</small>
    </div>
  `;
}

