function maybeAutoBuildBracket() {
  if (isTeamTandemMode()) return false;
  if (tournamentState?.mainBracket?.rounds?.length) return false;
  const validation = getBracketValidationState();
  if (!validation.buildReady) return false;
  const requestedMainSize = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;
  setTournamentStateState(createTournamentState(
    validation.rankedDrivers,
    normalizePreferredFormat(bracketModeSelect.value || FORMAT_CLASSIC),
    requestedMainSize,
  ), { syncQualifying: false });
  setCompetitionBracketPageState(tournamentState.lowerBracket ? "lower" : "main");
  saveBracketPagePreference(activeEventId, activeCompetitionBracketPage);
  return true;
}

function syncNetworkStatusIndicator() {
  const statusEl = document.getElementById("syncStatus");
  if (!statusEl || STANDALONE_DEMO_MODE) return;
  if (typeof navigator !== "undefined" && navigator.onLine === false) {
    statusEl.textContent = "Browser Offline";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    return;
  }
  if (isOfflineMode()) {
    statusEl.textContent = "Offline Protected";
    statusEl.classList.remove("online", "connecting");
    statusEl.classList.add("offline-protected");
    return;
  }
  if (!db || !auth?.currentUser) {
    statusEl.textContent = "Sync Connecting";
    statusEl.classList.remove("online", "offline-protected");
    statusEl.classList.add("connecting");
    return;
  }
  statusEl.textContent = "Sync Online";
  statusEl.classList.add("online");
  statusEl.classList.remove("offline-protected", "connecting");
}

