createEventSubmitBtn.addEventListener("click", async () => {
  if (!isWebsiteAdmin) return;
  const name = eventNameInput.value.trim();
  const date = eventDateInput.value;
  const competitionMode = normalizeCompetitionMode(competitionModeInput?.value);
  const tech1Mode = competitionMode === COMPETITION_MODE_TECH1_ANNIVERSARY;
  const teamTandemMode = competitionMode === COMPETITION_MODE_TEAM_TANDEM;
  const judgingMode = tech1Mode
    ? JUDGING_MODE_AVERAGE
    : teamTandemMode
    ? JUDGING_MODE_LINE_ANGLE_STYLE
    : normalizeJudgingMode(judgingModeInput?.value);
  const judgeCount = teamTandemMode ? 3 : normalizeJudgeCountForMode(judgeCountInput.value, judgingMode);
  const rawVenueConfig = collectVenueConfigFromForm();
  const venueConfig = rawVenueConfig.qrCheckInEnabled ? issueVenueQrConfig(rawVenueConfig) : rawVenueConfig;
  const invites = { admin: "", j1: "", j2: "", j3: "" };
  const roleNames = {
    j1: judge1NameInput.value.trim(),
    j2: judge2NameInput.value.trim(),
    j3: judge3NameInput.value.trim(),
  };

  if (!name || !date) {
    createEventError.textContent = "Complete the event name and date before creating the competition.";
    createEventError.style.display = "block";
    return;
  }

  if (venueConfig.enabled && !hasValidVenueConfig({ venueConfig })) {
    createEventError.textContent = "Enable self-registration only after adding valid venue coordinates and a positive radius.";
    createEventError.style.display = "block";
    return;
  }

  if (createEventModalMode === "edit") {
    if (!activeEventMeta || !activeEventId) {
      createEventError.textContent = "Open an event before editing it.";
      createEventError.style.display = "block";
      return;
    }

    const nextRoleNames = buildDefaultRoleNames({
      ...(activeEventMeta.roleNames || {}),
      ...roleNames,
    });

    setActiveEventMetaState({
      ...activeEventMeta,
      name,
      date,
      judgeCount,
      judgingMode,
      competitionMode,
      modeSettings: getCompetitionModeSettings(competitionMode, { eventId: activeEventId, eventName: name }),
      venueConfig,
      roleNames: nextRoleNames,
      updatedAt: new Date().toISOString(),
    }, { syncQualifying: false });
    eventDirectory[activeEventId] = cloneEventMeta(activeEventMeta);
    saveDirectoryCache();
    saveEventStateCache();

    const removedJudgeRoles = JUDGE_ROLE_ORDER.filter((role, index) => index >= judgeCount);
    removedJudgeRoles.forEach((role) => {
      setRoleUnlockedForEvent(activeEventId, role, false);
    });

    const saved = await publishStateImmediately();
    if (saved === false) {
      createEventError.textContent = "Event settings could not be saved to cloud sync. Refresh your session and try again.";
      createEventError.style.display = "block";
      return;
    }
    if (tech1Mode) {
      await publishTech1SpecialEventShell({ showSuccessAlert: false });
      const currentControl = tech1SpecialEventState.bracket?.tech1JudgeControl || null;
      if (currentControl?.matchId && currentControl.status === "voting") {
        const nextBracket = {
          ...tech1SpecialEventState.bracket,
          tech1JudgeControl: {
            ...currentControl,
            judgeRoles: getTech1JudgeRoles(activeEventMeta),
            updatedAt: new Date().toISOString(),
          },
        };
        if (!shouldUseTech1LocalStore()) {
          await firestoreWriteService.publishSpecialEventBracket(getActiveTech1SpecialEventId(), nextBracket);
        }
        updateTech1SpecialEventState({ bracket: nextBracket });
      }
    }
    syncScheduledActiveEventSelection({ publishSelection: Boolean(isWebsiteAdmin && !localEventPreviewMode) });
    renderEventDirectory();
    renderRoleAdminPanel();
    renderDriversTable();
    if (document.getElementById('view-bracket').classList.contains('is-active')) {
      renderBracket();
    }
    hideCreateEventModal();
    window.alert("Event settings were updated.");
    return;
  }

  const eventMeta = await createEventRecord({ name, date, invites, roleNames, judgeCount, judgingMode, competitionMode, venueConfig });
  setDeletedEventId(eventMeta.id, false);
  eventDirectory[eventMeta.id] = eventMeta;
  saveDirectoryCache();
  hideCreateEventModal();
  openEventById(eventMeta.id, "registration", true);
  applyActiveEventState({
    drivers: createDriverSet(),
    bracket: null,
    twinComp: null,
    qualifyingFlow: createEmptyQualifyingFlow(),
    formatMode: FORMAT_CLASSIC,
    lowerCount: "0",
  });
  saveEventStateCache();
  await publishStateImmediately();
  applyRoleChange("spectator");
  renderDriversTable();
  globalRoleSelect.value = "admin";
  showPasswordModal("admin");
});

