document.addEventListener("click", async (event) => {
  const streamerActionButton = event.target.closest("[data-action^='streamer-']");
  if (!streamerActionButton) return;
  const action = streamerActionButton.dataset.action || "";
  const scene = normalizeStreamerScene(streamerActionButton.dataset.scene || streamerFeaturedScene);
  const variant = normalizeStreamerVariant(streamerActionButton.dataset.variant || "scene");
  const previewUrl = streamerActionButton.dataset.url || "";

  if (action === "streamer-select-scene") {
    streamerFeaturedScene = scene;
    openStreamerRoute({
      ...streamerRouteState,
      view: "streamer-dashboard",
      scene,
    });
    return;
  }

  if (action === "streamer-unlock-admin") {
    requestRoleAccess("admin");
    return;
  }

  if (action === "streamer-copy-live-link") {
    const copied = await copyTextToClipboard(getNativeLiveViewerUrl());
    if (!copied) window.prompt("Copy the spectator LIVE link:", getNativeLiveViewerUrl());
    else window.alert("Spectator LIVE link copied.");
    return;
  }

  if (action === "streamer-copy-obs") {
    await copyStreamerRouteLink({
      view: "streamer-scene",
      scene,
      variant,
      demo: streamerRouteState.demo,
    }, "preview URL");
    return;
  }

  if (action === "streamer-copy-demo-obs") {
    await copyStreamerRouteLink({
      view: "streamer-scene",
      scene,
      variant,
      demo: true,
    }, "demo preview URL");
    return;
  }

  if (action === "streamer-open-preview" || action === "streamer-open-scene") {
    const openedWindow = window.open(previewUrl, "_blank", "noopener");
    if (!openedWindow) {
      window.alert("Please allow pop-ups to open the broadcast scene preview.");
    }
    return;
  }

  if (action === "streamer-open-demo") {
    openStreamerRoute({
      ...streamerRouteState,
      view: "streamer-demo",
      demo: true,
    });
    return;
  }

  if (action === "streamer-open-demo-scene") {
    openStreamerRoute({
      view: "streamer-scene",
      scene,
      variant,
      demo: true,
    }, { newTab: true });
  }
});

