function renderQualifyingOrder(rankedDrivers, plan) {
  const qResults = document.getElementById("qualifyingResults");
  const teamTandemMode = isTeamTandemMode(activeEventMeta);
  const tieInfo = getTopQualifierTieInfo(rankedDrivers);
  const fullscreenStandingsLimit = document.body.classList.contains("qualifying-fullscreen") ? 10 : rankedDrivers.length;
  const visibleStandingsDrivers = rankedDrivers.slice(0, fullscreenStandingsLimit);
  const standingsSignature = visibleStandingsDrivers.map((driver, index) => `${index + 1}:${driver.id}:${formatScore(driver.bestScore)}`).join("|");
  const shouldAnimateStandings = lastStandingsSignature !== null && standingsSignature !== lastStandingsSignature;
  lastStandingsSignature = standingsSignature;
  qResults.innerHTML = "";
  qResults.classList.remove("empty-state");

  if (teamTandemMode) {
    topQualifierTiePanel.classList.add("hidden");
    topQualifierTiePanel.textContent = "";
    if (!rankedDrivers.length) {
      qResults.textContent = "Register at least 2 teams to unlock the randomized Team Tandem bracket.";
      qResults.classList.add("empty-state");
      return;
    }
    const list = document.createElement("ol");
    list.className = "qualifying-results-simple";
    visibleStandingsDrivers.forEach((team, index) => {
      const item = document.createElement("li");
      item.innerHTML = `
        <div class="standings-row-main">
          <span class="standings-rank">${index + 1}.</span>
          <span class="standings-driver-name">${escapeHtml(team.name || `Team ${index + 1}`)}</span>
        </div>
        <span class="standings-score">${escapeHtml(getTeamTandemMemberSummary(team) || getTeamTandemMetaLine(team) || "Team roster pending")}</span>
      `;
      list.appendChild(item);
    });
    qResults.appendChild(list);
    return;
  }

  if (!rankedDrivers.length) {
    lastStandingsSignature = null;
    topQualifierTiePanel.classList.add("hidden");
    topQualifierTiePanel.textContent = "";
    qResults.textContent = "Add driver names in registration, then enter scores to build the standings.";
    qResults.classList.add("empty-state");
    return;
  }

  if (tieInfo) {
    const names = tieInfo.tiedDrivers.map((driver) => formatDriverDisplayName(driver)).join(", ");
    topQualifierTiePanel.classList.remove("hidden");
    topQualifierTiePanel.textContent = `Top qualifier tie: ${names}. Lower registration order keeps the higher seed automatically.`;
  } else {
    topQualifierTiePanel.classList.add("hidden");
    topQualifierTiePanel.textContent = "";
  }

  const cutoffCount = plan ? plan.qualifiedCount : rankedDrivers.length;
  const list = document.createElement("ol");
  list.className = `qualifying-results-simple ${shouldAnimateStandings ? "is-animating" : ""}`;

  visibleStandingsDrivers.forEach((driver, index) => {
    const isQualified = index < cutoffCount;
    const item = document.createElement("li");
    if (!isQualified) item.classList.add("is-dimmed");
    if (shouldAnimateStandings) item.style.setProperty("--standings-delay", `${Math.min(index * 38, 300)}ms`);
    const trophyMarkup = getStandingsTrophyMarkup(index);
    item.innerHTML = `
      <div class="standings-row-main">
        <span class="standings-rank">${index + 1}.</span>
        ${trophyMarkup}
        <span class="standings-driver-name">${escapeHtml(formatDriverDisplayName(driver))}</span>
      </div>
      <span class="standings-score">Best score: ${escapeHtml(formatScore(driver.bestScore))}</span>
    `;
    list.appendChild(item);
  });

  qResults.appendChild(list);
}

function updateQualifyingDensity() {
  const rankedDrivers = rankDrivers(appDrivers);
  let density = "standard";
  if (rankedDrivers.length >= 26) {
    density = "ultra";
  } else if (rankedDrivers.length >= 16) {
    density = "compact";
  }
  document.body.dataset.qualifyingDensity = density;
}

function renderSpectatorSpotlightCard(label, title, copy) {
  return `
    <article class="spectator-spotlight-card">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(title || "Pending")}</strong>
      <small>${escapeHtml(copy || "Details will update as the event progresses.")}</small>
    </article>
  `;
}

function renderDriverSpotlightCards(driver, queue = []) {
  if (currentRole !== "spectator" || !driver) return "";
  const currentIndex = queue.findIndex((entry) => entry.id === driver.id);
  const onDeck = currentIndex > -1 ? queue[currentIndex + 1] || null : null;
  const bestScore = getBestScore(getLiveRunAverage(driver, 1), getLiveRunAverage(driver, 2));
  return `
    <div class="spectator-spotlight-grid" aria-label="Driver spotlight">
      ${renderSpectatorSpotlightCard("Driver Spotlight", formatDriverDisplayName(driver), driver.teamName || driver.chassis || "Independent driver")}
      ${renderSpectatorSpotlightCard("Car / Chassis", driver.chassis || "Chassis TBA", bestScore !== null ? `Best live score ${formatScore(bestScore)}` : "Score pending")}
      ${renderSpectatorSpotlightCard("On Deck", onDeck?.name || "Waiting", onDeck ? (onDeck.teamName || onDeck.chassis || "Next driver queued") : "Final driver is on track")}
    </div>
  `;
}

function renderTeamBattleSpotlightCards(entry) {
  if (currentRole !== "spectator" || !entry?.match?.left || !entry?.match?.right) return "";
  const left = entry.match.left;
  const right = entry.match.right;
  return `
    <div class="spectator-spotlight-grid" aria-label="Team battle spotlight">
      ${renderSpectatorSpotlightCard("Now Battling", `${left.name || "Team 1"} vs ${right.name || "Team 2"}`, entry.meta || entry.title || "Current battle")}
      ${renderSpectatorSpotlightCard("Team 1", left.name || "Team 1", getTeamTandemMemberSummary(left) || getTeamTandemMetaLine(left) || "Lineup pending")}
      ${renderSpectatorSpotlightCard("Team 2", right.name || "Team 2", getTeamTandemMemberSummary(right) || getTeamTandemMetaLine(right) || "Lineup pending")}
    </div>
  `;
}

function renderQualifyingLivePanel() {
  if (!qualifyingLivePanel) return;
  if (isTeamTandemMode(activeEventMeta)) {
    const teamEntries = getTeamTandemRosterEntries(appDrivers);
    const bracketPublished = Boolean(tournamentState?.mainBracket?.rounds?.length);
    const currentEntry = getCompetitionFlowEntriesForState(tournamentState).currentEntry || null;
    qualifyingLivePanel.innerHTML = `
      <div class="qualifying-live-card">
        <p class="qualifying-live-kicker">Team Tandem Status</p>
        <div class="qualifying-live-driver">${escapeHtml(bracketPublished ? "Bracket Live" : "Randomized Bracket Only")}</div>
        <div class="qualifying-live-note">${escapeHtml(bracketPublished
          ? (currentEntry?.match?.left?.name && currentEntry?.match?.right?.name
            ? `${currentEntry.match.left.name} vs ${currentEntry.match.right.name} is the current battle.`
            : "Open Competition to start the next Team Tandem battle.")
          : `${teamEntries.length} team${teamEntries.length === 1 ? "" : "s"} registered. Launch the bracket directly from registration when the roster is ready.`)}</div>
        ${renderTeamBattleSpotlightCards(currentEntry)}
      </div>
    `;
    return;
  }
  if (isTwinTripleMode(activeEventMeta)) {
    const state = getTwinCompState();
    const round = getTwinCompCurrentRound(state);
    const currentTeam = getCurrentQualifyingDriver();
    const latest = state.latestScore;
    const winner = state.winnerName || (state.winnerId ? state.teams.find((team) => team.id === state.winnerId)?.name : null);
    const eliminationLimit = getTwinCompEliminationLimit();
    const scoredCount = round?.teamIds?.filter((teamId) => getTwinCompTeamRoundScore(teamId, round)).length || 0;
    const totalCount = round?.teamIds?.length || getTwinCompActiveTeams(state).length || getRegisteredDrivers(appDrivers).length;
    qualifyingLivePanel.innerHTML = `
      <div class="qualifying-live-card">
        <div class="qualifying-live-head">
          <div>
            <p class="qualifying-live-kicker">${escapeHtml(getTwinCompModeTitle())}</p>
            <div class="qualifying-live-driver">${escapeHtml(winner ? `Winner: ${winner}` : currentTeam ? (currentTeam.teamName || currentTeam.name || "Current Team") : "Waiting For Round")}</div>
            <div class="qualifying-live-meta">Round ${round?.number || Math.max(state.roundNumber || 0, 1)} | ${scoredCount}/${totalCount} teams scored</div>
          </div>
          <div class="qualifying-live-progress">${getTwinCompActiveTeams(state).length} Active</div>
        </div>
        <div class="qualifying-live-stats">
          <div class="qualifying-live-stat"><span>Latest Score</span><strong>${formatScore(latest?.score ?? null)}</strong></div>
          <div class="qualifying-live-stat"><span>Elim Points</span><strong>${currentTeam ? (state.teams.find((team) => team.id === currentTeam.id)?.eliminationPoints || 0) : "-"}/${eliminationLimit}</strong></div>
          <div class="qualifying-live-stat"><span>Eliminated</span><strong>${state.teams.filter((team) => !team.active).length}</strong></div>
        </div>
        <div class="qualifying-live-footer">
          <div class="qualifying-ready-list">${renderTwinCompStandingsList(state, { compact: true })}</div>
          <div class="qualifying-live-actions">
            <div class="qualifying-live-note">The bottom half of finalized scores receive 1 point. Teams are eliminated at ${eliminationLimit} points, and final rounds keep one survivor.</div>
          </div>
        </div>
      </div>
    `;
    return;
  }
  syncQualifyingFlowState();
  const queue = getQualifyingDriverQueue();
  const currentDriver = getCurrentQualifyingDriver();
  const qualifyingPhase = getQualifyingFlowPhase(qualifyingFlow, appDrivers);
  if (qualifyingPhase === "empty") {
    lastQualifyingDriverId = null;
    lastQualifyingLiveScoreSignature = "";
    qualifyingLivePanel.innerHTML = `
      <div class="qualifying-live-card">
        <p class="qualifying-live-kicker">Now Qualifying</p>
        <div class="qualifying-live-driver">Waiting For Drivers</div>
        <div class="qualifying-live-note">Add driver names in registration to start the live qualifying queue.</div>
      </div>
    `;
    return;
  }

  if (qualifyingPhase === "waiting") {
    lastQualifyingDriverId = null;
    lastQualifyingLiveScoreSignature = "";
    qualifyingLivePanel.innerHTML = `
      <div class="qualifying-live-card">
        <p class="qualifying-live-kicker">Qualifying Status</p>
        <div class="qualifying-live-driver">Waiting To Start</div>
        <div class="qualifying-live-note">Event admin can start qualifying once the driver list is ready.</div>
      </div>
    `;
    return;
  }

  if (qualifyingPhase === "complete" || !currentDriver) {
    lastQualifyingDriverId = null;
    lastQualifyingLiveScoreSignature = "";
    qualifyingLivePanel.innerHTML = `
      <div class="qualifying-live-card">
        <p class="qualifying-live-kicker">Qualifying Status</p>
        <div class="qualifying-live-driver">Qualifying Complete</div>
        <div class="qualifying-live-note">All registered drivers have finished their qualifying runs.</div>
      </div>
    `;
    return;
  }

  const currentIndex = Math.max(0, queue.findIndex((driver) => driver.id === currentDriver.id));
  const run1Avg = getLiveRunAverage(currentDriver, 1);
  const run2Avg = getLiveRunAverage(currentDriver, 2);
  const bestScore = getBestScore(run1Avg, run2Avg);
  const liveScoreSignature = `${currentDriver.id}:${formatScore(run1Avg)}|${formatScore(run2Avg)}|${formatScore(bestScore)}`;
  const shouldAnimateLiveScore = Boolean(lastQualifyingLiveScoreSignature && liveScoreSignature !== lastQualifyingLiveScoreSignature);
  lastQualifyingLiveScoreSignature = liveScoreSignature;
  const activeJudgeRoles = getActiveJudgeRoles(activeEventMeta);
  const shouldAnimateCurrentDriver = lastQualifyingDriverId !== null && currentDriver.id !== lastQualifyingDriverId;
  lastQualifyingDriverId = currentDriver.id;
  const readyMarkup = activeJudgeRoles.map((role) => {
    const isReady = hasSubmittedRequiredRuns(currentDriver, role);
    const justSubmitted = isReady && isJudgeSubmissionFeedbackActive(currentDriver.id, role);
    return `<span class="qualifying-ready-pill ${isReady ? "is-ready" : ""} ${justSubmitted ? "just-submitted" : ""}">${escapeHtml(getRoleDisplayName(role))} ${isReady ? "Submitted" : "Waiting"}</span>`;
  }).join("");

  qualifyingLivePanel.innerHTML = `
    <div class="qualifying-live-card ${shouldAnimateCurrentDriver ? "is-advancing" : ""}">
      <div class="qualifying-live-head">
        <div>
          <p class="qualifying-live-kicker">Now Qualifying</p>
            <div class="qualifying-live-driver">${escapeHtml(formatDriverDisplayName(currentDriver))}</div>
          <div class="qualifying-live-meta">Reg #${escapeHtml(formatDriverRegistrationNumber(currentDriver))} | Driver ${currentIndex + 1} of ${queue.length}</div>
          ${currentRole === "spectator" ? `<div class="qualifying-live-note">Spotlight driver for ${escapeHtml(activeEventMeta?.name || "the current event")}</div>` : ""}
        </div>
        <div class="qualifying-live-progress">${currentIndex + 1}/${queue.length}</div>
      </div>
      <div class="qualifying-live-stats">
        <div class="qualifying-live-stat ${shouldAnimateLiveScore ? "score-just-updated" : ""}">
          <span>${getQualifyingRunAggregateLabel(1, activeEventMeta, { live: true })}</span>
          <strong>${formatScore(run1Avg)}</strong>
        </div>
        <div class="qualifying-live-stat ${shouldAnimateLiveScore ? "score-just-updated" : ""}">
          <span>${getQualifyingRunAggregateLabel(2, activeEventMeta, { live: true })}</span>
          <strong>${formatScore(run2Avg)}</strong>
        </div>
        <div class="qualifying-live-stat ${shouldAnimateLiveScore ? "score-just-updated" : ""}">
          <span>${usesCategoryJudging(activeEventMeta) ? "Best Total" : "Best Score"}</span>
          <strong>${formatScore(bestScore)}</strong>
        </div>
      </div>
      ${renderDriverSpotlightCards(currentDriver, queue)}
      <div class="qualifying-live-footer">
        <div class="qualifying-ready-list">${readyMarkup}</div>
        <div class="qualifying-live-actions">
          <div class="qualifying-live-note">${usesCategoryJudging(activeEventMeta)
            ? "Advances automatically when Line, Angle, and Style are all submitted for this driver."
            : "Advances automatically when all active judges submit scores for this driver."}</div>
        </div>
      </div>
    </div>
  `;
}

function updateQualifying() {
  syncForcedJudgeRoleFromUnlockedState();
  const teamTandemMode = isTeamTandemMode(activeEventMeta);
  const rankedDrivers = teamTandemMode ? buildTeamTandemOrderedParticipants(appDrivers) : rankDrivers(appDrivers);
  const enteredDriverCount = teamTandemMode ? getTeamTandemRosterEntries(appDrivers).length : getEnteredDriverCount(appDrivers);
  const customLowerCount = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;
  const plan = teamTandemMode
    ? getTeamTandemCompetitionPlan(rankedDrivers.length)
    : getCompetitionPlan(rankedDrivers.length, bracketModeSelect.value, customLowerCount);
  const ready = rankedDrivers.length >= 2;
  const autoBuiltBracket = teamTandemMode ? false : maybeAutoBuildBracket();

  let modeLabel = "Classic bracket";
  if (isSdcFormat(bracketModeSelect.value)) {
    modeLabel = `SDC bracket Top ${getRequestedSdcMainBracketSize(bracketModeSelect.value)}`;
  }

  let planDescription = plan.description;
  if (!teamTandemMode && isSdcFormat(bracketModeSelect.value)) {
    const selectedSize = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;
    const scoredValidSizes = getValidSdcMainBracketSizes(rankedDrivers.length);
    if (selectedSize && !scoredValidSizes.includes(selectedSize)) {
      planDescription = `SDC Top ${selectedSize} selected. ${rankedDrivers.length} scored driver${rankedDrivers.length === 1 ? "" : "s"} ready now out of ${enteredDriverCount} entered. This bracket can launch once at least ${selectedSize} drivers have qualifying scores.`;
    }
  }

  renderQualifyingOrder(rankedDrivers, plan);
  renderQualifyingLivePanel();
  updateQualifyingDensity();
  renderCommandCenter();
  if (autoBuiltBracket) publishState();
  if (ready) launchWarning.style.display = 'none';
}

function applySearchFilter() {
  const query = getRosterSearchQuery();
  [...driversTableBody.querySelectorAll("tr")].forEach((row) => {
    const id = row.dataset.id;
    const driver = appDrivers.find(d => d.id === id);
    if (!driver) return;
    row.classList.toggle("hidden", !matchesDriverSearchQuery(driver, query));
  });
  [...mobileDriversList.querySelectorAll("[data-id]")].forEach((card) => {
    const id = card.dataset.id;
    const driver = appDrivers.find(d => d.id === id);
    if (!driver) return;
    card.classList.toggle("hidden", !matchesDriverSearchQuery(driver, query));
  });
}

