function renderTech1PodiumRevealRow(place, label, driver, revealed, canReveal) {
  const placeText = place === 1 ? "1st Place" : place === 2 ? "2nd Place" : "3rd Place";
  const revealText = `Click to reveal (${label})`;
  const prompt = revealed
    ? `<strong class="tech1-podium-reveal-name">${escapeHtml(driver?.name || "TBD")}</strong>`
    : `<span class="tech1-podium-reveal-prompt">${escapeHtml(revealText)}</span>`;
  return `
    <button
      class="tech1-podium-reveal-row ${revealed ? "is-revealed" : ""} ${canReveal || revealed ? "" : "is-locked"}"
      type="button"
      data-tech1-action="podium-reveal-place"
      data-place="${place}"
      ${canReveal || revealed ? "" : "disabled"}
      aria-label="${escapeAttributeValue(revealText)}"
    >
      <span class="tech1-podium-reveal-place">${placeText}</span>
      <span class="tech1-podium-reveal-body">${prompt}</span>
    </button>
  `;
}

function renderTech1PodiumRevealCard(bracket = null, options = {}) {
  if (!isTech1PodiumRevealVisible(bracket)) return "";
  if (isTech1PodiumRevealDismissed(bracket)) return "";
  const revealState = getTech1PodiumRevealState(bracket);
  const podium = getTech1PodiumDrivers(bracket);
  const hasThirdPlaceWinner = Boolean(podium.third?.id);
  const canRevealThird = hasThirdPlaceWinner;
  const canRevealFirst = hasThirdPlaceWinner && revealState[3];
  const canRevealSecond = false;
  const revealReady = isTech1PodiumRevealReady(bracket);
  const showCloseButton = canControlTech1PodiumReveal();
  const extraClass = options.className ? ` ${options.className}` : "";
  return `
    <article class="tech1-podium-reveal-card ${isTech1PodiumFullyRevealed(bracket) ? "is-complete" : ""}${extraClass}" data-tech1-podium-signature="${escapeAttributeValue(getTech1PodiumRevealSignature(bracket))}">
      <div class="tech1-podium-reveal-head">
        <strong>${revealReady ? "Podium Ready" : "Podium Pending"}</strong>
        <span>${revealReady ? "Trophy reveal sequence" : "Finish 3rd place result to unlock reveal"}</span>
      </div>
      <div class="tech1-podium-reveal-list">
        ${renderTech1PodiumRevealRow(1, "Winner of bracket", podium.first, revealState[1], canRevealFirst)}
        ${renderTech1PodiumRevealRow(2, "Runner up (reveals with 1st place)", podium.second, revealState[2], canRevealSecond)}
        ${renderTech1PodiumRevealRow(3, "3rd place winner", podium.third, revealState[3], canRevealThird)}
      </div>
      ${showCloseButton ? `
        <div class="tech1-podium-reveal-actions">
          <button class="button button-secondary" type="button" data-tech1-action="close-podium-reveal">Leave Podium Reveal</button>
        </div>
      ` : ""}
    </article>
  `;
}

function renderTech1FullscreenPodiumRevealOverlay(bracket = null) {
  const shouldRenderInFullscreen = document.body.classList.contains("bracket-fullscreen")
    || document.body.dataset.tech1PersistFullscreen === "true";
  if (!shouldRenderInFullscreen) return "";
  if (!isTech1PodiumRevealVisible(bracket)) return "";
  const cardMarkup = renderTech1PodiumRevealCard(bracket, { className: "tech1-podium-reveal-card-fullscreen" });
  if (!cardMarkup) return "";
  const branding = TECH1DRIFT_ANNIVERSARY_CONFIG.branding || {};
  const lightLogo = branding.logoLight || branding.logo || "./assets/tech1drift-vector-transparent-black.svg";
  const darkLogo = branding.logoDark || branding.logo || "./assets/tech1drift-vector-transparent.svg";
  const alt = branding.logoAlt || "Tech 1 Drift logo";
  return `
    <div class="tech1-podium-fullscreen-shell" aria-live="polite">
      <div class="tech1-podium-fullscreen-logo" aria-hidden="true">
        <img class="tech1-logo-light" src="${escapeAttributeValue(lightLogo)}" alt="${escapeAttributeValue(alt)}" />
        <img class="tech1-logo-dark" src="${escapeAttributeValue(darkLogo)}" alt="${escapeAttributeValue(alt)}" />
      </div>
      ${cardMarkup}
    </div>
  `;
}

function renderTech1CompetitionBracketView() {
  setBracketReorderUiState({ bracketReorderModeEnabled: false });
  clearBracketSwapSource();
  const summaryStrip = document.getElementById("summaryStrip");
  if (summaryStrip) {
    summaryStrip.innerHTML = "";
    summaryStrip.style.display = "none";
  }
  document.getElementById("battleFlowPanel")?.classList.add("hidden");
  const battleFlowContent = document.getElementById("battleFlowContent");
  if (battleFlowContent) battleFlowContent.innerHTML = "";
  document.getElementById("competitionBracketTabs")?.classList.add("hidden");
  document.getElementById("lowerBracketRuleAlert")?.classList.add("hidden");
  document.getElementById("lowerBracketPage")?.classList.remove("is-active");
  document.getElementById("mainBracketPage")?.classList.add("is-active");
  const lowerBracketBoard = document.getElementById("lowerBracketBoard");
  if (lowerBracketBoard) lowerBracketBoard.innerHTML = "";
  document.getElementById("championBanner")?.classList.add("hidden");
  if (winnerRevealOverlay) {
    winnerRevealOverlay.classList.add("hidden");
    winnerRevealOverlay.innerHTML = "";
  }
  if (competitionDecisionPanel) {
    competitionDecisionPanel.classList.add("hidden");
    competitionDecisionPanel.innerHTML = "";
  }
  document.getElementById("competitionReviewBanner")?.classList.add("hidden");
  document.getElementById("competitionOmtOverlay")?.classList.add("hidden");
  document.getElementById("emptyBracketState")?.classList.add("hidden");
  const mainBracketTitle = document.getElementById("mainBracketTitle");
  if (mainBracketTitle) mainBracketTitle.textContent = "Tech 1 Drift Anniversary";
  const bracketBoard = document.getElementById("bracketBoard");
  const judgeOnlyView = Boolean(currentRole?.startsWith("j"));
  syncTech1VsBattlePresentation(tech1SpecialEventState.bracket);
  if (bracketBoard) {
    bracketBoard.classList.toggle("hidden", judgeOnlyView);
    bracketBoard.innerHTML = judgeOnlyView ? "" : renderTech1SoloStyleCompetitionPanel(buildTech1ControlViewModel());
  }
  requestAnimationFrame(() => syncTech1VsOverlayAnchor());
  requestAnimationFrame(() => requestAnimationFrame(() => syncTech1VsOverlayAnchor()));
  const shouldKeepDecisionPanelVisible = isTech1PodiumRevealVisible(tech1SpecialEventState.bracket);
  const podiumRevealMarkup = shouldKeepDecisionPanelVisible
    ? renderTech1PodiumRevealCard(tech1SpecialEventState.bracket)
    : "";
  if (shouldKeepDecisionPanelVisible && competitionDecisionPanel) {
    if (canControlTech1PodiumReveal() && podiumRevealMarkup) {
      competitionDecisionPanel.innerHTML = `
        <div class="winner-reveal-stage tech1-winner-reveal-stage">
          ${podiumRevealMarkup}
        </div>
      `;
      competitionDecisionPanel.classList.add("is-contest-overlay");
      competitionDecisionPanel.classList.remove("hidden");
    } else {
      competitionDecisionPanel.classList.add("hidden");
      competitionDecisionPanel.innerHTML = "";
      competitionDecisionPanel.classList.remove("is-contest-overlay");
    }
  }
  renderCompetitionJudgePanel();
  if (!shouldKeepDecisionPanelVisible || !podiumRevealMarkup) {
    renderTech1CompetitionDecisionPanel();
  }
  scheduleBracketRefit();
}

function openTech1PodiumRevealFromJudgePhone() {
  if (!tech1JudgeOneCanRevealPodium()) {
    showRoleAuthorizationNotice("j1", "open Tech 1 podium reveal");
    return;
  }
  const bracket = normalizeTech1ThirdPlaceMatch(tech1SpecialEventState.bracket);
  if (!isTech1PodiumRevealVisible(bracket)) {
    window.alert("Finish the Tech 1 final battle before opening the podium reveal.");
    return;
  }
  tech1PodiumRevealDismissedSignature = "";
  setCompetitionBracketPageState("main");
  saveBracketPagePreference(activeEventId, "main");
  switchView("bracket");
  renderBracket();
  renderTech1EventControlWorkflow();
}

function updateCompetitionBracketPage() {
  const hasLowerBracket = Boolean(tournamentState?.lowerBracket?.rounds?.length);
  const resolvedPage = hasLowerBracket ? activeCompetitionBracketPage : "main";
  document.getElementById("lowerBracketPage").classList.toggle("is-active", resolvedPage === "lower" && hasLowerBracket);
  document.getElementById("mainBracketPage").classList.toggle("is-active", resolvedPage === "main" || !hasLowerBracket);
  document.querySelectorAll("[data-bracket-page]").forEach((tab) => {
    const page = tab.dataset.bracketPage;
    const hidden = page === "lower" && !hasLowerBracket;
    tab.classList.toggle("hidden", hidden);
    tab.classList.toggle("is-active", !hidden && page === resolvedPage);
  });
}

function chooseWinner(bracketKey, roundIndex, matchIndex, side) {
  if (!adminCanEdit() && !STANDALONE_DEMO_MODE) return;
  let match = null;
  if (bracketKey === "lower") {
    if (!tournamentState.lowerBracket) return;
    match = tournamentState.lowerBracket.rounds[roundIndex].matches[matchIndex];
  } else if (bracketKey === "third") {
    match = tournamentState.mainBracket?.thirdPlaceMatch;
  } else {
    if (!tournamentState.mainBracket) return;
    match = tournamentState.mainBracket.rounds[roundIndex].matches[matchIndex];
  }
  if (!match) return;
  const selectedDriver = match[side];

  if (!selectedDriver || !match.left || !match.right) return;

  if (participantKey(match.winner) === participantKey(selectedDriver)) {
    // If clicking the driver who is ALREADY the winner, undo it
    match.winner = null;
    match.winnerMode = null;
    clearWinnerAnimationState();
  } else {
    // Otherwise, set them as the new winner
    match.winner = cloneDriver(selectedDriver);
    match.winnerMode = "manual";
    const isPodiumRevealProtectedBattle = bracketKey === "third"
      || (bracketKey === "main" && roundIndex === (tournamentState?.mainBracket?.rounds?.length || 0) - 1);
    if (isPodiumRevealProtectedBattle) {
      clearWinnerAnimationState();
    } else {
      triggerWinnerAnimation(buildWinnerAnimationState(bracketKey, roundIndex, matchIndex, side, selectedDriver));
    }
  }

  clearCompetitionJudgeControl(tournamentState);
  publishState();
  renderBracket();
}

function handleBracketSlotInteraction(bracketKey, roundIndex, matchIndex, side) {
  if (!bracketReorderModeEnabled) {
    chooseWinner(bracketKey, roundIndex, matchIndex, side);
    return;
  }

  const slot = { bracketKey, roundIndex, matchIndex, side };
  if (!isBracketSlotReorderable(bracketKey, roundIndex, matchIndex, side)) return;
  const match = getCompetitionMatchRef(bracketKey, roundIndex, matchIndex, tournamentState);
  if (!match?.[side]) return;

  if (isBracketSwapSource(slot)) {
    clearBracketSwapSource();
    renderBracket();
    return;
  }

  if (!bracketSwapSource) {
    setBracketReorderUiState({ bracketSwapSource: slot });
    renderBracket();
    return;
  }

  const previousSource = bracketSwapSource;
  clearBracketSwapSource();
  const swapped = swapBracketSlotDrivers(previousSource, slot);
  if (!swapped) {
    setBracketReorderUiState({ bracketSwapSource: slot });
    renderBracket();
  }
}

function handleBracketBoardDragStart(e) {
  if (!bracketReorderModeEnabled) return;
  const sourceButton = e.target.closest("[data-draggable-slot='1']");
  const sourceSlot = parseBracketSlotData(sourceButton);
  if (!sourceSlot || !isBracketSlotReorderable(sourceSlot.bracketKey, sourceSlot.roundIndex, sourceSlot.matchIndex, sourceSlot.side)) {
    return;
  }
  activeBracketDragTarget = null;
  bracketDragSwapHandled = false;
  setBracketReorderUiState({ activeBracketDragSource: sourceSlot });
  clearBracketDragState();
  setBracketReorderUiState({ activeBracketDragSource: sourceSlot });
  sourceButton.classList.add("is-bracket-drag-source");
  try {
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", JSON.stringify(sourceSlot));
  } catch (error) {
    console.warn("Bracket drag payload could not be attached.", error);
  }
}

function handleBracketBoardDragOver(e) {
  if (!bracketReorderModeEnabled) return;
  if (!activeBracketDragSource) return;
  const dropTarget = e.target.closest("[data-drop-slot='1']");
  const targetSlot = parseBracketSlotData(dropTarget);
  if (!canSwapBracketSlots(activeBracketDragSource, targetSlot, activeEventMeta)) return;
  if (!isBracketSlotReorderable(targetSlot.bracketKey, targetSlot.roundIndex, targetSlot.matchIndex, targetSlot.side)) return;
  e.preventDefault();
  if (e.dataTransfer) {
    e.dataTransfer.dropEffect = "move";
  }
  activeBracketDragTarget = isSameBracketSlot(activeBracketDragSource, targetSlot) ? null : targetSlot;
  document.querySelectorAll(".is-bracket-drop-target").forEach((element) => {
    if (element !== dropTarget) {
      element.classList.remove("is-bracket-drop-target");
    }
  });
  if (!isSameBracketSlot(activeBracketDragSource, targetSlot)) {
    dropTarget.classList.add("is-bracket-drop-target");
  }
}

function handleBracketBoardDrop(e) {
  if (!bracketReorderModeEnabled) return;
  if (!activeBracketDragSource) return;
  const dropTarget = e.target.closest("[data-drop-slot='1']");
  const targetSlot = parseBracketSlotData(dropTarget);
  if (!canSwapBracketSlots(activeBracketDragSource, targetSlot, activeEventMeta)) {
    clearBracketDragState();
    return;
  }
  e.preventDefault();
  activeBracketDragTarget = targetSlot;
  bracketDragSwapHandled = swapBracketSlotDrivers(activeBracketDragSource, targetSlot);
  clearBracketDragState();
}

function handleBracketBoardDragEnd() {
  if (!bracketReorderModeEnabled) return;
  const sourceSlot = activeBracketDragSource;
  const targetSlot = activeBracketDragTarget;
  const shouldApplyFallback = !bracketDragSwapHandled
    && sourceSlot
    && targetSlot
    && canSwapBracketSlots(sourceSlot, targetSlot, activeEventMeta)
    && !isSameBracketSlot(sourceSlot, targetSlot);
  clearBracketDragState();
  if (shouldApplyFallback) {
    swapBracketSlotDrivers(sourceSlot, targetSlot);
  }
}

function handleBracketPointerStart(e) {
  if (!bracketReorderModeEnabled || e.button !== 0) return;
  const sourceButton = e.target.closest("[data-draggable-slot='1']");
  const sourceSlot = parseBracketSlotData(sourceButton);
  if (!sourceSlot || !isBracketSlotReorderable(sourceSlot.bracketKey, sourceSlot.roundIndex, sourceSlot.matchIndex, sourceSlot.side)) {
    return;
  }
  clearBracketDragState();
  setBracketReorderUiState({ activeBracketDragSource: sourceSlot });
  sourceButton.classList.add("is-bracket-drag-source");
}

function handleBracketPointerMove(e) {
  if (!bracketReorderModeEnabled || !activeBracketDragSource) return;
  const pointerTarget = document.elementFromPoint(e.clientX, e.clientY) || e.target;
  const dropTarget = pointerTarget?.closest?.("[data-drop-slot='1']") || null;
  const targetSlot = parseBracketSlotData(dropTarget);
  if (!canSwapBracketSlots(activeBracketDragSource, targetSlot, activeEventMeta)) {
    activeBracketDragTarget = null;
    document.querySelectorAll(".is-bracket-drop-target").forEach((element) => element.classList.remove("is-bracket-drop-target"));
    return;
  }
  if (!isBracketSlotReorderable(targetSlot.bracketKey, targetSlot.roundIndex, targetSlot.matchIndex, targetSlot.side)) {
    return;
  }
  activeBracketDragTarget = isSameBracketSlot(activeBracketDragSource, targetSlot) ? null : targetSlot;
  document.querySelectorAll(".is-bracket-drop-target").forEach((element) => {
    if (element !== dropTarget) {
      element.classList.remove("is-bracket-drop-target");
    }
  });
  if (activeBracketDragTarget) {
    dropTarget.classList.add("is-bracket-drop-target");
  }
}

function handleBracketPointerEnd() {
  if (!bracketReorderModeEnabled || !activeBracketDragSource) return;
  const sourceSlot = activeBracketDragSource;
  const targetSlot = activeBracketDragTarget;
  const swapped = Boolean(
    targetSlot
    && canSwapBracketSlots(sourceSlot, targetSlot, activeEventMeta)
    && !isSameBracketSlot(sourceSlot, targetSlot)
    && swapBracketSlotDrivers(sourceSlot, targetSlot)
  );
  bracketPointerSwapHandled = swapped;
  clearBracketDragState();
}

document.getElementById("lowerBracketBoard").addEventListener("dragstart", handleBracketBoardDragStart);
document.getElementById("lowerBracketBoard").addEventListener("dragover", handleBracketBoardDragOver);
document.getElementById("lowerBracketBoard").addEventListener("drop", handleBracketBoardDrop);
document.getElementById("lowerBracketBoard").addEventListener("dragend", handleBracketBoardDragEnd);
document.getElementById("lowerBracketBoard").addEventListener("mousedown", handleBracketPointerStart);

document.getElementById("bracketBoard").addEventListener("dragstart", handleBracketBoardDragStart);
document.getElementById("bracketBoard").addEventListener("dragover", handleBracketBoardDragOver);
document.getElementById("bracketBoard").addEventListener("drop", handleBracketBoardDrop);
document.getElementById("bracketBoard").addEventListener("dragend", handleBracketBoardDragEnd);
document.getElementById("bracketBoard").addEventListener("mousedown", handleBracketPointerStart);
document.addEventListener("mousemove", handleBracketPointerMove);
document.addEventListener("mouseup", handleBracketPointerEnd);

document.getElementById("lowerBracketBoard").addEventListener("click", (e) => {
  if (bracketPointerSwapHandled) {
    bracketPointerSwapHandled = false;
    return;
  }
  const btn = e.target.closest(".slot-button[data-bracket='lower'], .driver-button[data-bracket='lower']");
  if (btn) handleBracketSlotInteraction("lower", parseInt(btn.dataset.round, 10), parseInt(btn.dataset.match, 10), btn.dataset.side);
});

document.getElementById("bracketBoard").addEventListener("click", (e) => {
  if (bracketPointerSwapHandled) {
    bracketPointerSwapHandled = false;
    return;
  }
  const btn = e.target.closest(".slot-button[data-bracket='main'], .slot-button[data-bracket='third']");
  if (btn) handleBracketSlotInteraction(btn.dataset.bracket, parseInt(btn.dataset.round || "0", 10), parseInt(btn.dataset.match || "0", 10), btn.dataset.side);
});

document.getElementById("view-bracket").addEventListener("click", (e) => {
  const mainRevealButton = e.target.closest("[data-action='main-show-podium-reveal']");
  if (mainRevealButton) {
    maybeOpenMainPodiumReveal({ force: true });
    return;
  }
  const twinActionButton = e.target.closest("[data-action^='twin-']");
  if (twinActionButton) {
    const action = twinActionButton.dataset.action;
    if (action === "twin-start-round") {
      if (startTwinCompRound()) {
        publishState();
        renderBracket();
      }
      return;
    }
    if (action === "twin-finalize-round") {
      if (finalizeTwinCompRound()) {
        publishState();
        renderBracket();
      }
      return;
    }
    if (action === "twin-sync-teams") {
      syncTwinCompTeamsFromRoster();
      publishState();
      renderBracket();
      return;
    }
    if (action === "twin-reset") {
      if (window.confirm("Reset Twin Comp rounds, elimination points, and current scores?")) {
        resetTwinCompEvent();
        publishState();
        renderBracket();
      }
      return;
    }
    if (action === "twin-show-podium-reveal") {
      twinPodiumRevealState.dismissedSignature = null;
      maybeOpenTwinCompPodiumReveal();
      return;
    }
  }
  const btn = e.target.closest(".battle-flow-option.current[data-flow-bracket]");
  if (!btn) return;
  chooseWinner(btn.dataset.flowBracket, parseInt(btn.dataset.flowRound || "0", 10), parseInt(btn.dataset.flowMatch || "0", 10), btn.dataset.flowSide);
});

twinPodiumRevealModal?.addEventListener("click", async (e) => {
  const revealButton = e.target.closest("[data-action='twin-podium-reveal']");
  if (revealButton) {
    const place = Number.parseInt(revealButton.dataset.place || "0", 10);
    if (place === 1 || place === 2 || place === 3) {
      twinPodiumRevealState.revealed = {
        ...(twinPodiumRevealState.revealed || {}),
        [place]: true,
      };
      renderTwinCompPodiumRevealModal();
      if (isTwinCompPodiumFullyRevealed()) {
        await autoCompleteEventAfterPodiumReveal("Twin Comp podium");
      }
    }
    return;
  }
  if (e.target === twinPodiumRevealModal) {
    twinPodiumRevealState.dismissedSignature = twinPodiumRevealState.signature;
    closeModal(twinPodiumRevealModal);
  }
});

twinPodiumRevealCloseBtn?.addEventListener("click", () => {
  twinPodiumRevealState.dismissedSignature = twinPodiumRevealState.signature;
  closeModal(twinPodiumRevealModal);
});

mainPodiumRevealModal?.addEventListener("click", async (e) => {
  const revealButton = e.target.closest("[data-action='main-podium-reveal']");
  if (revealButton) {
    const place = Number.parseInt(revealButton.dataset.place || "0", 10);
    if (place === 1 || place === 2 || place === 3) {
      if (place === 2 && !mainPodiumRevealState.revealed?.[1]) return;
      mainPodiumRevealState.revealed = {
        ...(mainPodiumRevealState.revealed || {}),
        [place]: true,
        ...(place === 1 ? { 2: true } : {}),
      };
      renderMainPodiumRevealModal();
      if (isMainPodiumFullyRevealed()) {
        await autoCompleteEventAfterPodiumReveal("main bracket podium");
      }
    }
    return;
  }
  if (e.target === mainPodiumRevealModal) {
    mainPodiumRevealState.dismissedSignature = mainPodiumRevealState.signature;
    closeModal(mainPodiumRevealModal);
  }
});

mainPodiumRevealCloseBtn?.addEventListener("click", () => {
  mainPodiumRevealState.dismissedSignature = mainPodiumRevealState.signature;
  closeModal(mainPodiumRevealModal);
});

competitionJudgePanel?.addEventListener("click", async (e) => {
  const tech1VoteButton = e.target.closest("[data-action='tech1-judge-vote'], [data-tech1-judge-vote='1']");
  if (tech1VoteButton) {
    if (!tech1VoteButton.disabled) {
      tech1VoteButton.closest(".competition-vote-grid")?.querySelectorAll("[data-action='tech1-judge-vote'], [data-tech1-judge-vote='1']").forEach((button) => {
        button.classList.remove("selected", "button-accent");
        button.classList.add("button-secondary");
      });
      tech1VoteButton.classList.remove("button-secondary");
      tech1VoteButton.classList.add("button-accent", "selected");
    }
    await submitTech1JudgeVote(tech1VoteButton.dataset.side, currentRole);
    renderCompetitionJudgePanel();
    renderTech1DriftView();
    renderTech1EventControlWorkflow();
    return;
  }
  const deductionButton = e.target.closest("[data-action='judge-competition-deduct']");
  if (deductionButton) {
    const side = deductionButton.dataset.side === "right" ? "right" : "left";
    const deduction = Number.parseInt(deductionButton.dataset.deduction || "", 10);
    if (!Number.isFinite(deduction)) return;
    if (!applyCompetitionJudgeDeduction(side, deduction, currentRole, activeEventMeta, getCompetitionJudgeControl())) return;
    renderCompetitionJudgePanel();
    return;
  }
  const scorecardButton = e.target.closest("[data-action='judge-competition-submit-scorecard']");
  if (scorecardButton) {
    const panelScope = scorecardButton.closest(".competition-judge-card") || competitionJudgePanel;
    const side = scorecardButton.dataset.side === "right" ? "right" : "left";
    const activeInput = panelScope?.querySelector(`input[data-side='${side}']`);
    const score = toNumber(activeInput?.value ?? "");
    if (score === null) return;
    setCompetitionJudgeDraftScore(side, score, currentRole, activeEventMeta, getCompetitionJudgeControl(), true);
    await submitCompetitionJudgeScorecard({ side, score }, currentRole);
    return;
  }
  const voteButton = e.target.closest("[data-action='judge-competition-vote']");
  if (!voteButton) return;
  if (isTech1AnniversaryMode(activeEventMeta) && currentRole?.startsWith("j")) {
    if (!voteButton.disabled) {
      voteButton.closest(".competition-vote-grid")?.querySelectorAll("[data-action='judge-competition-vote']").forEach((button) => {
        button.classList.remove("selected", "button-accent");
        button.classList.add("button-secondary");
      });
      voteButton.classList.remove("button-secondary");
      voteButton.classList.add("button-accent", "selected");
    }
    await submitTech1JudgeVote(voteButton.dataset.side, currentRole);
    renderCompetitionJudgePanel();
    renderTech1DriftView();
    renderTech1EventControlWorkflow();
    return;
  }
  if (!voteButton.disabled) {
    voteButton.closest(".competition-vote-grid")?.querySelectorAll("[data-action='judge-competition-vote']").forEach((button) => {
      button.classList.remove("selected", "button-accent");
      button.classList.add("button-secondary");
    });
    voteButton.classList.remove("button-secondary");
    voteButton.classList.add("button-accent", "selected");
  }
  await submitCompetitionJudgeVote(voteButton.dataset.side, currentRole);
});

competitionJudgePanel?.addEventListener("change", (e) => {
  const scoreInput = e.target.closest("input.competition-stage-score-input[data-side]");
  if (!scoreInput) return;
  const side = scoreInput.dataset.side === "right" ? "right" : "left";
  const nextValue = toNumber(scoreInput.value ?? "");
  if (nextValue === null) return;
  if (!setCompetitionJudgeDraftScore(side, nextValue, currentRole, activeEventMeta, getCompetitionJudgeControl(), true)) return;
  renderCompetitionJudgePanel();
});

competitionDecisionPanel?.addEventListener("click", async (e) => {
  const tech1DecisionButton = e.target.closest("[data-action='tech1-admin-decision']");
  if (tech1DecisionButton) {
    await applyTech1JudgeDecision(tech1DecisionButton.dataset.decision || "advance");
    renderBracket();
    renderTech1DriftView();
    renderTech1EventControlWorkflow();
    return;
  }
  const reviewButton = e.target.closest("[data-action='review-competition-decision']");
  if (reviewButton) {
    await requestCompetitionDecisionReview();
    return;
  }
  const continueButton = e.target.closest("[data-action='continue-competition-flow']");
  if (continueButton) {
    await continueCompetitionFlow();
  }
});

document.getElementById("resetBracketBtn").addEventListener("click", () => {
  if (!adminCanEdit() || !tournamentState?.qualifiedDrivers?.length) return;
  const lowerCount = getRequestedSdcMainBracketSize(bracketModeSelect.value) || 0;
  setBracketReorderMode(false, { render: false });
  setTournamentStateState(createTournamentState(tournamentState.qualifiedDrivers, normalizePreferredFormat(tournamentState.preferredFormat || FORMAT_CLASSIC), lowerCount), { syncQualifying: false });
  publishState();
  renderBracket();
});

inlineResetBracketBtn?.addEventListener("click", () => {
  document.getElementById("resetBracketBtn")?.click();
});

async function bootstrapApp() {
  applyClientBranding();
  syncBracketFullscreenSizing();
  syncForcedHostContext();
  hydrateEventAdminBrowserUnlockFromExistingSessions();
  initializeTheme();
  await initLocalState();
  const initialExplicitRoute = parseRouteFromLocation()
    || (String(window.location.hash || "").toLowerCase() === "#/website-admin" ? { kind: "website-admin" } : null);
  startAutoEventSwitchWatcher();
  if (STANDALONE_DEMO_MODE) {
    activateStandaloneDemoWindow();
  }
  await maybeRunPendingTestScenario();
  renderEventDirectory();
  setWebsiteAdminAccess(isWebsiteAdmin);
  const hasExplicitInitialRoute = Boolean(initialExplicitRoute);
  if (hasExplicitInitialRoute) {
    applyResolvedRoute(initialExplicitRoute);
  } else {
    applyRoleChange(forcedHostContext?.kind === "website-admin" ? "spectator" : currentRole);
    applyRouteFromLocation();
  }
  ensureForcedHostRoleAccess();
  if (db && auth?.currentUser) {
    setupCloudSync(auth.currentUser);
    if (initialExplicitRoute) {
      window.setTimeout(() => {
        applyResolvedRoute(initialExplicitRoute);
      }, 350);
    }
  }
}

if (typeof window !== "undefined" && ["127.0.0.1", "localhost"].includes(window.location.hostname)) {
  window.__PRODIGY_QA_DEBUG = () => ({
    activeEventId,
    activeEventMeta: activeEventMeta ? cloneEventMeta(activeEventMeta) : null,
    currentRole,
    nativeStreamActive,
    nativeStreamHasLocalStream: Boolean(nativeStreamLocalStream),
    nativeStreamRemoteSessionId,
    nativeStreamViewerId,
    nativeStreamViewerConnectionState,
    nativeStreamViewerMediaState,
    nativeStreamViewerPlayBlocked,
    nativeStreamViewerLastError,
    nativeStreamRemoteTrackCount: getNativeRemoteTrackCount(),
    nativeStreamRemoteVideoTrackCount: getNativeRemoteTrackCount("video"),
    nativeStreamRemoteAudioTrackCount: getNativeRemoteTrackCount("audio"),
    nativeLiveVideoMuted: Boolean(nativeLiveVideo?.muted),
    nativeLiveVideoPaused: Boolean(nativeLiveVideo?.paused),
    nativeLiveVideoReadyState: Number(nativeLiveVideo?.readyState || 0),
    nativeLiveStageState: nativeLiveStage?.dataset?.streamState || "offline",
    nativeStreamAuthorized: isNativeStreamerAuthorized(),
    localEventPreviewMode,
    lastLocalPush,
    lastRemoteDirectorySyncStamp,
    lastRemoteActiveEventSyncStamp,
    lastRemoteEventSyncStamp,
    eventDirectoryKeys: Object.keys(eventDirectory || {}),
    directoryActiveEventName: activeEventId && eventDirectory[activeEventId]
      ? eventDirectory[activeEventId].name || null
      : null,
  });
  window.__PRODIGY_QA_NATIVE_STREAM = {
    start: () => startNativeStream(),
    stop: () => stopNativeStream(),
    toggleAudio: () => toggleNativeStreamAudio(),
    toggleCamera: () => toggleNativeStreamCamera(),
    renderLayout: (layoutKey) => {
      const normalizedLayout = STREAMER_SCENE_META[layoutKey] ? layoutKey : resolveNativeStreamLayoutKey();
      if (nativeLiveStage) nativeLiveStage.dataset.layoutKey = normalizedLayout;
      if (streamerLivePreviewShell) streamerLivePreviewShell.dataset.layoutKey = normalizedLayout;
      renderNativeBroadcastOverlay(nativeLiveOverlay, normalizedLayout);
      renderNativeBroadcastOverlay(streamerOverlayPreviewFrame, normalizedLayout);
      return normalizedLayout;
    },
  };
}

// Final Init Call
bootstrapApp();

